/** Olandese: Guida e Novita' (testi senza nome, chiave `t.<impronta del testo inglese>`). Generato da `scripts/importa-nl.mjs` dal foglio `docs/traduzione-olandese.csv`: non si modifica a mano. */
export const NL_TEXTS: Record<string, string> = {
  "t.100829qiojv": "Notches worden niet bewaard: ze verdwijnen vanzelf als je de band of frequentie van de radio verandert en zijn na een herstart weg, want een storing hoort alleen bij die frequentie.",
  "t.100j34gwrwx": "[[ca.phone]]: “[[ca.phone.ok]]” als netwerk en firewall goed zijn; “[[ca.phone.warn]]” bij een “Openbaar” netwerk of zonder thuisadres; “[[ca.phone.bad]]” als de Windows-firewall Aurora blokkeert. “[[diag.fix]]” leidt naar de pagina [[sw.tab.phone]].",
  "t.100yncnvyr7": "Filters op roepnaam, prefix en al gewerkt",
  "t.101hsp1tcil": "Kolom “[[ctl.grp.seq]]”: [[ctl.autoseq]] (de reeks gaat vanzelf door: rapport, R+rapport, RR73, 73, en aan het eind van het QSO gaat het naar het logboek); [[ctl.single_qso]] (na een voltooid QSO stopt Aurora met zenden); [[ctl.answer_all]] (elk station dat jou roept gaat in de wachtrij); [[ctl.answer_b4]] (antwoordt ook aan stations die je al hebt gewerkt); [[ctl.bypass]] (slaat de controle op berichten van stations die niet in de lijst staan over); [[ctl.skip_tx1]] (bij het beantwoorden van een CQ begint het bij Tx2 in plaats van Tx1; uit in Hound); [[ctl.rrr]] (de afsluiting is RRR in plaats van RR73); [[ctl.tx_period]] (één klik wisselt tussen de twee zendperiodes: “Tx 00/30” of “Tx 15/45”; als je een station antwoordt, wordt de juiste vanzelf ingesteld).",
  "t.1021xy6y559": "Terwijl je zendt, stopt de waterval (er komt geen audio van de radio) en markeert een gele lijn de pauze; aan het eind van de zending begint hij weer.",
  "t.104ebzp7fgn": "Uitgang: de kaart die audio naar de radio stuurt om te zenden (meestal “Speakers (USB Audio Device)”).",
  "t.105xdqfiwl1": "[[agent.popup]] · [[agent.preview]] met “[[agent.try.update]]” en “[[agent.try.dx]]”: twee knoppen die meteen een voorbeeldkaart tonen (een voorbeeldupdate en een voorbeeld-DXpeditie, met verzonnen teksten) met de hierboven gekozen duur, om te zien hoe het eruitziet. De knoppen van de kaart (“[[agent.try.updMain]]”, “[[agent.try.later]]”, “[[agent.try.dxMain]]”, “[[agent.try.ignore]]”) zijn de echte, maar hier kondigt de kaart niets echts aan.",
  "t.105xxpznogh": "SSTV: luisteren blijft aan en handiger log",
  "t.1087fxhywsw": "Het tandwiel (“[[sstv.set.title]]”): opent de Instellingen op de SSTV-pagina’s in een apart venster, zodat de pagina en het luisteren blijven. Het is er niet op telefoons en tablets (de Instellingen kun je alleen op de pc wijzigen).",
  "t.10a6i47zyzt": "De onderdelen met “[[digi.mi.soon]]” (QPSK31, FSK31, MFSK, Olivia, Contestia, MT63, Throb, Hellschreiber, Packet, Pactor, Amtor) zijn grijs: ze bestaan nog niet en kunnen niet worden gekozen.",
  "t.10arsvkq0ry": "Contest: TX blijft aan",
  "t.10bilnwf2wt": "Daaronder “[[bands.far3]]”: de verste stations die jouw signaal hebben ontvangen (PSK Reporter), één per rij, met vlag, roepnaam, land, band, afstand en signaal in dB. Er verschijnen er drie; de vierde en de vijfde alleen als er ruimte is. Zonder ontvangsten staat er “[[bands.noPsk]]”.",
  "t.10ce0uphvn5": "“[[rep.sendBundle]]”: uploadt het pakket zonder persoonlijke gegevens (opgeschoond logboek, crashrapporten, versie, radio, PTT, audio) en toont een code die je aan degene die je helpt kunt doorgeven, zodat die het kan terugvinden. De knop bestaat alleen als het adres van de rapportendienst in deze versie is ingesteld; anders zie je “[[rep.notConfigured]]” en wordt er niets verstuurd. Tijdens het versturen zie je “[[rep.sending]]”.",
  "t.10ep3rviz90": "Fabriekswaarden, in decimaal (en in hexadecimaal zoals de handleiding ze schrijft): IC-7300 = 148 (94h), IC-7610 = 152 (98h), IC-705 = 164 (A4h), IC-9700 = 162 (A2h). Als je in het menu van de radio niets hebt veranderd, is 0 of dit getal gelijkwaardig.",
  "t.10fxcekdr20": "Signalenpaneel: Controle, Wissen en hoogte (#50)",
  "t.10gy1luejlj": "Commando’s die naar Aurora terugkomen: op dezelfde poort van de bestemmingen met “[[int.wsjtx]]” komen antwoord op een station, zendstop, vrije tekst, kleuren van roepletters, lijsten wissen, locator wijzigen en configuratie. Ze gelden alleen met “[[ens.k.AcceptUDPRequests]]” aan (in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]); uit kan de bestemming alleen lezen.",
  "t.10h47ydv4fc": "[[cop.spots]] · [[cop.expire]]: uitklaplijst met [[cop.never]] (fabriek: ze blijven zolang de cluster ze houdt) of 5, 10, 15, 20, 30, 60 of 120 minuten. Kies een korte tijd als de lijst vol raakt met oude spots.",
  "t.10h6betrvbn": "Log4OM logt de QSO’s van Aurora zoals die van JTDX. De radio wordt apart gekoppeld (onderdeel “Log4OM: de radio via Aurora”).",
  "t.10hac8tqcfh": "Op de kaart: scrolwiel of de knoppen + en − om te zoomen, ingedrukt houden en slepen om te verschuiven. Een klik op een punt geeft vierkant, afstand, land en CQ- en ITU-zones. Een klik op een station in de lucht, of op zijn roepnaam, roept het: Aurora verlaat de lopende QSO en antwoordt dat station, zoals bij de wachtrij.",
  "t.10ijt6d5jhy": "Volledig handboek van alle Instellingen",
  "t.10ip2vstapb": "De frequenties voor CW, SSTV, RTTY en PSK volgen de bandplannen: HF uit het IARU-plan Regio 1, vanaf 6 m uit het ARI-plan. Activiteitscentra, QRS, QRP, EME en meteor scatter zijn inbegrepen.",
  "t.10jxym9lci5": "In Log4OM: Settings → Program configuration → CAT interface. CAT Engine: Hamlib.",
  "t.10kqiwxculg": "Eronder het spectrum met de vaste markeringen om de afstemming te centreren: de sync moet op de gele lijn van 1200 Hz vallen, zwart op 1500 en wit op 2300; een rode lijn (“[[sstv.mark.found]]”) toont waar de sync van de zender echt aankomt. Als de rode lijn ver van die van 1200 Hz zit, klopt de afstemming niet: zie “[[sstv.set.rxOffset]]” in de SSTV-instellingen.",
  "t.10lqea4i0nt": "Om zonder rotor te proberen: “[[rot.set.launch]]”, model “Hamlib Dummy”, geen poort, en zet dan “[[rot.set.enabled]]” aan. Om de antenne echt te draaien zie het onderdeel “De antenne-rotor” en de pagina [[nav.rotator]].",
  "t.10m903hhe8o": "Geen CQ? Aurora meldt het in een aparte melding: standaard beantwoordt het alleen CQ’s. Om elk bericht te beantwoorden: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]].",
  "t.10pklmh7q3z": "In PSK komt elk bit met zijn waarschijnlijkheid en de varicode wordt als hele woorden gelezen: een twijfelachtig bit breekt het teken niet en ruis drukt heel weinig af (onder een bepaalde waarschijnlijkheid wordt het teken niet afgedrukt). In het ontvangstvenster zet een dubbelklik op een roepnaam die in de lopende QSO en zoekt naam, QTH, locator en land op; rechtsklikken op een woord zet het in het gekozen logveld, en “[[digi.word.copy]]” en “[[digi.mi.clearRx]]” zijn er altijd.",
  "t.10rjki42jl5": "Verschijnt “[[aud.vol.off]]” in plaats van de regelaar, dan heeft dat apparaat geen volume dat je hier kunt aanpassen (bijvoorbeeld TCI of netwerkaudio): stel het niveau in het SDR-programma of in Cat4OM in, of in de systeemmixer.",
  "t.10rtqf4rioa": "Om te stoppen: STOP TX of de toets Esc (zie “Het zenden stoppen”). In contests is de herhaalde CQ “[[contest.autoCq]]” (F1); met de automatiseringen is er “[[auto.autoCqOn]]”.",
  "t.10shfsupxop": "Wat je hier niet kunt wijzigen: de repository waaruit de versies worden gelezen, de optie voor testversies (pre-release) en het leestoken voor een privérepository hebben geen zichtbare velden. Ze blijven op de standaardwaarden (de stabiele versies van Aurora op GitHub) en zijn alleen van belang voor wie ontwikkelt.",
  "t.10t7v5c87wa": "[[cat.grp.ptt]] · [[cat.ptt.port]]: verschijnt alleen bij PTT op DTR of RTS. Leeg = dezelfde poort als de CAT. Schrijf hem alleen als de PTT op een andere COM zit: de Yaesu FTdx101, FT-991A en FT-710 hebben bijvoorbeeld twee poorten, de “Enhanced COM Port” voor CAT en de “Standard COM Port” voor PTT.",
  "t.10ts8yjf0fc": "[[not2.grpColors]]",
  "t.10u8x7oepe0": "Alleen met OmniRig: [[cat.omnirig.rig]] (Rig 1 of Rig 2): welke van de twee radio’s van OmniRig Aurora bedient. Poort, snelheid en model stel je in het programma OmniRig in, niet hier.",
  "t.10ufnvi1wp": "Om een UltraFOX- of SuperFox-expeditie te roepen: schakel Hound in FT8 in. Aurora decodeert ook het brede signaal en antwoordt zoals bij klassieke Fox.",
  "t.10usxfuxtqi": "“[[qmap.period]]” en “[[qmap.submodes]]”: periode en submodi om naar te zoeken. “[[qmap.fading]]”: het fadingmodel voor EME. “[[qmap.also30]]” (bij een periode van 60 s zoekt hij ook naar Q65-30). “[[qmap.average]]” telt de periodes op voor zwakkere signalen; “[[qmap.clearAverage]]” leegt het gemiddelde. “[[qmap.save]]” past alles toe.",
  "t.10xa6lxqho4": "Dit zijn de twee plekken, buiten de Instellingen, waar Aurora je vertelt dat er een nieuwe versie is. Ze hebben geen vakjes om in te stellen: het zijn de knoppen.",
  "t.10y4vcktxzj": "CQ roepen vanaf de pagina Station",
  "t.10zi27ezrie": "“[[stats.missing]]”: opent met een klik en toont de landen die je nog niet hebt gewerkt, één label per land.",
  "t.1108re41lyh": "De gele kaart zegt hoeveel seconden het decoderen duurde en, als de gebruikte diepte bekend is, stelt hij de stap hieronder voor (Diep → Normaal → Snel): bij diepte Diep zegt hij over te schakelen naar Normaal, bij Normaal naar Snel. Bij Snel valt er niets meer weg te halen, dus de kaart geeft alleen algemeen advies (zet SWL uit, a7/a8 en zware programma’s).",
  "t.1142thpp31l": "«Zenden» staat bovenaan de pagina, met F1 om te starten en Esc om te stoppen; het label «Luistert» is weg. Ontvangen en verzonden beelden staan in twee horizontale stroken die je met de pijltjes verschuift.",
  "t.114eszr12n0": "“[[int.name]]”: een naam om hem in de lijst te herkennen (maximaal 40 tekens). Alleen voor jou.",
  "t.114rqzxlcu9": "SSTV: FSK-ID en mode wordt vanzelf herkend",
  "t.116bhi9fa5k": "Rij met knoppen: “[[contest.rules]]” (de regels in het kort en de officiële link), “[[contest.calendar]]”, “[[contest.export]]” (het bestand voor de organisator, zie hieronder), “[[contest.settings]]” (de contestinstellingen, aanpasbaar en per contest opgeslagen), “[[contest.training]]”, “[[contest.analysis]]” en “[[contest.end]]” (zet de contest uit en gaat terug naar de vorige instellingen).",
  "t.116he6owt59": "Hoe je een berichtrij leest",
  "t.116mp77pl7b": "Tabellen met kolommen (RX-venster, DX Cluster): sleep de kop om de kolom te verplaatsen (of Alt + pijltjes), sleep de rechterrand om de breedte te wijzigen (of Alt + Shift + pijltjes), rechtsklik op de kop om te resetten.",
  "t.1186eqb7vcp": "Hounds roepen boven 1000 Hz, nooit eronder: het lage deel is van de Fox.",
  "t.11899vyx9i2": "Radiofrequentie in MHz: die zie je alleen als het display van de radio verborgen is (anders lees je hem daar al).",
  "t.119yfnb60dq": "Fox en Hound: wat ze zijn",
  "t.11d0mpkrw3q": "“[[ca.close]]” sluit de kaart (Enter ook). Nadat je iets hebt opgelost, open je “[[ca.run]]” opnieuw om het teken te zien veranderen.",
  "t.11fat73tulr": "Het display is donker met de radio uit en «Split uit» staat links. Clusteropties en «DX-spot» ook in FT8. In PSK·RTTY·CW grepen om de breedte van de RX- en TX-vensters en van «Signalen» te wijzigen. Knoppen lichten op bij het erover bewegen van de muis en de subpunten van de Instellingen volgen een geleidelijn.",
  "t.11fgtosqin8": "Test: maak een QSO; de regel verschijnt in het Log4OM-logboek.",
  "t.11fto49ogvm": "[[auto.b2]] (drie keuzeknoppen): bij meerdere interessante CQ's in dezelfde cyclus kiest Aurora er maar één. [[auto.prefer.rarity]] (standaard): eerst de gezochte, dan nieuw land, nieuw op band of mode, zone, grid; het sterkste signaal beslist bij gelijke stand. [[auto.prefer.snr]]: het sterkste van de interessante. [[auto.prefer.score]]: een score die nieuwigheid (10 punten per niveau) en signaal (tot 18 punten, van −24 tot +12 dB) weegt.",
  "t.11gnage677": "De afstand is in km of in mijlen, afhankelijk van de voorkeuren. Het blok werkt zichzelf elke 10 seconden bij; de condities komen van N0NBH (hamqsl.com).",
  "t.11kgxlb724f": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.tab.macros]] bewaar je de lijst met kant-en-klare teksten voor het vrije deel van het bericht, met symbolen die Aurora ter plekke vervangt. De lijst wordt meteen opgeslagen en blijft op dit apparaat (niet op de pc als je op de telefoon zit, en andersom).",
  "t.11nu597jam1": "“[[sstv.rx.tx]]”: zendt meteen het beeld dat in het tabblad “[[sstv.view.tx]]” is voorbereid en brengt je erheen. Het is grijs als je niet kunt zenden, als je aan het ontvangen bent ([[sstv.rx.txWait]]) of als je al zendt.",
  "t.11pm9ffshzw": "Verkenner opent met het bestand Aurora-assistenza-….zip al geselecteerd: stuur het per e-mail, WhatsApp of Telegram.",
  "t.11rm4otni1b": "Veelvoorkomende problemen",
  "t.11vj835o6ht": "Spots: de lijst is dezelfde als die van het DX Cluster van Aurora, met de kolommen [[cluster.col.by]], [[cluster.col.freq]], [[cluster.col.call]], [[cluster.col.country]], [[cluster.col.mode]], [[cluster.col.comment]] en [[cluster.col.time]]. Een klik (of een dubbelklik, volgens “[[cop.choose]]”) verplaatst de radio zodat het signaal op de ontvangsttoon valt, zet de roepnaam in de huidige QSO en, als de modus van de spot RTTY, CW of PSK is en de modus van de pagina een andere, verandert ook de modus van de pagina.",
  "t.11vq8vots64": "Boven het vak verschijnt, zodra het zenden begint, de lijst van wat je al hebt uitgezonden (“[[digi.tx.sentTitle]]”); die maak je leeg met “[[digi.mi.clearTx]]”.",
  "t.11w502na6lr": "Rechtsklik op een toets van de macrobalk, of de opdracht <EDITMACRO:nome> in een andere macro. Het venster “[[digi.edit.title]]” opent; met “[[digi.edit.ok]]” wordt de macro opgeslagen, met “[[digi.edit.cancel]]” verandert er niets.",
  "t.11y33iu2afy": "De twee verticale balken zijn Rx (groen) en Tx (rood), met hun frequentie bovenaan geschreven (“Rx 1500”). Je sleept ze met de muis; of je zet de focus erop met Tab en gebruikt de pijltjes links en rechts: 10 Hz per keer, 50 Hz met Shift ingedrukt.",
  "t.11yhdwc0vl6": "Laatste deel van de pagina [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]: hoe berichten over jou worden herkend en de lipjes (“markeringen”) aan de rand van de rijen. Alles geldt meteen, behalve waar anders vermeld.",
  "t.11yppo1n200": "Op de cursor: een groene vlag (rood bij zenden) op het ontvangstpunt, en een ruit (PSK, CW) of een paar driehoeken verbonden door een lijn (RTTY: de twee tonen, even ver uit elkaar als de shift) voor ontvangst, in donkerpaars, en voor zenden, in rood. Als Lock uit staat, vallen de twee paren samen en vormen ze één ruit.",
  "t.1201ueihhc3": "De andere modi dan FT8 en VHF (PSK, RTTY, CW, SSTV, satellieten) hebben hun eigen pagina en hun eigen balk: de pagina’s [[nav.fox]], [[nav.contest]] en [[nav.stats]] zijn er niet.",
  "t.120m8bxhfou": "Een telefoon of tablet koppelen",
  "t.122wsdtnhzh": "[[sw.digi.perMode]] · RTTY, “[[digi.rtty.reverse]]” (standaard uit) en “[[digi.rtty.uos]]” (standaard aan): Rev wisselt mark en space om, voor een station dat andersom zendt; met de radio op LSB draait Aurora ze al zelf om. UOS gaat na een spatie terug naar letters, zodat een gemiste letterverschuiving de tekst niet in cijfers verandert: laat het aan.",
  "t.1232ou9h5a6": "Stationsmeldingen minder opdringerig",
  "t.123kpcb1nt7": "Delete of Backspace: verwijdert de gekozen laag (niet terwijl je in een vak typt).",
  "t.124dev7bxmf": "[[nav.log]]",
  "t.1258lm894p8": "Pagina’s en panelen",
  "t.125y1db1954": "[[agent.title]] · meldingentabel: één rij per type, kolommen “[[agent.kind]]”, “[[agent.show.popup]]”, “[[agent.show.icon]]”, “[[agent.show.off]]”; in elke rij kies je maar één kolom. “[[agent.show.popup]]” = de kaart verschijnt op het bureaublad; “[[agent.show.icon]]” = geen kaart, alleen een teken op het icoon in het systeemvak; “[[agent.show.off]]” = niets. De rijen, met de standaardkeuze: “[[agent.kind.news]]” ([[agent.kind.news.tip]]; pop-up), “[[agent.kind.prop]]” ([[agent.kind.prop.tip]]; alleen icoon), “[[agent.kind.dxped]]” ([[agent.kind.dxped.tip]]; pop-up), “[[agent.kind.daily]]” ([[agent.kind.daily.tip]]; uit). Wanneer wijzigen: kies “[[agent.show.popup]]” alleen voor wat je meteen wilt zien.",
  "t.126m4h6db1z": "Aparte vensters en indeling",
  "t.1274sqtfaqs": "[[lay.settings]] · [[sch.use]] (vinkvak, standaard uit): zet het hele schema aan of uit. Met het vakje uit blijven de rijen ingevuld maar gebeurt er niets. De wissel gebeurt op de opgegeven minuut, vraagt radiobesturing (CAT) en werkt niet tijdens het zenden.",
  "t.127aqvg013u": "Weet je poort en snelheid niet? Probeer “[[cat.detect]]”: het vindt ze voor je. Als je OmniRig gebruikte, staan ze in het instellingenvenster daarvan.",
  "t.129cled0m8i": "[[set.add]] · veld “[[macro.new]]” (tekst, tot 30 tekens): typ de macro. Gebruik @ voor de roepnaam van de DX, & voor die van jou en # voor het rapport. De vrije tekst die eruit komt is in hoofdletters en maximaal 13 tekens lang; wat ontbreekt (bijvoorbeeld het rapport) wordt weggelaten.",
  "t.12a4od0uloq": "“[[onl.grpSolar]]” · “[[onl.solar]]” (standaard aan): elk half uur downloadt Aurora van hamqsl.com de zonneflux, de A- en K-indexen en de per band berekende condities, en toont ze in [[nav.propagation]]. De site ziet alleen je IP-adres. “[[ens.test]]” downloadt de gegevens één keer en controleert of ze te lezen zijn.",
  "t.12a9hrsp22u": "[[lay.lists]] · [[fil.countries]]: tekstveld, namen van de landen die je wilt verbergen, gescheiden door komma's (bijvoorbeeld Italy, Germany). Standaard leeg.",
  "t.12aagjh20nj": "[[gen.screen]] · [[gen.clearOnChange]]: selectievakje, standaard aan. Als de radio naar een andere band of mode gaat (FT8, FT4, JT), wordt [[panel.all]] leeggemaakt: de berichten van de vorige band zijn niet meer nuttig. Het geldt ook voor wijzigingen in de engine. Uit blijft de lijst zoals ze is en maak je haar met de hand leeg met Wissen.",
  "t.12e2f62z27b": "De sync valt ver van de lijn van 1200 Hz: de radio is niet goed afgestemd of de geluidskaart zit naast de frequentie. Corrigeer het met “[[sstv.set.rxOffset]]” in de SSTV-instellingen.",
  "t.12eyx27vm7c": "Zet [[gen2.waitFeatures]] aan ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]): het staat standaard uit, dus Wait and Reply en Wait and Call doen niets tot je het aanzet.",
  "t.12f1e7pdkoh": "[[tab.windows]] · [[win.reset]]: zet alles terug zoals in het begin: volgorde, hoogtes en scheidingslijn van de panelen op de hoofdpagina, niets verborgen, en alle aparte vensters gaan terug naar het hoofdvenster. Als het klaar is, verschijnt “[[win.done]]”. Gebruik het als de hoofdpagina onbruikbaar is geworden.",
  "t.12jjldr4iw": "“[[dxs.look]]” · “[[dxs.captions]]” (aan): de drie kleine regels (land, band en mode met de roepletters) onder de zes labels. “[[dxs.total]]” (aan): het aantal gewerkte landen, linksboven in het raster. “[[dxs.tryField]]” (aan): het veld waarin je roepletters typt om te zien hoe de kaart ze beoordeelt. “[[dxs.compact]]” (uit): kleinere vakjes, labels en ruimte, zodat er meer plaats overblijft voor het logboek; zet het aan op kleine schermen.",
  "t.12o9rw7ues9": "De code zegt “[[pair.expired]]”: maak op de pc een nieuwe en voer hem meteen in.",
  "t.12r0y1a2jfs": "Icom IC-7300, IC-705, IC-9700: één enkele USB COM-poort (CI-V loopt over de USB-kabel) plus de geluidskaart “USB Audio CODEC”. Kies in [[cat.rig]] het model met de naam van de radio; de snelheid moet die zijn die in het menu van de radio is ingesteld (item CI-V, zie de handleiding); het CI-V-adres ([[cat.civ]]) laat je op 0 staan voor de fabriekswaarde en, als je het in het menu hebt gewijzigd, schrijf je het DECIMAAL (IC-7300 = 148, niet 94h): zie “CI-V-adres van Icom-radio’s (decimaal)”.",
  "t.12vlj2nchgk": "[[toast.grp]] · [[toast.test]]: toont meteen drie voorbeeldberichten (succes, informatie, fout) met de huidige keuzes. [[set.reset]]: zet alleen dit vak terug op de standaardwaarden.",
  "t.12wfiwu11u0": "[[digi.menu.edit]] › [[digi.mi.clearTx]]: maakt het zendvenster leeg en ook de lijst met al uitgezonden tekst boven het vak.",
  "t.12xt3121nuv": "Veelgestelde vragen",
  "t.12ym175c24d": "Open het log: na ongeveer 15 seconden, de tijd die het nodig heeft om op te starten, komen de QSO’s vanzelf aan in de volgorde waarin je ze maakte.",
  "t.12zfbsaidex": "[[ens.g.wsprnet]] · lampje, “?” en [[ens.st.title]]: het lampje voor de titel toont hoe het ging ([[ens.led.off]], [[ens.led.untested]], [[ens.led.ok]], [[ens.led.err]]); de “?” legt uit wat er wordt verstuurd; eronder geeft “[[ens.st.title]]” het resultaat ([[ens.st.ok]] of [[ens.st.err]]) met de tijd, en hoeveel uploads nog in de wachtrij staan. Antwoordt WSPRnet niet, dan probeert Aurora het hooguit een uur opnieuw. Er is geen testknop: een testspot zou in de openbare database terechtkomen.",
  "t.130ehgvk7vl": "Er komt niets aan: een ander programma gebruikt poort 2237 al (GridTracker, JTAlert, een ander logprogramma). Gebruik een andere vrije poort (bijvoorbeeld 2239), zowel in Aurora als in LogHX.",
  "t.13202u8yqvm": "[[not2.grpTable]] · [[not2.alsoSound]]: speelt naast de kleur het geluid af dat voor dat type is gekozen (verderop gekozen, in “[[not2.grpColors]]”). Vergrendeld als het markeren van de rij uit staat. Om het echt te horen moet “[[alert.button]]” aan staan (zie de pagina “[[sw.pg.alerts]]”).",
  "t.134f56zi51": "In Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[int.title]]” › “+ [[int.p.loghx]]”. Laat 127.0.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.loggedAdif]]” aan.",
  "t.134vty509pa": "De AFC is begrensd: hij gaat niet verder dan ±15 Hz van de gekozen frequentie in PSK31 (±30 in PSK63), de halve shift in RTTY, ±50 Hz in CW; hij gaat niet in notches, blijft binnen de banddoorlaat en blijft staan als het signaal verdwijnt, in plaats van achter het naburige station aan te gaan.",
  "t.135v7u6ma2a": "Op de telefoon staat de knop [[stop.button]] onderaan het scherm.",
  "t.137q52gni7k": "Nieuw DXCC en gezocht station: de gemarkeerde meldingen",
  "t.137wqutopko": "Alleen RTTY: “[[digi.rtty.shift]]” (23, 85, 160, 170, 182, 200, 240, 350, 425, 450 of 850 Hz; standaard 170) en “[[digi.rtty.baud]]” (45, 45,45, 50, 56, 75, 100, 110, 150, 200 of 300; standaard 45,45), die meteen worden bewaard zoals de keuzemenu’s in de statusbalk; daarna [[digi.rtty.reverse]] ([[digi.rtty.reverseTip]]) en [[digi.rtty.uos]] (standaard aan).",
  "t.13bi81xoayt": "[[gen.screen]] · [[gen.log4omCount]]: getalveld van 1 tot 200, fabrieksinstelling 20. Hoeveel van de laatste QSO's van het Log4OM2-logboek in het logvenster worden getoond; het logboek wordt alleen gelezen, Aurora wijzigt het nooit.",
  "t.13gmyyr9cb1": "[[wfs.colors]] · [[wfs.scale]] (standaard aan): deelt elke rij door de mediaanwaarde, zodat de achtergrondruis altijd dezelfde kleur heeft, ongeacht het audioniveau, en alleen de signalen erboven zichtbaar blijven. [[wfs.flatten]] (standaard aan): haalt de curve van de achtergrondruis over de band weg; handig als het filter van de radio de ruisvloer scheeftrekt. Zet het uit als je de “rauwe” waterval wilt.",
  "t.13hkzy551no": "Stem af op een SSTV-frequentie (bijvoorbeeld 14,230 MHz USB) en open [[nav.sstv]]: het luisteren begint vanzelf en blijft aan tot je op “[[sstv.rx.stop]]” drukt, ook terwijl je een beeld voorbereidt in “[[sstv.view.tx]]”. De modus wordt herkend aan de VIS of, als de VIS gemist is, aan het ritme van de synchronisatielijnen; eenmaal herkend blijft hij tot het einde van het beeld.",
  "t.13i9mp0ma4o": "[[fil.decode]] · [[dec.ftolQ65]]: uitklaplijst met de frequentietolerantie rond Rx, van 1 tot 1000 Hz (1, 2, 5, 10, 20, 50, 100… tot 1000); fabriekswaarde 50 Hz. Het is het venster waarin Q65 altijd het beste signaal, de QSO-lijst en het gemiddelde probeert. Vergroot hem voor EME met een grote Dopplerverschuiving.",
  "t.13j2e3v0i4n": "[[lotw.grp]] · [[lotw.color]] (standaard lichtgroen) en [[lotw.months]]: hoeveel maanden terug de laatste upload meetelt, kies uit “[[lotw.m3]]”, “[[lotw.m6]]”, “[[lotw.m12]]” (standaard), “[[lotw.m24]]” of “[[lotw.m0]]” (markeert ook wie al jaren niet heeft geüpload). Ze blijven vergrendeld als “[[lotw.enable]]” uit staat.",
  "t.13j31ydxyq3": "De roepnaam, naam, QTH en locator worden ook ingevuld met een dubbelklik op een roepnaam in het ontvangstvenster, vanuit het signaalpaneel (“[[digi.band.toQso]]”) of met een klik op een spot.",
  "t.13j7zbykb1i": "[[gen2.wsjtx3]] · [[gen2.waitFeatures]] (standaard uit): met een ingestelde DX en [[ctl.enable_tx]] uit gaat de QSO vanzelf verder als de DX je roept (Wait and Reply); met de knop Wait and Call ingeschakeld roep je de DX zelf op als die CQ roept of zijn QSO afsluit, tot ongeveer 3 keer. Let op: er kan een zending starten zonder dat je iets doet; laat het uit als je geen verrassingen wilt.",
  "t.13lkddo7xzs": "“+ [[int.p.wsjtx]]”: naam GridTracker, 127.0.0.1, poort 2237, alleen “[[int.wsjtx]]” aan. Hij ontvangt de WSJT-X-stream: Heartbeat (bij het starten en elke 15 seconden), Status bij elke wijziging (frequentie, modus, huidige DX, bericht dat wordt verzonden), Decode voor elk gedecodeerd bericht, Clear, QSO Logged aan het einde van een QSO en Close als je Aurora sluit. Voor GridTracker, JTAlert, QLog, CQRLOG, MacLoggerDX en de andere programma’s die de WSJT-X-stream lezen. Met “[[ens.k.AcceptUDPRequests]]” aan kunnen deze programma’s ook een station beantwoorden, de zending stoppen of roepletters kleuren.",
  "t.13mhultrdat": "De seconden van de periode (“07/15”: huidige seconde en lengte van de periode) en, onder de balk, een dunne voortgangsbalk van de periode.",
  "t.13mizugmr7m": "De kaart heeft een band met het draaiende logo, een label voor het soort melding (Update, Propagatie, DXpeditie, Overzicht, of de naam van de auteur), de titel en een korte tekst. Er klinkt een kort melodietje als hij verschijnt; feestdagberichten hebben warme kleuren en thema’s (Kerst, Nieuwjaar, Pasen, update, service) hebben een eigen uiterlijk.",
  "t.13mr7c3vmbl": "Open [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].",
  "t.13n9qlt82l4": "[[nav.sat]]: drie pagina’s, [[sw.pg.orbits]], [[sat.set.catMap]] en [[sw.pg.doppler]]. Elke wijziging wordt meteen opgeslagen. Je komt hier ook via het tandwiel op de pagina Satellieten en, voor SSTV, via het ⚙-wieltje op de SSTV-pagina.",
  "t.13qd88sl2gi": "[[digi.mi.anticlick]] (aan): haalt de horizontale lijnen van tastkliks van de waterval, zonder de signalen aan te raken; het geldt zolang de pagina luistert, ook voor de waterval van de andere pagina’s. Dit vinkje leeft in de engine, niet alleen op deze pagina.",
  "t.13tmcm11q2m": "Klik in het paneel [[panel.tx]] op de zesde rij (“[[tx.step.6]]”): de stip toont dat Aurora bij dat bericht begint. De tekst kun je ter plekke schrijven (bijvoorbeeld “CQ DX” of “CQ EU”); in Hound wordt de CQ niet gezonden.",
  "t.13v1mfei7sz": "Het tandwiel rechts van de eerste rij wisselt tussen “[[digi.bar.extended]]” en “[[digi.bar.compact]]”: met één rij toon je de andere door Ctrl en/of Shift ingedrukt te houden.",
  "t.13xm5v8a9fu": "[[aud.input]] (vak en lijst): de geluidskaart die het audiosignaal van de radio ontvangt. Bij radio’s met interne USB-audio is dat “Microphone (USB Audio CODEC)” of iets dergelijks; bij de andere de kaart van de interface die op de radio is aangesloten. Elke regel toont mono of stereo en “[[aud.inUse]]” als het de geopende is. “[[aud.defaultPlain]]” volgt de keuze van Windows; “[[aud.unset]]” verschijnt als je nog nooit een ingang hebt gekozen; een regel met “(not found)” is een apparaat dat je eerder koos en dat nu is losgekoppeld. Op Linux heten ingangen “alsa_input…” (PulseAudio of PipeWire).",
  "t.13ytjdun3qi": "De zes berichten Tx1-Tx6 (de naam van elk: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): de verlichte stip is het bericht dat Aurora zendt of in de volgende periode gaat zenden. Een klik op een rij kiest bij welk bericht de engine begint. De tekst kun je ter plekke schrijven (tot 37 tekens): Enter of het veld verlaten bevestigt, Esc annuleert, en als je het leegmaakt komt het standaardbericht terug.",
  "t.13yz22r6dsv": "Modus, submodus en frequentie",
  "t.13z0ywh2fvi": "[[radio.sharing]] · [[radio.control]]: rij die je alleen kunt lezen. “[[radio.on]]” betekent dat Aurora de band en de frequentie van de radio kan wijzigen vanaf de pagina Station; het gaat aan door de radio in het bovenste deel van deze pagina te verbinden. Hier valt niets te wijzigen.",
  "t.141rxbvqp1x": "[[wfs.spectrum]] · [[wfs.specPct]]: hoeveel van de hoogte de spectrumgrafiek onder de waterval inneemt, van 0 (verborgen) tot 100; standaard 30. De waterval verdwijnt nooit helemaal. [[wfs.specMode]]: “[[wfs.current]]” (standaard) toont het laatste spectrum; “[[wfs.cumulative]]” het gemiddelde van de hele periode, waardoor stabiele signalen opvallen en dat elke periode opnieuw begint.",
  "t.142aloo356f": "Aurora kan wachten tot de DX vrij is in plaats van over hem heen te zenden.",
  "t.142h4cihhyg": "Modus Q65",
  "t.142rvw1d54i": "De zes berichten, genummerd van 1 tot 6, met eronder het label van wat ze zijn ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], [[phone.kind.rr73]], [[phone.kind.73]], [[phone.kind.cq]]): met een tik kies je welk bericht in de volgende periode de lucht in gaat. Berichten die al zijn verzonden zijn gedimd; het huidige is gemarkeerd; een leeg bericht kun je niet aantikken.",
  "t.144pyc9l29m": "Een CQ beantwoorden",
  "t.147zpak6kbr": "CW ontvangen en zenden",
  "t.1489px2pfwo": "De diagnosemeldingen rechtsonder",
  "t.149c1jo47se": "Als de installatie niet start, verschijnt er een bericht met de reden en de link om het installatieprogramma met de hand te downloaden.",
  "t.14aspo1cyvr": "Volledig onderdeel: «Log gesloten: QSO’s komen later aan»; «QSO’s verloren terwijl het log gesloten is: waar je het aanzet»; «Een QSO ontbreekt in het externe log».",
  "t.14bqwznhyu3": "[[acc.preview]]: twee live vensters, “[[acc.previewPhone]]” (390×844) en “[[acc.previewTablet]]” (1180×820). Daarin zit het echte Aurora, met echte gegevens, zoals dat apparaat het zou zien; de bediening werkt echt (ook het zenden, als dat openstaat). Er is niets in te stellen. Wanneer: om te zien hoe het er op een telefoon uitziet zonder de telefoon te pakken.",
  "t.14bu1ac4aam": "De pagina [[nav.log]] (titel “[[exp.title]]”) toont alle QSO’s van het interne logboek van Aurora. Je gebruikt hem om ze te zoeken, te corrigeren, te verwijderen, er met de hand een toe te voegen en ze op te slaan in een ADIF- of Cabrillo-bestand. Rechtsboven: “＋ [[exp.add]]” en “[[exp.back]]” (terug naar het Station).",
  "t.14ex3w000de": "De gekozen geluidskaart of de audio-uitgang voor het zenden is verdwenen (radio uit, USB-kabel eruit): zet de radio aan, Aurora pakt hem zelf weer op.",
  "t.14fzs1durxi": "SSTV: Zenden bovenaan en geschiedenis in stroken",
  "t.14g5iqm4hu6": "Log4OM: de radio via Aurora",
  "t.14gexx04zz1": "DX-split vanuit de DX Cluster",
  "t.14ipskpq8yz": "De knop “Clear” staat hier niet meer: om de lijsten te legen gebruik je “[[list.clear]]” in de titelbalk van Band activity en van het RX-venster.",
  "t.14jojqljaom": "“De agent afsluiten”: sluit het pictogram tot de volgende Windows-start; het automatisch starten blijft staan. Om het echt te verwijderen zet je “[[agent.enabled]]” uit in [[nav.settings]] › [[sw.sec.access]] › [[agent.tab]].",
  "t.14o794wvwf7": "Als Aurora niet bereikbaar is, verschijnt “[[app.noCore]]” en de knop “[[app.retry]]”. Als de telefoon al een ander adres kende en dat antwoordt, stelt de pagina “[[app.moved]]” voor, met de link “Openen” gevolgd door het adres: let op, een ander adres dan aurora.local kan opnieuw om koppelen vragen.",
  "t.14p1pkgfa4c": "“+ [[int.p.multicast]]”: naam Multicast, adres 239.255.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.multicast]]” aan, “[[int.ttl]]” 1, “[[int.iface]]” 127.0.0.1. Hij ontvangt dezelfde WSJT-X-stream, maar naar een groep gestuurd: alle programma’s die zijn geabonneerd op groep 239.255.0.1 op poort 2237 ontvangen hem tegelijk (bijvoorbeeld GridTracker 2 en QLog), zonder om de poort te vechten. Elk programma moet op dezelfde groep en dezelfde poort staan. Voor een programma op een andere computer zet je het adres van deze pc in het thuisnetwerk bij de interface.",
  "t.14q6ldb4ltf": "Onderaan elke Instellingen-pagina (niet alleen Radio) staan vier knoppen en een statusregel. De eerste twee testen de radio zonder de Instellingen te verlaten.",
  "t.14qqrhoh122": "Er komt niets aan bij het programma: adres en poort moeten in beide programma’s overeenkomen; druk op “[[ens.test]]” en controleer of het programma luistert. Als er “port already in use” staat, houdt een ander programma de poort vast: sluit dat of verander de poort.",
  "t.14va2a74wja": "Druk op “[[newdx.off]]” onder de kaarten, of haal het vinkje weg bij “[[not2.popNew]]” (en “[[not2.popNewBand]]”) in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], vak “[[not2.grpAlerts]]”.",
  "t.14wsjmfo02y": "Veel items worden na een moment vanzelf opgeslagen, en ook als je de pagina verlaat (de voorkeuren van Aurora en pagina’s zoals [[tab.radio]] en [[sw.tab.rotator]]). De items van de engine (modi, services, log), de Automatiseringen en de SSTV-instellingen blijven “in behandeling”: onderaan zegt het venster hoeveel het er zijn en “[[sw.save]]” slaat ze op (het venster blijft open, “[[sw.close]]” sluit het). Als je sluit met wijzigingen in behandeling, vraagt Aurora of je ze wilt weggooien.",
  "t.14wu3ep0mo5": "Dit zijn de meldingen die enkele seconden blijven staan (bijv. “Antwoorden …”). Ze verschijnen direct bij de klik; mislukt het commando daarna, dan worden ze een fout.",
  "t.1509ogmh9gl": "Klik op het pictogram: er opent een venster met “Nieuwe versie van Aurora: X (in gebruik Y)”. De knop “[[upd.install]]” downloadt (indien nodig) en installeert: Aurora sluit en start zelf opnieuw. “[[upd.open]]” opent de notities en de download op de website. “[[upd.later]]” verbergt de melding tot de volgende versie.",
  "t.1532e3ayh8x": "Bij het overschakelen van RTTY naar FT8, of na een korte CAT-onderbreking, gaat de radio niet meer uit zichzelf in split. PSK, RTTY, CW en SSTV zenden in simplex.",
  "t.153yc7c0c79": "“[[ens.g.clublog]]” · “[[ens.k.ClublogSend]]” (standaard uit): stuurt elke QSO in realtime naar ClubLog, één voor één. “[[ens.k.ClublogEmail]]” is het e-mailadres van het account. “[[ens.k.ClublogPasswd]]”: gebruik liever een “Application Password” dat je in de ClubLog-instellingen aanmaakt dan het accountwachtwoord. “[[ens.k.ClublogCall]]”: leeg = jouw roepletters uit Persoonlijke gegevens; vul het alleen in voor een ander logboek (bijvoorbeeld een speciale roepletters). “[[ens.k.ClublogApiKey]]”: de sleutel die ClubLog op verzoek aan programmaschrijvers geeft via de ClubLog-ondersteuning; Aurora heeft er geen ingebouwd, dus je moet hem hier invullen. Hier kan “[[ens.test]]” niet testen zonder te versturen: het controleert alleen of de gegevens er zijn. Met verkeerde inloggegevens stopt de upload vanzelf (ClubLog blokkeert wie blijft proberen) en begint opnieuw zodra je ze corrigeert.",
  "t.156d0m7co0l": "Onbevestigde landen",
  "t.158x1rit5ou": "Het gelogde QSO heeft ook een eigen geluid: “[[snd.ev.qso_logged]]” (standaard de fanfare). Je kunt een ander geluid kiezen, de stem, een eigen WAV/MP3-bestand of geen geluid.",
  "t.1590q3vofta": "[[sat.map.pick]]: uitklaplijst met “[[sat.set.mapAuto]]” (fabriek: Aurora kiest zelf de beste beschikbare), “[[sat.map.builtin]]” (de meegeleverde kaart) en je afbeeldingen uit de map “maps”. Kies alleen een specifieke kaart als “[[sat.set.mapAuto]]” je niet bevalt.",
  "t.15af9isucn1": "De knop “[[sstv.tx.send]]” is grijs: je hebt de eigen engine van Aurora en de audio-uitgang naar de radio nodig ([[nav.settings]] › [[sw.sec.station]] › Audio).",
  "t.15aii2c343s": "[[bfl.title]] · [[bfl.tags]]: pillen voor de nieuwigheden die in [[panel.all]] getoond worden: [[bfl.all]] (geen filter, fabrieksinstelling), [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]]. Een regel wordt getoond als hij minstens een van de gekozen soorten heeft. Het is dezelfde keuze als de kleine knop “Filter” van het paneel en het geldt ook voor de automatiseringen: wijzig het als je alleen wilt zien wat je nodig hebt (bijvoorbeeld alleen nieuwe DXCC).",
  "t.15bj0b329qo": "De UTC-tijd met seconden, en rechts de naam en versie van Aurora. Als het programma niet antwoordt, wordt de versie vervangen door een tekst die dat zegt.",
  "t.15dk2wkrb4c": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[int.title]]”. Andere programma’s die van Aurora ontvangen, één per rij, tot 16. De “?” bij de titel legt alles uit en waarschuwt voor dubbelen. De lijst wordt alleen opgeslagen met “[[sw.save]]” als elke waarde geldig is; zolang er één als fout is gemarkeerd, wordt er niet opgeslagen.",
  "t.15ezj5mfb7": "Gaat niet in TX: dan is het CAT (poort, snelheid, PTT, CI-V/CAT-menu).",
  "t.15h4io4p7bg": "[[ap.theme]] · [[gen.language]]: open het menu met de vlag en kies de taal; de hele interface, inclusief de Gids, verandert meteen. Het is de eerste regel van de pagina. Wijzig het als Aurora is geopend in een taal die niet de jouwe is.",
  "t.15k80yb690r": "Alleen CW: “[[digi.cw.bandwidth]]” (50, 100, 150, 250, 500 of 1000 Hz, de laatste “breed” voor het overzicht; standaard 150) en “TX op ontvangen snelheid”: het onderdeel is grijs tot er een CW-signaal is om de snelheid van te meten. Volledige uitleg bij “CW ontvangen en zenden”.",
  "t.15kals6h8ln": "“Tx” (200-3000 Hz) en “Rx” (100-3000 Hz): de audiofrequenties. Typ en druk op Enter, of verlaat het veld, om ze toe te passen; de velden volgen ook de waterval. Het veld Tx wordt rood als de frequentie buiten 200-2700 Hz valt: veel radio’s verlagen daar het vermogen (zie “Tx-frequentie buiten 200-2700 Hz”).",
  "t.15kswseyy75": "De kaart Alles controleren",
  "t.15lsvtn93xb": "Aan het begin van de zending verschijnt ook een rode waarschuwing. Breng Tx terug binnen het bereik, of verschuif de frequentie van de radio.",
  "t.15lvekyffkj": "In Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[int.title]]” › “+ [[int.p.bblogger]]”. Laat 127.0.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.loggedAdif]]” aan.",
  "t.15s3r973b0y": "Geen geluid terwijl je zendt: “[[not2.muteTx]]” in [[sw.pg.alerts]] (standaard aan). Het volume van alle geluiden is de schuif “[[snd.volume]]” (standaard 50%) in het vak “[[snd.title]]”, zonder het Windows-volume aan te raken.",
  "t.15tagb0nofa": "De geluidskaart",
  "t.15tl8qu7h86": "Het menu [[digi.menu.view]]",
  "t.15u5eiluwbi": "“[[digi.rtty.title]]” · [[digi.rtty.profiles]]: vier profielen, de stippen Set 1-4. Een profiel bevat [[digi.rtty.reverse]], [[digi.mi.afc]], [[digi.mi.snap]], [[digi.mi.squelch]], [[digi.rtty.uos]], de squelchdrempel (verticale schuifregelaar), “[[digi.rtty.txHz]]” en “[[digi.rtty.rxHz]]”, “[[digi.rtty.receiver]]”, “[[digi.rtty.shift]]” (ook 22 en 30 Hz), “[[digi.rtty.baud]]” (ook 10) en “[[digi.rtty.charset]]” ([[digi.rtty.cs.ita2]], [[digi.rtty.cs.lower]], [[digi.rtty.cs.cyrillic]], [[digi.rtty.cs.swedish]]).",
  "t.15umjj0q7fs": "[[sw.sub.ft8]] · [[sw.pg.messages]]",
  "t.15vax6652gn": "“[[panel.all]]”: de berichten van de band. Eén tik op een rij beantwoordt dat station. Daaronder twee vakken die je met een tik op de titel opent en sluit: “[[panel.cluster]]” (de spots van de band; een tik stemt af; ontbreekt als de cluster uit is) en “[[phone.log]]” (de laatste 3 QSO’s).",
  "t.15vpdft8iko": "[[nav.contest]]: in beide groepen, om contests te doen in FT8, FT4, MSK144 en Q65 (zie “Contest: de balk en de tabbladen”).",
  "t.15w53tldfc8": "Sneltoetsen en gebaren",
  "t.15zcqc6mjsm": "Volledig onderdeel: «Een telefoon of tablet koppelen»; «De weergave op afstand»; «De telefoon wordt niet bijgewerkt».",
  "t.160zm79yi2j": "[[auto.b4]] · [[auto.filterCallers]] (vakje, standaard uit): ook als je zelf CQ roept, antwoordt Aurora niet op stations die door de filters van [[panel.all]] (continenten, landen, roepnamen) verborgen zijn of hieronder zijn uitgesloten. Uit geldt dit alleen met de automatisering aan in live mode.",
  "t.161vyx19yt9": "Pause (of het onderdeel [[digi.mi.tx]] van het menu [[digi.menu.options]], of de knop RX/TX linksonder): zend je niet, dan opent het het zenden en houdt het aan, en stuurt de tekst in het vak en wat je daarna schrijft; zend je wel, dan sluit het het zenden en ga je terug naar ontvangen zodra de al geschreven tekst klaar is. In RTTY wordt zonder tekst het ruststreepsignaal uitgezonden.",
  "t.164hg10igd5": "Dubbelklikken antwoordt alleen als “[[gen.dblReply]]” aan staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Als [[ctl.enable_tx]] niet aangaat, verschijnt er een fout.",
  "t.16c7ljyklpf": "LogHX: QSO’s en “Active calls” via het netwerk (UDP)",
  "t.16ggvygxen4": "Doorgestreepte rij: station al gewerkt.",
  "t.16iqwqoa3vz": "De vakken [[ens.g.log]] en [[ens.g.alltxt]] verschijnen alleen met de eigen engine van Aurora (de standaard). De knop om het huidige QSO met de hand te loggen is iets anders: die zet je aan in [[sw.sub.ft8]] › [[sw.pg.messages]] met “[[pref.cmdLogQso]]”.",
  "t.16j122ss1dx": "[[not2.grpAlerts]] · geluidsmenu van de gemarkeerde melding (naast de positie, naam “[[snd.ev.new_dx_popup]]”) en menu “[[snd.ev.qso_logged]]”: het geluid van de kaart voor nieuw DXCC en dat van een QSO dat in het logboek komt. Ze hebben een fabrieksgeluid (een alarm en een fanfare). Kies “[[snd.none]]” om het te verwijderen, ▶ om te luisteren. Het geluid van de kaart hoor je alleen met “[[alert.button]]” aan.",
  "t.16lit8smebg": "Geldt voor “[[int.adif]]” en “[[int.n1mm]]”, niet voor de WSJT-X-stroom (GridTracker, JTAlert), die tijdens het werken nodig is.",
  "t.16m2v3c2kc": "[[sw.sub.vhf]] · [[sw.pg.contest]]",
  "t.16n8howvnoh": "Ik zie signalen maar niets wordt gedecodeerd",
  "t.16nton3erot": "Kaartbalk: “[[sat.tle.refresh]]” (downloadt de baangegevens; ernaast lees je hoe lang geleden je ze hebt gedownload; zijn er geen, dan “[[sat.tle.none]]”) en de knop “[[sat.set.title]]”, die de satellietinstellingen opent ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: server met baangegevens, automatische update, kaart, Doppler en rotor). Het keuzemenu “[[sat.map.pick]]” kiest de wereldkaart; met “[[sat.map.add]]” voeg je er een toe (equirectangulaire afbeelding van 360° × 180°).",
  "t.16q5mj0q13s": "“[[sat.data.title]]”: positie (lengtegraad, breedtegraad, hoogte), elevatie, azimut, afstand, snelheid en radiale snelheid, “[[sat.d.approaching]]” of “[[sat.d.receding]]”, “[[sat.d.visible]]” of “[[sat.d.hidden]]”; daaronder “[[sat.orbit.title]]” (inclinatie, excentriciteit, periode, omlopen per dag, datum van de gegevens). “[[sat.info.title]]”: transponder, uplink en downlink, of hij inverteert; de frequenties moet je op AMSAT controleren.",
  "t.16rrzf0bot0": "Test: maak een QSO met Aurora (of voeg er met de hand een toe vanaf de Logboek-pagina): het moet in het LogHX-logboek verschijnen.",
  "t.16spnlgcdkg": "Je maakt het beeld klaar zoals in een klein tekenprogramma: een achtergrondfoto en daarbovenop teksten en vormen (de “lagen”), en dan zend je. De voorvertoning in het midden heeft dezelfde resolutie die het andere station krijgt.",
  "t.16srk3yd7vb": "Willekeurige tekens op ruis: zet [[digi.mi.squelch]] aan en verhoog de drempel van de modus. Zwakke signalen die niet verschijnen: verlaag hem of zet de squelch uit.",
  "t.16t8sh4mve": "Voor de volgende keren: zet “[[int.resend]]” aan in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]: QSO’s die je maakt terwijl het log gesloten is, worden vanzelf verstuurd als je het weer opent. Voor de al verloren QSO’s: [[nav.log]], filter op datum, sla op als ADIF en importeer het bestand in het programma.",
  "t.16tzi8uytsr": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[cop.title]]. Het zijn dezelfde opties als het DX Cluster-tandwiel op de pagina PSK · RTTY · CW: hoe een spot wordt gekozen, hoe lang hij blijft staan en welke kolommen worden getoond. Elke wijziging werkt meteen en blijft op dit apparaat.",
  "t.16v1x8lxse0": "Een tilde voor de waarde (~S3) betekent een schatting op basis van de audio: de radio stuurt de S-meter niet door (bijv. met OmniRig).",
  "t.16vwyz4tik3": "Een gewijzigde macro heeft geen effect: controleer “[[digi.edit.scope]]” (een macro “Alleen modus” wint van de basismacro) en het vinkje “[[digi.mi.macrosMerge]]” in het menu [[digi.menu.file]].",
  "t.16xtx95uz1i": "Log: een opgeslagen QSO corrigeren en verwijderen (#47)",
  "t.16ycxayoyfr": "De tekst is onleesbaar met de gekozen kleur: druk in “[[ap.color]]” op “[[ap.colorTheme]]”, of zet “[[ap.contrast]]” aan.",
  "t.170wz7d5f4l": "Na een crash (met “[[rep.ask]]” aan): bij de herstart verschijnt een venster “[[rep.crashTitle]]” met “[[rep.crashSend]]” (verstuurt het rapport en toont dan een code die je kunt doorgeven aan wie je helpt, en “[[rep.close]]”), “[[rep.show]]” (toont de exacte tekst) en “[[rep.no]]” (verstuurt niets en vraagt niet opnieuw naar die crash). “[[rep.crashSend]]” is grijs als deze versie geen adres van de dienst heeft ingesteld.",
  "t.1712meraz6x": "De waterval toont de audio tussen 0 en 5 kHz (0-3,5 kHz als je [[digi.mi.wideWaterfall]] uitzet); hoe lichter de kleur, hoe sterker het signaal. Je gebruikt hem om te kiezen naar welk signaal je luistert.",
  "t.171zsnk6sl9": "“[[digi.band.history]]”: alle tekst van de laatste 60 seconden van dat signaal, bijgewerkt zolang het venster open is. “[[digi.band.tune]]” verplaatst de ontvangst naar het signaal, “[[digi.band.toQso]]” zet de roepnaam in de huidige QSO (en zoekt naam, QTH en land op), “[[digi.band.close]]” sluit (ook met Esc). Als het signaal al 45 seconden weg is, staat dat in het venster.",
  "t.173up6aw9jd": "Als expeditie: vink in [[nav.fox]] “UltraFOX” aan. Elke even periode draagt één signaal van 750 tot 2260 Hz alle stations in de wachtrij (RR73 en rapporten), of de CQ.",
  "t.176jlgscc71": "Tx en Rx: de audiofrequenties in Hz. Typ en druk op Enter; ▲ kopieert Rx naar Tx, ▼ Tx naar Rx.",
  "t.178wpoe9jh1": "Tussen twee naburige vensters zit een scheiding (paarse balk): sleep die om het ene smaller en het andere breder te maken.",
  "t.17cv1xuhd8s": "De map waar de beelden worden bewaard, kies je bij “[[sstv.set.folder]]” in de SSTV-instellingen (hier kun je hem niet wijzigen). Als je de ontvangen beelden niet wilt bewaren, zet je “[[sstv.set.autoSave]]” uit.",
  "t.17d686pums": "[[sstv.set.grpClock]] · “[[sstv.cal.button]]”: kopieert de correctie die bij het laatste goed ontvangen beeld is gemeten (compleet, met goede sync) naar het veld erboven; druk dan op “[[sw.save]]”. Onder de knop staat een regel met de gevonden meting, of dat er nog geen geschikt beeld is (en de knop blijft uit). Gebruik hem na het ontvangen van een beeld uit een betrouwbare bron, zoals een referentiezending of een station met een nauwkeurige klok.",
  "t.17e66ly4206": "“[[bands.title]]” toont de propagatie overdag en ’s nachts per bandgroep (de band waarop je zit is gemarkeerd) en de drie verst gelegen stations die jou hebben gehoord. Het vereist de online diensten: schakel in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] propagatie en PSK Reporter in; ontvangstrapporten komen in realtime binnen en de pagina wordt elke 10 seconden vernieuwd.",
  "t.17hw81lk6bj": "[[lay.notes]]: uitklapbaar vak onderaan de pagina met de algemene uitleg: hoe de verbinding werkt, het delen, en wat je doet als de COM-poort al door een ander programma wordt gebruikt.",
  "t.17idfzrpoa6": "Verbind voor Doppler de radio via Hamlib ([[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]), kies de “[[sat.ctl.transponder]]” en schakel “[[sat.ctl.doppler]]” in: boven de minimale elevatie zet Aurora de ontvangst op de hoofd-VFO en het zenden op de split-VFO, elke seconde gecorrigeerd. Verstel bij een lineaire transponder “[[sat.ctl.downlink]]”: de uplink volgt vanzelf, ook als de transponder inverterend is zoals RS-44.",
  "t.17irb1c52xs": "Het werkt niet tijdens het zenden, alleen vanaf de pc waarop Aurora draait en niet met OmniRig. Waarden die de radio weigert, worden overgeslagen. Houd de muis boven een knop om te zien wat de klik doet.",
  "t.17n1hnwnle0": "“[[int.wsjtx]]”: de binaire stream van het WSJT-X-protocol (Heartbeat, Status, Decode, Clear, QSO Logged, Close); commando’s komen terug op dezelfde poort, als je ze hebt toegestaan in “[[ens.k.AcceptUDPRequests]]”. Zet het aan voor GridTracker, JTAlert, QLog en dergelijke.",
  "t.17ngl9tvu5d": "Om te zenden schakel je naar “[[sstv.view.tx]]”, kies je de “[[sstv.tx.mode]]” (resolutie en duur staan naast de naam) en laad je een foto met “[[sstv.bg.load]]”, door hem erop te slepen of te plakken met Ctrl+V; kader hem in door te slepen en met het wieltje.",
  "t.17no68o6io0": "[[seq2.switches]] · [[seq2.prioCq]] (standaard uit): laat Aurora bij de keuze wie het roept ook kijken tussen de CQ’s van andere stations, en geeft voorrang aan wie CQ roept boven wie jou roept. Werkt met [[sw.save]].",
  "t.17s3rxgxe8i": "De dubbelklik van GridTracker doet niets in Aurora: zet “[[ens.k.AcceptUDPRequests]]” aan en kies bij “[[ens.k.AcceptUDPReplyMessages]]” welke berichten je accepteert.",
  "t.17sasthmcl4": "Onder de modusselectie staat een balk van segmenten: elk segment is een schakelaar (aan = groen) of een knop. Zweef boven een item om de uitleg te lezen. Als de bediening van Aurora niet bereikbaar is, zijn de segmenten grijs.",
  "t.17slp3qn0hx": "Ernaast de stations in de wachtrij, hooguit 4, één per rij met de stip van de plaats: een klik op een roepnaam verlaat het huidige QSO meteen en antwoordt dat station (zie “Naar een station in de wachtrij springen”). De pijl “Volgende in de wachtrij” roept de eerste.",
  "t.17tj84bx90h": "De pil “[[bfl.all]]” haalt het filter weg (je ziet alles). De andere zijn de berichttypen, met dezelfde namen als de gekleurde labels: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] en [[kind.new_state_band]] (de Amerikaanse staten). Meerdere pillen aan = een bericht komt door als het minstens één van die nieuwtjes heeft (logica “of”).",
  "t.17uydns0tgf": "[[nav.settings]] › [[sw.fam.modes]] bevat de instellingen van elke modus. Hier worden drie takken uitgelegd: [[sw.sub.digi]], [[sw.sec.sstv]] en [[nav.sat]]; FT8, JT, VHF, WSPR en Contest worden elders uitgelegd. Kun je een onderdeel niet vinden, gebruik dan de zoekfunctie bovenaan het Instellingenvenster.",
  "t.17v8dvi8x4m": "In [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]: model, poort en snelheid gelijk aan het CAT-menu van de radio, dan “[[cat.connect]]”. Bij Icom-radio’s voer je het CI-V-adres decimaal in.",
  "t.187ik44dwjt": "[[ens.g.log]] · [[ens.k.dBtoComments]] en [[ens.k.distanceToComments]] (standaard uit): voegen de dB-rapporten en de afstand toe aan het opmerkingenveld van elk gelogd QSO. Vink ze aan als je die gegevens in het log wilt zonder ze te typen.",
  "t.18amb73fb2z": "“[[cmd.report]]” (van -50 tot +49 dB): het rapport dat je stuurt (Tx2 en Tx3). Aurora stelt het in op basis van het signaal van het station; met de hand geschreven geldt het meteen en blijft het staan tot er een ander rapport van de engine komt.",
  "t.18anw1chi37": "Het uploaden staat standaard uit, zoals “Upload spots” in WSJT-X: uit wordt er niets verzonden. De spots worden openbaar op wsprnet.org; wat er verzonden wordt, staat in de privacyverklaring.",
  "t.18b30qa93dl": "[[acc.pair]] · [[acc.alt.title]]: als de pc meer adressen heeft, verschijnt hieronder een QR voor elk van de andere, met het type netwerk ([[acc.kind.wifi]], [[acc.kind.cable]], [[acc.kind.mdns]], [[acc.kind.virtual]], [[acc.kind.other]]). Wanneer: als de eerste QR niet op de telefoon opent, probeer dan de volgende.",
  "t.18cjj6filbk": "De pagina Nieuws",
  "t.18d9k1ofp6d": "Bovenaan staat de filterbalk, die alleen verandert wat je ziet (de spots blijven in het geheugen): “[[cluster.filter.band]]” (“[[cluster.filter.bandNow]]” = de band waarop de radio staat, of een of meer banden), “[[cluster.filter.mode]]”, “[[cluster.filter.spotter]]” (“[[cluster.filter.spotterMine]]” of de gekozen continenten), de knop “[[cluster.filter.newOnly]]” (alleen spots die nieuw zijn voor je zoeklijst: land, locatorveld, band), het veld “[[cluster.filter.search]]”.",
  "t.18dbxa3vv3j": "Als je op een pagina bent die geen moduspagina is (bijvoorbeeld [[nav.log]] of [[nav.dxmap]]), is er geen pil verlicht; een klik op “FT8” of “VHF” brengt je terug naar het Station.",
  "t.18g5pbr9ayz": "“[[sstv.tpl.title]]”: “[[sstv.tpl.cq]]”, “[[sstv.tpl.reply]]” en “[[sstv.tpl.qsl]]” zetten een kant-en-klaar sjabloon in de plaats van de huidige lagen. “[[sstv.tpl.save]]” vraagt om een naam en slaat het beeld op zoals het is (met de foto, als die niet te groot is); in “[[sstv.tpl.mine]]” opent een klik op de naam hem opnieuw en de knop “Wissen” verwijdert hem. De sjablonen blijven op deze computer.",
  "t.18ly7v9rjcn": "[[cat.catmode]]: de modus die Aurora bij elke frequentiewijziging in de radio terugschrijft, omdat sommige radio’s de modus oproepen die voor de band is opgeslagen. “[[cat.catmode.none]]” (fabrieksinstelling) raakt de modus op de radio niet aan; kies voor FT8 met de audio over de USB van de radio “[[cat.catmode.data]]” (DATA-USB); “[[cat.catmode.usb]]” voor gewone USB.",
  "t.18np4trrlt0": "[[fil.decode]] · [[dec.jt65Ap]]: selectievakje, standaard uit. In JT65 decodeert het ook a priori met je roepnaam, die van de DX en de fase van de QSO (alleen met [[ctl.enable_tx]] aan). Zet het aan om zwakke signalen te horen van het station dat je roept. Naast de mode staat ook een knop “AP”.",
  "t.18o0yxassw7": "[[sstv.log.clear]]: maakt alle velden leeg.",
  "t.18o73rsn9tr": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]].",
  "t.18polm8cyd0": "Een station beantwoorden met een dubbelklik.",
  "t.18q4367ju8s": "[[digi.mi.snap]]: een klik op de waterval verplaatst de afstemming naar de piek van het signaal (in RTTY naar het paar van de twee tonen). Standaard aan.",
  "t.18qy5e38129": "PSK31, PSK63, RTTY, CW: de modus die in gebruik is, heeft het vinkje. Een klik wijzigt en bewaart hem. RTTY kiezen opent “[[digi.rtty.title]]” niet: dat venster opent met een klik op de modusnaam in de statusbalk.",
  "t.18rh5v425l9": "De filters verbergen of markeren rijen in de lijsten zonder het decoderen te raken. Ze worden vanzelf opgeslagen.",
  "t.18u8miqvfdx": "[[rd.title]] · [[rd.hide]]: haalt het display uit de kop (de gekozen stijl wordt onthouden). Zet het aan als je meer ruimte nodig hebt of geen CAT gebruikt. Zonder CAT (besturingssysteem “[[cat.backend.none]]”) verschijnt het display sowieso niet.",
  "t.18w155fg99t": "[[ap.preview]]: een voorbeeldvak met normale tekst, secundaire tekst, een gegevensregel en de vier statuskleuren (“[[ap.stOk]]”, “[[ap.stWarn]]”, “[[ap.stDanger]]”, “[[ap.stAccent]]”): het toont meteen het effect van wat je hebt veranderd. De knop “[[ap.reset]]” zet contrast, lettertypen, loggrootte, tekstkleur en tekstgrootte (100%) terug op de standaardwaarden en zet het donkere thema terug; de taal verandert niet.",
  "t.18wjuebginy": "Tijdens de contest worden decodes op waarde gesorteerd: punten en nieuwe multipliers bovenaan (★ = aanbevolen), dupes doorgestreept, in geel die niet in de contest zitten. Dubbelklik om te roepen, of “[[contest.cq]]”.",
  "t.18xq28mphhu": "Als je de berichten van je QSO niet in Bandactiviteit wilt zien (ze staan al hier), zet dan “[[rxw.exclusive]]” aan in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; standaard verschijnen ze in beide.",
  "t.18y41lwcg3m": "Ctrl+V: plakt een foto als achtergrond (als er een beeld op het klembord staat en je niet in een vak typt).",
  "t.18yoac63mgk": "Drie mechanismen, alle standaard aan en alle uit te zetten in [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] › [[rep.title]]: het rapport na een crash (“[[rep.ask]]”), automatische rapporten (“[[rep.auto]]”) en dagelijkse statistieken (“[[rep.active]]”). Roepletters, locators, berichten, IP-adressen, e-mailadressen, wachtwoorden en je gebruikersnaam worden vóór het versturen verwijderd; minidumps worden nooit verstuurd.",
  "t.18yr6ppa32r": "[[sw.pg.personal]]",
  "t.191oofqdltx": "Radio’s die werken: SDR’s met TCI die de I/Q-stream sturen, bijv. SunSDR2 (Pro, DX, QS) en ColibriNANO met ExpertSDR2/3, ANAN en Hermes-Lite 2 met Thetis. Of een opgenomen I/Q-WAV-bestand. Radio’s met alleen audio-uitgang volstaan niet.",
  "t.192m67s99ie": "Filteren wie je CQ beantwoordt",
  "t.192s3hzez1z": "De PTT testen: “[[sw.testPtt]]” onderaan laat de radio één seconde zenden (zie het onderdeel over de knoppen onderaan): gebruik een dummy load of een geschikte antenne.",
  "t.194vkzax332": "[[digi.mi.controlBar]] (aan) toont of verbergt de macrobalk; [[digi.bar.extended]] (aan) toont de 4 rijen samen: als het uit staat, zie je één rij en wisselt Ctrl of Shift ingedrukt houden van rij (het is ook het tandwiel naast de toetsen).",
  "t.194x3bykp1v": "Cijfers over de ontvangst: hoeveel stations je de laatste uren hebben ontvangen, de verste, het beste rapport en de balken “[[prop.stat.byBand]]” met de kleur van elke band.",
  "t.196dmhw6fxh": "De radio gaat naar TX maar er komt geen vermogen uit: de audio naar de radio ontbreekt.",
  "t.196pyntgc9a": "[[sw.sub.jt]]",
  "t.19765yrr7rw": "[[bar.profile]]: de naam van het radioprofiel in gebruik, als je meer dan één profiel hebt ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).",
  "t.19aolicvvwz": "De kaart voor nieuw DXCC verschijnt niet: controleer of “[[not2.popNew]]” (en voor landen die al op andere banden zijn gewerkt “[[not2.popNewBand]]”) aan staat, of de kaart niet al met de × is gesloten (hij komt pas na een herstart terug) en of het station zich niet al heeft getoond (één keer per station). “[[not2.dxcc]]” moet ook aan staan in de Kleurentabel, anders herkent Aurora het nieuwe land niet.",
  "t.19bq2gs77um": "[[digi.scan.title]] · [[digi.scan.once]] (standaard uit): de scan stopt bij het eerste gevonden station in plaats van door te gaan. Zet het aan als je alleen een signaal wilt vinden en het dan wilt volgen.",
  "t.19c0bubk8uq": "Roepletters, locator, regio en type 2 zijn engine-items: het aantal “wijzigingen om toe te passen” onderaan loopt op en ze gaan in met “[[sw.save]]”. Naam, achternaam, QTH en e-mail worden meteen opgeslagen.",
  "t.19dk9sadpvz": "“[[logio.import]]”: kies een ADIF-bestand (.adi, .adif of .txt) met je geschiedenis, bijvoorbeeld het bestand dat je uit je oude logprogramma hebt geëxporteerd. QSO’s die er al staan, worden niet dubbel toegevoegd. Aan het einde zegt een melding hoeveel er zijn geïmporteerd, hoeveel er al waren, hoeveel er zijn weggegooid en hoeveel records er zijn gelezen; de DXCC-kaart en de statistieken worden opnieuw berekend. De knop blijft uit tijdens het importeren (“Importing…”). Wanneer gebruik je het: de eerste keer, zodat de labels “eerder gewerkt” en “nieuw DXCC” kloppen.",
  "t.19egtaxfypf": "[[gen.screen]] · [[gen.dblReply]]: selectievakje, standaard aan. Een dubbelklik op een bericht stelt dat station in als DX en op het juiste moment roept Aurora het zelf op (zenden moet open staan). Uit selecteert een dubbelklik alleen.",
  "t.19f1h14zcp3": "[[sat.map.pick]] · een kaart toevoegen: de regel onder de uitklaplijst (“[[sat.map.addHint]]”) geeft het formaat, een equirectangulaire afbeelding van 360° × 180°. Kopieer het bestand naar de map “maps” van de gegevens van Aurora en open de pagina opnieuw: hij verschijnt in de uitklaplijst. Er is hier geen knop om hem toe te voegen.",
  "t.19h3d8rm5vz": "[[nav.propagation]]",
  "t.19hi4hovua8": "[[lay.status]] · statusregel: “[[upd.uptodate]]” in het groen als je de laatste versie hebt; als er een nieuwe is, zegt hij welke, met de link “[[upd.open]]” (opent de releasepagina met notities en downloads in de browser). Als de controle mislukt (geen internet, site onbereikbaar), verschijnt de reden in het rood.",
  "t.19i3e1rhlnq": "[[sstv.log.save]]: schrijft de QSO in het logboek van Aurora met SSTV als modus, de band en de frequentie van de radio. Zonder roepnaam verschijnt “[[sstv.log.needCall]]”; als het lukt, wordt het paneel leeg.",
  "t.19jhgw8gsk9": "[[gen2.wsjtx3]] · [[gen2.fullDuplex]] (standaard uit): voor satellieten en full-duplexradio's. Als het aan staat, wordt ook de periode waarin je zendt gedecodeerd (je ziet je eigen terugkerende signaal); die berichten worden getoond maar laten de reeks niet antwoorden. Uit wordt de zendperiode niet gedecodeerd.",
  "t.19kz0hx34ex": "Typ het model in het zoekveld (bijv. FT-2000) en klik erop in de lijst die verschijnt.",
  "t.19l3y7afl38": "De pagina [[nav.textModes]] ontvangt en verzendt tekst in PSK31, PSK63, RTTY en CW (en leidt naar de SSTV-pagina) met dezelfde geluidskaart en dezelfde PTT als FT8, zonder FT8 te storen. De modus kies je in het menu [[digi.menu.mode]] van de pagina (zie “De pagina [[nav.textModes]]: hoe hij is opgebouwd”).",
  "t.19l6kk3p03w": "Robuuster: nette bestanden, CAT start opnieuw, minder vastlopers",
  "t.19lcmh5iwrf": "[[wfs.preview.title]]: de knop “[[wfs.preview.show]]” (daarna “[[wfs.preview.hide]]”) opent de echte waterval en het echte spectrum, zoals op de pagina Station, zodat je elke optie meteen ziet. Standaard is het dicht en Aurora onthoudt de laatste keuze. Het voorbeeld schakelt zichzelf uit als je het sluit, van pagina wisselt of het venster minimaliseert, en gebruikt dan niets. Als er geen gegevens binnenkomen, verschijnt “[[wfs.preview.noData]]”.",
  "t.19m6srg251k": "Bijwerken in één keer",
  "t.19nfxnidby7": "[[not2.grpWorked]] · [[not2.unconfirmed]] en [[not2.unconfirmedGrid]]: een land (of grid) dat is gewerkt maar zonder bevestiging in het logboek (LoTW of QSL) blijft “nieuw” in de kleuren, in het filter van Bandactiviteit en in Automatisering. Engine-items, standaard uit; ze zijn alleen van belang als het logboek de bevestigingen bevat. [[not2.unconfPreview]]: twee voorbeeldrijen laten het verschil zien (het echte nieuwtje in effen kleur, het alleen-onbevestigde lichter en gestreept).",
  "t.19ng6vpv8x5": "Het binnenkomende beeld wordt regel voor regel op het grote scherm getekend, in de echte resolutie van de modus. Ernaast staan de signaalgegevens en de bediening.",
  "t.19phv7jw6sm": "Online logboekdiensten en roepnaamopzoeking",
  "t.19rarlma5wn": "Tijdens het zenden toont een balk de voortgang (modus, verstreken en totale tijd) en op de voorvertoning is het deel dat al is verzonden donkerder, met een lijn tot waar je bent. Als het klaar is (ook bij stoppen of een fout), gaat de pagina vanzelf terug naar het tabblad “[[sstv.view.rx]]”.",
  "t.19s9elbzpis": "De waterval is zo breed als het radiofilter dat via CAT wordt gelezen (tot 5000 Hz; 0-3000 Hz als de radio het niet meldt). Een groene lijn markeert het begin van elke periode.",
  "t.19ue6fh81sp": "[[sw.pg.reporting]]",
  "t.19yzmz30m2s": "De modus en de frequentie veranderen niet terwijl je zendt, maar de knop verandert niet van kleur: de klik wordt gewoon genegeerd.",
  "t.1a0f724hevk": "[[gen.screen]] · [[gen2.showTx]]: selectievakje, standaard aan. Je verzonden berichten verschijnen ook in de lijst met ontvangen berichten, in het venster [[rxw.title]]. Zet het uit als je alleen wilt zien wat je ontvangt (het is het tegenovergestelde van [[bfl.hideOwnTx]]).",
  "t.1a14040cctv": "Kies welke soorten getoond worden (fouten worden altijd getoond) en hoeveel seconden ze blijven.",
  "t.1a5f0mhdfxl": "Ernaast verschijnt “Hound” (of “Super Hound”) als de modus Hound aan staat: groen als de Fox een OTP-code heeft gestuurd en de dienst die heeft bevestigd, rood als hij nog niet is geverifieerd. Daaronder staat een regel “Fox … verified” of “NOT valid”.",
  "t.1a7du021j2o": "[[not2.grpDisplay]] · [[not2.hlDxCall]] (standaard aan) en [[not2.hlDxGrid]] (uit): markeren in de berichttekst de roepletters en de locator van het DX-station dat je roept, waar ze ook voorkomen. Zet ze uit als de lijsten te druk lijken.",
  "t.1a87ykkoqdy": "Met de pijlen ◀ ▶ aan de zijkanten van de strook scrolt hij; je scrolt ook met het muiswiel of met de pijltjestoetsen als de strook de focus heeft. Een pijl is grijs aan de uiteinden.",
  "t.1a8gpdkrntn": "Modi JT65 en JT9",
  "t.1a8r1jrba84": "QMAP · [[sdr.openQmap]]: opent de pagina [[nav.qmap]] (in het hoofdvenster als de Instellingen in een apart venster staan), waar de I/Q-bron, de periode en de submodi worden gekozen. Volledige instructies in het Guide-onderdeel over QMAP.",
  "t.1a8zw8iw8hz": "Het pictogram is er niet: de agent staat uit. Zet “[[agent.enabled]]” aan in [[nav.settings]] › [[sw.sec.access]] › [[agent.tab]] en open Aurora opnieuw, of start Windows opnieuw op.",
  "t.1a9f0rbdynx": "Open [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]].",
  "t.1aa6kvswdnx": "Eronder of ernaast (onderaan op telefoons en smalle vensters) staan de geschiedenissen “[[sstv.hist.received]]” en “[[sstv.hist.sent]]”.",
  "t.1aalgaymh7": "Ctrl+klik op de waterval voegt een notch toe die met meer dan 60 dB onderdrukt: hij verplaatst en verbreedt met de muis, rechtsklik verwijdert hem en «Notches wissen» wist ze allemaal. De BPF-schakelaar zet een smal bandfilter aan en de AFC loopt niet meer weg naar stations in de buurt. De notches worden gewist als je van frequentie verandert; in split verplaats je de ontvangst met Shift+klik.",
  "t.1aap0hktddi": "Meer over CW staat bij het onderwerp “CW ontvangen en zenden”.",
  "t.1ad0czydufh": "Een zeldzame DXpeditie krijgt honderden oproepen. Om er veel te werken gebruikt de expeditie (de “Fox”) een speciale FT8-modus en volgen de stations die haar roepen (de “Hounds”) nauwkeurige regels.",
  "t.1adzdsxv8w1": "“[[int.title]]”: de extra bestemmingen, één per programma; de velden en knoppen worden uitgelegd bij de onderwerpen “Integrations: the fields of a destination” en “Integrations: what each program receives”.",
  "t.1afzarrwb5f": "“[[lp.log]]” (of de Enter-toets) logt de QSO met je correcties; “[[lp.discard]]” gooit hem weg zonder op te slaan. Esc sluit het venster niet (het blijft staan tot STOP TX).",
  "t.1ahmt9csj8d": "Automatisch CQ: de toets met <AUTOCQ> (standaard F1) zet het aan; Aurora herhaalt de tekst van de macro “AutoCqText” (ontbreekt die, die van F2) met een pauze van 8 seconden na elke oproep, tot je het uitzet; het start niet als het zenden niet klaar is of als je al zendt. Is de macro leeg, dan verschijnt “[[digi.run.autoCqNoMacro]]”.",
  "t.1ahv1wz6y6l": "Klik in de lijst op een satelliet om hem te volgen; het vinkje toont hem op de kaart met zijn radiovoetafdruk. De tabel “[[sat.pass.title]]” geeft begin, maximale elevatie, einde en azimut van de volgende overkomsten.",
  "t.1akvfqmvh5y": "Aurora decodeert met alle processoren op één na. Aanbevolen: 4 kernen en 8 GB geheugen. Met 2 kernen of 4 GB werkt het, maar bij veel signalen kan het decoderen te laat klaar zijn.",
  "t.1aohw3tch91": "Als het koppelen is ingetrokken, doe “[[acc.pair]]” opnieuw vanaf de pc.",
  "t.1aon0lpu0tq": "Elk spoor is een station. De groene balk is jouw ontvangstfrequentie (Rx), de rode jouw zendfrequentie (Tx): ze zijn zo breed als een signaal van de modus (43,75 Hz in FT8).",
  "t.1aq98netqx4": "In PSK31 en PSK63 leest het paneel “[[digi.band.title]]” boven de waterval alle signalen van de gekozen modus tegelijk, elk met een eigen ontvanger (zoals een browser): een signaal komt in de lijst zodra de ontvanger het als PSK herkent, met frequentie, S/R, roepnaam met vlag en laatste tekst (onzekere tekens in grijs). Stations die CQ roepen hebben een gemarkeerde regel en worden bovenaan geteld. Klik om er een te beluisteren, dubbelklik voor de laatste 60 seconden; “[[digi.band.miPsk]]” in het menu Opties zet het uit.",
  "t.1ar01uxubmk": "“[[onl.grpDxped]]” · “[[onl.dxped]]” (standaard aan): verdeelt het paneel “[[panel.cq]]”: rechts de DXpedities die in de lucht zijn (gemarkeerd als je ze nu hoort), de komende en de geschiedenis; de kalender wordt elke 6 uur van ng3k.com gedownload en de site ziet alleen je IP-adres. Hiermee worden ook de DXpedities in de DX Cluster gekleurd. “[[onl.dxpedDays]]” (standaard 15, 0 tot 90; blijft op dit apparaat): hoeveel dagen beëindigde DXpedities nog onderaan de lijst worden getoond. “[[ens.test]]” downloadt de kalender één keer en controleert of hij te lezen is.",
  "t.1ar7v190iai": "[[lay.options]] · [[fil.worked]] en [[fil.workedAll]]: twee selectievakjes, standaard uit. Het eerste verbergt de CQ's van stations die je al op deze band hebt gewerkt; het tweede werkt alleen samen met het eerste en haalt elk bericht van hen weg, niet alleen de CQ. Zet ze aan om niet meer te zien wie je al hebt gewerkt.",
  "t.1arakv1ra5": "Onder de bovenbalk, van boven naar beneden. Op de tablet in landschapsstand staat de bandactiviteit in de linkerkolom en de rest rechts.",
  "t.1arskzhscvp": "[[sw.digi.perMode]] · RTTY, schuifregelaar voor de squelchdrempel (S/R van 0 tot 40 dB, fabriek 0): bij RTTY kijkt de squelch al hoe zeker de laatste tekens zijn en blijft hij stil op ruis, zelfs bij heel lage S/R; deze drempel op de signaal-ruisverhouding telt alleen boven 0 dB. Hij telt alleen met “[[digi.mi.squelch]]” aan.",
  "t.1atdnpnpc37": "[[sw.contest.title]] · [[contest.set.start]] en [[contest.set.end]]: UTC-datum en -tijd met de hand. Ze dienen voor contests zonder vaste kalender (Custom, EU VHF, RSGB) of om de data uit de regels te corrigeren.",
  "t.1au648yljtx": "Niets gelogd: de verbinding in Log4OM moet actief zijn en op dezelfde poort als Aurora; druk na een wijziging op “Save and apply”.",
  "t.1avz0tk1i5r": "Het vak “[[toast.grp]]” staat onderaan de pagina [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]]: dit zijn de berichten die een paar seconden verschijnen na een opdracht (“Handeling uitgevoerd”, een fout…). Er worden er hooguit vier tegelijk getoond; een klik op een bericht sluit het meteen. Alles geldt meteen.",
  "t.1axb69qzdxy": "De pagina [[nav.qmap]] (titel “[[qmap.title]]”) toont alle Q65-signalen in een stuk van de band waarnaar een SDR-ontvanger luistert. Zie ook “QMAP: alle Q65 in een stuk van de band”. Zonder SDR zegt hij “[[qmap.needSdr]]”.",
  "t.1axtagd9aw6": "aurora.local antwoordt niet: gebruik het IP dat getoond wordt in [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] → “[[acc.addresses]]”.",
  "t.1ayh8ykzt86": "[[digi.scan.title]] · [[digi.scan.dwell]]: hoe lang de ontvanger op elk gevonden station blijft voordat hij doorgaat naar het volgende, van 2 tot 600 seconden (fabriek 10). Meer tijd om wat tekst te lezen, minder om de band snel af te zoeken.",
  "t.1b0bv6f36at": "“VHF”: de groep van modi voor VHF, microgolven en EME. Het menu biedt JT65, JT4, Q65 en MSK144; de startmodus is MSK144. Het werkt als “FT8”: het onthoudt de laatste modus die je koos en verplaatst zo nodig de radio.",
  "t.1b0jc6bfw5d": "“[[sstv.rx.fskId]]”: de roepnaam die in FSK is ontvangen, of een streepje. Dan “Regel … van …”: de voortgang van het beeld, met de balk.",
  "t.1b1a372v7ae": "Vak “[[stats.byBand]]”: per band de gewerkte landen en de QSO’s, met een balk om in één oogopslag te zien waar je het meest hebt gewerkt.",
  "t.1b1iko45s2d": "Voor QSO’s die al kwijt zijn: open [[nav.log]], filter op datum de QSO’s die ontbreken en sla ze met “[[exp.save]]” op in een ADIF-bestand; importeer dat bestand daarna in het logprogramma (bijna alle hebben “ADIF importeren”). Voor een online dienst (ClubLog, QRZ.com, eQSL, LoTW) upload je hetzelfde ADIF-bestand via de website.",
  "t.1b2m3qrrd3u": "In Instellingen › ADIF-bestand zet de knop «Nieuw leeg logboek» het huidige logboek apart (een gecontroleerde kopie naast het bestand) of wist het, met dubbele bevestiging. De Bandactiviteit wordt een raster: de kolommen verplaats je door de titel te slepen, verbreed je vanaf de rand en worden onthouden.",
  "t.1b50dz4pb4d": "Boven de lijst: “[[contest.order]]” met “[[contest.order.value]]” (nieuwe punten en multipliers bovenaan, alleen de laatste twee periodes) en “[[contest.order.time]]” (alle, op tijdsvolgorde); “[[contest.onlyCq]]” (verbergt de QSO’s tussen andere stations); een filter op locator, die je met de ✕ weghaalt.",
  "t.1b5tsmon1wg": "Vink je “[[ens.k.PromptToLog]]” aan en verschijnt het venster niet, controleer dan of je op [[sw.save]] hebt gedrukt en of het QSO echt compleet is (rapport ontvangen en afsluiting): bij een onvoltooid QSO heeft Aurora niets om te loggen.",
  "t.1b69lfb8q23": "S-meter, vermogen, SWR en ALC aflezen.",
  "t.1b6ddd0a5vy": "[[rot.set.apply]]: slaat de in het vak ingevulde onderdelen op (verbinding, model, poort, snelheid, adres, draaibereik); de knop wordt pas actief als er iets op te slaan is en de uitkomst verschijnt ernaast. Anders dan [[rot.set.enabled]], dat zichzelf opslaat, wachten deze onderdelen op deze knop.",
  "t.1b7s2dekcfn": "[[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]]. Aurora draait de antenne met rotctld, het programma van Hamlib voor rotors (dezelfde Hamlib als voor de CAT). Hier kies je hoe je het bereikt; de commando’s (naar de DX draaien, lange weg, stop) staan op de pagina [[nav.rotator]]. Je locator in [[sw.pg.personal]] is nodig: de richting wordt ermee berekend.",
  "t.1b7ujwswh73": "[[aud.output]] (vak en lijst): de geluidskaart waar het zendaudio uit komt, dus de geluidskaart van de radio (“Speakers (USB Audio CODEC)” of iets dergelijks). De keuze geldt vanaf de volgende zending (een lopende zending wordt niet onderbroken). Als er bij het starten geen uitgang was geopend, zegt de statusregel dat zenden niet actief is en geldt de keuze vanaf de volgende start. Op Linux heten uitgangen “alsa_output…”.",
  "t.1b9rrr1mpru": "“[[dec.slowPc.always]]” houdt het altijd aan, “[[dec.slowPc.never]]” altijd uit (alles werkt meteen, zoals vroeger).",
  "t.1bb8i8teu1x": "[[digi.edit.scope]]: “[[digi.edit.scopeAll]]” slaat de macro op voor alle modi; “Alleen” gevolgd door de huidige modus slaat hem alleen voor die modus op en hij wint van de basismacro met dezelfde toets.",
  "t.1bbeh1fyud5": "Om vanuit het venster “Active calls” te roepen (dubbelklik, auto call en auto answer van LogHX) zet je in Aurora [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[ens.g.udp]]” › “[[ens.k.AcceptUDPRequests]]” aan. Zonder dit ontvangt LogHX alles maar kan het Aurora niet laten zenden.",
  "t.1bbpz2xr4xf": "[[digi.spot.ok]] verstuurt de spot en bevestigt met “Spot verstuurd naar DXSummit”; [[digi.spot.cancel]] sluit. Als de roepnaam of de frequentie ontbreekt, verschijnt “[[digi.spot.bad]]”; als de spot niet wegkomt, “[[digi.spot.fail]]”.",
  "t.1bbrjbgcogc": "Voltooide QSO’s worden vanzelf gelogd; “[[fox.drop]]” stopt een QSO die niet antwoordt.",
  "t.1be0izs5xg3": "Terwijl je zendt pauzeert de waterval (de radio levert dan geen audio) en hervat bij ontvangst; een gele lijn markeert de pauze. In het menu “[[wft.spec]]” verbergt “[[wfs.specOff]]” het spectrum; sleep de grijze balk boven het spectrum om de hoogte te wijzigen.",
  "t.1bejrh39dum": "Als je met de muis over een afgekapte opmerking gaat, verschijnt de hele tekst in het vakje.",
  "t.1bf7d5bdxj7": "Rijen van Fox-stations (DXpedities in Fox/Hound) tonen het hele bericht, de vlag en het land van de Fox (de roepnaam tussen < >) en het label FOX.",
  "t.1bimw7f0k9x": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]. Een DX Cluster is een netwerk van servers waar zendamateurs de stations melden die ze horen (frequentie, roepletters, modus). Aurora logt met je roepletters in via telnet en toont de spots van anderen; hij stuurt er zelf nooit. Voor zeldzame stations is het de snelste manier om te weten waar ze zijn. Deze pagina slaat zelf op: elke wijziging gaat weg na een korte pauze of als je de pagina verlaat. Volgorde op het scherm: “[[cluster.servers]]”, “[[lay.settings]]”, “[[cluster.add.heading]]”, “[[cluster.dxpedColor]]”, “[[cluster.state]]”, “[[cluster.command]]”.",
  "t.1bk2df9841h": "De uitvoer gebruikt een korte buffer en het echte formaat van de kaart, zodat de PTT niet vóór het einde van de golf valt. Elke kaartwissel komt in het logboek, de volumeteksten noemen Windows niet meer en de pagina Radio past ook op smalle schermen.",
  "t.1bk9xt1irrr": "[[sstv.set.grpRx]] · [[sstv.rx.lock]]: de uitklaplijst heeft “[[sstv.rx.lockNone]]” (fabriek: de modus wordt herkend uit de VIS-code) of één specifieke modus, en dan worden alleen beelden in die modus ontvangen. Kies alleen een modus als je luistert op een frequentie waar iedereen dezelfde gebruikt.",
  "t.1bnxqcsemys": "[[ens.g.log]] · [[ens.k.toRTTY]] (standaard uit): schrijft in gelogde QSO’s de modus als RTTY in plaats van de echte modus. In Aurora geldt het alleen voor JT9: bij FT8 en FT4 verandert het nooit iets, dus laat het uit tenzij een diploma bijzondere eisen heeft.",
  "t.1bodazkjnp2": "[[lay.status]] · [[upd.latest]]: de laatste versie die op de site is gevonden (een streepje als Aurora nog niet heeft gecontroleerd). Is ze nieuwer dan de jouwe, dan verschijnt ze gemarkeerd met een ster en het woord NEW. Alleen-lezen.",
  "t.1bpxkr0g3n0": "De ✕ rechtsboven sluit het venster.",
  "t.1bqiwx44wex": "Tx-frequentie buiten 200-2700 Hz",
  "t.1bqrilyqez9": "Voor de meest voorkomende radio's toont Aurora “[[cat.preset.title]]” in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]], met een knop die de waarden invult.",
  "t.1bs4nlnd5yj": "Het laatste onderdeel, in klein lettertype, is het getoonde stuk audio (bijvoorbeeld “0–3000 Hz”); de waterval is zo breed als het radiofilter dat via CAT wordt gelezen (0-3000 Hz als de radio het niet zegt).",
  "t.1bs6eqbqmqy": "[[seq2.switches]] · [[seq2.answerAll]]: beantwoordt elk station dat je roept: ze komen allemaal in een wachtrij en zodra het QSO is gelogd, volgt het volgende. Uit beantwoord je alleen degenen die je kiest (rechtsklik of dubbelklik). Dezelfde schakelaar als in het QSO-paneel (“[[ctl.answer_all]]”).",
  "t.1bscpwbqosl": "De onderbalk",
  "t.1btu5hbhorw": "Controleer of telefoon en pc in hetzelfde thuisnetwerk zitten en Aurora open staat op de pc.",
  "t.1bu6gl72ei3": "Lijsten onderaan · [[auto.queue]] en [[auto.recent]]: de eerste toont de volgende stations die Aurora zou roepen (volgnummer, roepnaam, signaal; als je er met de muis boven staat zie je de reden), de tweede de laatste automatisch geroepen stations (ook die van “zou hebben beantwoord” uit dry run), elk maar één keer, de meest recente eerst. Ze zijn alleen om naar te kijken, er valt niets in te stellen.",
  "t.1bvgptdnux8": "Het gekozen bestand laadt niet en “[[sstv.bg.badFile]]” verschijnt: de gelezen formaten zijn JPEG, PNG, WebP, GIF en BMP.",
  "t.1bvxyolqiwq": "SSTV: sneltoetsen",
  "t.1bw8lawqe6a": "Esc: stopt de zending meteen en zet [[ctl.enable_tx]] uit (AutoTX en AutoSeq blijven ongemoeid). Het werkt alleen als “[[gen.escStop]]” aan staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Twee keer snel Esc (binnen 0,7 s) maakt ook het station vrij om te roepen, zoals “[[ctl.clear_dx]]”.",
  "t.1bwf2e5jv1y": "Kop · [[auto.modeChoice]]: twee knoppen, [[auto.modeDry]] en [[auto.modeLive]]. In [[auto.modeDry]] (standaard) beslist Aurora en schrijft het naar het logboek, maar het zendt nooit en raakt [[ctl.enable_tx]] niet aan. [[auto.modeLive]] kun je alleen op de pc kiezen, na bevestiging van de melding (jij blijft de verantwoordelijke operator; ARRL en DXCC accepteren geen volledig automatische QSO's) en het zet [[ctl.enable_tx]] aan terwijl de automatisering aan blijft. De knop is uit als zenden op deze pc gesloten is. Terug naar dry run vraagt geen bevestiging.",
  "t.1bxiz4ugtpe": "“[[lay.settings]]” · “[[cluster.login]]”: commando’s die naar de cluster worden gestuurd zodra je binnen bent, één per regel (maximaal 10, hoogstens 80 tekens), bijvoorbeeld set/ft8 om alleen FT8 te krijgen of accept/spots on hf/ft8. Alleen vraag- en instelcommando’s zijn toegestaan (sh/, show/, set/, unset/, accept/, reject/, clear/, help, bye): nooit spots of openbare berichten. Een niet-toegestaan commando toont de waarschuwing en wordt niet opgeslagen. Standaard leeg; verander het alleen als je spots aan de bron wilt filteren.",
  "t.1bykpr9e9s3": "Stel bij RTTY shift en snelheid in zoals het station dat je kopieert (meestal 170 Hz en 45,45 baud); “[[digi.freq.rx]]” is het midden tussen de twee tonen (in USB is de mark de hogere toon). Macro’s wijzig je met een rechtsklik op de toets (zie “Een macro bewerken”).",
  "t.1bznbwfx3gf": "[[sw.pg.digiMacros]] · de lijst: elke rij heeft de toetsnaam (met de gekozen kleur), het label (of het begin van de tekst), voor wie hij geldt (“[[digi.edit.scopeAll]]” of “alleen” de modus in gebruik) en de knop “[[sw.macros.edit]]”. Is er geen macro, dan verschijnt “[[sw.macros.empty]]”.",
  "t.1c6cl5docfs": "Als het station dat je oproept niet antwoordt, klik je in het paneel [[panel.tx]] op een roepnaam in de wachtrij: Aurora laat het huidige QSO vallen en antwoordt dat station. De kleine knop » springt naar de eerste in de wachtrij.",
  "t.1c7j2qal2k1": "[[set.add]] · knop [[set.add]]: zet de getypte tekst onderaan de lijst. Hij blijft uit zolang het veld leeg is; een tekst die al in de lijst staat, wordt niet twee keer toegevoegd.",
  "t.1c7olqu1v4k": "“[[pair.code]]”: de 8 cijfers die op de pc staan (2 minuten geldig). Met de QR-code vult het veld zich in en start het koppelen vanzelf. Zonder camera typ je de code met de hand.",
  "t.1c8pl30jqhf": "[[sstv.set.grpClock]] · [[sstv.set.slant]]: van -5000 tot 5000 ppm in stappen van 10 (fabriek 0). De scheefstand wordt bij elk beeld vanzelf gecorrigeerd; deze waarde is alleen voor geluidskaarten die ver naast de frequentie zitten, als alle lijnen op dezelfde manier scheef binnenkomen.",
  "t.1cawhcscmef": "“[[wish.notifyUrl]]” (optioneel, standaard leeg): om de melding ook op je telefoon te krijgen, met de pagina dicht en onderweg. Installeer de gratis app ntfy op de telefoon, kies een geheim onderwerp (bijvoorbeeld aurora-jouw-naam-1234) en schrijf hier https://ntfy.sh/aurora-jouw-naam-1234, of het adres van je eigen ntfy-server (het moet met http:// of https:// beginnen). Het bericht loopt via de ntfy-server: kies een onderwerp dat moeilijk te raden is. “[[wish.test]]” stuurt een testmelding in de pagina en, als het adres is ingevuld, ook naar de telefoon; je ziet of het is aangekomen. De knop blijft uit zolang er wijzigingen zijn die nog niet zijn opgeslagen.",
  "t.1ci5gi4quy4": "Kop · knop [[auto.turnOn]] / [[auto.turnOff]]: zet de automatische antwoorden aan en uit. Vanaf de telefoon gaat hij alleen in dry run aan. In live mode gaat [[ctl.enable_tx]] terug naar hoe het was zodra de automatisering uitgaat (met de hand, bij een grens, zonder verbonden apparaten of met STOP TX).",
  "t.1ci8be5goqe": "[[tab.schedule]] · [[sch.band]] (keuzelijst per rij): de band waar je op dat tijdstip naartoe gaat. De keuze [[sch.none]] laat de rij leeg: kies je die, dan verdwijnt de rij uit het schema.",
  "t.1cilv6134mq": "Je keuze wordt vanzelf bewaard en geldt ook voor “[[panel.cq]]” en voor de automatiseringen (die alleen antwoorden aan de stations die door het filter komen). Het verandert de decodering niet: het verbergt alleen rijen.",
  "t.1cim41uxa6h": "De schakelaar voor het lichte/donkere thema (hetzelfde pictogram als op de pc).",
  "t.1civmd3xnne": "In [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]], groep “[[lotw.grp]]”: “[[lotw.enable]]” (standaard aan), “[[lotw.color]]” en “[[lotw.months]]” (3, 6, 12 of 24 maanden, of “[[lotw.m0]]”). Alleen stations die binnen die maanden hebben geüpload tellen mee.",
  "t.1cqhf6dpgu4": "Druk op Toepassen of Opslaan en dan op [[auto.turnOn]]. Probeer eerst [[auto.modeDry]]: het [[auto.log]] zegt wie het zou hebben beantwoord (groen), wie het heeft overgeslagen en waarom (oranje) en wat het blokkeerde (rood). Schakel als je klaar bent op de pc met de schakelaar in de kop over naar [[auto.modeLive]]: Aurora vraagt je de melding te bevestigen (het zendt vanzelf, jij blijft verantwoordelijk, ARRL en DXCC accepteren geen volledig geautomatiseerde QSO’s); terug naar [[auto.modeDry]] vraagt geen bevestiging.",
  "t.1cr24xhgigq": "[[sw.sec.sstv]] › [[sw.pg.rx]]",
  "t.1crs18dl35s": "Bovenaan zeven vakken met de cijfers (ga er met de muis op staan om te lezen hoe ze berekend worden): “[[stats.qsos]]”, “[[stats.calls]]”, “[[stats.dxcc]]”, “[[stats.cq]]” en “[[stats.itu]]” (met de voortgangsbalk en het totaal), “[[stats.grids]]” en “[[stats.prefixes]]”.",
  "t.1cspkkdrbxa": "Het is vanzelf uitgegaan: het [[auto.log]] geeft de reden (een grens die op de pc is vastgelegd, geen apparaat verbonden, STOP TX of de limiet van QSO's per uur). Zet het weer aan na controle.",
  "t.1cvpjlcxo6b": "De waterval",
  "t.1cy2rmaiube": "Rechtsklikken op een vakje van de onderste balk opent een klein menu: Squelch, AFC, Lock, Snap, squelch-drempel, UTC-klok en knipperende TX.",
  "t.1d1wpqc3d49": "[[sw.tab.info]]",
  "t.1d3p6w9atlu": "[[digi.edit.insert]]: schrijft de gekozen opdracht in de tekst, waar de cursor staat (ook met een dubbelklik op de opdracht).",
  "t.1d3rpz11twr": "De pagina [[nav.textModes]]: hoe hij is opgebouwd",
  "t.1dbblkhy5yq": "Kies in “[[digi.ms.title]]” “[[digi.cw.bandwidth]]”: 150 Hz past bijna altijd; smaller (50-100 Hz) haalt ruis en nabije stations weg. Met de AFC aan haakt de toon in op het station, ook als het enkele tientallen Hz ernaast ligt, en volgt het als het verloopt; bij alleen ruis blijft hij stil.",
  "t.1dcx5gmduil": "De antennerotor",
  "t.1ddsrwd8xau": "Om de QSO te verwijderen druk je op ‘[[exp.edit.delete]]’ en bevestig je: hij verdwijnt uit het logboek en het ADIF-bestand van Aurora en kan niet vanuit het programma worden hersteld.",
  "t.1dj2io0vn4f": "De kopbalk en de poster",
  "t.1dm6lab91ge": "Bij “[[acc.devices]]” zie je de gekoppelde telefoons; “[[acc.revoke]]” verwijdert er één.",
  "t.1dmf4mgmukx": "[[sw.pg.profiles]]",
  "t.1dmqqrp2y4u": "Stel voor de rotor deze in via [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] en schakel “[[sat.ctl.rotor]]” in: hij volgt azimut en elevatie van de gekozen satelliet en gaat vlak voor de overkomst naar het punt waar die opkomt. In de radar is de blauwe ring waar de rotor naartoe wijst.",
  "t.1dmrmzse2cf": "[[tab.windows]]",
  "t.1do8852abqe": "Zendproblemen: “je kunt niet zenden omdat de radio niet verbonden is” (CAT niet ingesteld), “je zendt zonder radio” (de PTT wordt niet aangestuurd, alleen goed met VOX), “de radio is niet op zenden gegaan” (met de reden; zie “De PTT schakelt niet”), “de radio is opnieuw opgestart met een vermogen van x%” (bij sommige radio’s stel je dat alleen in met de knop RF PWR), “OmniRig antwoordt niet”, “de radio maakt geen verbinding” (poort bezet). De knoppen “[[diag.fix]]” leiden naar [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].",
  "t.1do9cq95i3r": "Wie naar u luistert, moet dezelfde modus en dezelfde T/R-periode gebruiken.",
  "t.1dpxr2d2f2o": "Gebruik je ook JTAlert: in BBLogger gaan de rijen “Msg ID 5” en “Msg ID 12” naar de poort van JTAlert, 2334, niet 2237.",
  "t.1dqhquxggzz": "[[not2.grpAlerts]] · [[not2.alertMy]] (standaard aan) en [[not2.alertDx]] (uit): een melding met het gekozen geluid als een station jouw roepletters roept of beantwoordt, en als er een bericht komt van het DX-station waarmee je werkt. Het geluid kies je in de menu’s “[[snd.ev.alert_my_call]]” en “[[snd.ev.alert_dx_call]]” van het vak “[[snd.title]]”.",
  "t.1dr8kawm8av": "Op de telefoon antwoordt één tik op een rij meteen.",
  "t.1du1c3fmtpz": "[[digi.mi.rx]] en [[digi.mi.tx]]: het vinkje zegt of Aurora ontvangt of zendt. TX kiezen (sneltoets: de toets Pause) opent het zenden en houdt het aan; RX kiezen terwijl je zendt, sluit het aan het einde van de tekst. Zie “RX/TX, Pause, Esc en Auto CQ”.",
  "t.1du9gq47xox": "[[sw.tab.appearance]]",
  "t.1duv5li7fxz": "[[sw.mem.title]] · de lijst: twintig genummerde rijen, elk met een samenvatting van wat erin staat (modus, frequenties, RTTY, AFC, Snap, squelch) of “[[sw.mem.empty]]”. Een geheugen vul je via het menu [[digi.menu.options]] › [[digi.mi.memory]] › [[digi.mi.memWrite]] van de werkpagina, niet vanaf hier.",
  "t.1dwhf4qy6hv": "Onderaan, [[about.links]]: vijf knoppen die de browser openen: “[[about.site]]”, “[[about.repo]]” (de code op GitHub), “[[about.releases]]” (de installatieprogramma’s van alle versies), “[[about.issues]]” (om een probleem te melden of de auteur te schrijven) en “[[about.qrz]]”.",
  "t.1dx5t4i6lp5": "“[[ens.g.udp]]” · “[[ens.k.AcceptUDPRequests]]” (standaard uit): als dit aan staat, kunnen de verbonden programma’s Aurora aansturen (een station beantwoorden met een dubbelklik, stoppen, vrije tekst schrijven, kleuren, locator wijzigen…). Uit kunnen ze alleen lezen, en vanuit een UDP-commando begint er geen zending. Zet het alleen aan als je de dubbelklik van GridTracker of iets dergelijks wilt. “[[ens.k.AcceptUDPReplyMessages]]” (standaard “[[jx.reply.1]]”) kiest welke antwoordverzoeken hij accepteert: “[[jx.reply.1]]”, “[[jx.reply.2]]” of “[[jx.reply.3]]”; dit telt alleen als het vorige vak aan staat.",
  "t.1dzcuer81vc": "[[fil.decode]] · [[dec.ftolMsk144]]: uitklaplijst van 20 tot 500 Hz (20, 50, 100, 150, 200… tot 500); fabriekswaarde 50 Hz. Hij bepaalt hoe ver van Rx de meteoorpings bij MSK144 worden gezocht. Verhoog hem als jouw frequentie of die van het andere station niet nauwkeurig is.",
  "t.1e1llz859ru": "[[cat.grp.split]] · [[cat.split]]: “[[cat.split.none]]” (fabrieksinstelling) laat de radio in simplex; “[[cat.split.rig]]” is een echte split (de zend-VFO verschuift en de audio blijft tussen 1500 en 2000 Hz); “[[cat.split.emulate]]” verschuift de frequentie alleen tijdens het zenden. Met FT-991(A) Link is er geen echte split (alleen VFO A). Zet het aan als je radio harmonischen of ruis maakt bij hoge audio.",
  "t.1e7to3dfqwq": "Klik op de waarschuwing: Aurora probeert eerst de Windows-tijd te corrigeren met de NTP-servers; alleen als dat niet lukt (meestal ontbreken de beheerdersrechten) opent [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]], met de test van de NTP-server.",
  "t.1e9f7b3w00a": "Het is de lijst van CW- en PSK-signalen die Aurora op de band hoort, op de pagina van de tekstmodi: een klik op een rij stemt af op dat station.",
  "t.1e9hnn5t96k": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]] vind je de tabel met afstemfrequenties: als je een band (en een modus) kiest, zet Aurora de radio op de frequentie van die rij. Eén rij tegelijk, en de tabel slaat zichzelf op.",
  "t.1ea0vrameks": "[[lay.settings]] · [[upd.interval]]: numeriek veld, 1 tot 168 uur (standaard 1; 6-24 is meestal genoeg). Hoeveel uur er zit tussen de eigen controles van Aurora. Het wordt grijs als “[[upd.enabled]]” uit staat. Valt de waarde buiten de grenzen, dan verschijnt “[[upd.invalid]]” en wordt hij niet bewaard. Wanneer: verhoog het als je minder contact met de site wilt.",
  "t.1echqxiya8v": "Een QSO die al in het logboek van Aurora staat, kan worden gecorrigeerd (verkeerde roepnaam, tijd, band, rapporten, locator, naam, opmerking) of verwijderd.",
  "t.1edd5xokq1x": "[[sat.ctl.title]] · [[sat.ctl.prepoint]] (standaard aan): kort voor de overvlucht draait de rotor al naar waar de satelliet opkomt, zodat hij de eerste minuten niet hoeft in te halen. Hij kan niet worden gewijzigd zolang “[[sat.ctl.rotor]]” uit staat.",
  "t.1edlzzdejx0": "Het tabblad “[[contest.tab.race]]” is de werkpagina tijdens de contest. De sneltoetsen F1–F4 staan in “Contest: toetsenbord en opdrachten”.",
  "t.1efb53tw8ft": "[[digi.scan.title]] · [[digi.scan.timeMarks]] en [[digi.scan.freqMarks]] (standaard aan): voor elk gevonden station schrijven ze de UTC-tijd en de frequentie in de ontvangen tekst, zodat je weet wanneer en waar je alles hebt gehoord. Zet ze uit voor schone tekst.",
  "t.1eff0n83tkc": "“[[fil.always]]”: deze stations worden getoond, ook als een ander filter ze zou verbergen.",
  "t.1egkqvm3dv3": "[[digi.edit.title]] · [[digi.edit.scope]]: “[[digi.edit.scopeAll]]” geldt voor PSK, RTTY en CW; “Alleen” de modus in gebruik geldt alleen voor die modus en wint van de basismacro van dezelfde toets. Een macro “alleen modus” die leeg blijft, maakt de toets in die modus vrij.",
  "t.1egmx0libb9": "WSPR-modus en uploaden naar WSPRnet",
  "t.1ejrn8pty0m": "Signaalmetingen (alleen als het luisteren aan staat): S/N in dB in alle modi, IMD bij PSK (gemeten tijdens de omkeringen aan het begin van elke zending: onder -20 dB is het signaal schoon), ontvangen snelheid bij CW.",
  "t.1enfkk94csc": "“+ [[int.p.loghx]]”: naam LogHX, 127.0.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.loggedAdif]]” aan. Hij ontvangt de WSJT-X-stream (status en decodes, ook voor het venster met actieve oproepen) en, na elke QSO, het ADIF-record in bericht 12, zodat de QSO aankomt ook als het programma hem niet uit het bericht QSO Logged haalt. In het logboek moet je het ontvangen van de UDP-stream van WSJT-X/JTDX aanzetten, met 127.0.0.1 en dezelfde poort, en het automatisch loggen van ontvangen QSO’s. Gebruik je een andere poort dan 2237 (bijvoorbeeld 2239), verander die dan op beide plekken.",
  "t.1eofwbo071v": "Foutrapporten: wat wordt verstuurd en hoe zet je het uit",
  "t.1epdsmmkxkl": "Rechts van de balk staat het OTP-vak: “[[fox.otpOn]]” / “[[fox.otpOff]]”, de “[[fox.otpSeed]]” (16 tekens A-Z en 2-7, opgeslagen op de pc; leeg = de opgeslagen blijft), “[[fox.otpEvery]]” (hoeveel periodes tussen de codes), “[[fox.otpSave]]” en “[[fox.otpRemove]]”. Je gebruikt het om de Hounds te bewijzen dat jij de echte expeditie bent.",
  "t.1epsndesd4m": "Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] → “[[ens.g.adif]]”: zet “[[ens.k.EnableUDP2adifBroadcast]]” aan, 127.0.0.1, poort 2237.",
  "t.1eu7mqksb97": "Om een contest echt te gebruiken (activeren, roepen, het Cabrillo exporteren) ga je naar de pagina [[nav.contest]]: hier bereid je alleen de gegevens voor. Voor contests met MSK144 of Q65 staan dezelfde instellingen in [[sw.sub.vhf]] › [[sw.pg.contest]].",
  "t.1ev4e58v2a9": "Dubbelklik op een rij: de radio gaat naar de spotfrequentie, zonder te zenden. Eén klik is genoeg als je dat in het tandwiel kiest (hieronder). Met “UP 5” in de opmerking en Split DX aan gaat de radio ook in split (zie “DX-split vanuit de DX Cluster”). Als je de muis over de roepnaam beweegt, verschijnt de stationskaart; rechtsklik op DX of DE: “Open op QRZ.com”.",
  "t.1ewt9mrboaa": "Als je de lijst met de hand scrolt, gaat hij na 15 seconden zonder aanraking terug naar boven, waar de expedities in de lucht staan. Je zet het aan en uit met “[[onl.dxped]]” in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.1ex4yqjv0m0": "Ziet de waterval er grijs of te helder uit, probeer dan eerst “[[wfs.zero]]” (lager zetten) en daarna “[[wfs.gain]]”; om terug te gaan druk je op “[[set.reset]]”.",
  "t.1exbrfu4sa3": "Proceduretekens verschijnen als <AR>, <BT>, <KN> en <SK>; zo geschreven in de zendtekst of in een macro gaan ze als één teken de lucht in.",
  "t.1ey5wbsumao": "Het paneel met de zes Tx-berichten en, onderaan de pagina, de drie knoppen die altijd binnen vingerbereik zijn.",
  "t.1eygjcs8hkz": "Het paneel CQ en nieuws, en DXpedities",
  "t.1f04krwe5t5": "De telefoon toont bevroren gegevens of een oude versie na een update van Aurora.",
  "t.1f0mctbu1i4": "Notches, banddoorlaat en begrensde AFC",
  "t.1f0xpqorm5m": "Als er een nieuwe versie is, verschijnt bij het opstarten midden in beeld een poster met wat er nieuw is: “Installeren en herstarten” installeert hem, “Later” verbergt hem tot de volgende versie. Intussen downloadt Aurora hem zelf op de achtergrond en controleert de handtekening: een kleine oranje balk bovenaan toont de voortgang en daarna “Klaar · Installeren en herstarten”, zodat de installatie meteen start zonder op de download te wachten.",
  "t.1f27flkooup": "“[[rep.auto]]” (aan): bij elke ernstige fout gaat er een kort rapport uit: versie, systeem, engine, radiomodel, PTT, CAT, geluidskaart, gebied en opgeschoond bericht. Identieke fouten hooguit één keer per uur en met een maximum per dag (hieronder vermeld). Als het aan staat, zie je hieronder ook hoeveel rapporten er wachten en hoeveel er vandaag zijn verstuurd.",
  "t.1f64k6d5nl7": "De audio mist blokken: de knop “[[diag.howto]]” opent een kaartje met de controles die je op volgorde doet (USB-kabel, USB-energiebesparing, zware programma’s). “[[diag.fix]]” brengt je naar de pagina [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].",
  "t.1f86z2pulvm": "“[[lay.settings]]” · “[[cluster.splitDx.set]]” (standaard aan, blijft op dit apparaat): bij een dubbelklik op een spot waarvan de opmerking UP, DN of QSX zegt (bijvoorbeeld “UP 5” of “QSX 14.030”), zet Aurora de ontvangst op de frequentie van de spot, de zending op de andere VFO verschoven met wat de opmerking zegt en zet hij de split van de radio aan. Het geldt voor de cluster van de pagina [[nav.station]] en van de pagina [[nav.digi]]. Met het vak uit stemt de dubbelklik alleen af. Het werkt als de radio split meldt (Hamlib, OmniRig, TCI, Cat4OM); hij gaat vanzelf uit als je van band of frequentie wisselt.",
  "t.1f8g1zi4jju": "Het pictogram van Aurora naast de klok. Windows 11 zet het meestal onder de pijl “^”: Aurora probeert het na een paar seconden zelf zichtbaar te maken; lukt dat niet, sleep het dan naast de klok. De tooltip bij het pictogram zegt “Aurora”; als je voor een melding “alleen pictogram” koos, toont hij de titels van de nieuwe meldingen.",
  "t.1fbjvjoh9ro": "[[sstv.set.grpTx]] · [[sstv.set.txOffset]]: van -200 tot 200 Hz in stappen van 5 (fabriek 0). Verschuift alle uitgezonden tonen met zoveel Hz: het is alleen nodig als je radio ze verkeerd uitzendt (wie je ontvangt ziet ze verschoven).",
  "t.1fblxmlr1r2": "[[sat.ctl.title]] · [[sat.ctl.doppler]] (standaard uit): boven de minimale elevatie corrigeert Aurora de radiofrequentie elke seconde voor Doppler, ontvangst op de hoofd-VFO en zending op de split-VFO. Zet het aan als je een overvlucht volgt met de radio verbonden.",
  "t.1fbxalikb6d": "“[[sstv.rx.cancel]]”: gooit het beeld weg dat binnenkomt (alleen actief tijdens een ontvangst).",
  "t.1fbynbj1khn": "BBLogger: QSO’s via het netwerk (UDP), aanbevolen",
  "t.1fcea7qjes4": "De geluidsmeldingen aanzetten: klik in de onderbalk op de luidspreker. Doorgestreept = uit (de standaard); met golven = aan. Zodra hij aanstaat, stelt de schuif ernaast het algemene volume in (van 0 tot 100%, standaard 50%); als hij uit staat, is de schuif vergrendeld. De eerste klik laat de browser ook de audio ontgrendelen.",
  "t.1ffco2nw3b2": "De kleur (en gemarkeerde rij) van een type nieuwtje: haal in [[sw.tab.colors]], in de tabel, het vinkje “[[not2.colHighlight]]” van de rij weg en druk op “[[sw.save]]”. Om de kleur te wijzigen, gebruik je de kiezer in het vak “[[not2.grpColors]]”.",
  "t.1ffv7nhfb7u": "[[gen.screen]] · [[pref.cmdTune]] en [[pref.cmdLogQso]]: twee selectievakjes, standaard uit. Ze tonen in het paneel Commando's de knop Tune (vaste draaggolf om af te stemmen) en de knop Log QSO (logt de huidige QSO met de hand). Zet ze alleen aan als je ze nodig hebt.",
  "t.1fgcfe9xk6i": "Is de Fox echt? OTP-controle",
  "t.1fkmcx3fpuk": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]] vind je de Fox-verificatie (voor wie een expeditie in Hound roept) en de instellingen van de FT8- en FT4-contests, dezelfde als het tandwiel van de pagina [[nav.contest]]. Het Fox-vak bestaat alleen met de eigen engine en geldt met [[sw.save]]; het contestformulier wordt opgeslagen met zijn eigen knop [[contest.set.save]].",
  "t.1fs895wiqqz": "[[bak.intro]]",
  "t.1ftn1bujepw": "Eén programma per poort: een COM-poort kan maar door één programma worden geopend. Sluit WSJT-X, JTDX, logprogramma's en al het andere dat de radio gebruikt. Heb je ze samen nodig, leid ze dan via OmniRig of Cat4OM: Aurora ondersteunt beide ([[cat.backend]] → “[[cat.backend.omnirig]]” of “[[cat.backend.cat4om]]”).",
  "t.1fu81pckrcg": "[[seq2.switches]] · [[seq2.single]]: na een voltooid QSO stopt Aurora met zenden. Na het QSO laat het de keuze van de volgende DX aan jou (of aan de wachtrij [[seq2.answerAll]]). Dezelfde schakelaar als in het QSO-paneel (“[[ctl.single_qso]]”).",
  "t.1fwsnrpojq6": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. De pagina voor wie een SDR-radio heeft: ze verzamelt op één plek wat nodig is (TCI en QMAP) en heeft geen eigen instellingen, want het TCI-adres is dat van de CAT, de TCI-audio is die van de pagina Audio en de QMAP-schakelaar is een voorkeur. Met een gewone radio (FT-2000, IC-7300…) heb je haar niet nodig.",
  "t.1fy81t10wtq": "Start rigctld onder Linux niet? De melding geeft de reden die Hamlib opgeeft (met zijn regels): lees die om te zien of model, poort of snelheid fout is. Een Icom op 4800 baud opent langzaam: Aurora wacht tot 15 seconden.",
  "t.1fzripza1v": "Een “*” in de tekst is een teken dat Morse niet kent: als je er veel ziet, valt de toon buiten het filter. Zet de cursor op het signaal of zet AFC aan.",
  "t.1g0ulcd0k3p": "In de grote beelden van de geschiedenissen: ← en → voor het vorige en het volgende, Esc om te sluiten. Op de miniatuurstroken: ← en → om te scrollen.",
  "t.1g14b1xuwj": "Bovenaan band en modus: als je zendt, vraagt Aurora om bevestiging voordat het ze wijzigt.",
  "t.1g33cb29v7": "De onderste balk toont S/R (in 3 kHz, zoals WSJT-X) en de herkende snelheid. De squelch kijkt naar diezelfde S/R, niet naar het volume; ook uitgeschakeld wordt onder ongeveer -16 dB niets afgedrukt, zodat ruis het venster niet vult. Probeer bij een onregelmatige handsleutel “[[digi.cw.som]]”.",
  "t.1g3q3y2yi5f": "[[wfs.res]] · [[wfs.navg]] (1 tot 50, standaard 1): hoeveel spectrumrijen worden gemiddeld voordat er één wordt getekend; hoger = tragere en minder ruisige waterval. [[wfs.speed]]: “[[wfs.speedWsjtx]]” (standaard: één rij per half FT8-symbool, ongeveer 52 rijen per periode, signalen als compacte blokken) of “[[wfs.speedJtdx]]” (15 rijen per seconde, ongeveer 225 per periode, signalen als lange strepen).",
  "t.1g6gu3opsri": "Bij CW: “[[digi.cw.bandwidth]]” (standaard 150 Hz), “[[digi.cw.som]]” (voor een onregelmatige sleutel met de hand; standaard uit), de vakken [[digi.band.mi]], [[digi.band.spots]] en [[digi.band.spotsCqOnly]], de keuzelijst “[[digi.band.validation]]” ([[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]], [[digi.band.valMaximum]]) en de schuifregelaar voor de squelchdrempel (S/N van -30 tot +20 dB, standaard -15).",
  "t.1gaua23kzwe": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] kan Aurora vanzelf de CQ’s beantwoorden die je iets nieuws opleveren. De kop toont altijd of het aan staat, in welke modus en wat het vandaag heeft gedaan; eronder staan vijf blokken regels, elk met zijn eigen “?”.",
  "t.1gd8yjcywop": "Onder de roepnaam van de zender, in Bandactiviteit en het RX-venster, geeft een gekleurde balk aan dat dat station LoTW gebruikt: het loont om het te werken als je de bevestiging wilt.",
  "t.1geu6vx0bgr": "Eerste regel: als de pc op wifi zit, geeft hij de netwerknaam en zegt hij dat de telefoon op hetzelfde netwerk moet zitten (niet het “gast”-netwerk); als de pc op een kabel zit, zegt hij “[[net.cable]]”. Als je “[[net.waiting]]” ziet, wacht Aurora tot de telefoon het adres opent.",
  "t.1gf93sotihm": "De keuzelijst “[[digi.band.validation]]” in het paneel bepaalt hoe streng roepnamen worden gecontroleerd: Aurora telt hoe de roepnamen van elk land zijn opgebouwd (uit het log, de DX-clusterspots en MASTER.SCP, als je die in de gegevensmap van Aurora zet) en een roepnaam met een zeldzame vorm moet meerdere keren gehoord worden voordat hij telt. Lokale spots bevatten de S/R in 500 Hz gemeten met ingedrukte seinsleutel (mediaan van de laatste 15 seconden), de WPM en CQ of DE; hoogstens één per roepnaam en band per 10 minuten, opnieuw als het station meer dan 1 kHz verschuift of CQ begint te roepen. Met “[[digi.band.spotsCqOnly]]” alleen stations die roepen.",
  "t.1gfkxye3va0": "Alleen met FT-991(A) Link: [[cat.ft991.address]] (fabriekswaarde 127.0.0.1:50001): het UDP-adres dat het programma FT-991(A) Link toont na “Start UDP”. Verander het alleen als je in dat programma een andere poort koos.",
  "t.1gkmv0ml1uf": "Elk item heeft zijn eigen “?” met een korte uitleg. Ander FT8-gedrag staat elders: full duplex en wachten in [[tab.sequence]], vak [[gen2.wsjtx3]]; Hound- en Fox-verificatie in [[sw.sub.contest]].",
  "t.1gl50njtlnr": "[[cat.cat4om.management]]: standaard 127.0.0.1:17300, de beheerpoort van Cat4OM. Van daaruit vindt Aurora zelf de groep en de Control-poort ervan (Cat4OM kent die toe aan de groep, bijvoorbeeld 5001), zoals Decodium met “Automatic discovery”. Laat [[cat.cat4om.group]] en [[cat.cat4om.address]] leeg: na het verbinden verschijnen de gevonden waarden in grijs. Vanaf een andere pc vult u het adres van de Cat4OM-pc in en zet u netwerk aan in Cat4OM.",
  "t.1gmkkz81qi3": "Toont de telefoon bevroren gegevens: tik op ⟳. Zie anders “De telefoon werkt niet bij”.",
  "t.1gotll4r1cv": "[[gen2.fox]] · [[gen2.houndAuto]]: selectievakje, standaard aan. Als de gekozen DX zendt als WSJT-X Fox, zet Aurora Hound zelf aan, verplaatst Tx boven 1000 Hz en zet split aan; het zet ze uit als de DX met normale berichten antwoordt of als je een andere DX kiest. Zet het alleen uit als je [[ctl.hound]] met de hand wilt beheren.",
  "t.1gplh2ip4jr": "Zegt het bericht daarentegen dat de poort bezet is (of dat de toegang wordt geweigerd op Windows), dan gebruikt een ander programma of een andere kopie van Aurora hem: sluit die of deel de radio (vak [[cat.share]]). Zegt het dat de poort niet bestaat, lees dan de poorten opnieuw in, controleer of de radio aan staat en de kabel is aangesloten, en kies de poort opnieuw.",
  "t.1gqm5n6ej0y": "WSPR-2 kies je in de modusselectie: perioden van twee minuten, alleen baken, zoals WSJT-X. Naast de modus staan het vermogen, [[mode.wsprPct]] (standaard 20%, met de tweeuurstabel van WSJT-X) en [[mode.wsprType1]]; er wordt alleen gezonden met [[ctl.enable_tx]] aan, tussen 1400 en 1600 Hz. De waarde van [[mode.wsprPct]] wordt verstuurd als je Enter drukt of het veld verlaat.",
  "t.1grwql0zdh5": "Als Log4OM na een update van Aurora OFFLINE toont, druk dan op “Save and apply” om opnieuw te verbinden.",
  "t.1gsb2ptdtqw": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiRxTx]]. Hier stel je frequenties, squelch en parameters van PSK31, PSK63, RTTY en CW samen in (de werkpagina toont alleen die van de modus in gebruik). Elke wijziging werkt meteen. Naam en QTH voor QSO’s staan hier niet: ze staan in [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]. Laadt de pagina niet, dan antwoordt de engine van Aurora niet.",
  "t.1gshxkvwjgh": "Aan het eind van de ontvangst verschijnt “[[sstv.rx.saved]]” (het beeld staat in de geschiedenis) of “[[sstv.rx.lost]]” (het signaal verdween voor het eind en het beeld is weggegooid).",
  "t.1gta7bmh47n": "De bovenbalk",
  "t.1gui3r3xvw9": "[[not2.grpAlerts]] · [[not2.popNew]] en [[not2.popNewBand]]: de knipperende, gemarkeerde kaart rechtsboven op de pagina Station, met vlag, roepletters, land en tijd van de laatste ontvangst. Standaard aan. De eerste is voor een nooit gewerkt land, de tweede ook voor een land dat is gewerkt, maar niet op deze band. De kaart verschijnt één keer per station, hooguit twee tegelijk, en verdwijnt 10 minuten na de laatste ontvangst; met een dubbelklik op een kaart beantwoord je dat station. Om ze uit te zetten haal je beide vinkjes weg, of druk je op “[[newdx.off]]” onder de kaarten.",
  "t.1gx542y76na": "De kaart in het logboekpaneel",
  "t.1gxf8cjqs6g": "Een SSTV-zending duurt van een halve minuut tot bijna vijf: houd Pwr laag en stop de FT8-automatisering voor je zendt. Als het niet start, staat de reden erbij: “[[sstv.tx.busy]]”, “[[sstv.tx.disabled]]” of “[[sstv.tx.notReady]]”.",
  "t.1gzjkrghysz": "Linksboven staat de modus-keuzelijst, met PSK31, PSK63, RTTY, CW en SSTV: als je een tekstmodus kiest, selecteert Aurora die en opent de pagina PSK · RTTY · CW.",
  "t.1h3sanzxogb": "Sq: de ruisonderdrukking (squelch). Als die aan staat, wordt alleen getoond wat boven de drempel komt; het teken “Sq *” zegt dat het signaal erboven zit. Een rechtsklik opent het menu met de drempel.",
  "t.1h6wyhsjbqd": "Ik heb een verkeerde QSO gelogd: hoe corrigeer of verwijder ik hem?",
  "t.1h88yqh4fja": "“[[contest.log]]”: het logboek van deze contest (de QSO’s komen ook in het normale logboek), met het aantal QSO’s en van de onzekere. Een klik op de ontvangen exchange corrigeert hem (“[[contest.edited]]”); rechtsklik op een rij: geldig, onzeker of “[[contest.notInContest]]” (0 punten, buiten de Cabrillo gelaten). “[[contest.resetLog]]” begint het logboek na een bevestiging opnieuw vanaf nul (het oude blijft als kopie in de gegevensmap).",
  "t.1h9cn7c08gd": "In de bovenbalk opent “[[nav.textModes]]” de pagina voor tekstmodi: PSK31, PSK63, RTTY en CW. Alles past op één scherm. Kom je van een andere pagina, dan gaat de radio vanzelf naar de band van het IARU-bandplan voor de modus (heeft de gebruikte band geen frequenties voor die modus, dan naar de eerste in het plan); terwijl je zendt gebeurt dat niet. Het luisteren start vanzelf als je binnenkomt en stopt als je vertrekt, tenzij [[digi.autoReceive]] in de Instellingen aan staat.",
  "t.1hbt5lgjsjq": "[[sw.pg.qso]]",
  "t.1hc6v2gc5ou": "Op de telefoon zijn de Instellingen er niet: die wijzig je alleen vanaf de pc.",
  "t.1hdd46jq9op": "Bij een uitgeschakelde radio verschijnt er een grote tekst «RADIO UIT» in het midden van elk display. De notches zijn fluorescerend groen en goed zichtbaar en «Notches wissen» verschijnt alleen wanneer het nodig is. Clusterspots kunnen nu ook 45 minuten blijven staan.",
  "t.1he4qqxg96l": "FST4 en FST4W kiest u in de moduskeuze, met de T/R-periode naast de modus, zoals in WSJT-X: FST4 van 15 s tot 30 min, FST4W van 2 tot 30 min. FST4 is voor QSO’s met zwakke signalen, met berichten en volgorde zoals FT8. FST4W is een baken zoals WSPR: geen QSO’s, ontvangen berichten starten de volgorde niet.",
  "t.1hgouclbjyn": "De kolommen hebben een kop — de tijd (of “[[rxw.col.age]]”), dB, DT, “[[rxw.col.msg]]”, “[[rxw.col.country]]” — die je sleept om de volgorde van de kolommen te wijzigen; de rechterrand van een kop slepen wijzigt de breedte en dubbelklikken op de rand past de kolom aan zijn inhoud aan. Rechtsklik op de kop: “Reset columns”. Alt + pijltjes verplaatsen ook de gekozen kolom.",
  "t.1hixrvu4m46": "Probeer altijd eerst [[auto.modeDry]]: het logboek zegt wie Aurora zou hebben beantwoord, wie het heeft overgeslagen en waarom. Als je klaar bent, schakel je op de pc over naar [[auto.modeLive]]. STOP TX zet de automatisering altijd uit en stopt ook een CQ die Aurora zelf had geroepen; de grenzen die op de pc zijn vastgelegd blijven actief. Jij blijft de operator die verantwoordelijk is voor elke zending.",
  "t.1hj2sohcl7e": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: [[cat.backend]] TCI, adres 127.0.0.1:40001, daarna [[cat.connect]].",
  "t.1hlqrnchsjx": "Filterbandbreedte: “[[digi.cw.bandwidth]]” van 50 tot 500 Hz, en 1000 Hz “[[digi.cw.wide]]”. Minder Hz = minder ruis en minder stations in de buurt, maar de toon moet gecentreerd zijn (AFC achtervolgt hem). Je verandert het in het menu [[digi.menu.mode]], met de keuzelijst in de statusbalk of in het venster “[[digi.ms.title]]”.",
  "t.1hng6abwpxs": "[[digi.mi.flashTx]] (aan): het TX-label en het TX-vak in de statusbalk knipperen terwijl je zendt. Ook via de rechtsklik op de statusbalk.",
  "t.1hnysdswc6": "[[rx.grp]]: tien vakken die de items van het uitgebreide display aanzetten (het display onder het kopdisplay). Standaard aan: [[rx.vfoB]], [[rx.meters]], [[rx.frontEnd]], [[rx.agc]], [[rx.noise]]; uit: [[rx.supply]], [[rx.gains]], [[rx.ritXit]], [[rx.tuner]], [[rx.vfo]]. Behalve de instrumenten ([[rx.meters]]) hebben ze “[[cat.extras]]” aan nodig (vak “[[cat.grp.split]]”) en een radio die de gegevens kan geven: ontbreken ze, dan zegt het uitgebreide display dat. Voor FT8 loont het om [[rx.ritXit]] te tonen (ze moeten op nul staan) en [[rx.noise]] (NB/NR/notch aan verpesten het decoderen).",
  "t.1hoembgnton": "[[ca.audio]]: “[[ca.audio.ok]]” bij een goed niveau; “[[ca.audio.warn]]” als het zwak is of blokken verliest; “[[ca.audio.bad]]” als het stil is, overstuurd of met een vastgelopen ingang. “[[diag.fix]]” leidt naar de audiopagina.",
  "t.1hp88zw2v6h": "Je kunt kiezen wanneer het FT8-decoderen start en of er wordt gedecodeerd terwijl je zendt.",
  "t.1hpccpylywu": "De macrobalk",
  "t.1ht4gn9d7gk": "De knop RX/TX in de statusbalk is directer: terwijl je zendt, stopt indrukken het zenden meteen (zoals Esc); in rust opent hij het zenden.",
  "t.1hv0xay4d2l": "In het radiomenu: de opties die in het vak staan (CAT-snelheid gelijk aan Aurora, data-audio via USB).",
  "t.1hv4w7adw06": "Met de pagina open blijft het luisteren aan tot je op «Luisteren stoppen» drukt en het hervat vanzelf na je uitzending. In het log wordt de roepletters meteen opgezocht op QRZ.com of HamQTH en vult naam, QTH en Locator in; de pagina is compacter, met Ontvangen en Verzonden in een kolom rechts.",
  "t.1hvhseyxun": "Met Hamlib toont het display de echte waarden van de radio: S-meter bij ontvangst, vermogen bij zenden.",
  "t.1hwsbqhvtjo": "Als je de link of de QR vanaf de pc opent, bevat het adres al de code: de pagina koppelt vanzelf, met één enkele poging, en de telefoon laadt opnieuw op het station. De QR maak je op de pc in [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] met de knop “[[acc.showCode]]”.",
  "t.1i06gckas5w": "[[fil.continents]]: zeven selectievakjes, [[cont.AF]], [[cont.AN]], [[cont.AS]], [[cont.EU]], [[cont.NA]], [[cont.OC]] en [[cont.SA]]; vink een continent aan om de berichten ervan niet meer te zien. Geen enkel aangevinkt (fabrieksinstelling) = alles getoond. Gebruik ze om de continenten uit te sluiten waarin je niet geïnteresseerd bent.",
  "t.1i1bosldsfv": "[[auto.b5]] · [[auto.autoCqOn]] en [[auto.autoCq]] (een vakje en een getalveld van 2 tot 120 minuten, standaard uit; als je het vakje aanvinkt, begint het bij 5): na zoveel minuten zonder CQ om te beantwoorden roept Aurora CQ, maar alleen in live mode, met inactief zenden en binnen het tijdvenster. Elke CQ telt als een antwoord achter elkaar zonder QSO: bij de grens schakelt hij uit. Zie ook “Aurora zelf CQ laten roepen”.",
  "t.1i1dnjh9bqo": "[[wfs.palette]]: 30 paletten plus een eigen palet. [[wfs.gain]] en [[wfs.zero]] maken signalen en achtergrond helderder of donkerder.",
  "t.1i21bmmasc0": "[[digi.menu.configure]] › [[digi.mi.personal]]: opent [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]], waar je de naam en QTH invult die de macro’s gebruiken (<MYNAME>, <MYQTH>).",
  "t.1i2ga3luo1h": "Op de Logpagina corrigeer je met een dubbelklik op de rij of «Bewerken» roepletters, band, rapporten, locator en de rest, of verwijder je het QSO na een bevestiging. De correctie komt ook in het ADIF-bestand van Aurora.",
  "t.1i2k0q7tn8l": "In het midden bovenaan staat het venster “[[digi.rx.title]]” (de ontvangen tekst) en eronder het venster “[[digi.tx.title]]” (de tekst om te zenden). De scheidingslijn tussen de twee kun je slepen; de verhouding wordt onthouden.",
  "t.1i3581ooo47": "[[cop.choose]] · [[cop.rotor]] (standaard uit): met hetzelfde gebaar draaien de antennes naar het land van de spot. Hiervoor moet de rotor verbonden zijn ([[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]]) en je locator ingevuld in [[sw.pg.personal]].",
  "t.1i37xlowt98": "Aurora start nu ook op oudere Windows 10",
  "t.1i3a9thg8ru": "De berichtgeschiedenis",
  "t.1i7ci14sw7w": "Elk automatisch CQ telt als één antwoord op rij zonder QSO: bij de grens die op de pc is vastgelegd, schakelt de automatisering zichzelf uit. STOP TX stopt altijd alles. Jij blijft de operator die verantwoordelijk is voor elke zending.",
  "t.1i82ocqi7j9": "In Hound-modus roept Aurora nooit CQ. Expedities die SuperFox gebruiken (een breed signaal dat tot 9 stations beantwoordt) worden nog niet door Aurora ontvangen: dat komt in een latere versie.",
  "t.1iackvfo1m5": "Om een QSO te volgen dubbelklik je op het station in Bandactiviteit: de RX-frequentie springt ernaartoe en het RX-venster volgt die QSO. Standaard blijven de berichten ook in Bandactiviteit staan; wil je ze alleen in het RX-venster, schakel dan “[[rxw.exclusive]]” in het vak “[[fil.grp.rx]]” in.",
  "t.1iczk8mwbqq": "Elk paneel van de Stationspagina heeft rechtsboven de knop ⧉ (“[[win.detach]]”): daarmee verplaats je dat paneel naar een tweede scherm. De paneelgroottes liggen vast; zie ook “De blokkenpagina”.",
  "t.1ie22j7uhnc": "Alleen VFO A wordt gebruikt: bij split verschuift Aurora de frequentie alleen tijdens het zenden (geëmuleerde split). Zegt de status dat FT-991(A) Link niet antwoordt, controleer dan of in FT991Link de poort open is en UDP is gestart.",
  "t.1ie3e24pgz7": "“[[int.adif]]”: het ADIF-record als gewone tekst, één datagram per QSO, verder niets (gelezen door Log4OM 2 met een ADIF_MESSAGE-verbinding en door WaveLogGate).",
  "t.1iez95k7u8": "Boven de waterval decodeert het paneel “[[digi.band.title]]” alle CW-signalen in de audioband tegelijk, elk met een eigen ontvanger: één regel per signaal met frequentie, WPM, S/R, roepnaam (vlag, CQ of DE; cursief zolang hij niet bevestigd is) en laatste tekst, met onzekere tekens in grijs. De roepnaam staat ook in de waterval boven het spoor. Een klik zet de ontvangst op dat signaal, een dubbelklik toont alle tekst van de laatste 60 seconden. Aan- en uitzetten gaat in het menu Opties (“[[digi.band.mi]]”); bij te veel signalen blijven de sterkste, zodat niet meer dan een kwart van een kern wordt gebruikt. Bevestigde roepnamen komen als lokale spots in het DX-clusterpaneel van Aurora (“[[digi.band.spots]]”): ze blijven op je pc, er gaat niets het netwerk op.",
  "t.1ift5qqbttl": "[[aud.output]] · [[aud.vol.out]]: de Pwr-schuifregelaar, dus het Windows-volume van de uitgang naar de radio. Zie het onderdeel over de schuifregelaars Rx, Pwr en AUTO. [[aud.outch]]: “[[aud.ch.mono]]” (standaard) stuurt het geluid naar alle kanalen van het apparaat; “[[aud.ch.left]]” of “[[aud.ch.right]]” alleen aan die kant (de andere blijft stil); “[[aud.ch.both]]” dezelfde golf op twee kanalen. Links, Rechts en Beide vragen een stereo-uitgang.",
  "t.1igdm7x227r": "Met “[[rot.set.launch]]”: [[rot.set.port]] en [[rot.set.baud]]. De poort is die van de interface van de rotor, NIET die van de radio (op Windows COM5, op Linux /dev/ttyUSB1 en, voor de toestemming om hem te gebruiken, geldt de groep dialout uit het onderdeel over seriële poorten); je kunt hem leeg laten bij modellen die hem niet gebruiken. De snelheid moet die zijn die op de interface is ingesteld: “[[rot.set.default]]” gebruikt die van het model.",
  "t.1igzy7kur7p": "“[[digi.ms.title]]” · [[digi.ms.receive]]: “[[digi.freq.rx]]” (van 200 tot 3500 Hz, standaard 1000), [[digi.mi.afc]], [[digi.mi.snap]], [[digi.mi.squelch]] en, afhankelijk van de modus, de volgende onderdelen. Elke wijziging wordt meteen opgeslagen.",
  "t.1ihn4r86q5b": "Zet “[[int.adif]]” (Log4OM, WaveLogGate) of “[[int.n1mm]]” (HRD Logbook) aan, daarna “[[int.resend]]”. Zonder een van de twee formaten blijft het vakje grijs.",
  "t.1ihq2d9lomf": "[[aud.mode]] · [[aud.keep]] (getalveld, 0 tot 3650, standaard 7): hoeveel dagen Aurora de opgeslagen bestanden bewaart. Bij het opstarten en daarna eenmaal per dag verwijdert ze de .wav-bestanden van door Aurora opgeslagen perioden die ouder zijn; andere bestanden in de map worden nooit aangeraakt. 0 = voor altijd. Ook ALL.TXT volgt de limiet: als het groter wordt dan 50 MB of ouder is dan de limiet, wordt het geroteerd (hernoemd naar ALL-datum.TXT).",
  "t.1ijmmk4nzub": "Zo hebben logboek, spots en kaart de juiste band. Aurora onthoudt het ook als je het opnieuw opent.",
  "t.1ijz0xm2m1c": "Ontbreekt er iets, dan verschijnt onder het vak een melding: “[[digi.tx.notReady]]”, “[[digi.tx.busy]]”, “[[digi.tx.disabled]]”. Met open zenden stelt het vak “[[digi.tx.openHint]]” voor.",
  "t.1im3ewnkxh5": "“[[ens.info]]” (alleen lezen, onderaan): “[[rep.cty]]” zegt hoeveel DXCC-landen (bestand cty.dat) zijn geladen (of “[[rep.notLoaded]]”); “[[rep.log]]” zegt hoeveel QSO’s hij uit het logboek heeft gelezen (of “[[rep.notRead]]”), handig om te zien of “eerder gewerkt” en “nieuw DXCC” gegevens hebben; “[[rep.file]]” verschijnt alleen als de omgeving van Aurora een ADIF-exportbestand opgeeft (AURORA_EXPORT_FILE).",
  "t.1infs1rz0m4": "De Pwr-schuifregelaar",
  "t.1ipaj5jk215": "“[[lay.settings]]” · “[[cluster.callsign]]” (alleen lezen): de roepletters waarmee Aurora bij de clusters inlogt, overgenomen uit [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]] en vanzelf bijgewerkt als je ze wijzigt; wachtwoorden zijn niet nodig. Ontbreken ze, dan zie je “[[cluster.callMissing]]”: vul ze in bij de persoonlijke gegevens.",
  "t.1ipvfcy7jl": "De telefoon wordt niet bijgewerkt",
  "t.1iq5jajdaiy": "Bovenaan Tx, Rx en Rapport; eronder een rij knoppen.",
  "t.1iqqfuer5ww": "[[rd.title]]: het kopdisplay (frequentie, modus, ontvangst of zenden, S-meter, vermogen, SWR, ALC). Elke stijl is een kaart met een voorbeeld met voorbeeldgegevens: klik op de stijl die je bevalt. De stijlen: [[rd.style.fluorescent]], [[rd.style.analog]], [[rd.style.color]], [[rd.style.amber]], [[rd.style.led]], [[rd.style.ledline]], de panelen [[rd.style.ft2000]] en [[rd.style.ic7610]] (ze nemen zelf de hele ruimte rechtsboven in en worden aangeklikt zoals het uitgebreide display), [[rd.style.icdual]], [[rd.style.icblue]] en de “bijna vierkante”: [[rd.style.icblueq]], [[rd.style.icblackq]], [[rd.style.yaesuq]] (ze nemen de plaats van de pictogrammen in). Instrumenten die de radio niet geeft, blijven uit.",
  "t.1irsegtowks": "“[[agent.kind.dxped]]”: de DXpedities die morgen beginnen, hoogstens drie, uit de NG3K-lijst. Heeft Aurora de lijst met landen die je nog nodig hebt bewaard (vanuit het DXpeditie-paneel, niet ouder dan 7 dagen), dan waarschuwt hij alleen voor die, anders voor alle. Standaard “Pop-up”.",
  "t.1it5l6mujpr": "“[[lay.lists]]” · “[[wish.countries]]” en “[[wish.grids]]”: bij “[[wish.countries]]” zet je de landnaam zoals je die in de berichtenlijst ziet (bijvoorbeeld Bulgaria of Fed. Rep. of Germany; maximaal 60 tekens per regel); bij “[[wish.grids]]” de locatorvakken van 4 tekens, bijvoorbeeld JN45 (twee letters van A tot R en twee cijfers).",
  "t.1itogjsvb7a": "In “[[contest.order.value]]” komen de berichten die je kunt beantwoorden eerst (CQ, QRZ en stations die jou roepen), daarna QSO’s tussen andere stations; “[[contest.onlyCq]]” verbergt die laatste. “[[contest.dupe]]” markeert stations die al op deze band zijn gewerkt en, als ze elders nog meetellen, de banden waar ze meetellen; dubbelklikken op een dupe vraagt om bevestiging. In multibandcontesten is dezelfde roepnaam op een andere band een nieuwe QSO: Aurora beantwoordt hem. Onder de tips staat, bij meer dan één band, een klein tabelletje met QSO’s, punten en multipliers per band. F1–F4 doen niets terwijl je in een veld typt of een venster open is.",
  "t.1iv4h5nm42k": "Het bandmenu begint op “[[dxmap.bandNow]]”: locatorvelden en PSK Reporter-spots van de band waarop je zit, in real time (een paar seconden) en elke 10 seconden ververst. “[[dxmap.onlyHeardMe]]” houdt alleen de lijnen naar stations die jou ontvingen; “[[dxmap.callLabels]]” schrijft de roepnamen altijd (uit, dan verschijnen ze bij muisaanwijzing). Tijdens het zenden loopt een rode lijn naar het station dat je oproept. Het tabblad “Kaart” van het logboekpaneel toont dezelfde kaart.",
  "t.1ivha3dpex1": "[[digi.mi.lock]]: vinkje = de zendfrequentie blijft waar hij is en je luistert elders (het rode paar op de waterval is de zending). Handig om een station te beantwoorden dat op een andere toon luistert, of voor split op een pagina vol signalen.",
  "t.1ixzltd3ygn": "Tussen de perioden staat nu een goed zichtbare balk met de UTC-tijd (#38). Tijdens een QSO verschijnen je zendingen in het RX-venster zodra ze starten, in de juiste volgorde (#42).",
  "t.1izvi4ybfcg": "Yaesu FTdx101D/MP, FTdx10, FT-991A, FT-710: de USB-kabel maakt twee virtuele COM-poorten aan (Silicon Labs CP210x). “Enhanced COM Port” is voor CAT, “Standard COM Port” voor PTT en CW-keying. Kies bij [[cat.rig]] het model met de naam van de radio; stel de CAT-snelheid in het radiomenu in (optie CAT RATE, zie de handleiding) en dezelfde bij [[cat.baud]].",
  "t.1j13tbe6io0": "Drie controles stoppen het zenden wanneer het niet de lucht in mag; het Tx-paneel toont de reden.",
  "t.1j22x9v8m6k": "[[sw.pg.digiMacros]]",
  "t.1j37s7ackm0": "Het filter vertraagt de tekst met ongeveer een derde seconde: dat is de prijs van zo’n scherpe snede. Zonder notches en zonder banddoorlaat komt de audio zonder vertraging en volledig ongewijzigd bij de decoder.",
  "t.1j407n77sut": "Download het installatieprogramma (Aurora_X.Y.Z_x64-setup.exe) van de Releases-pagina van Aurora op GitHub en voer het uit.",
  "t.1j7qfadeci2": "[[cat.profile]] · [[cat.profile.pick]]: lijst van de al opgeslagen profielen (leeg met “[[cat.profile.none]]” als er geen zijn). Een profiel kiezen kopieert zijn naam naar het vak ernaast, maar verandert nog niets: daarvoor heb je “[[cat.profile.load]]” nodig.",
  "t.1jasswi1ga8": "Alleen met Hamlib: [[cat.port]]. Typ of kies uit de lijst de poort van de radio: op Windows COM3, op Linux /dev/ttyUSB0, /dev/ttyACM0 of beter /dev/serial/by-id/… (die verandert niet bij een herstart). Voor een radio op het netwerk (rigctld van een ander programma, flrig) schrijf je adres:poort, bijvoorbeeld 127.0.0.1:4532. De knop “[[cat.ports.refresh]]” leest de poorten opnieuw: druk erop nadat je de radio hebt aangezet of de kabel hebt aangesloten. Windows kan het COM-nummer veranderen als je de radio uitzet: controleer het opnieuw. Op Linux: lees het onderdeel over seriële poorten en de groep dialout.",
  "t.1jch5sbx91r": "[[agent.title]] · [[agent.enabled]]: vakje, standaard aan. Als het aan staat, start de agent met Windows en blijft zijn icoon naast de klok staan, ook als Aurora gesloten is (een klik opent Aurora). Als het uit staat, worden de tabel hieronder en de opties van het vak “[[agent.popup]]” grijs en kunnen ze niet worden gewijzigd. Wanneer uitzetten: als je niet wilt dat de agent op de pc draait.",
  "t.1jfgl2apct3": "[[digi.menu.file]] › [[digi.mi.macrosMerge]]: staat er een vinkje (standaard, voor elke modus), dan worden de macro’s van de huidige modus bij de basismacro’s gevoegd en wint voor dezelfde toets de macro van de modus; zonder vinkje vervangen de macro’s van de modus de basismacro’s helemaal (heeft de modus er geen, dan blijven de basismacro’s). De keuze geldt voor elke modus apart: haal het vinkje weg als je bijvoorbeeld één set macro’s voor RTTY wilt.",
  "t.1jhkz5ksrw8": "De volgende twee keuzelijsten kiezen de band (“[[dxmap.bandNow]]” volgt de radio, of “[[dxmap.allBands]]”, of één band) en de modus van de vierkanten (“[[dxmap.allModes]]”; alleen actief als “[[dxmap.squares]]” aan staat). Rechts telt “n in de lucht” de stations in de lucht.",
  "t.1jhukdxq2wd": "[[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.doppler]]. Wat de radio en de rotor doen tijdens een overvlucht. Elke wijziging wordt meteen opgeslagen. Voor Doppler moet de radio verbonden zijn ([[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]) en voor de rotoroptie de rotor ([[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]]). De transponder en de downlinkfrequentie kies je op de pagina Satellieten, niet hier.",
  "t.1jiu2djnrb2": "De pagina [[nav.fox]] (titel “[[fox.title]]”) is voor wie vanaf een DXpeditie zendt en veel stations tegelijk bedient. Om een DXpeditie te roepen heb je hem niet nodig: dan gebruik je Hound op het Station (zie “Fox zijn (Foxpagina)”). Linksboven: je roepnaam, de modus en de status; daaronder de opties en de opdrachtbalk.",
  "t.1jjdt2uhuef": "Het paneel Zenden",
  "t.1jkhl5ctdid": "Het getal in Aurora en dat in de radio moeten hetzelfde getal zijn, op twee manieren geschreven. Snelle controle: staat er in de handleiding “94h”, dan heeft Aurora 148 of 0 nodig.",
  "t.1jkl1hojcv8": "[[sw.digi.perMode]] · CW, “[[digi.cw.bandwidth]]”: 50, 100, 150 (fabriek), 250, 500 of 1000 Hz (breed, voor overzicht). Smaller haalt meer ruis en stations in de buurt weg, maar de toon moet gecentreerd zijn (AFC volgt hem): 50-100 Hz voor zwakke en drukke signalen, 250-500 Hz om te zoeken.",
  "t.1jm0yfgd1s7": "Het tandwiel met de pijl (genaamd “[[nav.more]]”) opent een klein menu: [[nav.settings]], [[nav.wiki]] en [[nav.news]]. [[nav.settings]] opent direct op de instellingenpagina die past bij waar je bent (de pagina en de modus in gebruik); op de telefoon of in de browser van een andere computer is dit item er niet, en instellingen kunnen alleen vanaf de pc worden gewijzigd. Sluit het met Esc of met een klik erbuiten. Het tandwiel is verlicht als je op een van deze drie pagina’s bent.",
  "t.1jm15df0wi2": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]: druk op “[[sup.prepare]]”.",
  "t.1jnamulbiwj": "“[[digi.ms.title]]” · [[digi.ms.personal]]: [[digi.f.myname]] (maximaal 30 tekens) en [[digi.f.myqth]] (maximaal 40), hetzelfde als in [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]. “[[digi.ms.close]]” sluit het venster.",
  "t.1jnndslg531": "De pagina [[nav.sat]] toont op een wereldkaart, met dag en nacht, waar de amateursatellieten zijn, hun passages boven jou, een hemelradar en de baangegevens. Hij kan ook de Doppler op de radio corrigeren en de rotor laten draaien om de satelliet te volgen.",
  "t.1jnpttcgvut": "Een station dat altijd in dezelfde modus zendt, ontvang je beter met “[[sstv.rx.lock]]” vast in de SSTV-instellingen: de andere modi worden dan genegeerd. Standaard geldt “[[sstv.rx.lockNone]]” en wordt de modus herkend aan de VIS.",
  "t.1jpz9a35s": "Zoek met “[[rot.set.launch]]” het “[[rot.set.model]]” en kies het, daarna de “[[rot.set.port]]” en “[[rot.set.baud]]” van de rotorinterface. In beide gevallen kies je het “[[rot.set.range]]”, dat zijn de graden die de rotor kan afleggen (standaard 0° … 360°; met “[[rot.set.rangeCustom]]” schrijf je de grenzen in “[[rot.set.rangeFrom]]” en “[[rot.set.rangeTo]]”): wijzig het als je rotor meer dan een volledige cirkel draait (bijvoorbeeld 0° … 450°) of een andere eindaanslag heeft. Druk dan op “[[rot.set.apply]]”.",
  "t.1jq1nobzjpc": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › [[sw.pg.contest]] staan de instellingen van de contests waarin MSK144 of Q65 mag (bijvoorbeeld ARRL VHF, CQ WW VHF, EU VHF). Het is hetzelfde formulier als op de pagina [[sw.sub.ft8]] › [[sw.sub.contest]], zonder het Fox-vak; het opent op de actieve contest, als die bij deze tak hoort. Met de eigen engine en een VHF-modus in gebruik brengt het tandwiel van de pagina [[nav.contest]] je hier.",
  "t.1juazpii2qi": "Als het decoderen vaak uitloopt, biedt het venster «[[hl.slow.yes]]» (de instelling «[[dec.slowPc]]» wordt «[[dec.slowPc.always]]») of «[[hl.slow.no]]» aan. Het lampje zelf verandert nooit iets.",
  "t.1judlqsglbk": "De pagina “PSK · RTTY · SSTV” past op één scherm: bovenaan de macroblokken (rechtsklik om te bewerken) met ernaast de keuze van IARU-band en frequentie; daaronder ontvangen en zenden (de scheiding ertussen is versleepbaar), rechts de tabbladen DX Cluster en Log met de huidige QSO, en onderaan de waterval. De modus (PSK31, PSK63, RTTY, CW) wijzig je in het menu “[[digi.menu.mode]]” (dat ook een link naar de SSTV-pagina heeft). Het menu “Weergave” zet aan: onderstreepte verzonden tekst, alleen hoofdletters, doorgestreepte nul, knipperend TX, haarlijnen op de waterval en standaardrapporten 599. Met split (Lock) is het rode paar op de waterval de zending: een klik verplaatst het, met Ctrl verplaatst in plaats daarvan de ontvangst. In het DX Cluster stemt een klik op een spot het signaal af op de ontvangsttoon en, met “up N” in de opmerking, verplaatst hij de zending; de knop “Spot DX” stuurt de spot naar DXSummit.",
  "t.1jv7qzb8840": "Kop · [[auto.status]] (label [[auto.on]] of [[auto.off]]): zegt of de automatisering aan staat. Als hij aan staat, beoordeelt Aurora bij elke cyclus de CQ's en antwoordt (of zegt in dry run wie het zou hebben beantwoord). STOP TX zet hem altijd uit.",
  "t.1jvsvcu4nl7": "[[cat.split]]: “[[cat.split.rig]]” (Rig) doet een echte split in FT8 en FT4 met CAT-PTT: de zend-VFO verschuift en de audio blijft tussen 1500 en 2000 Hz, zoals in WSJT-X. “[[cat.split.emulate]]” (Fake It) verplaatst de frequentie alleen tijdens het zenden. Beide werken met Hamlib, TCI en OmniRig; FT-991(A) Link kent alleen Fake It. Als je de Tx-frequentie tijdens het zenden verplaatst, volgt de radio meteen.",
  "t.1jwirwgfgpk": "[[auto.b2]]: bij meerdere CQ’s in dezelfde cyclus kiest Aurora er maar één, de zeldzaamste, de sterkste of de beste op score.",
  "t.1jwizxqszrl": "De squelch van Aurora kijkt nooit naar het volume: bij PSK gebruikt hij de fasekwaliteit, bij RTTY en CW de signaal-ruisverhouding. De drempel blijft dus geldig ook als je het volume van de geluidskaart verandert.",
  "t.1jxdcn44rxh": "Status “[[rot.state.error]]”: controleer of de COM-poort die van de rotor is (niet die van de radio) en dat geen ander programma hem open houdt; Aurora probeert het zelf opnieuw.",
  "t.1jxnhppjen0": "Het opent met het tandwiel van het tabblad “[[digi.tab.cluster]]”. De keuzes blijven op dit apparaat. Dezelfde onderdelen staan ook in de Instellingen, op de pagina “[[cop.title]]” van [[sw.sub.digi]]. Esc of een klik erbuiten sluit het.",
  "t.1jyb1p2d8zp": "In [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] bepaal je wanneer Aurora je waarschuwt met een geluid of met de gemarkeerde kaart. Dit is het eerste deel, het vak “[[not2.grpAlerts]]”; verderop heeft de pagina de vakken “[[snd.title]]” en “[[toast.grp]]”. De vinkjes in dit vak gelden meteen.",
  "t.1k1l4bu16bs": "“[[dxs.guide.title]]” (bovenaan, alleen lezen): vijf punten die uitleggen waarvoor de kaart dient, de zes labels, het raster, de banden en de kleuren. Er zijn geen vakjes.",
  "t.1k40irhkrpr": "Alleen de roepnaam van de Fox, de tijd en de code gaan naar de controledienst. SuperFox heeft een eigen controle die Aurora nog niet ontvangt.",
  "t.1k49u6mc6jh": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]. Hier kies je waarheen de QSO’s en de status van Aurora gaan: logboeken, hulpprogramma’s zoals GridTracker, JTAlert of QLog, logprogramma’s. Van boven naar beneden: het vak “[[cta.log.section]]”, drie vakken (“[[ens.g.udp]]”, “[[ens.g.adif]]”, “[[ens.g.tcp]]”), “[[int.title]]” en tot slot “[[ens.info]]”. Elk vak heeft een lampje, een “?”, “[[ens.test]]” en het resultaat van de laatste upload, zoals in [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]]. Wijzigingen sla je op met “[[sw.save]]”, ze gelden meteen (zonder herstart) en kunnen alleen vanaf de pc thuis worden gemaakt.",
  "t.1k5870uxnfx": "Het handigste: “call to me”. Het rinkelt telkens als een station je antwoordt.",
  "t.1k66t60oia1": "Een klik op een rij verplaatst de ontvangst naar dat signaal (de rij van het vergrendelde signaal is gemarkeerd); een dubbelklik opent de “[[digi.band.history]]”: alle tekst van de laatste 60 seconden, met de knoppen “[[digi.band.tune]]” (verplaatst de ontvangst erheen), “[[digi.band.toQso]]” (zet de roepnaam in de QSO) en “[[digi.band.close]]”. Na 45 seconden stilte sluit het kanaal (“[[digi.band.historyGone]]”).",
  "t.1k6cl1762wj": "[[gen2.wsjtx3]] · [[gen2.pounce]] (keuzelijst, standaard “[[gen2.pounceFirst]]”): welke CQ de knop “[[ctl.pounce]]” beantwoordt: [[gen2.pounceFirst]] (de eerste gedecodeerde), [[gen2.pounceMaxDist]] (de locator moet in de CQ staan), [[gen2.pounceMaxDb]] of [[gen2.pounceMinDb]]. Stations die je in deze sessie al hebt gewerkt, worden overgeslagen. [[gen2.pounceNone]] zet Wait and Pounce uit.",
  "t.1ka4doqv3g0": "“[[ens.g.hamqth]]” · “[[ens.k.HamQTHLookup]]” (standaard uit), “[[ens.k.HamQTHUser]]” en “[[ens.k.HamQTHPasswd]]”: HamQTH is een gratis roepletterlijst (registreer gewoon op hamqth.com). Aurora gebruikt het na QRZ.com, of in zijn plaats als die uit staat of de roepletters niet vindt: zo krijg je naam en stad zonder het XML-abonnement van QRZ. Dezelfde regels: alleen naam, stad en land, resultaten drie dagen in het geheugen, geen verzoek als het uit staat. “[[ens.test]]” opent een sessie.",
  "t.1kalhnd5his": "“[[int.title]]”: meer programma’s, elk met adres, poort en wat het ontvangt. Knoppen: “+ [[int.p.wsjtx]]” (2237), “+ [[int.p.adif]]” (2333), “+ [[int.p.multicast]]” (239.255.0.1).",
  "t.1kbe0eun7no": "Lukt het nog steeds niet? Stuur wie je helpt de exacte foutmelding die je ziet, of het ondersteuningspakket: [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] → “[[sup.prepare]]”. Het bevat de logboeken en de instellingen, zonder wachtwoorden.",
  "t.1kbuel2sbk": "Kies in [[gen2.decStart]] [[gen2.decStartEarly]] voor meer tijd om te antwoorden, [[gen2.decStartLate]] om late signalen te vangen; standaard [[gen2.decStartNormal]].",
  "t.1kd1fkh0uny": "Radio uit, duidelijk zichtbaar",
  "t.1kdpbt2ezzu": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.wspr]] stel je de baken (WSPR en FST4W) en het uploaden van spots naar WSPRnet in. De drie bedieningselementen in het vak [[sw.wspr.beacon]] zijn dezelfde als naast de modus wanneer WSPR of FST4W in gebruik is en werken meteen, zonder [[sw.save]]; het uploaden naar WSPRnet geldt met [[sw.save]] en bestaat alleen met de eigen engine.",
  "t.1ke0r1007a": "Met [[digi.mi.lock]] aan is het rode paar de uitzending en blijft het staan: een klik verplaatst de uitzending; met Shift ingedrukt verplaatst de klik in plaats daarvan de ontvangst (Ctrl+klik plaatst een notch).",
  "t.1ke1o23cl3v": "In het grote beeld: “[[sstv.clean.original]]” of “[[sstv.clean.cleaned]]” met dezelfde twee schuifregelaars als bij de ontvangst; het onderschrift met roepnaam, modus, metingen, tijd en synckwaliteit; het vinkje “[[sstv.rx.smooth]]” (zachte vergroting in plaats van scherpe pixels, alleen voor deze weergave).",
  "t.1kfgmmasif8": "Knoppen onderaan: [[sw.testCat]], [[sw.testPtt]], [[sw.close]], [[sw.save]]",
  "t.1kfjy4emkdy": "Twee meldingen vallen meer op dan de andere: het kaartje voor een nieuw DXCC, dat rechtsboven knippert, en de balk met de zoeklijst, bovenaan de pagina.",
  "t.1khls8o7ju4": "“[[sstv.layers]]” (links): “[[sstv.add.text]]”, “[[sstv.add.rect]]”, “[[sstv.add.ellipse]]”, “[[sstv.add.frame]]” en “[[sstv.add.bars]]” voegen een laag toe. In de lijst staan bij elke laag: “[[sstv.layer.up]]”, “[[sstv.layer.down]]”, “[[sstv.layer.hide]]” (of “[[sstv.layer.show]]”), “[[sstv.layer.dup]]” en “[[sstv.layer.del]]”. Als de lijst leeg is, staat er “[[sstv.layers.empty]]”.",
  "t.1kib551fpw0": "De bovenrand van het paneel (een dunne lijn) kun je slepen om de hoogte te veranderen (van drie rijen tot de helft van de kolom); de hoogte wordt onthouden.",
  "t.1kil71ov64s": "Het paneel is in de hoogte verdeeld: bovenaan de CQ’s in een horizontale strook van twee rijen (één station per vakje; als er meer zijn dan er passen, scrolt het vanzelf en stopt onder de muis); eronder de DXpedities, één regel per stuk, met vlag en datum, ook die binnen 120 dagen komen.",
  "t.1kn5j8wcgho": "Volledig onderdeel: «Updates»; «[[tab.updates]]».",
  "t.1knsrz0uuos": "Propagatie: alle panelen",
  "t.1kppp22q67t": "Elk QSO kan rechtstreeks naar eQSL, Wavelog/Cloudlog, ClubLog, QRZ.com, HRDLOG.NET en LoTW, zonder tussenliggend programma.",
  "t.1kppryvgfgk": "Schakel het in bij Instellingen › Station › SDR · TCI · QMAP → “QMAP page in the menu”: het item QMAP verschijnt bovenaan.",
  "t.1kqsisk9emz": "Als het installatieprogramma oud was, verschijnt bij de eerste start eerst de poster van de nieuwe versie: druk op “[[upd.poster.install]]”, Aurora werkt zichzelf bij, start opnieuw en pas dan begint de gids. Met “[[upd.later]]” begint de gids meteen.",
  "t.1krcgrff5qc": "“[[digi.rtty.title]]” · “[[digi.rtty.factory]]”: zet alleen de fabriekswaarden van de gekozen set terug (Set 1 en 4: 170 Hz en 45,45 baud; Set 2: 22 Hz en 45,45 baud met de discriminator; Set 3: 30 Hz en 10 baud). “[[confirm.ok]]” slaat de gekozen set op en neemt hem in gebruik; “[[confirm.cancel]]” laat alles zoals het was.",
  "t.1ksu63cdmi1": "[[aud.mode]] (vak en lijst): of Aurora de ontvangen perioden als audiobestanden opslaat. “[[aud.save.0]]” (standaard) slaat niets op; “[[aud.save.1]]” bewaart alleen perioden met minstens één gedecodeerd bericht; “[[aud.save.2]]” slaat alles op. Elk bestand is een WAV (12 kHz, 16 bit) van ongeveer 360 kB per periode van 15 seconden, en Aurora verwijdert ze zelf na het aantal dagen bij “[[aud.keep]]”; met “[[aud.save.2]]” loopt de schijf toch snel vol. Zet het alleen aan om een decodeerprobleem te zoeken.",
  "t.1kt5z6okc1r": "[[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]]. Hiermee bestuur je Aurora, dat op de pc draait, vanaf een telefoon of tablet op het thuisnetwerk. De pagina heeft vier vakken onder elkaar. Je kunt hem alleen wijzigen vanaf de pc waarop Aurora draait: als je hem vanaf een telefoon opent, wordt de wijziging geweigerd en verschijnt “[[acc.pcOnly]]”.",
  "t.1ku4hm4fo5q": "[[lay.options]] · [[fil.nonStandard]]: selectievakje, standaard uit. Verbergt berichten met vrije tekst en ongebruikelijke formaten (contest, telemetrie) en laat de normale QSO's staan. Zet het aan om de lijst op te schonen; zet het niet aan tijdens een contest.",
  "t.1kuju737m0l": "[[ap.text]] · [[ap.fontData]]: het lettertype met vaste breedte van decodes, frequenties en tijden, zodat de kolommen netjes uitgelijnd blijven. Standaard JetBrains Mono; alternatieven Consolas, Cascadia Mono, Courier New.",
  "t.1l1azje4nrq": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], eerste vak. CAT is de opdrachtkabel: daarmee leest en wijzigt Aurora de frequentie en de modus van de radio en bedient het de PTT. De items veranderen met de gekozen [[cat.backend]]: hieronder staat per item wanneer het verschijnt. Geldige keuzes gaan na een moment vanzelf in ([[cat.apply]] past ze meteen toe); ze kunnen alleen worden gewijzigd vanaf de pc waarop Aurora draait.",
  "t.1l3myjbzmek": "Band Hopping",
  "t.1l736q7gops": "Voor de volgende QSO’s: zet in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] “[[int.resend]]” aan bij de ontvanger van je logboek (zie “Logboek gesloten: QSO’s komen later aan”). Aurora bewaart de QSO’s die gemaakt zijn terwijl het logboek dicht was en stuurt ze vanzelf zo’n 15 seconden nadat je het weer opent, in de volgorde waarin je ze maakte. Het werkt voor een logboek op dezelfde pc (adres 127.0.0.1) met “[[int.adif]]” of “[[int.n1mm]]”.",
  "t.1l7gyjvv4t": "De meest gebruikte plaatshouders: <MYCALL> je roepnaam, <CALL>, <NAME>, <QTH> en <WWLOC> van het andere station, <RSTS> en <RSTR>, <DATE>, <TIME>, <BAND>, <MODE>. Handige opdrachten: <AUTOCQ>, <SAVEQSO> (komt vóór de opruimopdrachten), <CLEARQSO>, <FQ:14070.5> (verplaatst de radio zodat het signaal op die frequentie valt), <AUDIOFQ:1500>, <WPM:20> en <BAUDRATE:45.45>. <TUNE>, <BOOKMARK> en <MACROS:file> staan in de lijst, maar antwoorden nu alleen “Command not available yet”.",
  "t.1l89kj9kpyd": "[[snd.title]] · drie knoppen: “[[snd.auto]]” geeft elke gebeurtenis een ander geluid, zo gekozen dat je de belangrijkste op het gehoor kunt onderscheiden; “[[snd.clear]]” haalt het geluid bij alle gebeurtenissen weg (dan speelt er niets tot je er weer kiest); “[[snd.stop]]” stopt het geluid dat nu speelt. Standaard hebben alleen de gemarkeerde melding voor nieuw DXCC en het gelogde QSO een geluid.",
  "t.1l8jdfbu153": "[[nav.settings]] › [[sw.sec.access]] › [[tab.updates]]. Het zegt welke versie van Aurora je gebruikt, of er een nieuwe is en hoe vaak er gezocht wordt. De controle maakt contact met de GitHub-site waar Aurora zijn versies publiceert en leest alleen de laatste release (naam, notities en adres). Op de pc downloadt Aurora een nieuwe versie, zodra die gevonden is, meteen op de achtergrond en controleert de handtekening, maar installeert hem pas als je erom vraagt. Wijzigingen in de velden worden vanzelf bewaard (“[[sw.updatesSelf]]”).",
  "t.1lan6yye1bh": "[[sat.set.update]] · [[sat.set.every]]: uitklaplijst met [[sat.set.manual]], elke 6 uur, elke 12 uur, elke dag (fabriek), elke 2 dagen, elke 7 dagen. Vaker als je satellieten volgt waarvan de baan snel verandert; “[[sat.set.manual]]” als je alleen zelf wilt updaten.",
  "t.1lb7266qm92": "[[gen2.fox]] · [[gen2.showOtp]]: selectievakje, standaard uit. Toont tussen de decodes ook de regels met de Fox-code (CALL.123456), die normaal verborgen zijn. Zet het aan uit nieuwsgierigheid of om te controleren.",
  "t.1lc1paiuq0d": "Het vak RX/STOP: groen “RX” als je luistert; terwijl je zendt wordt het de rode knop “[[stop.button]] (Esc)” en een klik stopt de zending meteen. Een dubbelklik op “RX” doet wat “[[ctl.clear_dx]]” doet: het maakt het station vrij en wist de QSO-berichten.",
  "t.1ldzqn2e27i": "In Bandactiviteit hebben de kolommen koppen en goed zichtbare lijnen, zoals in de DX-cluster: sleep een kop om de kolom te verplaatsen, de rechterrand om hem breder te maken (dubbelklik op de rand: past zich aan de inhoud aan); rechtsklik op de koppen: „[[cluster.cols.reset]]”. Volgorde en breedtes worden onthouden.",
  "t.1leq5wewlcy": "Kolommen, van links: de UTC-tijd (of de leeftijd van het bericht, als je dat aanzet in [[sw.pg.messages]]), het rapport in dB, DT (het tijdverschil in seconden met jouw klok: dicht bij nul is goed), de audiofrequentie in Hz (alleen in Bandactiviteit), het bericht, de vlag en het land met afstand en richting (als je ze aanzet in de voorkeuren) en tenslotte het gekleurde label. Tx-rijen (je eigen uitzendingen) hebben “Tx” in plaats van het rapport en, als ze identiek worden herhaald, één rij met “×N”.",
  "t.1lesqrb69fw": "[[wfs.spectrum]] · [[wfs.gain2d]] en [[wfs.zero2d]] (−50 tot 50, standaard 0): de versterking bepaalt hoeveel de curve stijgt per dB signaal; de nulstand verschuift alles omhoog of omlaag. Ze werken alleen op de grafiek, niet op de waterval.",
  "t.1lfird6dd4q": "[[acc.pair]] · [[acc.showCode]]: knop. Hij maakt een eenmalige code en toont hieronder de QR, de code, de link om op de telefoon te openen en de adressen van de pc. Wanneer: om een nieuwe telefoon of tablet te verbinden. Zodra de telefoon is gekoppeld, verdwijnt de QR vanzelf en verschijnt een bevestiging.",
  "t.1lfzsw1w0p5": "[[digi.log.search]]: schrijf een roepnaam, ook een gedeeltelijke, en de lijst wordt beperkt tot de QSO’s die hem bevatten.",
  "t.1lge3qmk75c": "Telefoon en tablet",
  "t.1lhdhm58fjg": "De PTT is degene die in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] is gekozen (CAT met Hamlib of OmniRig): controleer dat hij niet op VOX is blijven staan.",
  "t.1loioodcann": "[[ap.text]] · [[ap.logSize]]: de grootte van het loglettertype, van 10 tot 24 px (standaard 12). De kolommen passen zich vanzelf aan: er wordt geen tekst afgesneden.",
  "t.1lvyxq21bej": "Status: “[[rot.state.connected]]”, “[[rot.state.moving]]”, “[[rot.state.off]]” of “[[rot.state.error]]”. Is de rotor uit, dan zegt de kaart “[[rot.offText]]” en leidt de knop “[[rot.openSettings]]” naar de instellingen.",
  "t.1lwp8g5nfda": "«Inschakelen»: langere wachttijd, nieuwe volgorde",
  "t.1lzxrpei3al": "Luisteren, fijn afstemmen, zenden, scannen en geheugens. Veel onderdelen hebben ook een knop in de statusbalk.",
  "t.1m5azjmn0bd": "“[[cluster.command]]”: kies de server (“[[cluster.command.server]]”, alleen verbonden servers), typ een commando (bijvoorbeeld sh/dx 20 voor de laatste 20 spots, of sh/users) en druk op “[[cluster.command.send]]”. Alleen vragen en instellingen; het antwoord van de cluster wordt niet getoond, maar de spots die volgen verschijnen in het paneel DX Cluster. Een niet-toegestaan commando of een server die niet verbonden is, geeft een waarschuwing.",
  "t.1m7yrckldff": "JT4 (submodus A) kies je in de modusschakelaar, zoals JT65 en JT9: periodes van een minuut, vier tonen 4,375 Hz uit elkaar. De officiële JT4-frequenties liggen op de microgolven; op HF-banden gebruiken de knoppen de JT65-frequentie.",
  "t.1m84pmgnudn": "[[cat.profile]] · [[cat.profile.name]]: de naam waaronder je een profiel opslaat of aanmaakt, maximaal 80 tekens (bijvoorbeeld “FT-2000 thuisstation” of “IC-705 portable”). Een ongeldige of al gebruikte naam wordt geweigerd met een melding.",
  "t.1mazfrzlv4e": "Als de COM-poort van de FT-991 wordt vastgehouden door het programma FT-991(A) Link, stuurt Aurora de CAT-commando's via UDP: frequentie, mode en PTT, zonder om de poort te vechten.",
  "t.1mcrge86y3h": "Het venster “[[digi.rx.title]]” toont de tekst die Aurora decodeert; het venster “[[digi.tx.title]]” is het vak waarin je schrijft wat je wilt zenden.",
  "t.1mekwp2jnkf": "Standaard: als het QSO compleet is, logt Aurora het meteen, zonder te vragen, en stopt het zenden. Om verder te gaan roep je opnieuw CQ of kies je een andere DX.",
  "t.1mf289yh8w0": "Berichten die tijdens je zending worden gedecodeerd worden getoond, maar de reeks beantwoordt ze niet.",
  "t.1mgnywzqrol": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.files]]. Het interne logboek bewaart elke QSO die Aurora heeft gelogd. Hier download je het als ADIF-bestand of voeg je je eigen geschiedenis eraan toe, zonder dubbelen. Hetzelfde vak staat ook bovenaan [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]], met de titel “[[cta.log.section]]”.",
  "t.1mi6c64pwgi": "Contest: de band of de modus is volgens de regels niet toegestaan, of een samengestelde roepnaam staat geen contestberichten toe. De link leidt naar de pagina [[nav.contest]].",
  "t.1mjm8oy8wyz": "[[sw.contest.title]] · [[contest.set.activity]] en [[contest.set.cqWord]]: de keuzelijst bepaalt de vorm van de contestberichten ([[contest.act.standard]], NA VHF, ARRL Digi, WW Digi, EU VHF, Field Day, RTTY Roundup (RU)); standaard is het die welke de regels voorzien. Het veld [[contest.set.cqWord]] wijzigt het CQ-woord; leeg gebruikt het woord uit de regels (getoond als hint). Wijzig ze alleen als de regels het vragen.",
  "t.1mmnuixmr07": "QMAP luistert tegelijk naar een stuk tot 90 kHz breed en decodeert elk Q65-signaal dat het vindt: handig op 6 m, 2 m en EME, waar stations over veel frequenties verspreid zijn. Alleen voor bezitters van een SDR-ontvanger: met een gewone radio (FT-2000, IC-7300 en dergelijke) heeft het niets om te lezen.",
  "t.1mns1xms7ct": "[[sw.tab.rotator]]",
  "t.1moll0yjdy8": "[[digi.menu.help]] › [[digi.mi.guide]]: opent de Gids van Aurora (helemaal, niet alleen het deel voor deze pagina).",
  "t.1moo47q4zlj": "Open in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] het vak “[[toast.grp]]”.",
  "t.1moq7aeiyb5": "Een rechterklik opent het menu. “Open Aurora” doet hetzelfde als de linkerklik.",
  "t.1mq4nvufifm": "Met de knop “[[ctl.spot]]” van het tabblad “[[digi.tab.cluster]]”. Je meldt aan DXSummit een station dat je hebt gehoord. Het werkt alleen als “Spot op DXSummit” aan staat in [[nav.settings]] › [[sw.fam.log]] › Online diensten.",
  "t.1mqui58y085": "Een DXpeditie heeft een rij met roepnaam, vlag, land, verkorte QSL-route en de datum: “until …” (in de lucht), “from …” (komt eraan, tot 120 dagen vooruit) of “ended …” (afgelopen, voor het aantal dagen dat je kiest in “[[onl.dxpedDays]]”). Het label “Fox/Hound” zegt dat je de expeditie in Fox/Hound hoort werken (je hebt Hound nodig om haar te werken).",
  "t.1mucbufzfgc": "Als je “[[jx.PromptToLog]]” hebt aangezet (standaard staat het uit), verschijnt er aan het eind van een QSO een venster midden op het scherm, zodat je de gegevens kunt controleren voordat ze in het logboek komen. Staat het uit, dan wordt de QSO zonder vragen vanzelf opgeslagen.",
  "t.1n0lohc57ij": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.jt]] staan de decodeeropties van JT65 en JT9, met de fabrieksinstellingen van WSJT-X. De pagina bestaat alleen met de eigen engine; de items gelden vanaf de volgende periode, na [[sw.save]]. FST4 en FST4W hebben hier geen eigen items.",
  "t.1n0sg4vvbuz": "[[auto.b1]]: vink de nieuwigheden aan die je wilt (nieuw land, nieuw op de band, [[auto.newMode]], grid, zone) en het minimale signaal.",
  "t.1n2v06cxt7k": "De pagina [[nav.contest]] doet alles in één programma: berichtenreeks van de contest, dupes, punten, multipliers, live score, rate en het bestand voor de organisator. De regels van WW Digi, ARRL Digi, ARRL Field Day, FT Challenge, ARRL VHF, CQ WW VHF, IARU MGM 50/70 MHz, EU VHF, ARI FT8 Activity, DARC FT4, RSGB FT4, PACCdigi, YBDXPI FT8, VHF-UHF FT8 Activity (EU en NA), NCCC FT4 Sprint en een «Custom» contest zijn inbegrepen.",
  "t.1n5w993z0iv": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]] › [[sw.pg.rx]]. Hoe Aurora SSTV-beelden ontvangt: modus, afstemming, automatisch luisteren, klok van de geluidskaart en uiterlijk van de viewer. Wijzigingen gaan door met “[[sw.save]]” onderaan (behalve “[[sstv.rx.smooth]]”). Verschijnt de melding dat een getal niet klopt, verbeter dan het veld: de correcties zijn hele getallen.",
  "t.1n5zdkgejfv": "“[[contest.qsoNow]]”: het station waarmee je in QSO bent en zijn automatische reeks ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): een klik op een rij kiest dat bericht, “[[contest.onAir]]” zegt welk er uitgaat. Is het station niet in de contest (het antwoordt met het rapport in dB), dan verschijnen “[[contest.normal.rpt]]”, “[[contest.normal.rrpt]]” en “RR73” om met de normale berichten af te sluiten: de QSO komt in het normale logboek en telt niet mee voor de contest.",
  "t.1n7uspiqh1n": "Om op de snelheid van de roeper te antwoorden gebruik je “TX op ontvangen snelheid” in het menu [[digi.menu.mode]], of de knop “[[digi.st.txAtRx]]” in de onderste balk: de zendsnelheid wordt die welke bij ontvangst is gemeten, afgerond op hele WPM. Dit werkt alleen als de ontvangst aan staat en er een signaal is.",
  "t.1n7wotaua2i": "Staat de radio in split, dan verschijnt een knop die hem terugzet naar simplex, wie hem ook aanzette: een «UP»-spot, FT8, de radio zelf of een ander programma. Nooit tijdens het zenden.",
  "t.1n89ohehd44": "Waarschuwingen bovenaan het vak: is OmniRig gekozen maar niet geïnstalleerd (“[[cat.omnirig.absent]]” in de lijst), dan meldt Aurora dat, en het is beter over te stappen op Hamlib, dat al is meegeleverd. Met Hamlib en zonder rigctld (het programma van Hamlib, meestal verwijderd door het antivirus) verschijnt een waarschuwing met de knop “[[cat.restore]]” (alleen Windows): die downloadt het opnieuw van de officiële release en controleert de vingerafdruk. Op Linux zet je rigctld naast Aurora of schrijf je het pad in de variabele AURORA_RIGCTLD.",
  "t.1n8jooh9mjh": "De audio-ingang en -uitgang van de radio kiezen.",
  "t.1n9j1c56due": "Als een bericht “verdwijnt”, probeer dan eerst [[fil.bypass]]: komt het terug, dan is het een filter op deze pagina. Elk item heeft ook de “?” met een korte uitleg.",
  "t.1n9px455ceb": "[[lay.settings]] · [[clock.servers]]: de NTP-servers, één per regel, van 1 tot 8, als naam of adres (met :poort als het niet 123 is). Aurora gebruikt die met de laagste netwerkvertraging. Standaard: it.pool.ntp.org, ntp1.inrim.it, time.cloudflare.com en time.windows.com. Wijzig ze alleen als een server niet antwoordt of om je eigen te gebruiken; bij ongeldige waarden verschijnt “[[clock.invalid]]” en wordt er niets opgeslagen.",
  "t.1n9ybcyuosc": "Dubbelklik op de spot (enkele klik op de pagina’s PSK, RTTY en CW, als je die hebt gekozen): ontvangen (VFO A) op de spot, zenden (VFO B) verschoven, split aan. Boven de tabel verschijnt “Split DX: Tx 14.030” met de knop “[[cluster.splitDx.off]]”.",
  "t.1na24bum64c": "“[[ens.g.dxsummit]]” · “[[ens.k.AllowSpotsDXSummit]]” (standaard aan): activeert de knop “[[ctl.spot]]” van het paneel “[[panel.cluster]]” op de pagina [[nav.station]]. De spot gaat nooit vanzelf weg: jij verstuurt hem, één keer per station, met de zendfrequentie van de radio plus de ontvangstfrequentie en de modus als opmerking, en hij wordt op jouw naam op internet gepubliceerd. Zet het uit als je de knop niet actief wilt hebben. “[[ens.test]]” leest de laatste spot van DXSummit om te controleren of de site antwoordt; er wordt geen spot verstuurd.",
  "t.1naa68bepjx": "Verwijderen, toevoegen en corrigeren kan alleen vanaf de pc of vanaf het thuisnetwerk (“[[exp.localOnly]]”). Bij een leeg logboek zegt de pagina “[[exp.empty]]”. Om een ADIF-bestand te importeren (je geschiedenis) zie je “Statistieken en de DXCC-kaart”, vak “[[logio.title]]”.",
  "t.1nb5s77g5m3": "“[[ens.g.eqsl]]” · “[[ens.k.EQSLSend]]” (standaard uit): stuurt elke gelogde QSO naar eQSL. “[[ens.k.EQSLUser]]” en “[[ens.k.EQSLPasswd]]” zijn de gebruikersnaam en het wachtwoord van je eQSL-account. “[[ens.k.EQSLNick]]” heb je alleen nodig als je account meer dan één “QTH” heeft (bijvoorbeeld thuis en portable): schrijf de naam van de QTH die je wilt gebruiken, anders laat je het leeg. “[[ens.test]]” logt in bij eQSL zonder QSO’s te versturen.",
  "t.1nbztqomue9": "Laat Log4OM de radio lezen via Aurora (gedeelde CAT).",
  "t.1ndvgssh1u4": "Kies wat er getoond wordt in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], vak “[[cqp.title]]”: soorten berichten, alleen bepaalde stations, te verbergen stations, maximaal aantal rijen.",
  "t.1nfuqa95elu": "Een foute waarde is rood gemarkeerd, met de reden onder het veld, en de QSO wordt pas opgeslagen als je dat hebt verbeterd.",
  "t.1nhlpa88l8i": "Knoppen bovenaan (onder de tekst “[[int.empty]]” of “[[int.addMore]]”): “+ [[int.p.wsjtx]]”, “+ [[int.p.bblogger]]”, “+ [[int.p.loghx]]”, “+ [[int.p.multicast]]”, “+ [[int.p.adif]]” en “+ [[int.p.n1mm]]”. Elke knop voegt een bestemming toe met de juiste beginwaarden voor dat programma (zie “Integrations: what each program receives”). Ze gaan uit bij de zestiende bestemming (“At most 16 destinations”).",
  "t.1nhqsuwcwtc": "Op het spectrum onder het beeld helpen vaste merktekens bij het afstemmen: de synchronisatie moet op de gele lijn van 1200 Hz vallen, zwart op 1500 en wit op 2300 (de gestippelde lijnen zijn de VIS en de voorloopton). Zodra Aurora de afwijking heeft geschat, toont een rode lijn waar de synchronisatie echt ligt. Onder het beeld toont “[[sstv.clean.cleaned]]” het van ruis ontdaan, ook terwijl het binnenkomt; het origineel verandert niet.",
  "t.1ninkrr3hrj": "Als “[[ctl.unavailable]]” verschijnt, zijn de bediening van Aurora niet bereikbaar: controleer of Aurora open is op de pc.",
  "t.1nkuvsk2v0q": "Standaard aan, je kunt ze uitschakelen: ze helpen problemen op te lossen zonder persoonlijke gegevens te sturen.",
  "t.1nq8adeziei": "Het paneel DX Cluster: filters en kolommen",
  "t.1nr5zmhuna": "Kolommen: “[[exp.col.date]]”, “[[exp.col.time]]”, “[[exp.col.call]]”, “[[exp.col.band]]”, “[[exp.col.mode]]”, “[[exp.col.sent]]” en “[[exp.col.rcvd]]” (de rapporten in dB die je gaf en kreeg), “[[exp.col.grid]]”, “[[exp.col.country]]” en de knop “[[exp.edit.btn]]”. Bij grote logboeken worden er 300 rijen tegelijk getoond: scrol naar beneden of druk op “[[exp.more]]”; filters, selectie en export gelden voor het hele logboek.",
  "t.1nrdr905wks": "Onderaan het paneel [[panel.tx]] (of in één rij, op de pagina met blokken) staan twee audioniveaus: “Rx”, de ingang, en “Pwr”, de uitgang naar de radio.",
  "t.1nrjmdq2y9g": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]. Internetdiensten die Aurora gebruikt voor spots, opzoekingen en propagatiegegevens. Ze zijn optioneel: op deze pagina zet je ze aan en uit wanneer je wilt. Aurora doet maar zelden verzoeken en stuurt niets door van wat je ontvangt of zendt, behalve waar het staat vermeld (spots, op jouw naam). De vakken “[[onl.psk]]”, “[[onl.solar]]” en “[[onl.dxped]]” worden meteen opgeslagen; die in de vakken met rijen (spots, opzoekingen) met “[[sw.save]]”. De WSPRnet-spot staat niet hier maar in [[sw.fam.modes]] › [[sw.sub.wspr]].",
  "t.1nsn7sqwcyz": "De titel “[[sstv.title]]” en ernaast een statuslabel: “[[sstv.state.sending]]”, “[[sstv.state.receiving]]” of “[[sstv.state.off]]”. Als je alleen luistert, verschijnt er niets (dat is de normale toestand).",
  "t.1nsus64hw9x": "Open [[nav.contest]], kies de contest in het menu en druk op “[[contest.activate]]”. Aurora stelt berichten en CQ-woord, exchange, Fox en Hound uit, AutoSeq aan, Hold Tx Freq en modus in; wat er eerst stond wordt onthouden.",
  "t.1nt2a4h3xfp": "Statusbolletje: [[fox.state.off]] (Fox uit), [[fox.state.waiting]] (Fox aan maar Enable Tx uit), [[fox.state.ready]] (klaar, wacht op de volgende periode) of [[fox.state.onair]] (in de lucht).",
  "t.1nt5janboxe": "“[[cop.choose]]”: “[[cop.double]]” (standaard) of “[[cop.single]]”. Kies de enkele klik als je sneller wilt gaan en niet bang bent de verkeerde rij te pakken.",
  "t.1ntjzddhowx": "Brengt het kiezen van een band de radio niet waar je hem verwacht, kijk dan in deze tabel: welke rij heeft [[freq.preferred]] aangevinkt voor die band en modus, en of de rij grijs is door de gekozen regio.",
  "t.1nv2yx6sed2": "“[[contest.tips]]”: het tempo van de laatste 12 uur en de waarschuwingen (“[[contest.alert.ok]]” als alles in orde is; verder begin, einde, onzekere QSO’s, verplichte menselijke start, uren activiteit). Bij meerdere banden staat er ook de tabel met QSO’s, punten en multipliers per band.",
  "t.1nxf0wro3n0": "Kies bij “[[digi.scan.title]]” hoe lang je op elk station blijft (“[[digi.scan.dwell]]”), of je bij het eerste stopt (“[[digi.scan.once]]”) en of de tijd en de frequentie van elk station in de tekst worden afgedrukt.",
  "t.1nyyqk07klz": "De kaart voor nieuw DXCC hangt niet af van “[[alert.button]]”: hij verschijnt hoe dan ook; alleen het geluid ervan hangt af van “[[alert.button]]”. Om geen kaart en geen geluid te krijgen, druk je op “[[newdx.off]]”.",
  "t.1nz9r3nc6ik": "Je kunt het venster vergroten of verkleinen of het paneel verplaatsen: de waterval behoudt de reeds getekende rijen.",
  "t.1nzr1mxhurj": "Laat QMAP uit bij de FT-2000 of andere radio’s zonder I/Q-stream: voor gewone Q65 volstaat de modusschakelaar op de pagina Station.",
  "t.1o19je3tq73": "Er is één contestlogboek per editie (de begindag staat in de bestandsnaam), zodat wekelijkse en maandelijkse contesten niet door elkaar lopen; logboeken van eerdere versies worden nog gelezen. Als de contest eindigt blijft het logboek zoals het is en is de fase twee dagen “beëindigd”: Aurora verwijdert nooit zelf QSO’s, ook niet als je begin en einde met de hand wijzigt. Het serienummer is altijd het aantal QSO’s in het contestlogboek + 1, ook na een verworpen QSO of “Reset”. In de Cabrillo blijft een ontbrekende exchange “-” en de controle meldt het; QSO’s op banden die de regels niet toestaan worden weggelaten, met een waarschuwing; CATEGORY-TIME en CATEGORY-OVERLAY worden alleen geschreven als je ze in de instellingen invult.",
  "t.1o2xhc31037": "Afstandsbediening: Tx-berichten en de opdrachtbalk",
  "t.1o3wjpjjrp3": "[[rot.set.connection]]: “[[rot.set.launch]]” (standaard) als de rotor op deze computer is aangesloten: Aurora start de meegeleverde rotctld zelf met model, poort en snelheid. “[[rot.set.remote]]” als rotctld al door een ander programma is gestart of op een andere computer draait. Meldt een waarschuwing bij “[[rot.set.launch]]” dat rotctld niet is gevonden, herstel dan Hamlib vanaf [[sw.pg.radio]] (knop “[[cat.restore]]”) of schakel over naar “[[rot.set.remote]]”.",
  "t.1o3zqh5j7cv": "Kies met de rechtermuisknop een vrije plek op de waterval: de rode Tx-balk gaat erheen.",
  "t.1o45n1jb3w0": "Andere dingen die de belasting verlichten: zet “[[jx.SWLMode]]” uit (het zoekt dieper en in een breder venster: het is alleen nuttig als je niet zendt) en sluit zware programma’s. Direct na het starten van Aurora, terwijl radio en audio nog opstarten, verschijnt de kaart niet (ongeveer 20 seconden), en een al getoonde kaart verdwijnt vanzelf na ongeveer 10 minuten.",
  "t.1o7o55g8zq9": "[[cqp.title]] · [[cqp.limit]]: getalveld van 5 tot 200, fabrieksinstelling 40. Hoeveel regels het venster [[panel.cq]] bewaart; de oudste vallen eruit. Verhoog het als je een langere lijst wilt.",
  "t.1oc2ghw18qs": "Kies op de QMAP-pagina onder “I/Q source” “SDR via TCI” met het adres (bijv. 127.0.0.1:40001) of “I/Q WAV file” met het pad; daarna periode en submodus (bijv. 60 s, A) en “Apply”. “+30 s” zoekt ook naar Q65-30, “Average” telt periodes bij elkaar op voor zwakkere signalen.",
  "t.1ocma4utw96": "Gezondheidslampje van het station",
  "t.1oeh4xw2ujr": "Wat wordt er naar de ontwikkelaars van Aurora gestuurd, en hoe zet ik dat uit?",
  "t.1oena7wqfvj": "“[[ens.test]]” (in elke dienst, behalve waar anders staat) controleert de al opgeslagen instellingen zonder een QSO te loggen. Vóór het opslaan staat er “je kunt testen nadat je de wijzigingen hebt opgeslagen”. Daarna zie je “[[ens.test.ok]]” of “[[ens.test.err]]” (houd de muis erboven voor details). De test draait één keer vanzelf als de pagina opent en de dienst aan staat, en ook zodra je een wachtwoord of sleutel bevestigt en opslaat. Ernaast staat “[[ens.st.title]]”: het resultaat van de laatste upload (“[[ens.st.ok]]” of “[[ens.st.err]]”) met de tijd; als er geen netwerk is, blijven de QSO’s in de wachtrij staan (“N QSO’s in de wachtrij”) en worden ze vanzelf opnieuw geprobeerd.",
  "t.1ofxzbd7vfn": "Om meteen naar het volgende item te springen, zonder te wachten, rechtsklik je op de bandbalk.",
  "t.1ogjcw0u5am": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: [[cat.backend]] FT-991(A) Link (UDP), [[cat.ft991.address]] 127.0.0.1:50001 (of de in FT991Link ingestelde), daarna [[cat.connect]].",
  "t.1ogwl5ntunj": "“[[sstv.tx.to]]”: de roepnaam van het andere station, voor de plaatsaanduiding {CALL} van de teksten; als het leeg is, gebruikt Aurora de DX die in het station is gekozen (grijs getoond in het veld). Alleen letters, cijfers en “/”.",
  "t.1oht1t6ifr4": "“[[int.n1mm]]”: voor elke QSO het XML-bericht “contactinfo” van N1MM Logger+ (basispoort 12060): gelezen door HRD Logbook en programma’s die N1MM nabootsen.",
  "t.1oimmcrprwt": "[[cop.title]]",
  "t.1oiyuq5cwtm": "[[sw.pg.digiScan]]",
  "t.1olh8317ke6": "De ontvangstpagina heeft ook de knop “[[sstv.rx.tx]]”: die zendt het beeld dat in “[[sstv.view.tx]]” is voorbereid en brengt je daarheen. Als de zending eindigt, gaat de pagina vanzelf terug naar ontvangen, dat nooit is gestopt: je kunt ook het volgende beeld voorbereiden terwijl er een binnenkomt.",
  "t.1oljgglqp10": "Onder de menu’s staat links de macrobalk: 12 toetsen per rij, 4 rijen (zie “De macrobalk”). Ernaast staat de bandkeuze: de knop toont de band en frequentie van de radio in MHz; een klik opent de lijst met frequenties van het IARU-bandplan voor de huidige modus, één rij per band. De bandnaam brengt de radio naar de hoofdfrequentie; de andere frequenties staan ernaast (een klein label geeft de IARU-regio aan als ze alleen daar gelden). De keuze is vergrendeld terwijl je zendt. In SSTV en in de tekstmodi is de lijst die van het IARU-bandplan, niet die van FT8.",
  "t.1oqzylbm8qv": "De pc decodeert te langzaam: het kaartje zegt hoeveel seconden per periode en biedt twee knoppen, “[[diag.slow_pc.to2]]” of “[[diag.slow_pc.to1]]”, die de decodeerdiepte meteen wijzigen (geldt vanaf de volgende periode), plus “[[diag.slow_pc.setting]]” om de instelling te openen. Als het vaak gebeurt, voldoet de pc niet aan de eisen (zie “Welke computer je nodig hebt”).",
  "t.1or9w39ewb0": "Een dienst met een wachtwoord of sleutel verschijnt niet: Windows biedt op deze pc geen bescherming van geheimen; alleen LoTW blijft over.",
  "t.1osf8rf5gdh": "[[sw.sub.digi]]: vier pagina’s, [[sw.pg.digiRxTx]], [[sw.pg.digiMacros]], [[sw.pg.digiScan]] en [[cop.title]]. De eerste twee slaan bij elke wijziging vanzelf op, in de engine van Aurora (schuifregelaars als je ze loslaat, getallen als je het veld verlaat). De scaneigenschappen en geheugens en de DX Cluster-opties blijven op dit apparaat.",
  "t.1ovap98yqn3": "Jouw station",
  "t.1oxid21krfy": "“[[qmap.spectrum]]”: het spectrum van het stuk met de gevonden signalen; eronder hoeveel kandidaten en berichten hij heeft gevonden en hoeveel seconden gegevens hij gebruikt. De Maanrij geeft azimut, elevatie en Dopplerecho vanaf je locator.",
  "t.1oxr4gmnslm": "De preset “[[cat.preset.title]]” (vak na de verbinding, voor bekende modellen) schrijft voor je snelheid 115200, PTT via CAT en CI-V 0: voor een IC-7300, IC-7610, IC-705 of IC-9700 is dat de veiligste manier. Controleer daarna of in het menu van de radio de CI-V USB-snelheid 115200 is en het CI-V-adres het fabrieksadres.",
  "t.1ozdi7tuoua": "[[sstv.log.his]] en [[sstv.log.my]]: de rapporten (standaard 59, maximaal 3 tekens).",
  "t.1p0k6o0ro6g": "[[clock.state]] (vak, met de testled naast de titel): zegt of de klok goed staat, “[[clock.good]]” of “[[clock.bad]]”, en toont [[clock.offset]] (hoeveel ms achter of voor op de servers), [[clock.delay]] (netwerkvertraging), [[clock.server]] (de gebruikte), [[clock.answered]] (hoeveel servers antwoordden) en [[clock.when]] (tijdstip van de laatste meting); is de tijd gecorrigeerd, dan verschijnt “[[clock.corrected]]”. Vóór de eerste meting staat er “[[clock.none]]”. Buiten tolerantie betekent voorbij de hieronder gekozen alarmdrempel.",
  "t.1p0t4u81ppf": "[[sw.station]] · [[gen2.grid]]: je Maidenhead-locator, 4 of 6 tekens (bijvoorbeeld IO91wm). Ze wordt gebruikt voor afstanden, richtingen (ook voor de rotor) en de kaart; FT8-berichten bevatten de eerste 4 tekens. Vul ze juist in: met een lege of foute locator kloppen afstanden en rotor niet.",
  "t.1p1rh6goeue": "In PSK, RTTY en CW kun je draaggolven en smalle storingen uit de audio halen met notches, en met de banddoorlaat alleen het signaal houden waarnaar je luistert. Ze werken vóór de decoder en de notches ook vóór het zoeken naar signalen in de hele band; de waterval blijft de audio tonen zoals die is.",
  "t.1p23wjrb01e": "Bovenaan: “[[sstv.tx.send]]” (toets F1) zendt het samengestelde beeld en wordt, terwijl je zendt, “[[sstv.tx.stop]]” (toets Esc). Ernaast verschijnt “[[sstv.tx.done]]”, “[[sstv.tx.aborted]]” of de fout van de laatste zending. De knop is grijs als je niet kunt zenden: dan verschijnt “[[sstv.tx.notReady]]”.",
  "t.1p526ct6pav": "De roepnaam van de zender staat vet in het bericht, zodat je hem meteen ziet; de volgorde blijft die van FT8 (aan, van, info).",
  "t.1p5u2n9yj1n": "Het paneel [[panel.cq]] heeft twee delen: links de stations die CQ roepen, rechts (als de NG3K-kalender aan staat) de lijst met DXpedities, met de titel “[[dxp.title]]”. De inhoud van de CQ’s kies je in “[[cqp.title]]” (zie “[[panel.cq]] en DXpedities”).",
  "t.1p8m3mbnpj1": "Eerste instelling: Hamlib → kies het model → kies de poort → [[cat.baud]] gelijk aan die van de radio → druk op [[cat.connect]] (vak [[cat.grp.test]]). Weet je poort en snelheid niet, probeer dan “[[cat.detect]]”. Voor de controles als het niet verbindt: zie het item “De radio verbinden: de checklist”.",
  "t.1pa9lywsvp2": "De roos: de volle naald is de antenne, de gestippelde de bestemming; de groene markering is het DX-station (korte weg), de oranje de lange weg. Heeft de rotor een bereik groter dan 360°, dan geeft een gele band op het kompas de overlap aan, waar je vanuit twee hoeken kunt aankomen (de dichtstbijzijnde wordt gekozen). Klik op de roos om de antenne in die richting te sturen (“[[rot.clickHint]]”).",
  "t.1pb1pvdwybs": "De frequentie van de radio in MHz, links. Ernaast het label RX of TX: TX terwijl je zendt, en de pagina verandert van uiterlijk.",
  "t.1pb3wk1m7v2": "Berichtentabel: “[[qmap.col.freq]]”, “[[qmap.col.sked]]” (de frequentie waarop het station zendt dat zijn eigen Doppler corrigeert), “[[qmap.col.mode]]” en “[[qmap.col.msg]]”. De knop “[[qmap.qso]]” zet de radio op dat signaal in Q65, met de juiste periode en submodus; als niet alles in orde is, zegt hij wat er ontbreekt (het midden van de slice, of dat de radio niet is verplaatst). Zonder berichten: “[[qmap.empty]]”.",
  "t.1pbabn0hgmk": "Op de waterval werk je met de muis. De belangrijkste gebaren staan in “De waterval”; hier de rest.",
  "t.1pckqyeogq6": "[[about.donateTitle]]: twee optionele links die in de browser openen: “[[about.donateButton]]” (een bijdrage, geen verplichting; Aurora is en blijft gratis) en “[[about.star]]” (de ster op de repository, die niets kost maar helpt).",
  "t.1pdjf40s2q1": "[[tab.schedule]] · [[sch.hour]] en [[sch.minute]] (twee getalvelden per rij, vijf rijen): het UTC-uur (0-23) en de minuut (0-59) waarop de wissel plaatsvindt. Het uur typen in een lege rij maakt de rij aan (met band 20m, die je daarna wijzigt).",
  "t.1pdpc7rgl48": "[[cop.columns]]: één vak per spotkolom, [[cluster.col.by]], [[cluster.col.freq]], [[cluster.col.call]], [[cluster.col.country]], [[cluster.col.mode]], [[cluster.col.comment]] en [[cluster.col.time]]. In de fabrieksinstelling zijn alle zichtbaar; haal het vinkje weg om er een te verbergen en ruimte te maken. Eén kolom moet altijd aan blijven: de laatste kun je niet uitzetten.",
  "t.1ph5e2phwwb": "[[ca.title]] · [[ca.run]]: opent een kaart die station, radio, audio, klok en telefoon in één keer controleert (zie “De kaart Alles controleren”). Hij sluit met “[[ca.close]]” of Enter.",
  "t.1piztfaz526": "Druk op de pagina [[nav.station]] op de band (bijvoorbeeld 40m): Aurora stelt zijn eigen frequentie in voor die band en mode, zonder de radio aan te raken.",
  "t.1plg9g16i9b": "Volledig onderdeel: «Een optie vinden in de Instellingen»; «Hoe de instellingen werken».",
  "t.1pm1q9uo0va": "[[cat.cat4om.key]]: het wachtwoord van de groep, alleen als de groep erom vraagt (anders leeg). [[cat.cat4om.radio]]: de naam van de radio in Cat4OM (bijvoorbeeld kenwood/ts-990), niet de naam van de groep; leeg = de eerste beschikbare radio. Antwoordt de beheerpoort niet of vraagt hij om een wachtwoord, vul dan in [[cat.cat4om.address]] de “Control”-poort van de groep in die Cat4OM of Decodium toont (bijvoorbeeld 127.0.0.1:5001).",
  "t.1pm3ikhiwro": "In een contest schakelen “Enable Tx” en Auto CQ zichzelf niet meer uit: als een QSO eindigt (of de DX aan iemand anders antwoordt, of de watchdog afgaat) wordt het station vrijgegeven en gaat het meteen terug naar CQ. Alleen jij stopt het, met Esc of het TX-vierkant. Bij standaardberichten (bijvoorbeeld DARC FT4) schakelt “Skip Tx1” zichzelf uit bij activering, zodat het eerste bericht de locator bevat en de uitwisseling volledig wordt verzonden.",
  "t.1pq1etxtlh2": "Vanaf een telefoon of tablet in het thuisnetwerk bedien je Aurora dat op de pc draait.",
  "t.1pqvj82xwh3": "Vak “[[logio.title]]” (standaard open): “[[logio.export]]” opent de pagina [[nav.log]] om te exporteren; “[[logio.import]]” voegt de QSO’s uit een eigen ADIF-bestand toe aan het logboek (tot 256 MB; QSO’s die er al staan worden niet dubbel toegevoegd; alleen vanaf de pc of vanaf het thuisnetwerk). Aan het eind staat hoeveel QSO’s hij heeft toegevoegd, hoeveel er al waren en hoeveel hij heeft weggegooid.",
  "t.1psrttb03bl": "De klok",
  "t.1pulxnwsbmn": "De kolom Modus komt uit de opmerking of uit de frequentie (zie “De modus van DX Cluster-spots”). De hele opmerking lees je door de muis over de cel te bewegen.",
  "t.1pum2pk1l1": "Alleen met Hamlib: [[cat.rig.search]] en [[cat.rig]]. Typ merk of model (bijvoorbeeld FT-2000 of IC-7300): de passende modellen verschijnen onder het vak, klik op het jouwe. Of kies uit de lijst “[[cat.rig]]” (het beginitem is “[[cat.rig.none]]”: met Hamlib en zonder gekozen radio blijft [[cat.connect]] uitgeschakeld). Ontbreekt je model, probeer dan een verwant model van hetzelfde merk. Een regel eronder zegt hoeveel modellen Hamlib heeft.",
  "t.1pv0k6vyo70": "[[lay.settings]] · [[clock.enabled]] (standaard aan): Aurora controleert de klok zelf met de gekozen tussenpozen. Uit wordt hij alleen met de knop gecontroleerd. Laat het aan.",
  "t.1pyx17dqp3l": "[[bfl.title]] · [[bfl.minSnr]]: getalveld van −40 tot 40; verbergt signalen die zwakker zijn dan de ingevulde waarde. Leeg = geen limiet. Verhoog hem als de band vol zit met bijna-ruis die je niet nodig hebt.",
  "t.1q4vbcjsu3r": "Dubbele QSO’s: hetzelfde logboek ontvangt via twee wegen (stroom, ADIF, doorsturen vanuit GridTracker of JTAlert). Houd er maar één.",
  "t.1q6je2jwmqd": "[[wfs.spectrum]]",
  "t.1q70sz2v7hl": "Wachtwoorden en sleutels (geheime velden): typ en druk op Enter, of verlaat het veld (in het veld zie je “[[ens.pw.type]]”); daarna toont het veld “[[ens.pw.savedShort]]” •••• met “[[ens.pw.change]]” (typ een nieuwe) en “[[ens.pw.remove]]” (wis de opgeslagen waarde van de pc). Het geheim wordt nooit teruggelezen en verlaat de pc nooit; het blijft “in afwachting” tot je op “[[sw.save]]” drukt.",
  "t.1q7xrk6nllj": "Aurora zegt dat het zendt maar de radio niet: wat controleer ik?",
  "t.1q8yg3bylzb": "De taal wijzigen: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], vak “[[ap.theme]]”, item “[[gen.language]]”. Het menu heeft de vlaggen van de zeven talen (Italiaans, Engels, Duits, Frans, Spaans, Portugees, Nederlands); met het toetsenbord: pijlen om te openen en te bewegen, Enter of spatie om te kiezen, Esc om te sluiten, Home en End voor de eerste en de laatste. De wijziging geldt meteen voor de hele interface, de Gids inbegrepen, en blijft op dit apparaat (de telefoon heeft zijn eigen keuze).",
  "t.1q8zhxoi4t9": "Links de zon en de bandcondities; rechts de kaart en de lijst van wie jou ontving (PSK Reporter): nieuwe ontvangstrapporten komen in realtime binnen, binnen enkele seconden, en de pagina wordt elke 10 seconden vernieuwd. Standaard aan; schakel het uit in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.1qjd9ur0oks": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]] › [[sw.pg.tx]]. Hoe Aurora SSTV-beelden zendt. Wijzigingen gaan door met “[[sw.save]]” onderaan het venster. De roepletters die worden uitgezonden zijn die van het station ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]).",
  "t.1qjgrrs264w": "[[not2.grpMapColors]] · [[kind.grid_worked]] en [[kind.grid_confirmed]]: de twee kleuren van de locatorvakken op de pagina DX-kaart (gewerkt, bevestigd). Wijzig ze als je geel en groen niet uit elkaar kunt houden.",
  "t.1qjljgk37g8": "Het paneel Log en de DXCC-kaart",
  "t.1qljk09ybmv": "[[lay.options]] · [[fil.bypass]]: selectievakje, standaard uit. Toont alles zonder de filters te wissen: zet het uit en de filters zijn weer zoals ze waren. Gebruik het om snel te controleren wat je verbergt.",
  "t.1qn6uq1vslt": "[[auto.b4]] · [[auto.excluded]] (tekstveld): roepnamen waarop Aurora nooit antwoordt, gescheiden door komma's (bijvoorbeeld IU3ABC, IK1ABC); 3 tot 13 tekens, alleen letters, cijfers en “/”, tot 200. Ze worden in hoofdletters opgeslagen.",
  "t.1qnqcwyai3c": "Kiest de modus en toont voor RTTY en CW ook de onderdelen die die modus nodig heeft. De modus verandert meteen, zonder vensters te openen.",
  "t.1qq3b86nnjf": "Met [[ctl.answer_all]] aan wordt elk station dat je roept vanzelf in de wachtrij gezet.",
  "t.1qqko6bkngw": "[[bfl.title]] · [[bfl.hideToMe]]: selectievakje, standaard uit. Het haalt de berichten aan jouw roepnaam uit [[panel.all]]; de antwoorden blijven in het venster [[rxw.title]]. Zet het aan als je ze niet twee keer wilt zien.",
  "t.1qv03nv9ppk": "Het wordt aan- en uitgezet in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] met “[[cluster.splitDx.set]]” (standaard aan; het “?” ernaast legt alles uit).",
  "t.1qv4awrekwi": "Wat als “gezocht” telt, staat in [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (roepnamen, prefixen, landen, locatorvelden, banden, pauze tussen twee meldingen voor hetzelfde station, melding op de telefoon).",
  "t.1qyl3k2z4ne": "PRE en ATT: vanuit uit doorlopen ze de waarden die de radio accepteert (bijv. 10 en 20 dB) en gaan dan terug naar uit.",
  "t.1r08s26z8d4": "Om de gegevens te controleren voor het opslaan: vink “[[ens.k.PromptToLog]]” aan en druk op [[sw.save]]. Aan het eind van het QSO verschijnt het bevestigingsvenster: verbeter [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] of [[lp.f.comment]] en druk op [[lp.log]]; met [[lp.discard]] komt het QSO niet in het log.",
  "t.1r2fg4ttgdc": "“[[pair.button]]”: koppelt. Als alles goed gaat, laadt de pagina opnieuw en verschijnt het station. De telefoon onthoudt het adres (ook de vaste naam aurora.local) om Aurora terug te vinden als het IP van de pc verandert.",
  "t.1r3dp264fbm": "Een zojuist gelogd QSO knippert bovenaan. Hoeveel QSO’s je ziet: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] → “[[gen.log4omCount]]”.",
  "t.1r6gh0c0a5i": "[[cat.profile.delete]]: verwijdert het profiel dat je in “[[cat.profile.pick]]” hebt gekozen (de radio en de huidige instellingen veranderen niet). Er is geen bevestiging en het kan niet ongedaan worden gemaakt: heb je het nog nodig, maak het dan opnieuw aan. De knop blijft uitgeschakeld zolang je geen profiel kiest.",
  "t.1r6ygxz7n97": "[[aud.input]] · [[aud.vol.in]]: de schuifregelaar voor het opnamevolume van het gekozen apparaat (met de AUTO-aanduiding ernaast als die aan staat). Zie het onderdeel over de schuifregelaars Rx, Pwr en AUTO. Verschijnt “[[aud.vol.off]]”, dan kan het volume van dat apparaat hier niet worden aangepast.",
  "t.1r7xjwn5s98": "Bovenaan staat de tabel met de condities, dezelfde als op de pagina [[nav.propagation]]: vier bandgroepen (80-40 m, 30-20 m, 17-15 m, 12-10 m), een kolom voor de dag en een voor de nacht, met drie kleine balkjes en het oordeel (“[[prop.cond.Good]]”, “[[prop.cond.Fair]]”, “[[prop.cond.Poor]]”). De huidige kolom is gemarkeerd met “[[prop.here]]” en de groep waarop de radio staat met “[[prop.tuned]]”.",
  "t.1r9wsj1w0ot": "Naast de modus verschijnen de submodi, allemaal kleine keuzelijsten. JT4: [[mode.jt4sub]] van A tot G. JT65: [[mode.jt65sub]] A, B of C. Q65: [[mode.q65period]] (15, 30, 60, 120 of 300 seconden) en [[mode.q65sub]] van A tot E. FST4 en FST4W: [[mode.fst4period]] (FST4 van 15 s tot 30 minuten, FST4W van 2 tot 30 minuten). De periode en de submodus moeten gelijk zijn aan die van het station waarmee je werkt.",
  "t.1raz2iaalxv": "Spots komen niet aan op WSPRnet: controleer of [[ens.k.WSPRnetUpload]] aan staat en opgeslagen is, of roepletters en locator zijn ingevuld, of CAT de frequentie leest, en lees “[[ens.st.title]]” voor de fout.",
  "t.1rg6npr7jlo": "NB, NR, NOTCH en ATU: één klik zet aan, nog een klik zet uit.",
  "t.1rhb4eq28xk": "De pijl ▲ naast Tx kopieert de Rx-frequentie naar Tx (“[[ctl.rx_to_tx]]”); de pijl ▼ naast Rx kopieert Tx naar Rx (“[[ctl.tx_to_rx]]”).",
  "t.1rhna7q8olw": "Waar ze heen gaan: naar de dienst van wie Aurora ontwikkelt. Updates (de versiecontrole) zijn iets anders: ze maken contact met de GitHub-releasesite en worden uitgezet met “[[upd.enabled]]” in [[tab.updates]]. “[[sup.prepare]]” en “[[bak.make]]” versturen niets: ze maken alleen een zip op je Bureaublad.",
  "t.1riobx5qgg8": "[[sw.behavior]] · [[gen2.monitorOff]]: met het vakje aangevinkt blijft de ontvangst bij het starten uit en zet je hem aan met de monitorknop; niet aangevinkt (standaard) begint Aurora al te luisteren. Werkt vanaf de volgende start. Vink het aan als je niet wilt dat Aurora decodeert of zendt zodra het opent.",
  "t.1rm6giw4t0x": "Poster midden op het scherm: hij toont het lint “[[upd.poster.ribbon]]”, het nieuws van de versie in jouw taal (onder “[[upd.poster.news]]”) en de knoppen “[[upd.open]]”, “[[upd.later]]” (verbergt hem tot de volgende versie) en “[[upd.poster.install]]”. Als het pakket al is gedownload en gecontroleerd, begint vanzelf een aftelling van enkele seconden met “[[upd.poster.cancel]]” om die te stoppen; hij begint nooit terwijl de radio zendt. Bij de eerste start met een oud installatieprogramma komt hij eerst, met “[[upd.poster.firstRun]]”.",
  "t.1rnxt49n999": "“Rx”: een indicator van het niveau van de binnenkomende audio (piek- en gemiddeld niveau in dB, door erover te bewegen) met een oordeel — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] of [[rxl.state.overdrive]] — en de hint wat je moet doen. Het juiste niveau is “Good”.",
  "t.1rocambmqij": "Bovenaan staan zes labels: drie voor het land — “NEW ONE” (nog nooit gewerkt op een band of in een modus), “NEW BAND” (nog nooit op deze band), “NEW MODE” (nog nooit in deze modus) — en drie voor de locator: “NEW GRID”, “GRID BAND” en “GRID MODE”. Ze gaan aan als ze voor het station gelden; als je er met de muis boven blijft, lees je wat elk betekent.",
  "t.1roiyfbc9hz": "Volledig onderdeel: «Het paneel Signalen (CW en PSK)»; «Het paneel “[[digi.band.title]]”».",
  "t.1rpt7b90t8z": "De modus van DX Cluster-spots",
  "t.1rr2r697p2n": "Modusgegevens (bij PSK31 “31 bd”, bij PSK63 “63 bd”, bij CW de snelheid in WPM): een klik opent het venster “[[digi.ms.title]]”.",
  "t.1rse3hhz1b0": "[[acc.pair]] · met de QR op het scherm: de QR zelf (scan hem met de camera van de telefoon en open hem in Chrome of Safari: in Messenger of WhatsApp opent de pagina vaak niet), “[[acc.code]]” (typ hem met de hand als er geen camera is), “[[acc.link]]”, “[[acc.addresses]]” en hoeveel minuten de code geldig is. Zolang de QR open is, wordt de lijst met apparaten elke 2 seconden opnieuw gelezen.",
  "t.1rtzss6tqwi": "[[lay.settings]] · [[clock.auto]] (standaard uit): als de afwijking de drempel overschrijdt, verandert Aurora zelf de Windows-tijd. Aurora moet als administrator zijn gestart en het kan alleen vanaf de eigen pc worden aangezet. Lukt dat niet, laat het dan uit en corrigeer met de hand met “[[clock.correct]]” of via de Windows-instellingen.",
  "t.1rufjj5pua3": "Ctrl+Enter zendt de inhoud van het vak (als het zenden niet open is): alle tekst gaat de lucht in, daarna ga je terug naar ontvangen.",
  "t.1rukb0zxmjb": "Ingang: de kaart die het geluid van de radio ontvangt (meestal “Microphone (USB Audio Device)”).",
  "t.1rw20gbn18l": "[[gen.screen]] · [[gen.showDistance]] en [[gen2.azimuth]]: de eerste, standaard aan, toont de afstand vanaf je station bij berichten met een locator; de tweede, standaard uit, voegt het azimut toe, dus de graden waarheen je de antenne moet richten. Zet het azimut aan als je een richtantenne hebt.",
  "t.1rzewyz4ro5": "Een klik opent het venster «[[hl.title]]»: een regel voor CPU, decoderen, audio, CAT en klok met hun stip en wat te doen, en de grafiek van de laatste 10 minuten (CPU in procent en decoderen in procent van de beschikbare tijd, met de grens van 70 % gestippeld). Sluiten met ×, «[[hl.close]]» of Esc.",
  "t.1rzidah40i4": "Andere vakken van de pagina [[nav.contest]]: het bandadvies, de multiplierkaart en het contestlogboek staan in het tabblad “[[contest.tab.race]]”, onder de decodes; training en analyse hebben elk een tabblad.",
  "t.1rzpec2w1jr": "Boven de waterval, alleen bij CW en bij PSK31/PSK63: een lijst van alle signalen in de audioband, samen gedecodeerd, één rij per signaal. Bij RTTY bestaat het niet. Je zet het aan met het onderdeel “[[digi.band.mi]]” (CW) of [[digi.band.miPsk]] in het menu [[digi.menu.options]] en het is zichtbaar als [[digi.band.view]] ook is aangevinkt in het menu [[digi.menu.view]]; standaard staat het aan.",
  "t.1s0s73ycfgk": "[[sstv.log.call]]: de roepnaam, in hoofdletters. Eronder staat een regel met het land (uit cty.dat) en, als het opzoeken antwoord gaf, “Gegevens van” gevolgd door de naam van de gebruikte dienst; als het station er niet in staat, “[[sstv.log.notFound]]”.",
  "t.1s1oz3ztszu": "De QSO-schakelaars",
  "t.1s2btcanvky": "Controleer de Rx-balk: die moet “Goed” zeggen.",
  "t.1s2n8ru7w0h": "CQ roepen",
  "t.1s69opejj7j": "[[ens.g.alltxt]] · [[ens.k.WriteDecodedALLTXT]] (standaard aan): schrijft elke decodering in het bestand ALL.TXT, handig voor controles en statistieken. Zet het uit als je het niet nodig hebt en een kleiner bestand wilt.",
  "t.1s7oy1wvrhd": "In PSK toont de onderste balk S/R en IMD (de IMD wordt gemeten tijdens de doorlopende faseomkeringen aan het begin van elke uitzending; onder -20 dB is het signaal schoon). De squelch kijkt naar de fasekwaliteit (0-100), niet naar het volume: bij 15 wordt ruis niet afgedrukt en komen signalen door tot ongeveer -10 dB. De AFC volgt het station alleen als er een PSK-signaal is, dus bij ruis blijft hij stil.",
  "t.1s9o0yvjsif": "Zet de Pwr-schuif hoger en let op de ALC op het display (onderdeel “De Pwr-schuif”).",
  "t.1sa47j02te6": "“[[ens.g.adif]]” · “[[ens.k.EnableUDP2adifBroadcast]]” (standaard aan), “[[ens.k.UDP2Server]]” (127.0.0.1) en “[[ens.k.UDP2ServerPort]]” (2237): de secundaire UDP-server stuurt voor elke QSO alleen het ADIF-record als tekst, één datagram per QSO, voor logboeken die het zo ontvangen (Log4OM 2, WaveLogGate). Let op: standaard wijzen primair en secundair allebei naar 127.0.0.1:2237; laat alleen aan wat je logboek nodig heeft of geef de andere een andere poort. Als hetzelfde adres ook in “[[int.title]]” staat, stuurt Aurora de QSO maar één keer. “[[ens.test]]” stuurt een Heartbeat naar de tweede server.",
  "t.1sb89l13z26": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.pg.qso]] bepaal je hoe QSO’s worden gelogd (voor elke modus), welke QSO’s in het log gelden als “al gewerkt” en wat Aurora bij het starten doet. De onderdelen worden opgeslagen met [[sw.save]] onderaan het venster; bijna alle werken meteen.",
  "t.1seypt02j9w": "Aurora: verplaats de primaire server naar een andere poort (bijvoorbeeld 2238, of die van GridTracker), zodat 2237 vrij blijft voor Log4OM.",
  "t.1sgay2jjqf8": "De kaart rechtsboven voor een nieuw DXCC (vlag, roepletters, land): onder de kaarten staat de knop “[[newdx.off]]”, die ze allemaal uitzet. Om ze terug te krijgen: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], vakjes “[[not2.popNew]]” en “[[not2.popNewBand]]”. Om ze te verplaatsen: “[[not2.popPos]]”. De × op een kaart (“[[newdx.close]]”) sluit alleen dat station, tot Aurora de volgende keer wordt gestart.",
  "t.1sgb3odor9o": "Kop: het aantal signalen en hoeveel er CQ roepen, en de legenda van onzekere tekens (in grijs). Als het leeg is, zegt het paneel dat er nog geen signaal is herkend: ze verschijnen vanzelf.",
  "t.1sigctm4a3z": "Zet [[ctl.enable_tx]] aan: in de volgende periode zendt Aurora de CQ. Wie jou antwoordt, wordt automatisch bediend als [[ctl.autoseq]] aan staat. Als het QSO klaar is, begint de CQ alleen vanzelf opnieuw als [[ctl.auto_tx]] aan staat; met [[ctl.single_qso]] aan stopt Aurora na één QSO.",
  "t.1sik69dc9dg": "Statistieken en de DXCC-kaart",
  "t.1skigz1cxph": "[[sw.sec.sstv]] › [[sw.pg.tx]]",
  "t.1skl7kd3qfl": "Bij elke frequentiewijziging wordt de kaart leeggemaakt: alleen stations die daarna gehoord worden blijven staan.",
  "t.1sklcw8pdg1": "DX Cluster en menu’s met volle achtergrond",
  "t.1smhh26ne7x": "Satellieten: passages, Doppler en rotor",
  "t.1snkagke9i": "[[fil.decode]] · [[dec.aggressive]]: numeriek veld van 0 tot 10, fabriekswaarde 4. Hoe snel onzekere JT65-berichten worden geaccepteerd: 0 is voorzichtig, 10 geeft meer berichten en ook meer foute. Verhoog het als je zwakke JT65-signalen mist, verlaag het als er te veel foute berichten verschijnen.",
  "t.1sq3eav55us": "[[gen2.bandHop]] · [[gen2.bandHopList]] (tekstveld, standaard leeg): items gescheiden door komma's, bijvoorbeeld “FT8 20m, FT4 40m, MSK144 6m” (de frequentie komt uit de frequentietabel) of maximaal 8 eigen frequenties in kHz (bijvoorbeeld 14090), altijd in FT8. Ongeldige items worden weggegooid; met een lege lijst doet Band Hopping niets.",
  "t.1sqciq6bwrk": "Kies in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] de stijl bij “[[rd.title]]”: elke stijl heeft zijn eigen voorbeeld.",
  "t.1ssewnwrcgh": "“[[l4.title]]” · “[[l4.choose]]”: opent het Windows-venster “Bestand openen” om het SQLite-bestand van Log4OM te kiezen (de knop bestaat alleen als je Aurora op de pc zelf gebruikt). Aurora controleert het bestand, onthoudt het en laadt de QSO’s meteen opnieuw, zonder herstart.",
  "t.1sunaza27gn": "CW kies je in het menu [[digi.menu.mode]], net als de andere modi. Aurora zendt de tekst die je schrijft of de macro’s, en ontvangt door de snelheid zelf te decoderen. Er is geen ingang voor een seinsleutel of een elektronische keyer: CW begint altijd vanaf het toetsenbord.",
  "t.1sw98yncjwc": "Statusregel onder de ingang: de naam van het apparaat in gebruik of, als er geen ingang actief is, de rode waarschuwing “[[aud.nowInNone]]”; als de ingang niet openging, staat ook de reden van het systeem erbij. Blijft de Rx-balk stil, kijk dan eerst hier.",
  "t.1swx4rp37vc": "Meldingen en kaartjes die vanzelf verschijnen",
  "t.1sy3vgplcgl": "In Instellingen › DX Cluster kies je waar de spot vandaan vertrekt: de website DXSummit of de verbonden telnet-cluster, die hem naar het hele clusternetwerk brengt. Naast elke server staan inlognaam en wachtwoord; de spot telt pas als verzonden wanneer de cluster hem herhaalt.",
  "t.1t12zvug5ks": "Meldingen verschijnen niet meer in de eerste 20 seconden na het starten. «Geen bericht sinds N minuten» telt vanaf het moment dat je terugkeert op de pagina.",
  "t.1t281kj2gi": "[[sw.contest.title]] · [[sw.contest.which]]: keuzelijst met de contests die FT8 of FT4 toestaan; die welke aan staat, draagt het woord “[[sw.contest.active]]”. Hij opent vanzelf op de actieve contest, als die bij deze tak hoort; anders staat er “[[sw.contest.choose]]” en tot je er een kiest verschijnt alleen de opmerking [[sw.contest.note]]. Zonder de eigen engine toont hij “[[contest.unavailable]]”.",
  "t.1t30rd0u6zu": "[[sw.pg.orbits]] · [[sat.set.servers]]: één vak voor elke server die Aurora aanbiedt (het siteadres staat onder de naam); vink de servers aan waarvan je wilt downloaden. De regel “[[sat.set.serversHint]]” erboven herinnert je waarvoor ze dienen. In de fabrieksinstelling staan de servers die Aurora aanbiedt aan.",
  "t.1t6cq6ocikd": "Na de groep “[[bfl.except]]” staan vier pillen die verder afbakenen wat overblijft: “[[bfl.cqOnly]]” (alleen berichten van stations die CQ roepen), “[[bfl.rr73AsCq]]” (een station dat RR73 zendt telt ook als CQ), “[[bfl.hasGrid]]” (alleen stations die hun locator hebben gestuurd) en “[[bfl.notMyCont]]” (verbergt de stations van jouw continent).",
  "t.1t6pt5vdhva": "[[tab.frequencies]] · [[freq.addRow]]: voegt een rij onderaan de tabel toe (standaard 20m, FT8, 14.074 MHz, [[gen2.regionAll]], [[freq.preferred]] aangevinkt); wijzig daarna de velden van de rij. Gebruik het voor een alternatieve frequentie (bijvoorbeeld een DXpeditie) of voor een modus die voor die band ontbreekt.",
  "t.1tgne2dwtt5": "Het beeld komt scheef binnen: Aurora corrigeert de scheefstand bij elk beeld zelf; “[[sstv.set.slant]]” is alleen nodig bij geluidskaarten die ver naast de frequentie zitten.",
  "t.1thrgm9cge3": "De tabel heeft zeven kolommen: “[[cluster.col.by]]” (wie de spot stuurde), “[[cluster.col.freq]]” (in kHz), “[[cluster.col.call]]” (de DX), “[[cluster.col.country]]”, “[[cluster.col.mode]]”, “[[cluster.col.comment]]” en “[[cluster.col.time]]”. De volgorde wijzig je door de kop te slepen (of Alt + pijltjes), de breedte door de rechterrand te slepen (Alt + Shift + pijltjes); rechtsklik op de kop: “[[cluster.cols.reset]]”.",
  "t.1ti1wh8oi3e": "JT65-submodi en middeling",
  "t.1tjjhwkzkwg": "Kies in “Fast QSO”, in het menu onder “Auto-Save”, Aurora en vink “Auto-Save” aan.",
  "t.1tknk4zfu22": "Meldingen op een witte achtergrond, tooltip van de clusteropmerking, DXpeditiekaart in het donkere thema, Instellingenmenu in tegels en clusterknoppen met een blauwe rand. De melding over een zwak ingangssignaal verschijnt alleen als het aanhoudt en nooit tijdens het zenden.",
  "t.1tl7lrbvmm4": "Elke QSO gaat naar het normale logboek en naar het contestlogboek. Als het andere station de exchange herhaalt na jouw RR73, zendt Aurora vanzelf opnieuw RR73 en markeert de QSO als “[[contest.state.incerto]]”; de ontvangen exchange wordt met één klik in het logboek rechtgezet.",
  "t.1tn475j648c": "[[sat.set.update]] · statusregel en “[[sat.tle.refresh]]”: de regel zegt hoe lang geleden de gegevens zijn gedownload (of “[[sat.tle.none]]”); de knop downloadt ze nu en geeft een melding met het aantal bijgewerkte satellieten of de reden van de fout. Hij blijft uit tijdens het downloaden of als er geen server is aangevinkt.",
  "t.1towl1wii93": "“Pwr”: het audioniveau van de uitgang (Windows-mixervolume naar de radio, 100% op de schuifregelaar = 100% in de mixer). Als de radio voorbij ALC gaat, verlaag dan dit niveau; voor een schoon signaal moet de ALC op 0 blijven. Het kan ook worden ingesteld terwijl het zenden gestopt is. Als je erover beweegt, lees je het percentage en de demping in dB. Zonder radiobesturing en met Aurora aan verschijnt “Pwr –” (zie “De schuifregelaar Pwr”).",
  "t.1tppo6ct1re": "De QSO’s komen na het openen niet aan: de poort van de bestemming moet die zijn waarop het log luistert (in Log4OM moet de verbinding ADIF_MESSAGE actief zijn).",
  "t.1tq7llthkmo": "“[[sstv.tx.mode]]”: de keuzelijst met modi, met resolutie en duur naast de naam (van een halve minuut tot bijna vijf). Hij volgt de modus die bij de ontvangst is herkend (bij het openen begint hij bij de modus die in de SSTV-instellingen is gekozen) en kan niet worden gewijzigd terwijl je zendt.",
  "t.1tu027f31ke": "In het bericht staat de roepnaam van het zendende station vet (met een gekleurde onderstreping als het LoTW gebruikt); de roepnaam van de DX die je roept is gemarkeerd. Beweeg de muis over de roepnaam en de stationskaart verschijnt: land, continent, naam, plaats, azimut en afstand vanaf je station (als de locator bekend is) en hoe het QSO’s bevestigt (LoTW, eQSL, directe QSL, bureau, QSL via). De gegevens komen van QRZ.com of HamQTH als je die hebt aangezet ([[nav.settings]] › [[sw.fam.log]]).",
  "t.1tv61ps80tc": "Let op: met deze functies kan een zending starten zonder dat je iets indrukt. Wis de DX als de QSO klaar is.",
  "t.1tv9jvs6mjs": "Linux: de poorten zijn bestanden in /dev. USB-seriële kabels (chips CP210x, FTDI, CH340) verschijnen als /dev/ttyUSB0, /dev/ttyUSB1…; radio’s met native USB als /dev/ttyACM0. Ze verschijnen in de lijst [[cat.port]] en je kunt het pad ook met de hand typen. De paden /dev/serial/by-id/… zijn beter: ze veranderen niet bij een herstart of als je twee kabels omwisselt. Druk na het aanzetten van de radio of het aansluiten van de kabel op “[[cat.ports.refresh]]”.",
  "t.1tvewzg3yzz": "[[sw.pg.files]]",
  "t.1twlsupsx6u": "[[cat.share]] · [[cat.share.on]] (alleen Hamlib, standaard uit): een COM-poort kan maar door één programma worden gebruikt. Met dit vinkje houdt Aurora de COM van de radio vast en verbinden de andere programma’s (Log4OM2, JTDX, GridTracker, flrig…) met Aurora als met een “Hamlib NET rigctl”-radio. Het werkt alleen op deze pc. Druk na het aanzetten op [[cat.apply]] en daarna op [[cat.connect]]; start altijd eerst Aurora.",
  "t.1txtv68x1zo": "In FT8 kosten ongebruikte modi niets; modus «Trage pc»",
  "t.1u0h6448o4j": "Onderaan het venster toont een smalle balk de status van de periode en houdt geluidsmeldingen, thema en UTC-tijd binnen handbereik.",
  "t.1u0xoupjmwx": "“[[rep.active]]” (aan): één keer per dag gaat er een anonieme telling uit: een willekeurige installatiecode (of een code afgeleid van de roepletters, die nooit worden verstuurd), de Aurora-versie, het besturingssysteem, het land en het type computer (processor, kernen en geheugen). Het dient om te tellen wie Aurora gebruikt en te begrijpen op welke computers het moeite heeft. Zet het uit als je zelfs dit niet wilt.",
  "t.1u2tdrladea": "Log4OM 2: QSO’s ontvangen",
  "t.1u42db17y1s": "Kies bij een SDR met twee ontvangers RX1 of RX2 in [[cat.tci.receiver]]: frequentie, mode, PTT en audio gebruiken die ontvanger. RX2 wordt vanzelf ingeschakeld als hij uit staat.",
  "t.1u5zsuahxe5": "Schakel in het SDR-programma de TCI-server in (meestal poort 40001).",
  "t.1u6dm99tcxt": "[[sw.contest.title]] · [[contest.set.cabrillo]], [[contest.set.catTime]], [[contest.set.catOverlay]], [[contest.set.soapbox]]: [[contest.set.cabrillo]] is de naam van de contest in het Cabrillo (leeg = die van de regels; nodig voor de contest Custom); [[contest.set.catTime]] (bijvoorbeeld 6-HOURS) en [[contest.set.catOverlay]] (bijvoorbeeld ROOKIE) alleen als de regels ze voorzien, anders blijft de regel uit het Cabrillo; [[contest.set.soapbox]] is de vrije slottekst.",
  "t.1u6tqf56tmd": "[[sw.station]] · [[gen2.type2]]: gaat alleen over samengestelde roepletters van “type 2” (ongebruikelijk voorvoegsel of achtervoegsel, bijvoorbeeld PJ4/K1ABC), zoals in JTDX. In FT8 en FT4 verandert het geen enkel bericht: laat het zoals het is (fabriekswaarde “[[gen2.type2Full]]”; de andere keuzes zijn “[[gen2.type2Tx1]]” en “[[gen2.type2Tx5]]”).",
  "t.1u9dwcsgvma": "[[sw.contest.title]] · [[contest.category]], [[contest.set.mode]], [[contest.set.power]] en [[contest.set.bonus]]: [[contest.category]] is de categorie uit de regels (keuzelijst), [[contest.set.mode]] de mode die bij de start wordt voorgesteld uit de toegestane, [[contest.set.power]] het vermogen in watt (fabrieksinstelling 100; bij Field Day is het de vermogensvermenigvuldiger). [[contest.set.bonus]] verschijnt alleen bij contests waarvan de score bonussen heeft (Field Day): de bonuspunten die je met de hand aanvinkt.",
  "t.1uazifalbvr": "Foutrapporten",
  "t.1ubtxqei8s7": "Balk onderaan: “[[phone.cq]]” (roept CQ), “[[ctl.enable_tx]]” (wordt “[[phone.txOn]]”) en “[[phone.stop]]” (wordt “[[stop.button]]” terwijl je zendt); twee snelle tikken op stop maken ook het gekozen station weer vrij. Ze blijven altijd binnen bereik van je vinger.",
  "t.1uc4y6a61ns": "[[sat.ctl.title]] · [[sat.ctl.minEl]]: van 0 tot 60 graden (fabriek 0). Onder deze elevatie doen Doppler en de rotor niets. Verhoog hem (bijvoorbeeld 5-10 graden) als je de satelliet laag boven de horizon tussen huizen en bomen niet kunt horen en de rotor niet voor niets wilt bewegen.",
  "t.1uc91txk2yr": "In [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] bepaal je waar elk onderdeel van Aurora staat: in het hoofdvenster, in een apart venster (bijvoorbeeld op het tweede scherm) of verborgen. Hier vind je altijd alles terug, ook een gesloten venster of een venster op een scherm dat er niet meer is. Keuzes werken meteen.",
  "t.1uccgqhc8c0": "Diagnosemeldingen blijven hooguit 10 minuten staan na hun laatste bevestiging; als je ze sluit en het probleem is hetzelfde, komen ze niet terug.",
  "t.1ud3mfnrn3f": "“[[list.bottom.off]]” / “[[list.bottom.on]]”: waar nieuwe berichten verschijnen. Met de pijl ↑ staat het meest recente bovenaan en schuift de lijst omlaag; met ↓ is het meest recente de laatste rij. Elke lijst onthoudt zijn eigen keuze.",
  "t.1ueeu1aj94b": "De agent is een klein programma, hetzelfde als Aurora maar stil gestart, zonder venster en zonder engine: hij blijft als pictogram naast de Windows-klok staan, ook als Aurora gesloten is, om Aurora met een klik te openen en om je meldingen te tonen (nieuwe versies, berichten van de auteur en nog enkele andere). Hij staat standaard aan: hij start met Windows en, als hij er niet is, start hij wanneer je Aurora opent. Per gebruiker draait er maar één.",
  "t.1ueewvblym0": "De PTT schakelt niet",
  "t.1ugqcge21v0": "In het Logboek-paneel dat het logboek van Log4OM2 toont, zijn de QSO’s alleen-lezen: die corrigeer je in Log4OM2.",
  "t.1uh3h1boiav": "Log op een andere pc: van hieruit valt niet te weten of het open is, dus de QSO’s gaan zoals altijd meteen weg. Houd het log open of gebruik het rechtstreeks uploaden (Wavelog, ClubLog, QRZ.com), dat al een eigen wachtrij heeft.",
  "t.1uh8cjimotu": "Opent de telefoon de pagina niet? Telefoon en pc moeten op hetzelfde wifi zitten (niet het “gast”-netwerk), met mobiele data en VPN uit op de telefoon. Open de link in Chrome of Safari, niet in een andere app. Als Chrome op Android de pagina niet opent, probeer dan “Altijd beveiligde verbindingen gebruiken” uit te zetten of gebruik Firefox.",
  "t.1uhawnxgp5p": "[[digi.mi.threshold]]: opent het venster “[[digi.ms.title]]” (verderop beschreven), waar je de squelchdrempel van de huidige modus instelt.",
  "t.1ui7owwixdm": "“[[ens.g.adif]]”: “[[ens.k.EnableUDP2adifBroadcast]]”, [[ens.k.UDP2Server]] en [[ens.k.UDP2ServerPort]]. Het stuurt alleen het QSO als ADIF-tekst, één per datagram.",
  "t.1ujtlkqg9kj": "F1…F12 (met Ctrl en Shift) voeren de macro’s uit; een open venster “[[digi.edit.title]]”, “[[digi.ms.title]]” of “[[digi.rtty.title]]” blokkeert al deze toetsen tot je het sluit.",
  "t.1ul3pkmah86": "Een geluid speelt niet af: er zijn drie dingen samen nodig. 1) “[[alert.button]]” aan. 2) De melding van die functie aan (bijvoorbeeld “[[not2.alertMy]]”, of “[[not2.alsoSound]]” in de Kleurentabel). 3) Een geluid gekozen in het menu, niet “[[snd.none]]”. Verder: je zendt niet terwijl “[[not2.muteTx]]” aan staat, en je hebt minstens één keer in het Aurora-venster geklikt (de browser eist dat).",
  "t.1ulihrix3x": "CI-V is de “naam” waaraan een Icom-radio opdrachten herkent. De Icom-handleidingen schrijven hem HEXADECIMAAL (met de h, bijvoorbeeld 94h of 0x94); Aurora wil hem in het veld [[cat.civ]] van [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]] in DECIMAAL (0x94 = 148). De twee getallen door elkaar halen is de meest gemaakte fout: de radio antwoordt niet.",
  "t.1uoc8nlye95": "De status komt aan maar het QSO niet: zet in Aurora “[[int.loggedAdif]]” aan in de bestemming, of kies in BBLogger “UDP 5”.",
  "t.1up1u53isyf": "Ctrl+Z maakt de laatste wijziging ongedaan; Ctrl+Shift+Z of Ctrl+Y doet haar opnieuw. Ze werken niet als je in een vak typt.",
  "t.1up5fsrynhn": "[[toast.grp]] · [[toast.position]]: waar ze verschijnen, “[[toast.pos.top]]” (standaard), “[[toast.pos.topRight]]” of “[[toast.pos.bottom]]”. [[toast.size]]: “[[toast.sz.small]]”, “[[toast.sz.normal]]” (standaard) of “[[toast.sz.large]]”.",
  "t.1upqxbvj83": "Naast de selecties staat een kleine statusstrook. Meestal is hij bijna leeg: hij zegt je alleen iets als er een probleem is.",
  "t.1uqymfao55v": "“[[fox.callers]]” (links): wie jouw CQ heeft beantwoord. Velden: “[[fox.filter]]”, “[[fox.sort]]” en “[[fox.sort2]]” (SNR, roepnaam, locator, afstand, leeftijd, Hz, externe waarde), “[[fox.snrMin]]” en “[[fox.snrMax]]”, “[[fox.onlyNew]]” (verbergt wie al op deze band in het logboek staat), “[[fox.addBest]]” (zet de eerste 5 van de lijst in de wachtrij). Een dubbelklik op een rij of “[[fox.add]]” zet het station achteraan in de wachtrij; “[[fox.top]]” zet het bovenaan (het komt als volgende aan de beurt). Het label “[[fox.dupe]]” zegt dat het al in het logboek staat.",
  "t.1url27n4utt": "Is de tekst te klein? Druk op Ctrl + op elke pagina, of kies “[[ap.size]]”. Staat Aurora in de verkeerde taal? Wijzig “[[gen.language]]” in de eerste regel van deze pagina.",
  "t.1us8tiurido": "Contest: F1 start Auto CQ, F2 exchange, F3 R + exchange, F4 afsluiting (zie “Contest: toetsenbord en opdrachten”). Venster “QSO loggen”: Enter logt. Keuzemenu’s en vensters: Esc sluit. Taal: pijltjes, Enter, Esc, Home, End.",
  "t.1ut3rkw70gl": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] bepaal je wat je ziet in de berichtenlijsten: de filters van [[panel.all]] en [[rxw.title]], het venster [[panel.cq]] en hoe elke regel getekend wordt. Van boven naar beneden: de filtervakjes, dan [[cqp.title]], dan [[gen.screen]]. Filters werken alleen op wat je ziet: verborgen berichten blijven gedecodeerd en de automatiseringen zien ze nog steeds. Keuzes gelden meteen en worden onthouden na een herstart, zonder [[sw.save]].",
  "t.1utqh1ljiik": "De poort van de radio kies je in [[cat.port]] ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]]); hetzelfde geldt voor [[cat.ptt.port]] en voor de [[rot.set.port]] van de rotor. De naam van de poort verschilt en op Linux is een machtiging nodig.",
  "t.1uuh0fcd3s2": "Voor Wavelog, ClubLog, QRZ.com, HRDLOG.NET en LoTW heeft de directe upload al een eigen wachtrij: niet verstuurde QSO’s blijven wachten en gaan weg zodra de dienst antwoordt (zie “Online logdiensten en opzoeken van roepnamen”).",
  "t.1uv3fwp0m14": "“[[dxs.colors]]” · groepen “Vakjes FT8”, “Vakjes FT4” en “Vakjes DIG”: per mode drie kleurkiezers, één voor de vakjes “[[dxcc.cell.worked]]” (standaard groen), “[[dxcc.cell.unconfirmed]]” (oranje) en “[[dxcc.cell.none]]” (leeg). Naast elke kleur zet de knop ↺ (“[[dxs.factory]]”) de fabriekskleur terug, dat is die van het thema. Elke mode heeft zijn eigen kleuren, zodat je FT8 en FT4 uit elkaar kunt houden. Een vakje heeft altijd een rand, ook als je een kleur kiest die gelijk is aan de achtergrond.",
  "t.1ux97dxno81": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiScan]]. Twee vakken: de eigenschappen van het automatisch scannen van de band en de 20 geheugens met je favoriete instellingen. Beide blijven op dit apparaat. De scan start en stopt via het menu [[digi.menu.options]] van de pagina PSK · RTTY · CW; “[[digi.mi.scanProps]]” in hetzelfde menu opent deze pagina.",
  "t.1v0i4kgc0de": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], onderste deel van de pagina: de radio delen met andere programma’s, uiterlijk van het kopdisplay en uitgebreid display. De keuzes voor het display zijn puur grafisch en zijn meteen te zien.",
  "t.1v3jzvlxy79": "Wat is het paneel Signalen?",
  "t.1v64424vgwy": "[[sstv.set.grpRx]] · [[sstv.set.autoReceive]] (standaard uit): met het vak aan begint het SSTV-luisteren als Aurora start en blijft het aan, ook als je de SSTV-pagina verlaat; uit start je het vanaf de pagina.",
  "t.1v6x9aqwyma": "Kolom “[[ctl.grp.tx]]”: [[ctl.enable_tx]] (in de volgende periode zendt Aurora); [[ctl.auto_tx]] (automatisch zenden: het QSO en de CQ beginnen vanzelf opnieuw); [[ctl.wait_call]] (wacht tot de DX vrij is en roept hem dan); [[ctl.pounce]] (met Enable Tx uit antwoordt het vanzelf op de gekozen CQ). Als ze aan staan, worden deze vier schakelaars rood: dat betekent dat Aurora uit zichzelf mag zenden.",
  "t.1v8d5pvbv0h": "[[gen2.fox]] · [[gen2.otpVerify]]: selectievakje, standaard aan. In Hound, als de Fox zijn code stuurt (CALL.123456), vraagt Aurora de dienst of die geldig is en schrijft het op de pagina Station (“verified” of “not valid”). Alleen de roepnaam van de Fox, de tijd en de code gaan naar de dienst; de code 000000 (tests) wordt nooit geverifieerd. Zet het uit als je helemaal geen netwerkverzoek wilt.",
  "t.1v8iexpszal": "JT65-submodi: kies naast de modus A (tonen 2,69 Hz uit elkaar, HF en 6 m), B (dubbele afstand, EME op 2 m en 70 cm) of C (viervoudig, EME vanaf 23 cm); hij moet overeenkomen met die van je partner. In B en C zoekt Aurora naar één signaal, het sterkste binnen F Tol van de Rx-frequentie, meet de breedte en maakt de spectra dienovereenkomstig glad.",
  "t.1v8w9vban0e": "Wordt de sleutel geweigerd, controleer dan ook de pc-klok: Cat4OM ontvangt alleen een bewijs dat met de tijd is berekend, nooit de sleutel.",
  "t.1varj1btb3z": "Aurora en Log4OM besturen tegelijk dezelfde radio, via Cat4OM.",
  "t.1vatnchi4ar": "De stille update stopt niet meer als een antivirusprogramma het oude bestand vasthoudt: het installatieprogramma probeert het enkele seconden opnieuw en gaat dan toch door. Ontbreekt WebView2, dan installeert Aurora het zelf na jouw «Ja» en start daarna opnieuw.",
  "t.1vb760rz85j": "[[fil.highlight]] · [[fil.hlCalls]] en [[fil.hlCountries]]: twee tekstvelden met lijsten gescheiden door komma's (VK*, ZL*; landnamen zoals in de landenkolom). De regels van die stations of landen worden paars met een balk. Ze verbergen niets: ze laten de stations die je zoekt opvallen.",
  "t.1vdn2dgjs4s": "Boven de waterval staat het paneel “[[digi.band.title]]” (alleen in CW en PSK31/PSK63, en alleen als het aan staat): een lijst met alle signalen in de audioband.",
  "t.1vfbyl054cy": "[[not2.grpWorked]] · [[not2.hide]]: CQ’s van al gewerkte stations worden helemaal niet getoond (hun uitwisselingen met anderen blijven). Standaard uit; het vergrendelt net als de andere als er geen “nieuw”-markeringen aan staan. [[not2.invert]]: bij gekleurde types kleurt het de tekst in plaats van de achtergrond van de rij (geldt voor alle kleuren op deze pagina; standaard uit).",
  "t.1vhb0bky0gd": "Het filter “[[cluster.filter.spotter]]” naast band en modus: “[[cluster.filter.spotterMine]]” toont alleen de spots van stations op jouw continent (wat te horen is waar jij zit); je kunt ook de gewenste continenten aanvinken.",
  "t.1vj2dwripam": "Bandactiviteit: de titelbalk en het filter",
  "t.1vkiacik8st": "De Fox zendt onder 1000 Hz en beantwoordt meerdere stations tegelijk in dezelfde periode, met signalen naast elkaar.",
  "t.1vlaqw2ni2t": "“[[dxs.colors]]” · zes groepen “Label NEW ONE”, “NEW BAND”, “NEW MODE”, “NEW GRID”, “GRID BAND” en “GRID MODE”: voor elk vier kleuren, “[[dxs.bg]]” en “[[dxs.ink]]” als “[[dxs.on]]” en als “[[dxs.off]]”, met de knop ↺ om de fabriekskleur terug te zetten. De labels: NEW ONE = land nog nooit gewerkt; NEW BAND = land al gewerkt, maar niet op deze band; NEW MODE = land al gewerkt, maar niet in deze mode; NEW GRID, GRID BAND en GRID MODE zijn hetzelfde voor de locator (vak van 4 tekens). Ze krijgen de “aan”-kleuren als ze voor het station gelden, anders blijven ze “uit”.",
  "t.1vn10vzlzce": "Verloren QSO’s terwijl het logboek dicht is: waar je dit aanzet",
  "t.1vpu6tk7tdu": "Wacht tot je de Fox decodeert en dubbelklik dan op een van zijn regels: Aurora roept hem met roepnaam en locator.",
  "t.1vqq5ctcf3j": "Elke QSO gaat maar één keer weg: meteen als het log open is, of uit de wachtrij, nooit twee keer. De wachtrij blijft ook als je Aurora sluit (bestand log-in-attesa.json in de gegevensmap); een QSO die langer dan zeven dagen wacht, wordt weggegooid.",
  "t.1vt9yrn7uqs": "Het luidsprekerpictogram en de volumeschuif: de geluidsmeldingen (zie “Taal, thema en volume vanuit de balk”). Ernaast de maan, de zon of de half gevulde cirkel: het thema.",
  "t.1vu11y1lyw8": "[[fil.decode]] · [[dec.includeAveraging]]: vakje, standaard uit. Als één periode bij Q65 niet genoeg is, probeert Aurora het gemiddelde van de perioden met dezelfde pariteit op de ontvangstfrequentie. Zet het aan voor EME en voor signalen onder de ruis. Naast de modus staat de knop “Avg”.",
  "t.1vvcjb9w30": "Voeg een inkomende UDP-verbinding toe: type ADIF_MESSAGE, poort 2237 (dezelfde als Aurora); schakel hem in en druk op “Save and apply”.",
  "t.1vx24ri5jxa": "[[digi.mi.log]] (aan): de rechterkolom met de tabbladen DX Cluster en Log. [[digi.mi.rotor]] (aan): het tabblad Rotor, met de richting naar het DX-station van de huidige QSO; de rotor verbind je in [[nav.settings]] › [[sw.sec.station]].",
  "t.1w00z7qhoby": "Integraties: de velden van een bestemming",
  "t.1w4s17hd7m6": "[[not2.grpColors]] · [[not.restoreColors]]: zet de kleuren, de geluidsvakjes per type en ook het uiterlijk van berichten (al gewerkt, markeringen, “[[not2.invert]]”) terug zoals in een nieuw geïnstalleerde Aurora. Let op: het zet ook de gemarkeerde melding voor nieuw DXCC weer aan en zet de geluidsvakjes terug op de standaardwaarden. Het verwijdert niet de geluiden die je op de pagina “[[sw.pg.alerts]]” hebt gekozen, en ook niet de positie van de melding.",
  "t.1w5ce84ewqj": "[[lay.settings]] · [[set.save]]: slaat het schema op; het slaat zichzelf ook op na ongeveer een seconde en bij het verlaten van de pagina. Verschijnt “[[sch.invalid]]”, dan is iets buiten bereik (uur, minuut, band of meer dan vijf rijen) en is het niet opgeslagen.",
  "t.1w5kvmhd2tj": "Kolom [[freq.band]] en kolom [[freq.mode]] (twee keuzelijsten): de band en modus waarop de rij van toepassing is. Toegestane modi: FT8, FT4, JT65, JT9, Q65, MSK144, FST4, FST4W, WSPR. Dezelfde band en modus kunnen meerdere rijen hebben (de standaard en de alternatieven).",
  "t.1w6wyoixqln": "Ontvangstsnelheid: Aurora volgt hem zelf tussen de helft en het dubbele van de ingestelde snelheid en toont hem in WPM in de statusbalk.",
  "t.1w70nnn6s8u": "“+ [[int.p.n1mm]]”: naam N1MM XML, 127.0.0.1, poort 12060, alleen “[[int.n1mm]]” aan. Voor elke QSO ontvangt hij het XML-bericht “contactinfo” zoals N1MM Logger+ het stuurt: roepletters, band, frequenties, modus, rapporten, locator, naam, vermogen, opmerking en een identificatie die voor dezelfde QSO stabiel blijft, met Aurora als verzendend programma. Voor HRD Logbook en programma’s die N1MM nabootsen. Probeer het met je programma voordat je erop vertrouwt: het is niet voor alle programma’s getest. Je kunt ook “[[int.resend]]” aanzetten voor QSO’s die met het logboek dicht zijn gemaakt.",
  "t.1w737trj01b": "De keuze bij «Controle» wordt nu bewaard en springt niet meer terug naar «Normaal». Er is een knop «Wissen», de hoogte van het paneel is instelbaar en de roepletters op de waterval verdwijnen als het signaal wegvalt.",
  "t.1w7om5wef33": "[[gen2.fox]] · [[gen2.otpUrl]]: tekstveld, fabrieksinstelling https://www.9dx.cc. Het is het adres van de dienst die de Fox-codes verifieert: het moet beginnen met http:// of https://, geen spaties, maximaal 200 tekens. Het blijft grijs zolang [[gen2.otpVerify]] uit staat. Wijzig het alleen als de dienst van adres verandert.",
  "t.1w9n1nx07vj": "Het scherm: zolang er niets binnenkomt, staat er “[[sstv.rx.waiting]]” (of, als het luisteren uit staat, “[[sstv.rx.offHint]]”). Tijdens de ontvangst loopt een heldere lijn omlaag tot waar je bent. Bovenaan het beeld verschijnt de roepnaam die uit de FSK ID is gelezen, als het station die na het beeld verstuurt ([[sstv.rx.fskIdHint]]).",
  "t.1wazioxaytv": "[[sstv.log.name]], [[sstv.log.qth]], [[sstv.log.grid]] (maximaal 8 tekens) en [[sstv.log.note]]: ze worden ingevuld met het opzoeken, of schrijf ze zelf.",
  "t.1wbbmca6k3n": "[[gen.screen]] · [[gen.miles]]: selectievakje, standaard uit (afstanden in kilometers). Aan worden afstanden in mijlen getoond.",
  "t.1wcasa1q6f0": "[[auto.b3]] · [[auto.perHour]] (getalveld, 0 tot 120, standaard 0): maximaal zoveel QSO's in het laatste uur; als dat bereikt is, stopt Aurora met antwoorden tot de oudste uit het uur valt. 0 = geen limiet. In dry run tellen de stations mee die Aurora zou hebben beantwoord.",
  "t.1we3mimq1t8": "De roepnamen van de hele band verschijnen onder de schaal, boven het spoor van de signalen: twee naburige wisselen van hoogte; ze verdwijnen 75 seconden nadat ze voor het laatst zijn gehoord. Je zet ze uit met “[[digi.band.wfCalls]]” in het menu [[digi.menu.view]].",
  "t.1we6dmssbsh": "Een macro is een toets met een tekst en, indien nodig, opdrachten tussen < >. De “toets” is zowel de knop op het scherm als de toets op het toetsenbord met dezelfde naam. Aurora wordt geleverd met kant-en-klare fabrieksmacro’s.",
  "t.1wggkcdvzqm": "[[sstv.set.grpFolders]] · [[sstv.set.folder]]: waar ontvangen en uitgezonden beelden worden opgeslagen. Leeg (fabriek): de geschiedenismap in de map van Aurora, die het veld in grijs toont. Hij kan alleen vanaf de pc van Aurora worden gewijzigd, niet vanaf de telefoon; typ het volledige pad van een bestaande map.",
  "t.1wkdh41n1we": "Een klik op de roepnaam of het puntje: Aurora roept dat station op.",
  "t.1wl4m4ntrp6": "[[ctl.enable_tx]] (wordt “[[phone.txOn]]” als het aan staat): zet het zenden aan of haalt de toestemming weg, zoals op de pc. Grijs als zenden niet is toegestaan.",
  "t.1wmv0ry1dhb": "Toon: het is de “ontvangstfrequentie (Hz)” van de radio in het audiosignaal (standaard 1000 Hz; van 200 tot 3500). Je verplaatst hem met een klik op de waterval, door het getal in de statusbalk in te vullen, of met “[[digi.mi.seekLeft]]” en “[[digi.mi.seekRight]]”. Bij het zenden wordt dezelfde toon gebruikt, tenzij [[digi.mi.lock]] aan staat.",
  "t.1woglnyqjos": "“[[sat.list.title]]”: het veld “[[sat.list.search]]” zoekt op naam; een klik op de naam volgt de satelliet (hij verschijnt in “[[sat.data.title]]”); het vinkje laat hem op de kaart verschijnen. Satellieten zonder baangegevens zijn gemarkeerd met “[[sat.list.noTle]]”.",
  "t.1wzq934f1w0": "Kolommen: “[[digi.band.colFreq]]” (ten opzichte van de radio), WPM (alleen CW: de snelheid), S/N in dB, “[[digi.band.colCall]]” en “[[digi.band.colText]]”. In de roepnaamkolom: vlag, roepnaam, het label CQ of DE; cursief en lichter zolang hij niet geverifieerd is (“[[digi.band.notVerified]]”: maar één keer gehoord of met onzekere tekens), vet wanneer hij geverifieerd is (“[[digi.band.verified]]”). Zonder signalen zegt de lijst “[[digi.band.empty]]” (of “[[digi.band.emptyPsk]]”).",
  "t.1x130kzrk9g": "[[toast.test]] toont ze je meteen.",
  "t.1x2ru976tjd": "Het paneel DX Cluster is leeg: controleer of “[[cluster.enabled]]” aan staat, of minstens één server “[[cluster.server.on]]” en een groen lampje heeft, of de roepletters niet ontbreken (“[[cluster.callMissing]]”) en lees “[[cluster.state]]” voor de reden. Is een server rood, probeer dan een andere uit de lijst “[[cluster.add.catalog]]”.",
  "t.1x3s6suspr1": "Hoe gebruik ik Aurora vanaf mijn telefoon of tablet?",
  "t.1x5cc5hr1jz": "“[[contest.adv]]” (elke 15 seconden uit de decodes): per band van de regels de stations die je de laatste 15 minuten hebt gehoord, de nieuwe multipliers die je hoort en het geschatte tempo. Het zegt “Blijf op band · modus” of “Ga naar band · modus” met de reden, en een klik zet de radio op de geadviseerde band en modus; “[[contest.adv.ignore]]” wuift het weg. Het toont ook hoeveel bandwisselingen je hebt gedaan van het toegestane maximum.",
  "t.1x6t0m4q83y": "De hoofdknop hangt af van de melding: “Nu bijwerken” (update), “Openen” of “OK” (berichten van de auteur, afhankelijk van of ze een link hebben), “Open Aurora” (propagatie, DXpeditie, overzicht). Als je de kaart sluit, sluit de agent niet.",
  "t.1x87t95dm0t": "[[digi.spot.freq]]: de echte frequentie van het signaal in kHz, al uitgerekend (radiofrequentie plus ontvangsttoon); verbeter hem als dat nodig is.",
  "t.1x9kz6mt197": "[[bar.decodes]]: hoeveel decoderingen de laatste periode gaf. Ernaast toont een balk waar je in de periode zit (hij wordt rood terwijl je zendt) en een teller “seconde/lengte” (bijvoorbeeld 7/15). Op de pagina’s PSK·RTTY·SSTV en satelliet is dit deel er niet.",
  "t.1xci23m1uk8": "Het keuzemenu “[[digi.band.validation]]” bepaalt hoe streng je met roepnamen omgaat: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] of [[digi.band.valMaximum]]. Hoe strenger, hoe vaker een roepnaam met een ongewone vorm gehoord moet zijn voordat hij telt. Het “?” legt de regels uit.",
  "t.1xh2rl98mtg": "[[gen.screen]] · [[set.reset]]: knop; zet ALLE weergavevoorkeuren van Aurora terug op de fabrieksinstellingen, niet alleen die van dit vak (ook bijvoorbeeld “[[list.bottom]]” en “[[rxw.exclusive]]”). De filters en [[cqp.title]] hebben elk hun eigen [[set.reset]].",
  "t.1xiq6r01gkw": "Met [[digi.mi.hairlines]] aan zie je ook twee dunne lijnen op het ontvangst- en het zendpunt.",
  "t.1xkwffolvaa": "Rechts in de balk verschijnen twee dingen alleen wanneer nodig: het pictogram van de nieuwe versie (zie “De updatemelding in de balk”) en de knop ⤓ die alle losgemaakte vensters terugzet in het hoofdvenster (zie “Aparte vensters en indeling”).",
  "t.1xl4lfazo0t": "Als de frequenties van radio en Aurora verschillen, worden QSO's op de verkeerde band gelogd: controleer ze als je van band wisselt.",
  "t.1xmyad4ojfd": "“[[list.clear]]”: maakt alleen deze lijst leeg; berichten die daarna binnenkomen verschijnen weer. De andere lijst (RX-venster) verandert niet.",
  "t.1xmynhsnj5": "Het rechtermuismenu in tekstvakken",
  "t.1xoxysn097e": "Hij zendt maar het vermogen is nul",
  "t.1xrh8431s6z": "Schakel [[ctl.hound]] in: de controle start vanzelf wanneer de code binnenkomt ([[gen2.otpVerify]] staat standaard aan).",
  "t.1xrpgghr2qj": "“[[wft.flatten]]” haalt de achtergrondruiscurve weg (handig als het radiofilter de achtergrond scheef trekt). “[[wft.stamp]]” schrijft aan het begin van elke periode de UTC-tijd en de band op de waterval.",
  "t.1xs35cohobi": "[[toast.position]]: [[toast.pos.top]], [[toast.pos.topRight]] of [[toast.pos.bottom]]. [[toast.size]]: [[toast.sz.small]], [[toast.sz.normal]] of [[toast.sz.large]].",
  "t.1xukskylzn2": "“[[agent.kind.daily]]”: het overzicht van de vorige dag (“Gisteren: N QSO’s” en het aantal verschillende landen), gelezen uit het logboek van Aurora, na 8 uur ’s ochtends. Standaard “Uit”.",
  "t.1xuxwr6pbzu": "Met de telefoon op hetzelfde thuisnetwerk: [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] om te koppelen, daarna opent de weergave op afstand.",
  "t.1xyqn9z00s2": "Vink in het tabblad Hamlib “Connect to active HAMLIB instance” (127.0.0.1, 4532) en “VFO MODE” aan om beide VFO’s te zien.",
  "t.1y05phwogo8": "SSTV: het tabblad “[[sstv.view.rx]]”",
  "t.1y0qptypi4m": "De pagina [[nav.dxmap]] is een wereldkaart met de stations in de lucht, je vierkanten en de lijnen. Boven de kaart staat een balk met alle opdrachten; elk item heeft zijn tip. Dezelfde kaart staat in het tabblad “[[log.tab.map]]” van het Logboek-paneel, met één rij opdrachten (zie “De kaart in het Logboek-paneel”).",
  "t.1y0xe9drskz": "Het paneel toont de stations die CQ roepen en de voor jou nieuwe; [[panel.all]] toont in plaats daarvan alles.",
  "t.1y2vsauswvw": "[[wfs.bars]] · [[wft.stamp]] (standaard aan): schrijft de UTC-tijd en de band op de waterval aan het begin van elke periode. [[wfs.freqOn]] (uit): als je de aanwijzer boven de waterval houdt, zie je de audiofrequentie van dat punt in Hz.",
  "t.1y50gr2vo54": "De updatemelding in de balk",
  "t.1y58codxhjv": "Geluiden",
  "t.1y6xb0ap5kl": "Pad: [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (vak “[[rep.title]]”). Aurora kan fouten anoniem sturen naar wie het ontwikkelt, zodat ze kunnen worden verholpen: zonder roepletters, locator, berichten, IP-adressen, e-mails of wachtwoorden. De vakjes staan standaard aan en je kunt ze wanneer je wilt uitzetten. Je kunt ze alleen wijzigen vanaf de pc waarop Aurora draait (anders zie je “[[rep.onlyPc]]”) en ze worden meteen opgeslagen.",
  "t.1y8dxnpf6a": "De radio verbinden: de checklist",
  "t.1y8wmxsu4br": "De meldingen van de agent verschijnen in een “kaart”: een klein venster zonder rand rechtsonder op het scherm, boven de taakbalk, altijd vóór de andere vensters maar zonder de focus te stelen van waar je mee bezig bent.",
  "t.1y9ut713uut": "[[snd.title]] · tabel van de andere meldingen (kolommen “[[snd.col.event]]”, “[[snd.pick]]”, “[[snd.col.state]]”): één rij voor “[[snd.ev.alert_my_call]]”, “[[snd.ev.alert_dx_call]]”, “[[snd.ev.first_message]]”, “[[snd.ev.wanted]]” (stations in de verlanglijst, altijd actief), “[[snd.ev.new_dx_popup]]” en “[[snd.ev.qso_logged]]” (altijd actief). In elke rij kies je het geluid en lees je de status: “[[snd.state.ok]]” (het speelt af), “[[snd.state.none]]” (geen geluid ingesteld) of “[[snd.state.off]]” (het geluid is ingesteld, maar de melding staat uit in het vak hierboven).",
  "t.1ybm8c81c31": "[[not2.grpWorked]] · [[not2.potential]]: kleurt nieuwtjes ook in berichten tussen andere stations, niet alleen in CQ’s (engine-item, standaard uit). Zet het aan als je meteen wilt zien wie iemand nieuws roept.",
  "t.1ybodi5214s": "De radio verbinden (CAT)",
  "t.1yda96ai3n6": "[[rep.title]] · [[rep.sendBundle]]: uploadt naar de dienst van wie Aurora ontwikkelt de versie van het pakket zonder persoonlijke gegevens (opgeschoond logboek, crashrapporten, versie, radio, PTT, audio) en toont een code die je kunt doorgeven aan wie je helpt, zodat die het kan vinden. Het verschijnt alleen als deze versie het adres van de dienst heeft ingesteld; anders zegt een opmerking dat er niets wordt verstuurd. Tijdens het versturen staat er “[[rep.sending]]”. Wanneer: als wie je helpt de ontwikkelaar is en je de zip niet met de hand wilt versturen.",
  "t.1yiftorqf9n": "Een macro bewerken",
  "t.1yjtxoiq14c": "De schuifregelaar “Rx” stelt het opnamevolume van Windows in en schrijft het percentage ernaast. “[[rxl.auto]]” stelt het zelf in: het gaat meteen omlaag als het signaal oververzadigt, gaat langzaam omhoog als het zwak blijft; het pauzeert terwijl je zendt en gaat uit als je de schuifregelaar verplaatst.",
  "t.1yncitjzmj8": "Typ in het zendvak en verzend met Ctrl+Enter (alle tekst gaat de lucht in, daarna ben je terug in ontvangst), of open het zenden met de RX/TX-knop van de statusbalk of met de Pause-toets: het blijft aan en de tekst gaat de lucht in terwijl je typt (de al verzonden tekens worden rood). Om te stoppen: Esc, of nogmaals RX/TX of Pause (zie “De ontvangst- en zendvensters” en “RX/TX, Pause, Esc, dubbel Esc en automatische CQ”). De verzonden tekst verschijnt alleen in het ontvangstvenster als “[[digi.mi.echoRx]]” aanstaat in het menu [[digi.menu.view]] (standaard uit).",
  "t.1ynjqqvjiph": "De locator wordt gebruikt voor afstanden, de kaart en de stations die jou horen.",
  "t.1ynn900fe9i": "De waterval afstellen",
  "t.1yosswbtubd": "Bij PSK, RTTY en CW gaat de scan van het ene station naar het volgende en bewaren de 20 geheugens je favoriete instellingen. Ze stel je in via [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiScan]].",
  "t.1yqbp3rksei": "[[wfs.res]] · [[wfs.bpp]] (1 tot 100, standaard 4; 5 met de snelle stijl): hoeveel spectrumkanalen in één pixel worden opgeteld. Minder kanalen = meer detail en meer ruis; meer kanalen = een gladdere waterval maar bredere signalen. [[wfs.start]] (0 tot 4900 Hz, standaard 0): audiofrequentie van de linkerrand; verhogen snijdt het lage deel weg en vergroot de rest.",
  "t.1yqhwb7hea9": "[[acc.pair]] · netwerkcontrole: onder de QR toont een lijst met vinkjes de status van wifi, firewall en adres. Dit wordt uitgelegd in het hoofdstuk “Netwerkcontrole tijdens het koppelen”.",
  "t.1yrzckfpfeg": "Contesten",
  "t.1ytpyx23xqm": "[[lay.lists]] · [[fil.calls]]: tekstveld, roepnamen die je wilt verbergen, gescheiden door komma's; het sterretje past op alles wat zo begint (JA* = alle Japanse). Voor stations die steeds roepen en je niet interesseren.",
  "t.1yvqhlmtani": "“[[int.multicast]]”: aan betekent dat het adres een multicastgroep is en alle programma’s die op de groep zijn geabonneerd tegelijk ontvangen (bijvoorbeeld GridTracker en QLog op dezelfde poort). Uit gaat de stream naar één programma (unicast). Met het vak aan verschijnen “[[int.ttl]]” en “[[int.iface]]”.",
  "t.1ywexuxzvj0": "[[rep.title]] · [[rep.ask]]: vakje, standaard aan. Als Aurora door een fout is gesloten, vraagt het bij de volgende start of je het rapport wilt versturen (zie “Foutrapporten: wat wordt verstuurd en hoe zet je het uit”). Zet het uit als je nooit gestoord wilt worden.",
  "t.1yx1p1ga9wn": "Het logboek meldt “port already in use”: een ander programma gebruikt de poort (JTDX, GridTracker, JTAlert). Sluit het, of gebruik een andere poort of multicast.",
  "t.1z09c4ovwts": "Firewallregel: als het netwerk als “Openbaar” is ingesteld (“[[net.public]]”) of als de Windows-firewall de telefoon blokkeert (“[[net.blocked]]”), verschijnt er een rode regel met de knop “[[net.allow]]” (daarna “[[net.allowing]]” terwijl je in het Windows-venster bevestigt): Aurora haalt de blokkade weg en opent de poort op elk netwerk. Als je de Windows-bevestiging annuleert, zie je “[[net.allowFailed]]”. Als alles goed is, zegt de regel “[[net.allowed]]”.",
  "t.1z2t3zlbae3": "[[lay.lists]] · [[fil.showOnly]]: tekstveld; als je roepnamen of prefixen schrijft, gescheiden door komma's (JA*), worden alleen de berichten getoond van stations die met die zenden. Leeg = alles. Handig om een expeditie of een groep vrienden te volgen.",
  "t.1z35huvz4cs": "“[[rot.heading]]” geeft de huidige richting, “[[rot.degrees]]” is het veld waarin je de graden typt (Enter of “[[rot.go]]” om te gaan), “[[rot.stop]]” stopt meteen. De knop “[[rot.more]]” opent de rest: “[[rot.short]]” (naar het DX-station) en “[[rot.long]]” (lange weg), de “[[rot.steps]]” −10° / −2° / +2° / +10°, en Park (de rustpositie, met de opdracht om erheen te gaan en die om de huidige positie als rustpositie in te stellen).",
  "t.1z61kch23ks": "De Fox zijn (pagina Fox)",
  "t.1z6wlr84lqy": "De schakelaar “[[contest.toggleOff]]” / “[[contest.toggleOn]]” zet de gekozen contest aan (Aurora bereidt berichten, exchange, Fox en Hound uit, AutoSeq en Hold Tx Freq voor) of zet hem uit en herstelt de vorige instellingen.",
  "t.1z730hc0uot": "[[toast.grp]] · [[toast.secs.ok]], [[toast.secs.info]], [[toast.secs.error]]: hoelang elk type zichtbaar blijft voordat het vanzelf verdwijnt, van 1 tot 30 seconden (standaard 4,5, 5,5 en 8). Maak ze langer als je niet op tijd kunt lezen, korter als berichten in de weg zitten.",
  "t.1z7e2f06cq7": "Dubbele QSO’s: het QSO komt via twee wegen binnen. In [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] staan de primaire en secundaire UDP-server van Aurora ook op 127.0.0.1:2237: zet uit wat je niet nodig hebt, of gebruik niet ook de ADIF-bestandsmethode.",
  "t.1z8nn0zv4m3": "[[auto.b5]] · [[auto.bandHop]] en [[auto.bandHopWhere]]: het vakje zet het Band Hopping van de engine aan (op vaste tijden gaat de radio van de ene band uit de lijst naar de volgende en de automatisering gaat door op de nieuwe band); het wordt opgeslagen met [[sw.save]]. De knop [[auto.bandHopWhere]] opent de pagina [[tab.sequence]], waar je de bandenlijst schrijft ([[gen2.bandHopList]]). Zonder eigen engine van Aurora verschijnt “[[auto.bandHopNa]]” in plaats van het vakje.",
  "t.1z947gcpyrw": "[[wfs.bars]] · knoppen “[[wfs.wsjtx]]” en “[[wfs.jtdx]]”: met één klik zetten ze alle wateropties (resolutie, palet, niveaus, spectrum) op een van de twee kant-en-klare stijlen; de knop blijft gemarkeerd zolang de opties met de stijl overeenkomen. “[[wfs.wsjtx]]” is de beginstijl (4 kanalen per pixel, Flatten aan); “[[wfs.jtdx]]” is de snelle waterval (15 rijen per seconde, 5 kanalen, Flatten uit). [[set.reset]]: zet alle opties van deze pagina terug op de standaardwaarden.",
  "t.1z98j8powch": "Hij opent via de bovenbalk “[[nav.textModes]]” (en dan “[[nav.sstv]]” in het menu [[digi.menu.mode]] van de tekstmodipagina). Het luisteren gaat vanzelf aan als je binnenkomt en blijft aan tot je op “[[sstv.rx.stop]]” drukt, ook terwijl je een beeld voorbereidt; het gaat uit als je de pagina verlaat, tenzij [[sstv.set.autoReceive]] is ingesteld in de SSTV-instellingen.",
  "t.1zd9uzuy2fr": "Zenden: schrijf in het vak. Met de knop “RX/TX” in de statusbalk of met de toets Pause opent het zenden en blijft aan, en wat je schrijft gaat de lucht in terwijl je het schrijft: tekens die al de lucht in zijn, worden rood, met een klein streepje op het bereikte punt; die in de wachtrij zijn onderstreept. Het deel dat nog niet is verzonden, kun je corrigeren of wissen.",
  "t.1zdqvjo2x44": "Een SSTV-zending duurt van een halve minuut tot bijna vijf: houd Pwr laag en stop de FT8-automatisering voordat je zendt. De instellingen staan in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]], ook via het ⚙-wieltje op de pagina.",
  "t.1zgpfghippf": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]] bepaal je hoe het QSO verloopt: wanneer Aurora zelf naar het juiste bericht gaat, wie het beantwoordt, hoe vaak het herhaalt en wanneer het stopt, plus de timing van het zenden. De onderdelen verschijnen met de eigen engine van Aurora (de standaard); ze worden opgeslagen met [[sw.save]] en werken meteen, zonder herstart.",
  "t.1zhaf8g68o8": "Gaat er iets mis, dan zegt de kaart waarom en toont “Opnieuw proberen”: “Aurora zendt: probeer opnieuw als het zenden klaar is” (de update wacht tot het zenden klaar is), “De update start alleen vanaf de pc waarop Aurora draait”, “Deze Aurora kan zichzelf niet bijwerken”, “Aurora reageert niet”.",
  "t.1zhpy3ofbvs": "Elke bestemming is een vak met zijn naam (of adres:poort) in de legenda en de knop “[[int.remove]]”, die de rij uit de lijst haalt.",
  "t.1zidjqu82en": "Wacht na “Te veel pogingen” de getoonde seconden: de blokkade is er tegen wie willekeurige codes probeert.",
  "t.1zim2twmzeg": "[[auto.b5]]: na zoveel minuten zonder CQ die het beantwoorden waard is kan Aurora zelf CQ roepen (alleen in live-modus, met het zenden in rust), of Band Hopping inschakelen om van band te wisselen.",
  "t.1zjl1df211w": "[[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.orbits]]. Waar Aurora de baangegevens (TLE) vandaan haalt en hoe vaak hij ze vernieuwt: zonder actuele gegevens kloppen de berekende overvluchten niet. Elke wijziging wordt meteen opgeslagen. Het netwerk is nodig.",
  "t.1zjnmwz59wn": "“[[ens.g.hrdlog]]” · “[[ens.k.HrdlogSend]]” (standaard uit): stuurt elke QSO naar je logboek op HRDLOG.NET, met dezelfde wachtrij en nieuwe pogingen als de andere. “[[ens.k.HrdlogCall]]”: de roepletters van het logboek (leeg = die van jou). “[[ens.k.HrdlogCode]]”: de uploadcode die HRDLOG.NET in je profiel toont. Hier controleert “[[ens.test]]” alleen of de gegevens er zijn: de code wordt bij de eerste QSO gecontroleerd.",
  "t.1zl6bnco93c": "“[[sstv.rx.sync]]”: de synckwaliteit als percentage (de balk verandert van kleur boven 80% en boven 40%). “[[sstv.rx.level]]”: het audioniveau in dB, met de balk. “[[sstv.rx.offset]]”: hoeveel Hz de sync van het juiste punt af zit.",
  "t.1zm3ns05ngn": "Kies in het andere programma Hamlib via het netwerk (NET rigctl), adres 127.0.0.1, poort 4532.",
  "t.1zmwgx1n59w": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.radio]], vakken onder de verbinding: aanbevolen instellingen, status en test, PTT, split, modus en uitlezing. In de volgorde waarin ze verschijnen.",
  "t.1zngm8tbqza": "Als er een nieuwe versie van Aurora uitkomt, verschijnt rechts in de bovenbalk een klein pictogram (een pijl omlaag met een stip). Op de pc downloadt Aurora de versie op de achtergrond en controleert de handtekening.",
  "t.1zodsfb8ol": "In het Windows-programma van Aurora opent de rechterknop het browsermenu niet: buiten tekstvakken gebeurt er niets; in een vak opent een klein menu met alleen de nuttige items.",
  "t.1zqf61w3j79": "[[sw.contest.title]] · [[contest.set.save]]: knop; slaat het formulier op en toont “[[contest.set.saved]]”. Het formulier wordt niet vanzelf opgeslagen en de knop [[sw.save]] onderaan het venster slaat het niet op: denk eraan om deze in te drukken.",
  "t.1zqfiu2yndq": "Als het signaal niet vastloopt wanneer je klikt, zet dan [[digi.mi.snap]] uit en verplaats de cursor met de hand; zet daarna AFC aan, dat kleine afwijkingen volgt.",
  "t.1zrv2e8arm6": "JT65 heeft ook “[[dec.short.JT65AP]]” (a-priori-decodering), “[[dec.short.IncludeCorrelation]]” (diep zoeken) en de knop ⟲ ([[mode.jt65clearAvg]]). MSK144 heeft de keuzelijst [[mode.mskperiod]] (5, 10, 15 of 30 seconden) en “[[mode.mskSh]]” (korte berichten). WSPR en FST4W hebben [[mode.wsprPower]], “[[mode.wsprPct]]” (het percentage perioden waarin de baken zendt) en “[[mode.wsprType1]]”. Fabriekswaarden: vermogen 37 dBm (5 W), Tx Pct 20%.",
  "t.1zt7h0shgkk": "“[[exp.edit.save]]”: slaat de correcties op (heb je niets gewijzigd, dan sluit het gewoon). “[[exp.edit.cancel]]”, Esc of een klik buiten het venster: sluiten zonder iets te wijzigen. “[[exp.edit.delete]]”: haalt de QSO na een bevestiging uit het logboek en het ADIF-bestand van Aurora; vanuit het programma kun je dit niet terughalen.",
  "t.1zu9wsz6z6m": "Kop · cijfers van vandaag (UTC-dag): [[auto.today.replies]] (in dry run verschijnt [[auto.today.would]], dus die Aurora zou hebben gegeven), [[auto.today.qsos]] (gelogde QSO's met stations die de automatisering heeft geroepen of die op zijn CQ hebben geantwoord) en [[auto.today.last]] (tijd en roepnaam, of CQ).",
  "t.1zumwm5gl60": "In de radio: data-audio via USB (bijvoorbeeld DATA MOD USB bij Icom, DATA VOX OFF bij Kenwood).",
  "t.1zw1qhv3cmz": "Spots via de telnet-cluster",
  "t.1zxrc8yhpit": "PSK Reporter (vak alleen voor ontvangst) · “[[onl.psk]]” (standaard aan): Aurora luistert in realtime naar mqtt.pskreporter.info voor nieuwe ontvangsten van je roepletters en vraagt elke 5 minuten aan pskreporter.info om die van de laatste 3 uur, en toont ze in [[nav.propagation]] (kaart en lijst): wie jou heeft ontvangen en waar. De twee sites zien je roepletters en je IP-adres. Zet het uit als je niet wilt dat Aurora PSK Reporter benadert om te lezen.",
  "t.1zyec6zb70w": "“[[sstv.rx.mode]]” (rechts): de herkende modus. Eronder hoe die is gekozen: “[[sstv.rx.byVis]]”, “[[sstv.rx.bySync]]” (zonder VIS, als “[[sstv.set.autoSync]]” aan staat in de Instellingen) of “[[sstv.rx.byHand]]” (met “[[sstv.rx.force]]”).",
  "t.2008xw2r7nc": "Het eerste tabblad van de rechterkolom toont de spots van het DX Cluster van Aurora; een klik op een spot brengt de radio naar dat station. Het gekozen tabblad wordt onthouden.",
  "t.2012n4alzvz": "[[digi.menu.configure]] › [[digi.mi.modeSettings]]: opent de Instellingen op de pagina “[[sw.pg.digiRxTx]]” van de tekstmodi.",
  "t.201laoj2kku": "[[sw.contest.title]] · [[contest.set.freqs]] en [[contest.set.save]]: de frequentieknoppen (één klik zet de radio op de voorgestelde frequentie, CAT is nodig) verschijnen als de regels ze noemen; [[contest.set.save]] slaat het formulier op en toont “[[contest.set.saved]]”. Het formulier slaat niet vanzelf op en [[sw.save]] van het venster slaat het niet op.",
  "t.201lsgz12us": "De TX-aanduiding blijft branden terwijl de radio afstemt met TUNE; «Split uit» is altijd zichtbaar. Geen valse crashes meer na een update of het uitschakelen van de pc; één foute regel kost niet meer de hele frequentietabel; de Log4OM-database geeft een duidelijke melding.",
  "t.203aamp1587": "[[about.news]]: de laatste drie nieuwsberichten, in de taal van Aurora, en de link “[[about.allNews]]” die de pagina Nieuws in het hoofdvenster van Aurora opent.",
  "t.203wdkps573": "Audio met SDR’s en netwerkprogramma’s: met CAT op TCI (onderdeel [[sw.pg.sdr]]) tonen de twee lijsten “TCI (dalla radio)” als ingang en “TCI (alla radio)” als uitgang, zonder virtuele audiokabels; met Cat4OM verschijnt “Cat4OM (audio in rete)”. De knop “[[sdr.useAll]]” op de SDR-pagina kiest ze voor je. Het vak [[lay.notes]] onderaan herhaalt de algemene uitleg.",
  "t.2051s3gm1ss": "Berichten van de auteur: groeten en belangrijke mededelingen geschreven door wie Aurora ontwikkelt, één voor één, elk maar één keer; heeft een bericht een link, dan opent de knop “Openen” die in de browser. Ze verschijnen ook bij “Niet storen” en volgen vandaag de regel “[[agent.kind.news]]” in de Instellingen niet.",
  "t.205m6hveyjn": "[[ctl.split]] schakelt split in, [[ctl.clear_dx]] wist het te roepen station.",
  "t.206ei34l6qb": "[[nav.news]]",
  "t.206wy5h9dnk": "Boven het vak staat de macrobalk: 12 toetsen per rij (F1-F12), 4 rijen met Ctrl en Shift; het tandwiel toont ze allemaal. Een klik of de toets op het toetsenbord voert de macro uit; rechtsklik bewerkt hem (of “[[digi.mi.macrosMode]]” in het menu [[digi.menu.configure]]): toets, label, kleur, tekst, commando’s tussen < >, voor alle modi of alleen voor die in gebruik (zie “De macrobalk” en “Een macro bewerken”). De gegevens van het andere station die de commando’s <CALL>, <NAME> en <QTH> gebruiken, staan in de blauwe rij van de huidige QSO, in het tabblad “[[digi.log.title]]” rechts: typ ze daar in, of ze worden ingevuld met een dubbelklik op een roepletters in het ontvangstvenster (zie “Rechterkolom: het tabblad “[[digi.log.title]]” en de huidige QSO”).",
  "t.207qkeyjdqt": "Elk geheugen bewaart modus, frequenties, RTTY, AFC, Snap en squelch. Het wordt opgeslagen via het menu [[digi.menu.options]] › [[digi.mi.memory]] › [[digi.mi.memWrite]] van de pagina; bij “[[sw.mem.title]]” zie je het, roep je het op met “[[sw.mem.load]]” of maak je het leeg met “[[sw.mem.clear]]”.",
  "t.20965jg1461": "RX / TX: laat zien of je ontvangt of zendt; een klik start het zenden (als je inactief bent) of stopt het meteen (terwijl je zendt). Het knippert als [[digi.mi.flashTx]] aan staat.",
  "t.209z0b0ni5y": "“[[rep.show]]” en “[[rep.showAuto]]” tonen precies de tekst die zou worden verzonden. Rapporten gaan naar de dienst van de ontwikkelaar van Aurora (op Cloudflare) en worden na 90 dagen gewist; het ID is een willekeurig getal dat je met “[[rep.newId]]” opnieuw kunt maken.",
  "t.20a5tqkgjzi": "[[hl.title]]",
  "t.20bkxhtwl5x": "Van tijd tot tijd komt er rechtsonder een kaartje met een geluid, geschreven door de mensen die Aurora ontwikkelen (groeten, servicemeldingen, belangrijke updates). Het komt maar één keer per bericht, in de taal van Aurora, ook als Aurora gesloten is via de agent in het systeemvak; de knop “[[agent.msg.open]]” opent de link van het bericht, als die er is. Het kan niet worden uitgezet.",
  "t.20bry53rkhx": "Taal, thema en volume vanuit de balk",
  "t.20e78cp0jos": "[[sw.fam.modes]]",
  "t.20ehd3jbsbl": "[[tab.clock]]",
  "t.20frlozdny3": "Aurora controleert zelf en biedt de nieuwe versie aan: “[[upd.poster.install]]” installeert en start opnieuw, “[[upd.later]]” stelt uit. De opties staan in [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].",
  "t.20gxgrmg7dh": "Met de radio uit blijft het display zichtbaar, in grijs, en verdwijnt het niet meer met Cat4OM, TCI of FT-991(A) Link. In de DX-cluster staan «DX-spot» en het tandwiel met opties rechts in de titelbalk, niet meer boven de tabel.",
  "t.20j1ndldluq": "[[lay.status]] · [[upd.install]]: gemarkeerde knop die alleen verschijnt als er een nieuwe versie is en Aurora hem kan installeren (dat wil zeggen op de computer waarop Aurora draait, niet vanaf een telefoon). Hij downloadt en controleert de handtekening, sluit dan Aurora en start het bijgewerkt opnieuw, met hieronder een voortgangsbalk ([[upd.progress.title]]). Als het mislukt, verschijnt het bericht en kun je het installatieprogramma met de hand downloaden via de link “[[upd.open]]”.",
  "t.20jd6etq7vv": "[[not2.grpAlerts]] · [[not2.soundMy]]: vakje dat bij elk bericht met jouw roepletters het geluid afspeelt dat is gekozen voor “[[kind.my_call]]” op de pagina “[[sw.tab.colors]]”. Standaard aan; anders dan de melding hierboven, die afgaat als iemand jou roept.",
  "t.20jmfs0uzs": "Als de pc de versie al heeft gedownload, staat er in plaats van het pictogram een kleine oranje balk met de voortgang (“Controleren…”, “Installeren…”); als de download klaar is, staat er “[[upd.strip.ready]]” met de knop “[[upd.strip.install]]” (één klik en het wordt geïnstalleerd). Als de download mislukt, verschijnt “[[upd.strip.failed]]” met “[[upd.strip.retry]]”.",
  "t.20k2394mnwn": "Spots gecontroleerd op DXSummit",
  "t.20kddj4t9q": "Gaat in TX maar geen vermogen: dan is het audio (uitgang in [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]], data-audio via USB, niveau).",
  "t.20l43wh1l14": "Zend en let op de ALC van de radio.",
  "t.20myrhzl46s": "[[not2.grpTable]] · [[not2.perBand]] en [[not2.perMode]] (de twee vakjes na “[[not2.colHighlight]]”): ze bepalen wat als al gedaan telt. “[[not2.perBand]]”: het is nieuw, ook als je het op een andere band hebt gewerkt; “[[not2.perMode]]”: het is nieuw, ook als je het in een andere mode hebt gewerkt (FT8, FT4…). Ze blijven uit en vergrendeld als het vakje “[[not2.colHighlight]]” van de rij uit staat. Standaard: land en roepletters per band en per mode; grid alleen per band; zones en prefix uit.",
  "t.20n6onq38at": "Velden: [[exp.f.call]] (3 tot 13 letters, cijfers of “/”), [[exp.f.date]] en [[exp.f.time]] (in UTC), [[exp.f.band]] (keuzelijst), [[exp.f.freq]] in MHz (bijvoorbeeld 14.074, of leeg), [[exp.f.mode]] (keuzelijst, verdeeld in “[[exp.mg.digital]]”, “[[exp.mg.voice]]”, “[[exp.mg.cw]]” en “[[exp.mg.other]]”), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 of 8 tekens, of leeg), [[exp.f.name]], [[exp.f.qth]] en [[exp.f.comment]].",
  "t.20o1ldevfg3": "Het downloaden van de gegevens mislukt: controleer de verbinding en of minstens één server is aangevinkt, en probeer een andere server; heb je er zelf een toegevoegd, controleer dan of het adres echt een TLE-lijst geeft.",
  "t.20pkwpsdcyp": "De richting wordt berekend van jouw locator naar die van het DX-station: beide zijn nodig.",
  "t.20q16eoo4pl": "Aurora zegt TX maar de radio blijft op ontvangen: het is bijna altijd de CAT of de PTT.",
  "t.20qi9sydfd5": "Is “[[sup.sendMail]]” grijs? Typ eerst een volledig adres (met @ en domein) in “[[sup.email]]”.",
  "t.20uvyygzq45": "Paden worden met “›” geschreven, bijvoorbeeld [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]. eQSL, Wavelog, ClubLog, QRZ.com en LoTW staan in “[[sw.fam.log]] › [[sw.sec.log]]”; GridTracker, Log4OM en N1MM in “[[sw.fam.log]] › [[sw.pg.reporting]]”; spots naar PSK Reporter en DXSummit in “[[sw.fam.log]] › [[tab.online]]”.",
  "t.20uzsoaq7g2": "De RTTY-ontvanger decodeert elk teken als geheel en geeft het de kans dat het juist is: onzekere tekens verschijnen vervaagd. Drie ketens werken samen (gewoon, met begrenzer en met niveaus ten opzichte van de ruis) en voor elk teken wint de zekerste: zo houdt hij fading, flutter en een pompende AGC van de radio uit. Een verloren letters/cijfers-wissel wordt aan het eind van het woord hersteld, en herhaalde woorden (roepnamen, rapporten) worden opgeteld.",
  "t.20v3nqqvvok": "[[ctl.hound]]: Hound-modus, om een DXpeditie in Fox/Hound te roepen (hij gaat meestal vanzelf aan, zie “Een DXpeditie werken als Hound”). [[ctl.swl]]: alleen luisteren, de decoder zoekt dieper.",
  "t.20vp1pglfk6": "Het RX-venster staat standaard aan, zoals “Rx Frequency” in WSJT-X: het toont berichten rond de RX-frequentie, die aan jou gericht zijn en je eigen zendingen. Zet het uit en weer aan met de RX-knop in de waterval-balk; de keuze wordt onthouden.",
  "t.20w36e9pqt0": "Elke rij heeft het pictogram van het type, het versienummer, de titel en de datum; een klik op de rij opent de tekst. De rij van de versie die je gebruikt, staat al open en is gemarkeerd met “[[news.current]]”.",
  "t.20xvs11zzoe": "Display, cluster, PSK·RTTY·CW-vensters en knoppen",
  "t.20yls9a5lmo": "De pagina [[nav.sstv]] ontvangt en verzendt beelden (Martin, Scottie, Robot, PD, Wraase) met dezelfde geluidskaart en PTT als FT8, zonder het te storen.",
  "t.210fiinkhek": "Wat de automatische rapporten versturen: versie van Aurora en Windows, engine, radiomodel, PTT, CAT-backend, naam van de geluidskaart, probleemgebied, opgeschoonde foutmelding en hoe vaak het is gebeurd. Na een crash ook het opgeschoonde logboek en de tekstrapporten. Wat nooit wordt verstuurd: roepletters, locator, gedecodeerde berichten, QSO-logboek, ALL.TXT, instellingen, wachtwoorden en sleutels, IP-adressen, e-mailadressen, je Windows-gebruikersnaam. De identificatie is een willekeurig nummer dat je met “[[rep.newId]]” opnieuw kunt maken.",
  "t.2117n5wb41l": "De taal staat niet bovenaan: wijzig die in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], item “[[gen.language]]”. De geluidsmeldingen (de luidspreker, met het volume ernaast) en het lichte of donkere thema staan in de onderbalk, rechts, bij de klok (zie “Taal, thema en volume vanuit de balk”).",
  "t.211kx04qlqj": "[[not2.grpColors]]: één vak voor elk van de 17 berichttypes (“[[kind.tx_msg]]”, “[[kind.cq]]”, “[[kind.my_call]]”, “[[kind.standard_call]]”, de nieuwtjes CQ-zone, ITU-zone, land, grid, prefix en roepletters, elk ook “op nieuwe band of mode”, en “[[kind.worked_call]]”). Elk vak heeft, van links af: het geluidsmenu van dat type, een kleurstaal met jouw roepletters en de kleurkiezer. Klik op de kiezer en kies de kleur die je het mooist vindt: je ziet haar meteen in de staal en in de lijsten.",
  "t.211ykywfwvg": "Sommige macro’s gelden maar voor één modus: standaard zijn F10-F12 de snelheden, PSK31/PSK63 voor PSK, 15, 20 en 25 WPM voor CW, 45,45, 50 en 75 baud voor RTTY. Ze vervangen de basismacro’s of vullen ze aan volgens “[[digi.mi.macrosMerge]]”.",
  "t.2123icg13hx": "Met TCI (SDR) wordt de Pwr-schuifregelaar niet gebruikt: stel het vermogen in op de SDR, met PWR − / + op het radiodisplay.",
  "t.21446bqttn4": "Als het logboek leeg is, verschijnt “[[cta.log.none]]” met de knop “[[cta.log.go]]”, die naar de logboekinstellingen leidt. Hoeveel QSO’s je ziet, kies je in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] (“[[gen.log4omCount]]”).",
  "t.214pt3p7h1q": "Dit zijn de drie meest gestelde vragen. Taal, thema en volume staan niet allemaal op dezelfde plek: de taal staat in de Instellingen, volume en thema staan in de onderbalk.",
  "t.216kjz1gmzj": "De vensters “Modusinstellingen” en “RTTY-instellingen”",
  "t.2179qtk8zku": "Een QSO die je in Aurora corrigeert of verwijdert, wordt in de andere logboeken niet gecorrigeerd of verwijderd: dat moet daar ook met de hand.",
  "t.217tjo3iwzn": "Op de SSTV-pagina werken de toetsen als het tabblad “[[sstv.view.tx]]” zichtbaar is (behalve Esc, dat in heel Aurora ook een algemeen effect heeft).",
  "t.21a1efmlhqh": "[[win.where]]: één rij per onderdeel (“[[panel.waterfall]]”, “[[panel.station]]”, “[[panel.tx]]”, “[[panel.cq]]”, “[[panel.all]]”, “[[panel.log]]”, “[[panel.cluster]]”, “[[nav.dxmap]]”, “[[prop.psk]]”, “[[win.display]]”, “[[nav.rotator]]”, “[[nav.sstv]]”) met een menu dat zegt waar het staat. De keuzes: “[[win.place.main]]” (standaard), “[[win.new]]” (een eigen venster, om naar het tweede scherm te brengen), “[[win.dash]]” (het blokkendashboard, één venster dat de onderdelen verzamelt die je erin zet), de lijst van al geopende aparte vensters (om het erin of ernaast te zetten) en “[[win.place.hidden]]”.",
  "t.21bar5xhxz1": "LogHX en GridTracker samen: gebruik in Aurora “+ [[int.p.multicast]]” (239.255.0.1, poort 2237) en zet in LogHX multicast aan met dezelfde groep en poort; of laat LogHX de pakketten opnieuw doorsturen naar het andere programma (rebroadcast).",
  "t.21blg5x59q1": "De tray-agent (naast de klok) gebruikt de in Aurora gekozen taal: de pop-upkaarten volgen die meteen, het tray-menu na een herstart van de agent (bijvoorbeeld bij de volgende Windows-start).",
  "t.21dpexqeny0": "“Controleer op updates”: controleert meteen of er een nieuwe versie is (op GitHub) en antwoordt altijd met een kaart: “Aurora X is klaar” met de knop “Nu bijwerken” en het nieuws in het kort, of “Aurora is up-to-date”, of “Controle mislukt” als GitHub niet antwoordt.",
  "t.21esaya6sz": "Het radiodisplay bovenaan verschijnt niet: zonder CAT zou het niets te tonen hebben. Het komt terug zodra je Hamlib, OmniRig of TCI kiest.",
  "t.21f62p2a5vc": "Het handvat aan de bovenrand van het paneel sleep je om de hoogte van de lijst te wijzigen; de hoogte wordt onthouden. De opties “[[digi.band.spots]]”, “[[digi.band.spotsCqOnly]]” en “[[digi.band.wfCalls]]” zet je aan in de menu’s Opties en Beeld (geverifieerde roepnamen worden lokale spots van de DX Cluster van Aurora, op je pc; er gaat niets het netwerk op).",
  "t.21gkdzekv6r": "Op een pc die het zwaar heeft, worden tijdens het decoderen de achtergrondtaken (DX Cluster, DXpedities, PSK Reporter, roepnaam opzoeken, LoTW-lijst, satellietgegevens, controle op updates) even opzijgezet en uitgevoerd zodra het decoderen klaar is, hooguit 30 seconden later. Zo verliest de audio geen blokken en loopt het decoderen niet uit. Er gaat niets verloren: spots en gegevens komen gewoon een paar seconden later. Bovendien gebruiken SSTV, PSK · RTTY · CW en satellieten niets terwijl je FT8 werkt, als hun pagina’s gesloten zijn.",
  "t.21gpc0ka26m": "Stel je locator in bij [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]], open dan de pagina [[nav.sat]] en druk op “[[sat.tle.refresh]]”: Aurora downloadt de baangegevens van de servers die gekozen zijn in [[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sw.pg.orbits]] (standaard die van Aurora; ze worden elke dag vanzelf vernieuwd).",
  "t.21gw3dm3a8g": "Zonder QR: maak op de pc een code en schrijf hem in het veld “[[pair.code]]”: 8 cijfers, alleen getallen (andere tekens worden genegeerd), die welke de pc toont bij “[[acc.code]]”. De code is geldig voor de tijd die bij “[[acc.ttl]]” is ingesteld (standaard 10 minuten), wordt maar één keer gebruikt, en na een paar foute pogingen weigert de pc een tijdje.",
  "t.21idyztdfns": "Het paneel Signalen (CW en PSK)",
  "t.21jh5pzljj4": "Vrije tekst langer dan 13 tekens wordt nog steeds op 13 afgekapt.",
  "t.21lx89o54mz": "Het toont de laatste QSO’s: die van Log4OM als Aurora zijn logboek leest, anders het eigen logboek van Aurora, met land en rapporten.",
  "t.21sk97fza8c": "STOP TX schakelt de automatisering altijd uit en stopt ook de CQ die het zelf heeft geroepen. De limieten op de pc en het uitschakelen als er geen apparaat is verbonden blijven van kracht. In live-modus zet Aurora [[ctl.enable_tx]] vanzelf aan (zonder dat gaat er geen antwoord uit); wanneer de automatisering stopt, om welke reden ook, gaat [[ctl.enable_tx]] terug naar hoe het was voordat je het aanzette.",
  "t.21trv0vcmh2": "Volledig onderdeel: «De radio zendt niet»; «Hij zendt maar het vermogen is nul»; «De PTT schakelt niet».",
  "t.21uf1d2i1yf": "VFO schakelt naar de andere (A en B, of Main en Sub). RIT en XIT: een klik zet ze op nul.",
  "t.21y3v2t291c": "[[sw.station]] · [[gen2.call]]: je roepletters zoals je die zendt (bijvoorbeeld IU3ABC, of IU3ABC/P als je portable werkt). Ze komen in de berichten en het logboek. Verander ze alleen als je van roepletters wisselt of portable werkt. Ze gaan in na “[[sw.save]]” onderaan; staat er bij het item “[[ens.restart]]”, dan gaan ze in bij de volgende start.",
  "t.21yup8z1c8p": "[[ens.g.wsprnet]] · [[ens.k.WSPRnetUpload]]: vakje (het heet “[[ens.svc.on]]”), standaard uit. Aan: na elke ontvangen WSPR- of FST4W-periode stuurt Aurora wsprnet.org een rapport voor elk gedecodeerd signaal (of, als er niets is, de status van je station). De spots worden openbaar op de site en gaan via http, niet versleuteld; uit wordt er niets verstuurd. Je roepletters en locator ([[sw.sec.station]] › [[sw.pg.personal]]) en de radiofrequentie via CAT zijn nodig.",
  "t.21yuqhi6ilk": "Titelbalk: “[[rxw.title]]”, rechts de Rx-frequentie met zijn tolerantie (bijvoorbeeld “1500 Hz ±50”), daarna “[[list.clear]]” en “[[list.bottom.off]]” / “[[list.bottom.on]]”, die werken als in Bandactiviteit maar alleen hier gelden.",
  "t.223uns9doq0": "De DXCC-kaart vertelt je of het station dat je roept een nieuw land voor je is. Je vindt hem in het paneel Logboek en uitgebreid op de pagina [[nav.stats]]. Je stelt hem in via [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (welke rijen en banden, het totaal, het veld “Probeer”, de bijschriften).",
  "t.226h99jaxuu": "De radio maakt geen verbinding: waar begin ik?",
  "t.227dtqmxn71": "Het zenden stoppen",
  "t.22901fmxpqh": "Druk op “[[sstv.tx.send]]”: de radio zendt en de balk toont de voortgang; “[[sstv.tx.stop]]” zet audio en PTT meteen uit. Het verzonden beeld blijft in “[[sstv.hist.sent]]”. Met het toetsenbord: F1 zendt en Esc stopt (zie “SSTV: sneltoetsen”).",
  "t.229k1hp15wk": "[[sw.pg.radio]]: [[cat.grp.test]], [[cat.grp.ptt]], [[cat.grp.split]]",
  "t.22ajjfmkbez": "[[sw.testPtt]]: vraagt om bevestiging (“[[sw.pttConfirm]]”) en laat de radio dan één seconde ZENDEN. De test begint aan het begin van de volgende periode (in FT8 tot 15 seconden: de statusregel zegt “[[sw.pttWait]]”) en eindigt dan met “[[sw.pttDone]]”; gaat de radio niet in de lucht, dan zegt hij “[[sw.pttFail]]” (zenden niet ingeschakeld, verkeerde PTT of CAT). Sluit eerst een dummy load of een geschikte antenne aan.",
  "t.22bwkb77sn3": "De led AutoSeq draagt het niveau in zijn tekst (“AutoSeq 3”). Details over “[[ctl.wait_call]]” en “[[ctl.pounce]]” staan in “Wachten en antwoorden en [[ctl.wait_call]]”.",
  "t.22d54cz1fd8": "De rij met ontvangstbediening",
  "t.22dc4uvhe8a": "[[digi.tx.title]] · [[digi.autoReceive]] (standaard uit): met het vak aan begint het luisteren naar PSK, RTTY en CW vanzelf als Aurora start; uit start je het vanaf de werkpagina.",
  "t.22eo1jl1r4": "Een overzicht van alle bijzondere toetsen en klikken van de Stationspagina en de pagina’s eromheen.",
  "t.22f5qaykw46": "“[[pair.name]]”: de naam waaronder de telefoon op de pc verschijnt bij “[[acc.devices]]”. Aurora stelt er een voor op basis van het model van de telefoon; je kunt hem vrij wijzigen (van 1 tot 64 tekens).",
  "t.22fvp56w44y": "[[sw.digi.perMode]] · RTTY, “[[digi.rtty.shift]]” en “[[digi.rtty.baud]]”: twee uitklaplijsten met de meest gebruikte waarden. Fabrieksshift 170 Hz (je kunt kiezen van 23 tot 850) en snelheid 45,45 baud (van 45 tot 300). Ze moeten die van het station zijn waarnaar je luistert: met verkeerde waarden krijg je onzintekst.",
  "t.22h82abtngk": "De keuzelijst links ([[map.style]]) verandert de achtergrond van de kaart; de schuif ☼ ([[dxmap.brightness]]) maakt hem lichter of donkerder.",
  "t.22i3addk47y": "[[nav.sstv]]: schakelt naar de SSTV-pagina (de SSTV-pagina heeft bovenaan dezelfde lijst met modi en brengt je hier terug).",
  "t.22lgdc68zg9": "Als je externe logboek al naar een dienst uploadt, zet die dan niet ook in Aurora aan: het QSO zou dubbel aankomen.",
  "t.22ljnjrah7v": "[[cat.grp.link]] · [[cat.backend]]: hoe Aurora met de radio praat. “[[cat.backend.hamlib]]” (fabrieksinstelling) past bij bijna elke radio met een kabel; “[[cat.backend.omnirig]]” (alleen Windows) is alleen nodig als de radio al in OmniRig is ingesteld; “[[cat.backend.tci]]” voor SDR’s; “[[cat.backend.ft991link]]” als dat programma de poort van de FT-991 vasthoudt; “[[cat.backend.cat4om]]” om de radio met Log4OM te delen; “[[cat.backend.none]]” om zonder CAT te werken (band met de hand). Verander het alleen als je Hamlib niet gebruikt.",
  "t.22m8cfu5mxs": "[[ap.text]] · [[ap.color]]: de kleur van alle tekst. “[[ap.colorTheme]]” (standaard) gebruikt die van het thema; daarna zes kant-en-klare kleurstalen en de vrije kiezer “[[ap.colorFree]]”. Het wordt apart onthouden voor het lichte en het donkere thema. Onder de regel zie je de contrastverhouding: als die onder 4,5:1 zakt, waarschuwt een melding dat de tekst moeilijk leesbaar kan zijn, en is een sterkere kleur aan te raden.",
  "t.22mlcj14nt5": "Foxpagina: alle opdrachten",
  "t.22pi0qcdhbf": "“[[int.ttl]]” (alleen met multicast; standaard 1, 1 tot 255): hoeveel routers het datagram mag passeren. 1 blijft binnen het thuisnetwerk en is de aanbevolen waarde. “[[int.iface]]” (alleen met multicast, optioneel): het IPv4-adres van deze pc waarvandaan de multicast vertrekt: 127.0.0.1 voor programma’s op deze pc, het adres in het thuisnetwerk voor een andere computer; leeg laat Windows kiezen.",
  "t.22t42a3x3cs": "Audio-ingang oververzadigd (rood), stil (geel) of zwak (lichtblauw): pas het opnamevolume van Windows aan, de kabel of het gekozen apparaat; naast de schuifregelaar “Rx” staat ook “[[rxl.auto]]”, die het zelf bijstelt (zie “De niveaus Rx en Pwr”).",
  "t.22xdapv3zda": "[[auto.b4]] · [[auto.continents]]: het vakje [[auto.contExcludeShort]] en zeven continentvakjes (EU, NA, SA, AF, AS, OC, AN). Met minstens één continent aangevinkt antwoordt Aurora alleen daar; met [[auto.contExcludeShort]] aangevinkt doet het het omgekeerde en antwoordt het NIET op de gekozen continenten. Geen enkel aangevinkt = alles. Een station met onbekend continent wordt overgeslagen.",
  "t.22z0t7y55r": "Er wordt niets verzonden als zenden niet is ingeschakeld: zegt “[[sw.testPtt]]” “[[sw.pttFail]]”, controleer dan eerst [[sw.testCat]] en de PTT-methode in [[sw.pg.radio]].",
  "t.22z33rx43xk": "[[digi.menu.configure]] › [[digi.mi.macrosMode]] en [[digi.mi.macrosDefault]]: beide openen de Instellingen op de pagina “[[sw.pg.digiMacros]]” ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]]), waar je de macro’s in een tabel wijzigt. Om er maar één te wijzigen is een rechtsklik op de toets sneller.",
  "t.2307tdiv9lq": "De pagina [[nav.contest]] heeft bovenaan de contestbalk en, als er een contest loopt, drie tabbladen: “[[contest.tab.race]]”, “[[contest.training]]” en “[[contest.analysis]]”. Hoe je een contest instelt, staat in “Contests”.",
  "t.231gqsmkmh3": "RX/TX, Pause, Esc, dubbele Esc en automatisch CQ",
  "t.236uxnknikc": "[[not2.markers]] · [[not2.markOther]] (standaard aan): een lipje bij berichten tussen andere stations die een nieuwtje bevatten. [[not2.markRed]] (aan): rood lipje bij rijen waarin iemand jou roept. [[not2.markBlue]]: het lipje wordt blauw bij de rijen van het QSO dat je aan het maken bent; het is pas beschikbaar als het rode aan staat; standaard uit.",
  "t.237o2e61l01": "Dubbele QSO’s: laat hetzelfde QSO niet ook via GridTracker of JTAlert binnenkomen.",
  "t.238rnajf5jo": "Op de pagina [[nav.station]] verschijnt onder de Tx-berichten «Fox verified» in groen of «Fox NOT valid» in rood.",
  "t.23a5e9w3bxz": "[[cat.auto]] (standaard uit): bij elke start verbindt Aurora de radio zelf. Zet het aan als de instelling werkt en je niet elke keer op [[cat.connect]] wilt drukken. [[cat.extras]] (standaard uit): naast frequentie en modus leest Aurora voorversterker, verzwakker, AGC, NB/NR/notch, versterkingen, RIT/XIT, tuner en tweede VFO uit de radio, een paar tegelijk en alleen bij ontvangst: ze voeden het uitgebreide display. Op trage seriële poorten neemt het een beetje van de poort in. Deze twee vakken (en de volgende twee) worden meteen opgeslagen, zonder “[[cat.apply]]”.",
  "t.23b5c3vq97s": "In het geluidsmenu van elke melding staan, naast de geluiden van Aurora, “Stem” en “[[snd.myFiles]]”.",
  "t.23cvbvmuo7m": "De twee schakelaars bestaan alleen in FT8 en staan in de rij met ontvangstregelingen.",
  "t.23d1nrl16ab": "Kies in [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]] “TCI (dalla radio)” als ingang en “TCI (alla radio)” als uitgang.",
  "t.23dkvz8i4hz": "Bijna altijd is het de pc-klok: in FT8 moet die tot op een fractie van een seconde juist zijn. Kijk naar de klokwaarschuwing bovenaan en naar [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].",
  "t.23el4uxiawd": "Er komt niets aan: een ander programma gebruikt poort 2237 al (JTDX, WSJT-X, GridTracker). Sluit het, of gebruik een andere vrije poort (bijvoorbeeld 2239), zowel in Aurora als op de twee BBLogger-rijen.",
  "t.23g3w7frcxk": "Onderaan de boom staat “[[sw.tab.info]]”: dat is de pagina die je ziet als je Instellingen opent, met het laatste nieuws over Aurora en “[[about.donateTitle]]”.",
  "t.23g9wixqo90": "[[sw.sub.ft8]] · [[fil.decode]]",
  "t.23hu0ut17xa": "Rechterpaneel met een gekozen tekst: [[sstv.p.text]] (met de plaatsaanduidingen {MYCALL}, {CALL}, {RST}, {GRID}, {NAME}, {MODE}, {DATE}, {TIME} die zichzelf invullen), [[sstv.p.font]], [[sstv.p.size]], [[sstv.p.bold]], [[sstv.p.italic]], [[sstv.p.align]] ([[sstv.p.left]], [[sstv.p.center]], [[sstv.p.right]]), [[sstv.p.fill]] ([[sstv.p.solid]] of [[sstv.p.gradient]] met [[sstv.p.from]], [[sstv.p.to]] en [[sstv.p.angle]]), [[sstv.p.outline]] ([[sstv.p.width]] en [[sstv.p.color]]), [[sstv.p.shadow]], [[sstv.p.box]] (met [[sstv.p.color]] en [[sstv.p.opacity]]) en [[sstv.p.rotation]]. Elke kleur heeft de kiezer en een palet.",
  "t.23jjz5ohuct": "[[sw.digi.perMode]] · PSK31 · PSK63, schuifregelaar voor de squelchdrempel (van 0 tot 100, fabriek 15): hij meet de fasekwaliteit van het signaal, niet het volume, en werkt dus hetzelfde met sterke of zwakke audio. Op ruis alleen blijft de kwaliteit onder 10; met 15 komen signalen tot ongeveer -10 dB S/R door. Verhoog hem als er tekens op ruis verschijnen, verlaag hem als je zwakke signalen mist. Hij telt alleen met “[[digi.mi.squelch]]” aan.",
  "t.23le4ssow6p": "“[[wish.recent]]” (onderaan): de laatste meldingen die zijn afgegaan (maximaal 12), één per regel, met de roepletters, waarom ze afging (roepletters, prefix, land of grid), waarvandaan (bericht, cluster of test), band, frequentie en tijd. Als er geen melding is, zie je “[[wish.none]]”. Zo controleer je of de lijst doet wat je wilde.",
  "t.23mimunzod0": "Bijna altijd hoef je er niet aan te komen: laat 0 staan, dat betekent “de fabriekswaarde van het model”. Het veld verschijnt alleen als Hamlib, een seriële poort en een Icom-radio zijn gekozen (of als de waarde niet 0 is) en accepteert getallen van 0 tot 255.",
  "t.23mupz92383": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]]. De stations die je wilt werken: Aurora let op elk gedecodeerd bericht en elke clusterspot, ook met de pagina dicht, en waarschuwt je één keer per station (en wacht daarna de tijd die je kiest). Eén item per regel. De pagina slaat zelf op; is een item fout, dan verschijnt een rode waarschuwing en wordt er niet opgeslagen. Volgorde op het scherm: “[[lay.lists]]”, “[[lay.options]]”, “[[wish.notifyUrl]]”, “[[wish.recent]]”.",
  "t.23nepszvfx4": "De regels verbieden Fox/Hound en multi-streaming: zolang een contest actief is blijven ze uit. Veel contesten eisen ook dat de operator elke QSO start (geen onbemande automatische CQ). Regels veranderen elk jaar: “[[contest.rules]]” toont de controledatum, de te controleren punten en de link naar de officiële regels. Samengestelde roepnamen passen niet in contestberichten (alleen /P en /R): Aurora blijft bij normale berichten.",
  "t.23on29akgex": "Bij te veel signalen houdt Aurora de sterkste over, om niet meer dan een kwart van een kern te gebruiken; lokale spots gaan alleen naar het DX Cluster-paneel van Aurora, op je pc.",
  "t.23sksb828q3": "De linkerknop verplaatst de groene balk (Rx), de rechterknop de rode (Tx); Shift + klik verplaatst ook de rode. Houd de knop ingedrukt en de balk volgt de muis. De rode beweegt zelfs terwijl je zendt: de toon verandert meteen. Kies een vrije plek om te zenden.",
  "t.23toivqqjjw": "Tweede deel van [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: de spectrumgrafiek onder de waterval, balken en frequentie, kant-en-klare stijlen en eigen palet. Alles werkt meteen.",
  "t.23tti1u10ta": "Bovenaan staat de menubalk: [[digi.menu.file]], [[digi.menu.edit]], [[digi.menu.mode]], [[digi.menu.options]], [[digi.menu.view]], [[digi.menu.configure]], [[digi.menu.help]]. Elk onderdeel wordt in de menusecties hieronder uitgelegd. Een klik opent een menu; over de andere menu’s bewegen schakelt naar die menu’s, en een klik buiten het menu of Esc sluit het.",
  "t.23vatsl8ye7": "OmniRig: Aurora bestuurt het rechtstreeks via COM, zoals WSJT-X, zonder PowerShell. De fout “toegang geweigerd” is verdwenen, het OmniRig-venster springt niet meer op en PTT is sneller. OmniRig moet alleen geïnstalleerd zijn met de radio erin ingesteld.",
  "t.23xmg2eqqh0": "Zet in “[[fox.callers]]” de stations in de wachtrij (ook met een dubbelklik); Aurora zendt het rapport, wacht op R+rapport en sluit af met RR73, ook gecombineerd met het rapport voor de volgende.",
  "t.2401bzqbejm": "[[digi.mi.squelch]]: alleen wat boven de drempel van de modus uitkomt, wordt afgedrukt. Standaard uit; de drempel stel je in bij “[[digi.mi.threshold]]”.",
  "t.240ijs1xzhu": "Lijkt het CI-V-adres hexadecimaal ingetypt (88 in plaats van 136), dan verschijnt onder het veld een waarschuwing met een knop om het te corrigeren.",
  "t.244ncipyxnt": "[[sw.contest.title]] · [[sw.contest.open]]: knop; opent de pagina [[nav.contest]] in het hoofdvenster, waar je de contest activeert, aanroept en het logboek exporteert (EDI voor VHF-contests).",
  "t.2471n4jkyk0": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] en vink in het vak [[auto.b5]] “[[auto.autoCqOn]]” aan. Typ in het veld “[[auto.autoCq]]” na hoeveel minuten zonder CQ om te beantwoorden Aurora CQ moet roepen (2 tot 120; aanvinken van het vakje begint met 5).",
  "t.248k7d5gnb6": "[[cop.rotor]]: met dezelfde handeling draaien de radio en de antenne naar het land van de spot. Hiervoor moet de rotor verbonden zijn en je locator ingesteld. Standaard uit.",
  "t.24adwogtq3j": "“[[ens.g.adif]]” · “[[ens.k.UDP2Resend]]” (standaard aan): als het logboek dicht is wanneer je een QSO maakt, bewaart Aurora hem apart en stuurt hem vanzelf ongeveer 15 seconden nadat je het weer opent, in de volgorde waarin je ze hebt gemaakt. Het geldt voor een logboek op deze pc (127.0.0.1); bij het adres van een andere pc gaan de QSO’s meteen weg. Elke QSO wordt één keer verstuurd, de wachtrij blijft bestaan als je Aurora sluit en na zeven dagen wordt hij weggegooid. Details bij het onderwerp “Lost QSOs while the log is closed: where to turn it on”.",
  "t.24b20akmiin": "[[cat.grp.test]] · [[cat.state]]: de LED en de tekst vertellen hoe het gaat: “[[cat.state.disconnected]]”, “[[cat.state.connecting]]”, “[[cat.state.connected]]” (met [[cat.freq]], [[cat.radiomode]] en [[cat.ptt.state]] uit de radio gelezen), “[[cat.state.reconnecting]]” (Aurora probeert het zelf opnieuw) of “[[cat.state.error]]” met de reden in woorden. Mislukt het lezen, dan zegt een extra regel dat. Bij een Icom met PTT via CAT en een andere snelheid dan 115200 verschijnt een rode waarschuwing: het is de meest voorkomende oorzaak van een zending die niet start.",
  "t.24bagfpncpn": "Kolommen: “[[hist.col.when]]”, “[[hist.col.band]]”, “[[hist.col.mode]]”, “[[hist.col.snr]]”, “[[hist.col.freq]]” (audiofrequentie in Hz), “[[hist.col.text]]” (met het LoTW-teken als het station LoTW gebruikt) en “[[hist.col.country]]”. Een klik op een rij met een roepnaam zet die in het zoekveld (“[[hist.pick]]”).",
  "t.24hht2sedgq": "Grenzen en meldingen: het bestand mag niet groter zijn dan 256 MB (is het groter, exporteer het dan in twee delen, bijvoorbeeld per jaar, en importeer ze na elkaar); een leeg bestand geeft “The file is empty”; importeren kan alleen vanaf de pc of het thuisnetwerk, niet van buitenaf.",
  "t.24hpi0bswsx": "Is de tekst te klein? Kies in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] “[[ap.size]]” (van 90% tot 140%), of druk op elke pagina op Ctrl + en Ctrl − (Ctrl + gaat tot 160%); Ctrl 0 zet terug op 100%.",
  "t.24i2e8hwaxe": "Een DXpeditie werken als Hound",
  "t.24ne5y8joa1": "Volledig onderdeel: «Welke computer je nodig hebt»; «Als de pc traag decodeert».",
  "t.24o72g76kap": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]] → vak “[[rep.title]]”: zet “[[rep.ask]]” aan en, als je wilt, “[[rep.auto]]”. Om ze uit te zetten, haal je het vinkje weg: er wordt niets meer verzonden en de wachtrij wordt geleegd.",
  "t.24opqblujze": "Het RX-venster",
  "t.24pnj3k5z6s": "[[sw.sub.vhf]] · [[sw.pg.vhfModes]]",
  "t.24pqb3n8q72": "[[cmd.tune]] en [[cmd.logQso]] verschijnen als je ze aanzet in Instellingen › Modi › FT8 · FT4 › Berichten en filters: Tune zendt een draaggolf om af te stemmen (rood tijdens het zenden), Log QSO legt het lopende QSO met de hand vast. Tune start meteen, ook midden in een lange periode (FST4, FST4W, WSPR), en duurt hoogstens 2 minuten.",
  "t.24qv6x1jb5m": "Rechterkolom: het tabblad “[[digi.log.title]]” en de huidige QSO",
  "t.24uwtfqkts3": "Wat de waterval en de Rx- en Tx-balken tonen.",
  "t.24w5xxygqd6": "Komt een macro die roepnaam, naam of QTH noemt met lege plekken uit, vul dan eerst de gegevens in: de roepnaam en de gegevens van het andere station staan in de lichtblauwe rij van het “[[digi.log.title]]”, je eigen naam en QTH in “[[sw.pg.personal]]”.",
  "t.24x12qzxet1": "De knoppen van de kaart: “[[diag.slow_pc.to2]]” of “[[diag.slow_pc.to1]]” (verandert meteen de decodeerdiepte; het geldt vanaf de volgende periode), “[[diag.slow_pc.setting]]” (opent de pagina Decoderen) en de “×” die de kaart sluit. Eenmaal gesloten komt hij niet terug voor dezelfde diepte tot Aurora opnieuw start. Als de wijziging mislukt, zegt de kaart dat. Na een wijziging begint de telling van trage periodes weer bij nul.",
  "t.24xzt2qgjzu": "De melding over de trage pc blijft ook in het logboek van Aurora staan (met processors, decodeerthreads, diepte en SWL), handig om op te sturen naar wie je helpt met “[[sup.prepare]]”.",
  "t.24yhilxh6v1": "Een paar minuten geen bericht gedecodeerd (na 3 minuten stilte, lichtblauw): de band is dicht of de ontvangst is gestopt, controleer [[ctl.monitor]] en de audio.",
  "t.24yyynbym0j": "[[aud.apply]] (vak): “[[aud.apply]]” past de keuzes meteen toe (meestal niet nodig: ze worden na ongeveer een seconde en bij het verlaten van de pagina vanzelf toegepast); “[[aud.discard]]” annuleert de nog niet toegepaste keuzes; “[[aud.refresh]]” leest de apparaten van het systeem opnieuw in, om te gebruiken nadat je de radio hebt aangezet of de USB-kabel hebt aangesloten. Ernaast staat het aantal wachtende wijzigingen en eronder de uitkomst in gewone taal: wat is toegepast, wat niet en waarom, en welk apparaat in gebruik blijft.",
  "t.250gdylhk7j": "Twee kleine vensters die over de pagina heen opengaan. “[[digi.ms.title]]” opent met een klik op de modusgegevens in de statusbalk of met “[[digi.mi.threshold]]”; “[[digi.rtty.title]]” met een klik op de RTTY-naam onderaan (bij RTTY ook via het rechtsklikmenu op de statusbalk). Esc sluit ze.",
  "t.254y02fzch8": "Dubbele QSO’s: het QSO komt op twee manieren binnen. In [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] staan de primaire en secundaire UDP-server van Aurora ook op 127.0.0.1:2237: zet uit wat je niet nodig hebt, of verwijder de LogHX-bestemming en houd de primaire server.",
  "t.258p5r9c7rl": "Er is de instelling “[[dec.slowPc]]” ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]]): “[[dec.slowPc.auto]]” (standaard), “[[dec.slowPc.always]]” of “[[dec.slowPc.never]]”. Als ze aan staat, stelt Aurora tijdens het decoderen de achtergrondtaken (DX Cluster, PSK Reporter, LoTW en dergelijke) uit tot het decoderen klaar is. Als het decoderen niet op tijd klaar is, verschijnt bovendien een waarschuwing met de knop “[[diag.slow_pc.to2]]”, die de decodeerdiepte op Normaal zet: dat verandert Aurora nooit uit zichzelf.",
  "t.259lq1uavvh": "[[digi.edit.subset]] en de lijst eronder: alle opdrachten die Aurora kent, verdeeld in groepen ([[digi.edit.group.text]], [[digi.edit.group.program]], [[digi.edit.group.frequency]], [[digi.edit.group.autocq]], [[digi.edit.group.macros]], [[digi.edit.group.mode]], [[digi.edit.group.rotor]], [[digi.edit.group.rtty]], [[digi.edit.group.sstv]], [[digi.edit.group.cw]], [[digi.edit.group.hell]]), elk met zijn uitleg. Een opdracht met “[[digi.edit.soon]]” staat in de lijst, maar Aurora voert hem nog niet uit.",
  "t.25aimgdpxu": "Als je de update vanuit de agent in het systeemvak vraagt, verschijnt de poster niet: de kaart in het systeemvak doet alles. In het venster Instellingen verschijnt de poster alleen na “[[upd.check]]”, nooit vanzelf. Als je al de laatste versie hebt, opent hij met “[[upd.poster.upToDate]]”, je versie en de knoppen “[[upd.poster.allNews]]” en “[[upd.poster.ok]]”.",
  "t.25crq7s5inx": "Test: maak een QSO met Aurora (of voeg er met de hand een toe vanaf de Logboek-pagina): het moet in BBLogger verschijnen.",
  "t.25d17bdh2w1": "De kolommen verplaats je door de titels te slepen en maak je breder door de rand van de titel te slepen (dubbelklik op de rand: ze passen zich aan de inhoud aan); een rechtsklik op de titels opent ook het kolommenmenu. De linkerrand van de hele kolom kun je slepen om het logboek breder te maken.",
  "t.25dynay9sku": "[[wfs.colors]] · [[wfs.palette]]: de kleuren van de waterval, te kiezen uit 30 paletten plus “[[wfs.paletteUser]]” (je eigen, gemaakt in “[[wfs.palette.title]]”). Standaard “Default” (zwart, blauw, geel, rood). Naast het menu toont een balk de kleuren van het gekozen palet, van lage niveaus (links) tot sterke (rechts).",
  "t.25fic3gxngi": "“[[ctl.split]]”: houdt de zendfrequentie gescheiden van de ontvangstfrequentie (de split van de radio). “[[cmd.logQso]]”: verschijnt alleen als het op dezelfde plek is aangezet; het logt het QSO met de DX meteen, voor als de reeks het niet zelf heeft gedaan. “[[ctl.clear_dx]]”: maakt het station vrij om te roepen en de voorbereide berichten.",
  "t.25fsht9y7mj": "Windows: de poorten heten COM3, COM4… Verschijnt de poort niet in de lijst, open dan Apparaatbeheer van Windows, onder “Poorten (COM en LPT)”: de poort van de radio moet er staan, met de radio aan en de kabel aangesloten; ontbreekt hij, installeer dan het USB-stuurprogramma van de fabrikant.",
  "t.25h5cad6val": "[[clock.state]] · [[clock.correct]]: verschuift de Windows-tijd met de gemeten afwijking en meet daarna opnieuw. Aurora moet als administrator zijn gestart (rechtsklik op het pictogram › Als administrator uitvoeren: zonder dat weigert Windows en verschijnt een waarschuwing) en het werkt alleen vanaf de pc waar Aurora draait. Op Linux bestaat het niet: gebruik de synchronisatie van het systeem (NTP).",
  "t.25h5jjp955l": "“[[l4.title]]” · vak “[[l4.pathPlaceholder]]” met “[[l4.use]]” en “[[l4.remove]]”: typ of plak het pad met de hand en druk op “[[l4.use]]” (blijft uit zolang het vak leeg is); “[[l4.remove]]” laat Aurora de database niet meer gebruiken (uit als er geen is). Resultaat: “Database in use: N QSOs” of de fout (geen Log4OM-database, bestand vergrendeld, alleen te wijzigen vanaf het thuisnetwerk). Staat het pad in het bestand aurora.env (AURORA_LOG4OM_DB), dan ontbreken het vak en de knoppen: wijzig het daar en het geldt vanaf de volgende start.",
  "t.25ibcvqniw2": "Rechts van de modispillen staan de pagina’s. Eerst die van de groep in gebruik, dan een scheiding en de pagina’s die in elke modus werken, en ten slotte het tandwiel met zijn menu.",
  "t.25jf1lw7w2s": "Wie LoTW gebruikt",
  "t.25lc21xqqxb": "[[nav.fox]]: verschijnt alleen in de groep “FT8”. Hij is voor wie vanuit een DXpeditie zendt (zie “Pagina Fox: elk commando”); om een DXpeditie te roepen heb je hem niet nodig, je gebruikt Hound op de pagina Station.",
  "t.25lzwi0iowk": "Slechts één programma kan op een unicastpoort luisteren. Twee programma’s: elk één bestemming met verschillende poorten, of multicast als beide daarnaar kunnen luisteren.",
  "t.25mvirv3e8d": "[[wfs.bars]] · [[wfs.barsOn]] (standaard aan): de twee verticale balken op de waterval (groen Rx, rood Tx), net zo breed als het signaal van de modus, en de twee witte lijnen die de aanwijzer volgen. Als het uit staat, blijven alleen de labels over. [[wfs.periodLine]] (aan): een groene horizontale lijn bij elke nieuwe periode (geel als je in die periode hebt uitgezonden), om de periodes te scheiden.",
  "t.25my4rmsgi3": "Gebruik één methode tegelijk (netwerk of bestand), anders komen QSO’s dubbel binnen.",
  "t.25nc6txfjd2": "⟳ “[[phone.refresh]]”: wist de gecachte kopie van de interface in de telefoon en laadt de pagina opnieuw vanaf de pc. Dat is nodig na een update van Aurora, als de telefoon een oude versie toont.",
  "t.25qo8pv5yg8": "[[cat.grp.ptt]] · [[cat.ptt.method]] (alleen Hamlib): hoe Aurora de radio laat zenden. “[[cat.ptt.cat]]” (fabrieksinstelling) stuurt de opdracht over de CAT-kabel en is de keuze voor moderne Icom, Yaesu en Kenwood via USB; “[[cat.ptt.dtr]]” of “[[cat.ptt.rts]]” gebruiken een lijn van de seriële poort (interfaces met de PTT op RTS of DTR, zoals de FT-2000 met de RTS van de COM); “[[cat.ptt.vox]]” stuurt geen opdracht: de radio zendt als hij de audio hoort. Gaat de radio niet op TX, dan ligt het bijna altijd hieraan, of aan de snelheid.",
  "t.25rw3raa2l": "De verzonden tekst blijft in het zendvenster, met de geschiedenis boven het vak. Dubbel Esc zet Auto CQ uit en de RX/TX-knop in de balk stopt het zenden; de handvatten zijn discreter.",
  "t.25scbtkflcb": "Weet je poort en snelheid niet? Probeer “[[cat.detect]]”: het vindt ze voor je.",
  "t.25trvgawcfs": "[[ens.g.log]] · [[ens.k.PromptToLog]] (standaard uit): uit komt een afgerond QSO vanzelf en meteen in het log, zonder te vragen. Aan opent aan het eind van het QSO een venster met de gegevens ([[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]], [[lp.f.comment]]) om te controleren of te verbeteren, met de knoppen [[lp.log]] en [[lp.discard]]. Stapelen de QSO’s zich op, dan zegt het venster hoeveel er wachten; is de wachtrij vol, dan gaat de oudste vanzelf naar het log, en als je het vakje uitzet, gaan alle wachtende naar het log. Werkt vanaf het volgende afgeronde QSO.",
  "t.25vkgwwqfx3": "“[[cluster.add.heading]]” · “[[cluster.add.catalog]]”: een keuzelijst met de gecontroleerde openbare servers (naam, software, plaats en adres); kies er één (eerst “[[cluster.add.choose]]”): onderaan verschijnt een opmerking over die server; dan “[[cluster.add.button]]”. Poort 7300 is het meest gebruikelijk; de “RBN”-servers geven de automatische spots van het RBN-netwerk (FT8 en FT4 op poort 7001). Aurora stuurt geen spots: daarvoor heb je registratie bij de beheerder en een logprogramma nodig.",
  "t.25whsahqizm": "Open in BBLogger “Nuovo QSO” (Nieuw QSO) of “Fast QSO” en druk op het tandwielpictogram naast “Auto-Save”: “Configurazione interfaccia Wsjtx” opent.",
  "t.25xeofr566x": "Scan de QR-code met de cameraapp van de telefoon: Aurora opent en het koppelen wordt vanzelf voltooid. Zonder camera open je de getoonde link en voer je de code in.",
  "t.25ycs8nulrz": "[[nav.settings]] › [[sw.sec.station]] › [[tab.audio]]: de uitgang moet de kaart van de radio zijn (vaak “USB Audio CODEC”).",
  "t.25zuygqeklr": "Ongedaan maken, Opnieuw, Knippen, Kopiëren, Plakken, Verwijderen en Alles selecteren: de systeemitems, die altijd werken.",
  "t.2610crp25wp": "Paneltitel: “[[phone.txMessages]]” met de Tx-frequentie in Hz; tijdens het zenden wordt dit “[[phone.transmitting]]” met de seconden van de periode, en het paneel wordt rood met een voortgangsbalk.",
  "t.2616x4et8mr": "“[[ens.g.qrz]]” · “[[ens.k.QRZLogSend]]” (standaard uit): stuurt elke QSO naar je logboek op QRZ.com; je hebt een QRZ-abonnement nodig dat API-invoer toestaat, en dubbele QSO’s overschrijven geen QSO’s die er al staan. “[[ens.k.QRZLogKey]]” is de logboeksleutel, uit de logboekinstellingen op QRZ.com (niet het accountwachtwoord). “[[ens.k.QRZLogCall]]” (optioneel): als je QSO’s maakt met voor- of achtervoegsels (/P, /QRP, EA3/…) weigert QRZ de QSO’s waarvan de roepletters afwijken van die van het logboek; hier ingevuld gaan ze weg met deze roepletters; leeg = de eigen roepletters van de QSO. Het opzoeken van roepletters op QRZ.com is iets anders en staat in “[[tab.online]]”. “[[ens.test]]” vraagt QRZ om de status van het logboek zonder iets te schrijven.",
  "t.261hi75sqgh": "Open de pagina [[nav.rotator]]: de doorgetrokken naald is de antenne, de gestippelde het doel; de groene markering is het DX-station (korte weg), de oranje de lange weg.",
  "t.262541qcmzv": "Op de pagina begint elk QSO geselecteerd: filter op roepnaam, datums, band en modus, en vink de gewenste rijen uit of aan.",
  "t.262ajet4le7": "Het paneel [[panel.log]]",
  "t.265lo2epe9t": "Laat Aurora werken: als de Fox je een rapport geeft, zendt het R+rapport, en als zijn RR73 binnenkomt wordt de QSO gelogd.",
  "t.265u9csd92a": "Linksonder staat de waterval met de frequentieschaal; de bovenrand kun je slepen om de hoogte te wijzigen (van 50 tot 400 punten).",
  "t.266jitm6su3": "[[set.back]] brengt je terug naar de hoofdpagina.",
  "t.267on4keatd": "Q65 heeft ook: “[[mode.q65lor]]” of “[[mode.q65gau]]” ([[mode.q65fading]]), “[[mode.q65drift]]” van 0 tot 50 (0 = uit), de schakelaars “[[mode.q65eme]]” (echovertraging van de Maan) en “[[mode.q65contest]]” (lijst van Q65-contests), “[[dec.short.IncludeAveraging]]” en “[[dec.short.AutoClearAvg]]” (middeling van perioden) en de knop ⟲ ([[mode.q65clearAvg]]). Het “?” naast elk item (zweef erboven) legt uit wat het doet.",
  "t.268jfz3wgp7": "[[ap.text]] · [[ap.size]]: vergroot (of verkleint) de hele interface, tekst, knoppen, lijsten en waterval samen. Het menu loopt van 90% tot 140% in stappen van 5; standaard 100%. Op elke pagina doorloop je met Ctrl + en Ctrl − (ook op het numerieke toetsenbord) 90, 100, 110, 125, 140, 160%; Ctrl 0 gaat terug naar 100%. Het geldt alleen voor dit apparaat: de telefoon heeft zijn eigen grootte.",
  "t.26aqds6ogyf": "Op de hoofdpagina hoort de Rx-balk “Goed” te zeggen. Staat er Laag of Overstuurd, verschuif dan de Rx-schuifregelaar (of laat AUTO aan).",
  "t.26azanme6la": "[[ap.theme]] · [[ap.contrast]]: selectievakje. Neutrale achtergrond, tekst op volle sterkte, scherpe randen en verzadigde statuskleuren: zet het aan als je moeite hebt met lezen of als je in fel licht werkt. Werkt voor zowel het lichte als het donkere thema. Standaard uit.",
  "t.26bxr500q8": "Met de squelch aan wordt alleen afgedrukt als de laatste tekens waarschijnlijk zijn: geen verzonnen tekens op ruis, ook bij zeer zwakke signalen. De S/R-drempel uit de instellingen komt er alleen bij als je hem boven 0 dB zet.",
  "t.26e2axizetj": "Als alternatief voor het netwerk leest BBLogger het bestand dat Aurora bij elk QSO schrijft, aurora_log.adi. Het QSO bereikt BBLogger wanneer Aurora het logt: het is de veiligste manier, maar het toont het QSO niet terwijl het bezig is.",
  "t.26ed7gren5s": "[[sw.sub.wspr]]",
  "t.26ekur0jp06": "“[[dxs.bands]]” · 160m, 80m, 60m, 40m, 30m, 20m, 17m, 15m, 12m, 10m, 6m, 4m en U (allemaal aan): de kolommen van het raster; haal het vinkje weg bij de banden die je niet gebruikt voor een smallere kaart. “U” bundelt de banden korter dan 4 meter. Minstens één band moet aan blijven.",
  "t.26exok9uiwk": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]. Hier vertel je Aurora wie je bent: roepletters en locator komen in de berichten, het logboek, de afstanden en de richting van de rotor; naam, achternaam, QTH en e-mail zijn je gegevens als operator.",
  "t.26f3furuiwl": "PSK · RTTY · CW: duidelijker zenden",
  "t.26f4y57z8cc": "CI-V-adres van Icom-radio’s (in decimaal)",
  "t.26gw81yrnaw": "Je keuzes worden vanzelf opgeslagen ([[cat.apply]] laat ze meteen ingaan). Druk in het vak “[[cat.grp.test]]” op [[cat.connect]]: de status moet “Verbonden” worden en de frequentie van de radio verschijnt.",
  "t.26hmxfx0wih": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]. Hier vind je wat je nodig hebt als er iets misgaat of als je van pc verandert. De pagina heeft vijf vakken, in deze volgorde: “[[bak.title]]”, “[[sup.title]]”, “[[diag.crashFolder]]” (alleen als de pc de crashmap heeft), “[[ca.title]]” en “[[rep.title]]”. De vakken voor back-up en pakket werken alleen vanaf de pc waarop Aurora draait: vanaf een telefoon lees je “[[sup.onlyPc]]”.",
  "t.26i58pj035v": "Meldingen: verkeerde code (“[[pair.badCode]]”), verlopen (“[[pair.expired]]”), te kort (“[[pair.short]]”), geen naam (“[[pair.nameRequired]]”), te veel pogingen (wacht het getoonde aantal seconden). Antwoordt Aurora niet: “[[app.noCore]]”, met de knop om het opnieuw te proberen en, als er een ander al gebruikt adres wordt gevonden, om daarnaar over te schakelen.",
  "t.26iac8lhtz3": "[[digi.edit.text]]: het script. Gewone tekst wordt uitgezonden; de woorden tussen < > zijn opdrachten of plaatshouders. Bevat het script <TX>, dan begint de tekst meteen; zonder <TX> wordt de tekst alleen in het zendvak geschreven, na wat er al staat. Een alleenstaande <TX> zendt wat al in het vak staat.",
  "t.26lwqr1gqqg": "Volledig onderdeel: «De radio verbinden: de checklist»; «CI-V-adres van Icom-radio’s (decimaal)»; op Linux: «Seriële poorten: Windows en Linux (groep dialout)».",
  "t.26n6m4db7jb": "Knoppen van Opdrachten en muisfrequentie",
  "t.26pn22hrros": "Nieuw leeg logboek en Bandactiviteit in kolommen",
  "t.26rfvjjw01o": "Wordt een DXpeditie gespot met “UP 5” in de opmerking, dan zet een dubbelklik (of een enkele klik, als je op de pagina’s PSK, RTTY en CW “[[cop.single]]” hebt gekozen) op de spot de radio op ontvangst op de spotfrequentie en op zenden 5 kHz hoger, op de tweede VFO (echte split). Werkt in de DX-cluster van de pagina Station en van de pagina PSK · RTTY · CW.",
  "t.26sr01hqnt2": "Logboek onderaan · [[auto.log]] (met zijn “?”): de laatste 100 beslissingen, de meest recente bovenaan, elk met tijd, type ([[auto.kind.reply]], [[auto.kind.would_reply]], [[auto.kind.call_cq]], [[auto.kind.would_call_cq]], [[auto.kind.skipped]], [[auto.kind.blocked]], [[auto.kind.halted]], [[auto.kind.paused]], [[auto.kind.info]]) en reden. Groen: antwoorden en CQ's; oranje: overgeslagen, met de reden; rood: geblokkeerd door een limiet of door STOP. Het helpt te begrijpen waarom Aurora wel of niet antwoordde.",
  "t.26u9johrm0s": "De veiligheidsmeldingen bij het zenden (hoge SWR, bericht dat niet kan worden verzonden, Tx geblokkeerd door een extern programma, Hound uit zichzelf aan- of uitgezet) verschijnen in rood onder de DX-rij en verdwijnen na twee minuten.",
  "t.26vb5wjjhcp": "Zonder CAT: de band met de hand kiezen",
  "t.26vylg8smn4": "Controleer “[[contest.settings]]”: vaste exchange (Field Day “1D DX”), eerste serienummer, categorie, vermogen, Cabrillo-gegevens; kies voor contesten zonder vaste kalender begin en einde. De frequenties van de regels brengen de radio met één klik op de juiste frequentie.",
  "t.26w4kex4k4q": "[[seq2.switches]] · [[seq2.maxDist]] (standaard uit): als meerdere stations gelijk staan, kiest het de verste. De locator in de berichten is nodig om de afstand te kennen. Werkt met [[sw.save]].",
  "t.26yjyvs1hr2": "[[sw.station]] · [[gen2.region]]: de IARU-regio ([[gen2.regionAll]], [[gen2.region1]], [[gen2.region2]], [[gen2.region3]]). Ze bepaalt welke rijen van de frequentietabel (pagina [[sw.tab.freq]]) gelden: ze verandert de frequentie van een band met één rij niet, maar verbergt de rijen van de andere regio’s. Fabriekswaarde “[[gen2.regionAll]]”; kies de jouwe als een band frequenties toont die in jouw regio niet worden gebruikt.",
  "t.270yrzpe6gz": "[[agent.popup]] · [[agent.seconds]]: numeriek veld, 3 tot 60 seconden (standaard 10). Na deze tijd sluit de kaart vanzelf; met de muis erboven blijft hij open. Een waarde buiten de grenzen wordt teruggebracht tot de dichtstbijzijnde grens. Wanneer: verhoog het als je niet op tijd kunt lezen.",
  "t.2717znd4y1l": "Laat [[ctl.auto_tx]] aan staan.",
  "t.271j844791o": "Bij de eerste start meldt een strook dat anonieme fouten worden gestuurd naar de mensen die Aurora ontwikkelen, zonder roepnaam, locator, berichten of wachtwoorden, en dat je dit op elk moment kunt uitzetten. De link “[[rep.notice.open]]” leidt naar de juiste pagina; “[[rep.notice.ok]]” sluit de strook voorgoed. De schakelaars staan in [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (zie “Foutmeldingen”).",
  "t.272rqnjaxxc": "[[ctl.monitor]]: luisteren aan of uit. Als het uit staat, decodeert Aurora niets: het is de eerste schakelaar om te controleren als de berichtenlijst leeg blijft.",
  "t.272vbpbmb35": "“Alles wissen” (Clear all, Alles löschen…, in de taal van Aurora): onderaan, alleen in vakken die je kunt bewerken, maakt het het vak leeg waarop je klikte en werkt ook de pagina bij. Handig om in één keer een zoekveld of een roepletters te legen.",
  "t.278aqncv5n7": "De knop ⧉ rechtsboven verplaatst de kaart naar een apart venster (zie “Aparte vensters en indeling”).",
  "t.278vfr7jbnn": "Op Linux verschijnen de poorten “/dev/ttyUSB*” en “/dev/ttyACM*” in de lijst en worden ook paden “/dev/serial/by-id/…” geaccepteerd, die bij een herstart niet veranderen. Om alleen PTT op RTS/DTR te gebruiken, zonder CAT, kies je het Hamlib-model “Dummy” en geef je de poort op. Als Linux “Permission denied” zegt, is de poort niet bezet: je hebt geen toestemming om hem te gebruiken. Voeg je gebruiker toe aan de groep dialout met “sudo usermod -aG dialout $USER”, meld je dan af en weer aan (zie “Seriële poorten: Windows en Linux (groep dialout)”).",
  "t.27azdat040u": "Het veld “[[guide.search]]” staat bovenaan de inhoudsopgave: typ een woord en alleen de items die het bevatten blijven over (in de titel, de tekst, de stappen, de tips en de onderdelen “[[guide.fix]]”), in de taal die je hebt gekozen. Vindt hij niets, dan zegt hij “[[guide.none]]”.",
  "t.27c873c32jp": "Rechtsklik op de frequentieknop: hij springt direct naar de volgende frequentie in de lijst Band Hopping (de radio moet bestuurd worden; de lijst schrijf je in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). Met een contest aan toont de keuzelijst alleen de banden die de regels toestaan.",
  "t.27cyotftpzy": "De kaarten van de agent",
  "t.27ec1taxjnf": "“+ [[int.p.bblogger]]”: naam BBLogger, 127.0.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.loggedAdif]]” aan. Hij ontvangt dezelfde stream als het vorige onderwerp en, na elke QSO, het ADIF-record in bericht 12. In BBLogger (interface Wsjt_I) heb je de rijen “Msg ID 5” en “Msg ID 12” op 127.0.0.1:2237 nodig, het menu “UDP 12” en “Auto-Save”. Gebruik maar één methode, netwerk of ADIF-bestand: standaard staan de primaire en secundaire UDP-server ook op 127.0.0.1:2237 en met BBLogger kunnen ze dubbele QSO’s geven.",
  "t.27eqtyfroi9": "Rechtsklik nogmaals op de rij: het station verlaat de wachtrij.",
  "t.27jvpqwnyop": "De waterval: balken, pijlen en roepnamen",
  "t.27o5bsdp2vf": "Gebruik je maar een paar banden, zet de andere dan uit: de balk blijft korter en overzichtelijker (de helptekst van de pagina zegt: de band die je gebruikt wordt altijd getoond).",
  "t.27oqxs8tjk5": "Verbindingspil: hij is er niet zolang alles werkt. Als de pagina het contact met Aurora op de pc verliest, verschijnt “[[conn.connecting]]” (hij probeert opnieuw) of “[[conn.closed]]” (het contact is weggevallen). Controleer of Aurora op de pc open is en of het netwerk werkt.",
  "t.27qvlhxb5yq": "“[[lay.options]]” · “[[wish.enabled]]” (standaard uit): uit blijft de lijst bewaard, maar gaat er geen melding af. Zet het aan als je de lijsten hebt ingevuld. “[[wish.fromDecodes]]” (aan): zoekt de gezochte stations tussen de berichten die je ontvangt. “[[wish.fromCluster]]” (aan): zoekt ze ook in de spots van het DX Cluster, zodat je ze ziet ook als je ze nog niet ontvangt (het cluster moet aan staan).",
  "t.27qwztq5wu4": "Kop · [[auto.outWindow]] (label dat alleen soms verschijnt): de automatisering staat aan, maar de lokale tijd van de pc valt buiten het tijdvenster dat je in het vak [[auto.b3]] hebt gekozen; voorlopig antwoordt en roept Aurora niets.",
  "t.27sdwkur167": "Twee stroken met miniaturen, één voor ontvangen beelden (Aurora bewaart de laatste 200) en één voor verzonden beelden (de laatste 20; zie “[[sstv.set.saveTx]]” in de SSTV-instellingen). Naast de titel staat het aantal beelden.",
  "t.27t9b219d2q": "[[lay.lists]] · [[fil.only]]: keuzelijst met [[fil.onlyAll]] (fabrieksinstelling), [[fil.onlyCq]], [[fil.onlyCqRrr]] en [[fil.onlyCqRr73]]. Kies er een om alleen de CQ's en de QSO-afsluitingen te zien in plaats van elk bericht.",
  "t.27x5dvlh2fz": "[[ap.theme]] · [[ap.theme]]: drie knoppen, “[[theme.dark]]”, “[[theme.light]]” en “[[theme.auto]]” (volgt het Windows-thema en verandert ermee mee). Standaard donker. Hetzelfde bedieningselement is de pictogramknop rechtsonder, naast de UTC-klok.",
  "t.27yazrne3jk": "“[[sat.pass.title]]”: de volgende overvluchten van de satelliet die je volgt, met “[[sat.pass.hours]]” (tijdvenster) en “[[sat.pass.minEl]]” (lagere worden niet getoond), en de kolommen “[[sat.pass.aos]]”, “[[sat.pass.max]]”, “[[sat.pass.los]]”, “[[sat.pass.dur]]” en “[[sat.pass.az]]”. Een rij zegt “[[sat.pass.now]]” of “[[sat.pass.next]]”.",
  "t.27yl42huy5k": "Open [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]].",
  "t.27zdr47xv8w": "[[sw.tab.macros]]",
  "t.28020xv63w6": "[[nav.sat]] › [[sw.pg.orbits]]",
  "t.280j5bevfwp": "Vakken in het midden: “[[fox.inProgress]]” (rapport verstuurd, wacht op bevestiging, met de pogingen; “[[fox.drop]]” sluit een QSO die niet antwoordt en maakt de slot vrij), “[[fox.onAir]]” (de berichten die de Fox zendt, één per slot), “[[fox.queue]]” (wacht op een vrije slot; “[[fox.remove]]” haalt een station uit de wachtrij) en “[[fox.log]]” (de laatste 500 QSO’s die in deze sessie zijn afgesloten, met de knoppen ADIF, Cabrillo en Club Log om het op te slaan of te versturen).",
  "t.282bhrwaeq6": "Als er een nieuwe versie uitkomt, verschijnt het pictogram in de balk of de poster (zie “De updatemelding in de balk”). Voor de eerste QSO, als het logboek leeg is, biedt het paneel Log aan om er een te importeren of een extern logboek te koppelen.",
  "t.283v078fxpq": "Alleen met TCI: [[cat.tci.address]] (fabriekswaarde 127.0.0.1:40001: verander het als de SDR op een andere pc of op een andere poort draait) en [[cat.tci.receiver]] (RX1 of RX2: frequentie, modus, PTT en audio gebruiken de gekozen ontvanger; laat het bij een SDR met één ontvanger op RX1). Zie ook het onderdeel over de SDR met TCI.",
  "t.284dwsyaj5h": "[[tab.sequence]]",
  "t.2851rho2bp2": "Updates",
  "t.285detvuzoj": "“[[ens.g.qrzlookup]]” · “[[ens.k.QRZLookup]]” (standaard uit): als je met de muis boven een roepletters in de DX Cluster staat, vraagt Aurora aan QRZ.com de naam en stad van dat station (alleen naam, stad en land van degene die je opzoekt worden getoond). “[[ens.k.QRZUser]]” en “[[ens.k.QRZPasswd]]” zijn je gebruikersnaam en wachtwoord van QRZ.com (niet de logboeksleutel). Met het abonnement “XML Logbook Data” geeft QRZ volledige gegevens, zonder beperkte gegevens. Resultaten blijven drie dagen in het geheugen; uit wordt er geen verzoek gedaan. “[[ens.k.LookupToQso]]” (standaard aan, geldt als QRZ.com of HamQTH aan staat): elke gelogde QSO krijgt naam en stad (komt het antwoord niet binnen 2,5 seconden, dan wordt de QSO zonder gelogd); het geldt voor het logboek, de ADIF-export, directe uploads en ADIF via UDP. “[[ens.test]]” opent een sessie en zegt of het abonnement er is. QSO’s naar het logboek sturen is iets anders, in [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]].",
  "t.28arann7ke6": "Nieuwe staat (VS)",
  "t.28b8wuap0up": "Rij van de huidige QSO: [[digi.log.num]] (het nummer dat hij krijgt), [[digi.log.mode]], [[digi.log.freq]] (kHz: radio plus ontvangsttoon), [[digi.log.date]] en [[digi.log.utc]] (nu), dan vier velden om in te vullen: [[digi.log.call]] (wordt in hoofdletters gezet, maximaal 16 tekens), [[digi.log.name]] (maximaal 30), [[digi.log.qth]] (maximaal 40) en [[digi.log.grid]] (maximaal 8, in hoofdletters); [[digi.log.country]] vult zichzelf in met het opzoeken; ten slotte [[digi.log.rsts]] en [[digi.log.rstr]] (maximaal 4 tekens, standaard 599, en na elke QSO gaan ze terug naar 599 met [[digi.mi.defaultRst]]).",
  "t.28cluiskou6": "De taal van de agent is die welke in Aurora is gekozen (anders die van Windows, anders Engels): de kaarten volgen die meteen, het menu na een herstart van de agent.",
  "t.28csy2l4t1a": "[[sw.sec.sstv]] › [[sw.pg.images]]",
  "t.28evv74qci7": "[[sw.contest.title]] · het contestformulier: [[contest.set.activity]], [[contest.set.cqWord]], [[contest.set.exchange]], [[contest.set.serial]], [[contest.category]], [[contest.set.mode]] (hier ook MSK144 en Q65), [[contest.set.power]], [[contest.set.bonus]], [[contest.set.holdTx]], [[contest.set.rrr]], [[contest.set.callContest]], [[contest.set.grid6]] (in VHF-contests telt dit echt mee: het komt in het EDI-logboek), [[contest.set.antenna]] (voor de EDI-header, bijvoorbeeld “Yagi 9 el”), [[contest.set.operators]], [[contest.set.club]], [[contest.set.name]], [[contest.set.email]], [[contest.set.location]], [[contest.set.assisted]], [[contest.set.cabrillo]], [[contest.set.catTime]], [[contest.set.catOverlay]], [[contest.set.start]], [[contest.set.end]], [[contest.set.address]], [[contest.set.soapbox]]. Elk veld werkt zoals op de pagina [[sw.sub.ft8]] › [[sw.sub.contest]], waar ze één voor één worden uitgelegd.",
  "t.28fis2inowz": "Voor DXpedities: in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] staat “[[onl.dxped]]” standaard aan (hier uit te schakelen). De kalender komt van NG3K.",
  "t.28hoh3pip1p": "[[seq2.switches]] · [[seq2.autoseq]]: de automatische reeks. Aan gaat Aurora bij elk antwoord van het station zelf naar het juiste bericht (rapport, R+rapport, RR73, 73); uit verandert het bericht alleen als je op Tx1…Tx6 klikt. Het is dezelfde schakelaar “[[ctl.autoseq]]” als in het QSO-paneel: dezelfde stand op beide plekken, onthouden bij een herstart.",
  "t.28ikghd862u": "Vak “[[dxcc.title]]”: de DXCC-kaart (zie “De DXCC-kaart”) met de labels van het station dat je roept, de tabel per modus en band en, in “[[dxcc.countries.title]]” (opent met een klik), de lijst van landen met het veld “[[dxcc.countries.filter]]” en de keuzelijst om te kiezen welke rij van de tabel (FT8, FT4, DIG of alle modi) per land getoond wordt.",
  "t.28jorqvoft7": "[[sw.digi.perMode]] · CW, “[[digi.band.validation]]”: hoe streng je moet zijn met de gehoorde roepletters. [[digi.band.valMinimal]]: een aannemelijke vorm is genoeg. [[digi.band.valNormal]] (fabriek): bestaand land, verdachte vormen alleen als ze meerdere keren zijn gehoord. [[digi.band.valStrict]]: geen verdachte, ongebruikelijke alleen als ze zijn geverifieerd. [[digi.band.valMaximum]]: alleen geverifieerde roepletters met een typische vorm. Hoe strenger, hoe minder foute roepletters verschijnen, maar ook minder juiste.",
  "t.28l2bwpcd1a": "[[digi.log.save]] (het diskettepictogram, onderaan): schrijft de QSO in het logboek van Aurora met de band, de echte frequentie van het signaal, de modus, de rapporten, de locator, naam, QTH en notities. Zonder roepnaam verschijnt “[[digi.run.noCall]]”. De macro <SAVEQSO> doet hetzelfde.",
  "t.28leoc269th": "[[ctl.mtd]] (standaard aan) gebruikt alle processors van de pc: het decoderen is eerder klaar als de band druk is, met dezelfde resultaten.",
  "t.28lfz7zcr54": "Aurora waarschuwt je op vier verschillende manieren, en elke manier zet je op een eigen plek uit. Hier staat in het kort waar; details staan in de gedeelten “[[sw.pg.alerts]]” en “[[sw.tab.colors]]” en de andere van deze familie. Alles staat in [[nav.settings]] › [[sw.sec.look]].",
  "t.28lg1d7bnks": "Blauwe stip met een cijfer: station in de wachtrij, het cijfer is zijn positie.",
  "t.28m70xckez": "PSK · RTTY · CW overzichtelijker",
  "t.28n14pnerrd": "[[wfs.bpp]] (fabriekswaarde 4; 5 als je “[[wfs.speedJtdx]]” kiest in [[wfs.speed]]) en [[wfs.start]]: hoeveel detail en waar de waterval begint. [[wfs.navg]]: hoger maakt de waterval trager en minder ruisachtig.",
  "t.28nyzqmn52d": "Reageert STOP niet, dan verschijnt “[[stop.fail]]” (controleer de verbinding) of “[[stop.unpaired]]” (de telefoon is niet meer gekoppeld: koppel opnieuw vanaf de pc).",
  "t.28o0obkeqrz": "[[sat.set.servers]] · melding “[[sat.set.noServer]]”: verschijnt als er geen server is aangevinkt; zonder servers downloadt de updateknop niets. Vink er minstens één aan.",
  "t.28p57kkm0ab": "Rx zegt “[[rxl.state.silent]]”: controleer de audiokabel, of in [[sw.tab.audio]] de juiste ingang is gekozen (statusregel onder de lijst) en het opnamevolume. Rx “[[rxl.state.overdrive]]”: verlaag de regelaar of het audioniveau op de radio.",
  "t.28q11y4ob4j": "Standaard gaan de primaire en de secundaire server allebei naar 127.0.0.1:2237: laat alleen aan wat je logboek nodig heeft, of geef de andere een andere poort.",
  "t.28tm9xkd059": "De melding verschijnt bovenaan de pagina met de knop “[[wish.tune]]” om naar de frequentie te gaan; geluiden en de manier van waarschuwen stel je in bij [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]].",
  "t.28w558c4vr5": "[[win.where]] · “[[win.place.hidden]]”: bestaat alleen voor de panelen van de hoofdpagina en voor de rotor (voor de rotor zet het de kaart boven Station uit; de pagina Rotor blijft in het menu). DX-kaart, “[[prop.psk]]” en het Display van de radio kunnen niet verborgen worden: ze worden verplaatst of blijven waar ze zijn. Om een onderdeel terug te zetten kies je “[[win.place.main]]”.",
  "t.28z08ckxhcq": "[[wfs.palette.title]]: om je eigen palet te maken. Elk kleurpunt heeft zijn eigen kiezer en een × (“[[wfs.removeColor]]”; er zijn er minstens twee nodig); tussen het ene punt en het volgende loopt de kleur geleidelijk op, van 2 tot 255 punten. “[[wfs.addColor]]” voegt er een toe; “[[wfs.copyColors]]” begint met de kleuren van het palet dat je in het menu hebt gekozen. Als je een kleur verandert, wordt “[[wfs.paletteUser]]” vanzelf actief.",
  "t.29106by5070": "Wait and Call: met de DX ingesteld en [[ctl.autoseq]] aan, schakel je [[ctl.wait_call]] in. Wanneer de DX CQ roept of zijn QSO beëindigt (RR73, RRR, 73) roept Aurora hem vanzelf, tot ongeveer drie keer.",
  "t.292xuepvp76": "Firewallregel: als het netwerk als “Openbaar” is ingesteld, of de Windows-firewall de telefoon blokkeert (dat gebeurt als je op Annuleren hebt gedrukt bij de vraag van Windows), is de regel rood en heeft hij de knop “[[net.allow]]” (“[[net.allowing]]” tijdens de handeling). Windows vraagt om bevestiging: daarna haalt Aurora de blokkade weg en opent de poort op elk netwerk. Als je de bevestiging annuleert, wordt de regel niet toegevoegd: “[[net.allowFailed]]”. Als de firewall de telefoon doorlaat, is de regel groen: “[[net.allowed]]”. De knop werkt alleen op de Windows-firewall.",
  "t.294uorrnow0": "[[not2.grpColors]] · geluidsmenu (links van elke staal): “[[snd.none]]”, de stem, je eigen bestanden of een van de geluiden van Aurora; de knop ▶ speelt het af. Als je een geluid kiest, gaat ook de melding van dat type aan. Hoe geluiden en stem werken, staat uitgelegd op de pagina “[[sw.pg.alerts]]”.",
  "t.294wdwjjob8": "De twee tabbladen “[[sstv.view.rx]]” en “[[sstv.view.tx]]”. Van het ene naar het andere gaan stopt niets: de ontvangst gaat door, ook terwijl je samenstelt, en het werk in de editor gaat niet verloren.",
  "t.2952snivk02": "De Gids opent via [[nav.wiki]] in het tandwielmenu. Links staat de inhoudsopgave van de hoofdstukken, rechts de tekst.",
  "t.2962ypc64ar": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], vak [[gen2.bandHop]].",
  "t.296j581dkql": "De tekst wordt bepaald door een probabilistische decoder: die houdt de meest waarschijnlijke lezingen open (snelheid van 5 tot 60 WPM, seinstijl, woorden van het CW-verkeer) en kiest zodra hij nog twee tekens heeft gehoord; hij kan veel zwakkere signalen en de handseinsleutel aan. Een noise blanker haalt ontladingen weg vóór het filter. De filterbandbreedte is direct te wijzigen in het menu Modus of in de keuzelijst onderaan, ook breed (1000 Hz) voor een overzicht.",
  "t.296k9r2p06v": "[[nav.settings]] › [[sw.sec.station]] › [[tab.audio]]: uitgang en ingang op de geluidskaart van de radio (recente Icom, Yaesu en Kenwood: “USB Audio CODEC”).",
  "t.298cyxf5i80": "De kolom Modus komt uit het commentaar van de spot (“FT8 -10 dB”, “CW 22 wpm”, “VarAC VARA”). Staat het niet in het commentaar, dan kijkt Aurora naar de frequentie: dicht bij de werkfrequenties van FT8, FT4, JS8, WSPR en PSK31 toont het die modus; anders volgt het het bandplan van IARU Regio 1, CW in de delen alleen voor CW en SSB in de fonie-delen (FM boven 29,52 MHz). In gemengde delen (digitaal en CW, bakens, satellieten) en als het commentaar alleen “Digi” zegt, blijft de kolom leeg, om niet te gokken.",
  "t.299344liqlm": "Bij PSK: de schuifregelaar voor de squelchdrempel (fasekwaliteit van 0 tot 100, standaard 15) met ernaast de huidige kwaliteit; het vak [[digi.band.miPsk]].",
  "t.2993u7g46ue": "[[cat.preset.title]] (alleen met Hamlib en een bekend model: Icom IC-7300, IC-7610, IC-705, IC-9700; Yaesu FT-991, FT-710, FTDX10, FTDX101, FT-2000; Kenwood TS-590, TS-890): drie kolommen, [[cat.preset.aurora]] (aanbevolen snelheid, PTT en CI-V), [[cat.preset.radio]] (de items die je in het menu van de radio instelt, in het Engels geschreven zoals de radio ze schrijft) en [[cat.preset.audio]] (welke geluidskaart je kiest; “[[cat.preset.openAudio]]” opent de pagina Audio). “[[cat.preset.apply]]” schrijft alleen snelheid, PTT en CI-V, nooit de poort; daarna verschijnt “[[cat.preset.done]]”. Gebruik het bij de eerste instelling.",
  "t.29ae2xe57j3": "Een klik op een rij verplaatst de ontvangst naar dat signaal (de rij van het signaal waarop je luistert wordt gemarkeerd); de rijen van stations die CQ roepen worden op een andere manier gemarkeerd. Een dubbelklik opent de “[[digi.band.history]]”.",
  "t.29c31girjrp": "Stations in de lucht op de wereldkaart, gekleurd zoals in Bandactiviteit: ze vervagen met de tijd en een boogvormige lijn verbindt ze met jou. Achtergrond, helderheid, greyline, gewerkte (geel) en bevestigde (groen) vierkanten per band en modus staan in de balk; ⚙ opent de rest (automatische nachtkaart, schemering, Maan). Klik op een punt: vierkant, afstand, land en zones. «Propagation» toont de heatmap van wie jou ontving (PSK Reporter), met Spot RX, maximale leeftijd en een lijn van jouw station naar elk ander; «Who calls whom» trekt een stippellijn tussen de twee stations van elke oproep (kleuren, breedte en snelheid in het menu ⚙); vierkanten in de lucht zijn QSX, CQ, CQDX of QRZ, zoals de legenda linksonder zegt.",
  "t.29d65zls4xz": "[[cat.connect]]: verbindt de radio met de toegepaste waarden (heb je nog wijzigingen, dan past het die eerst toe). Bij het openen wordt de PTT uitgezet en gedurende 5 seconden wordt zenden niet geaccepteerd. Met Hamlib blijft de knop uitgeschakeld tot je een model kiest. [[cat.disconnect]]: zet de PTT uit, haalt de split weg en geeft de poort vrij: druk erop als een ander programma de poort van de radio moet gebruiken.",
  "t.29dg91r0c9m": "Als Aurora zegt dat de poort bezet is of toegang geweigerd wordt, gebruikt een ander programma (of een andere kopie van Aurora) die COM-poort al: sluit het, of deel de radio zoals hierboven. Als er staat dat de poort niet bestaat of niet gevonden is, heeft Windows hem misschien een ander nummer gegeven: ververs de poorten, controleer of de radio aanstaat en de kabel erin zit, en kies dan de COM-poort opnieuw. Op Linux betekent “Permission denied” niet dat de poort bezet is: je hebt geen toestemming om de poort te gebruiken. Oplossing: voeg je gebruiker toe aan de groep dialout met “sudo usermod -aG dialout $USER”, meld je dan af en weer aan (zie “Seriële poorten: Windows en Linux (groep dialout)”).",
  "t.29dpsfbrs0h": "Leeftijd van berichten en nieuwe berichten onderaan",
  "t.29e8yllybml": "Linux, “Permission denied”: dat betekent niet dat de poort bezet is, het betekent dat jouw gebruiker /dev/ttyUSB* en /dev/ttyACM* niet mag gebruiken. Die machtiging geeft de groep “dialout”. Open een terminal en typ: sudo usermod -aG dialout $USER. Log daarna UIT en weer in (of herstart de pc): zonder uit te loggen geldt de nieuwe groep niet. Controleer met het commando groups: dialout moet in de lijst staan.",
  "t.29egaipjba9": "Zet “[[cat.auto]]” aan zodat je het niet bij elke start hoeft te doen, en “[[cat.extras]]” voor de uitgebreide weergave. Deze twee vinkjes worden meteen vanzelf opgeslagen, net als “[[cat.powerOn]]” en “[[cat.powerOff]]” (ze zetten de radio aan en uit bij start en afsluiten: aanwezig bij Hamlib, TCI en FT-991(A) Link, bij Cat4OM alleen de tweede). De andere items worden na een pauze van ongeveer 1,5 seconde vanzelf toegepast (de radio maakt één keer opnieuw verbinding), of meteen met [[cat.apply]].",
  "t.29gm646lvp0": "Aurora draait de antenne met rotctld van Hamlib (dezelfde Hamlib als voor CAT): naar het DX-station, de lange weg, of waar je ook klikt.",
  "t.29j8jsrkd5a": "UltraFOX",
  "t.29k7q3taryr": "Wat nooit wordt verzonden: roepnaam, locator, gedecodeerde berichten, QSO-logboek, ALL.TXT, instellingen, wachtwoorden en sleutels, IP-adressen, e-mailadressen, je Windows-gebruikersnaam en de minidumps (die bevatten het geheugen van het programma).",
  "t.29kva7b2i63": "Sommige contests (bijvoorbeeld ARRL VHF) staan naast MSK144 en Q65 ook FT8 toe: ze staan in beide takken en het formulier is hetzelfde.",
  "t.29l2bu6gcvk": "Als je de muis over de waterval beweegt, tonen twee witte lijnen de breedte van een signaal; met “[[wfs.freqOn]]” aan verschijnt ook de frequentie in Hz onder de aanwijzer. De lijnen en de balken zet je uit met “[[wfs.barsOn]]” (de labels blijven).",
  "t.29m0f0lipne": "“Stem” spreekt de melding en de roepnaam uit in het fonetisch alfabet (bijv. “Nieuw DXCC! Zulu Six Two November Sierra”). Werkt zonder internet.",
  "t.29m0h15c0nd": "[[seq2.group]] · [[seq2.answerCq]], [[seq2.answerInCall]], [[seq2.sentRReport]], [[seq2.sentRR7373]] (vier rijen, elk met een vakje en een getal van 1 tot 5 “[[seq2.times]]”): het getal is het maximale aantal zendingen van hetzelfde bericht in die situatie; wordt het overschreden, dan gaat de volgende zending niet uit en gaat de reeks terug naar zoeken tussen de CQ’s of stopt. Het getal kun je alleen typen als het vakje is aangevinkt. Standaard: de eerste twee uit (2 en 3 keer als je ze aanzet), de laatste twee aan met 5 keer. Ze gelden niet voor gezochte stations of nieuwe DXCC’s, die je blijft roepen tot ze antwoorden. Zet de eerste aan om niet aan te dringen bij iemand die je oproep niet beantwoordt; laat de laatste aan, want veel stations sturen nooit de laatste 73.",
  "t.29me59w0bqf": "Telefoon: een tik op een bericht antwoordt; twee snelle tikken op STOP stoppen de zending en maken ook de DX vrij.",
  "t.29mingwu2o": "[[cat.port]]: de COM-poort van de radio. [[cat.baud]]: gelijk aan het CAT-menu van de radio. Bij een Icom wordt het CI-V-adres ([[cat.civ]]) DECIMAAL geschreven (IC-7300 = 148, niet 94h): zie “CI-V-adres van Icom-radio’s (decimaal)”.",
  "t.29qq1mmqokp": "Open [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] en kies “[[rot.set.connection]]”: “[[rot.set.launch]]” als de rotor op deze computer is aangesloten, “[[rot.set.remote]]” als rotctld al draait (ook op een andere computer): schrijf dan het adres in “[[rot.set.host]]” (127.0.0.1 als het deze computer is) en de poort in “[[rot.set.tcpPort]]” (standaard 4533).",
  "t.29r8jbu8671": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]]. Hier stuurt Aurora elk gelogd QSO rechtstreeks naar online logboeken, zonder tussenliggend programma, en leest hij de database van Log4OM. Eén dienst per rij: lampje, naam met “?”, velden, “[[ens.test]]” en resultaat. Wijzigingen worden opgeslagen met “[[sw.save]]” onderaan het venster. Wachtwoorden en sleutels worden alleen gebruikt als Windows geheimen op je pc beschermt (zonder dat verschijnen die diensten niet); LoTW heeft dat niet nodig.",
  "t.29uml83vhoy": "In het paneel [[panel.tx]] toont “[[tx.queue]]” onder de DX de wachtende stations met hun nummer. Ze worden na elkaar geroepen zodra de huidige QSO is gelogd.",
  "t.29w34io3g4v": "Verbinding, frequentie en klok linksboven",
  "t.29wcqhwibo1": "Vak “[[prop.psk]]”: de kaart met een lijn en een punt voor elk station dat jou heeft ontvangen (PSK Reporter) en de tabel met “[[prop.col.when]]”, “[[prop.col.who]]”, “[[prop.col.band]]”, “[[prop.col.snr]]” en “[[prop.col.distance]]”. Zonder ontvangsten staat er dat geen enkel station je de laatste uren heeft ontvangen. Nieuwe ontvangsten komen binnen een paar seconden binnen.",
  "t.29xiamish9r": "Op de kaart zie je de aangevinkte satellieten met hun baan en radiovoetafdruk, dag en nacht, “[[sat.sun]]” en “[[sat.moon]]” en je station (“[[sat.station]]”). Ernaast toont een hemelradar waar de gekozen satelliet staat en waar de rotor naartoe wijst (lichtblauwe ring).",
  "t.29xmolx0f09": "[[digi.spot.info]]: de modus en een korte opmerking; standaard staat hier de modusnaam (PSK31, RTTY, CW).",
  "t.29zsdycnkvw": "Ontvangen: de tekst komt teken voor teken binnen en scrolt vanzelf naar onderen. Onzekere tekens verschijnen in een lichtere tint (vager). Een dubbelklik op een roepnaam zet hem in de huidige QSO en zoekt naam, QTH, locator en land op.",
  "t.2a005jnjipp": "Hoe wijzig ik de taal of de tekstgrootte?",
  "t.2a08rfk4zps": "[[digi.mi.slashedZero]] (aan): de nul is doorgestreept in het ontvangst- en het zendvenster, zodat hij in roepnamen niet met de letter O wordt verward.",
  "t.2a1wt6ayp4g": "Het paneel [[panel.station]] heeft bovenaan drie grote numerieke velden en eronder een rij knoppen. Het is de volledige versie van “Het paneel Opdrachten”.",
  "t.2a23eeytz4q": "De statusbalk",
  "t.2a5rv882vw5": "Dubbelklik op een rij, of “[[exp.edit.btn]]”: opent het venster om die QSO te corrigeren of te verwijderen (zie “Het venster om een QSO te corrigeren of te verwijderen”).",
  "t.2a6i92r2swj": "Wil je de kleur van een type helemaal uitzetten? Haal in de tabel van het vorige gedeelte het vinkje “[[not2.colHighlight]]” bij die rij weg en druk op “[[sw.save]]”.",
  "t.2ad7lperylj": "Op de rij met tabbladen staat rechts de frequentiekeuzelijst met alleen de toegestane banden, en het kleine RX/TX-vak: groen “RX” bij luisteren (een klik maakt de huidige QSO vrij, zoals “Clear DX”), rood “TX” bij zenden (een klik stopt het meteen).",
  "t.2agfc84lfkq": "[[sw.digi.perMode]] · PSK31 · PSK63, “[[digi.band.miPsk]]” (standaard aan): decodeert elk PSK31- of PSK63-signaal in de audioband met een eigen ontvanger en bouwt de signaallijst van de werkpagina op. Zet het uit als de pc traag is en één signaal tegelijk genoeg is.",
  "t.2agmwjdl4zt": "Kies met de rechterknop een vrije plek in de waterval (rode balk).",
  "t.2ahi00pgr86": "De CQ-vakjes staan op twee rijen en schuiven zelf heen en weer als het er te veel zijn (ze stoppen als je de muis erover houdt): elk vakje heeft een vlag, een roepnaam en een land; het bericht, het rapport en de tijd staan in de hint. De kleur is die van het nieuws. Dubbelklik: je antwoordt. Rechtsklik: in de wachtrij. Een station dat 15 minuten niet is gehoord, verdwijnt.",
  "t.2ahk19xvg8w": "[[fil.worked]]; met “[[fil.workedAll]]” verdwijnen ook hun uitwisselingen met andere stations.",
  "t.2ai1xkvmggn": "De frequentieknop, naast de modusselectie, toont de band en de MHz en opent een lijst met alle frequenties van de huidige modus, gegroepeerd per band: de standaard en de alternatieven (ook die van DXpedities); de hoofdfrequentie van elke band heeft een gekleurde stip. Kies er een en Aurora stemt de radio daarop af. Bewerk de lijst in Instellingen › Modi › Gemeenschappelijk voor alle modi › Frequenties.",
  "t.2akh9th7n56": "Met de hand: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › “[[dec.depth]]”, met de drie keuzes “[[dec.depth1]]”, “[[dec.depth2]]” en “[[dec.depth3]]” (standaard Diep; Q65 gebruikt altijd diep). Hoe dieper, hoe meer zwakke berichten het vindt en hoe meer CPU het gebruikt. Als FT8 alleen goed werkt met “[[dec.depth1]]” of “[[dec.depth2]]”, zit de pc onder de aanbevolen vereisten (4 kernen en 8 GB; Aurora decodeert met alle processors op één na).",
  "t.2apjiphfq94": "Schakel in het SDR-programma de TCI-server in (meestal poort 40001) en de I/Q-stream op 96 kHz; stem de SDR af op het midden van het stuk waarnaar je wilt luisteren (bijv. 144,100 MHz).",
  "t.2apzlz7zkcm": "[[sup.title]] · [[sup.sendMail]]: hij is grijs tot het adres in “[[sup.email]]” geldig is. Hij maakt het pakket klaar (tenzij je minder dan 5 minuten geleden een pakket hebt gemaakt, dan hergebruikt hij dat), toont het in Verkenner en opent in een browsertab Gmail met ontvanger, onderwerp en tekst al ingevuld (versie, roepletters, radio, PTT). De zip wordt niet vanzelf bijgevoegd: sleep hem in het bericht. Je hebt geen mailprogramma nodig, maar wel Gmail.",
  "t.2argorylobz": "Vlag, land, afstand, richting, DT, leeftijd in plaats van de tijd, je eigen uitzendingen in de lijst en de lege rij tussen twee periodes zet je aan en uit in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. De lege toestand zegt “[[decode.empty]]” (of, in JT65 en JT9, dat de berichten aan het eind van de minuut binnenkomen).",
  "t.2atjts16i4z": "Pwr is het Windows-volume van de audio-uitgang naar de radio: 100% op de schuifregelaar = 100% in de Windows-mixer. Aurora zet het vóór elke zending weer gelijk.",
  "t.2av7dzvquyq": "Gebruik de Fox-modus alleen als je echt de expeditie bent en kondig het aan: op de normale band veroorzaakt het storing.",
  "t.2ax8vhu27qy": "AGC: auto, snel, middel, langzaam, uit, en dan weer van voren af aan.",
  "t.2axxq6uinl": "Eén radio, meerdere programma's",
  "t.2azbozybpk": "SSTV: het paneel “[[sstv.log.title]]”",
  "t.2azs9jgpbk0": "Tweede deel van de pagina [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]: de echte kleuren van elk berichttype, die van de kaart en de LoTW-gebruikersbalk. Alles hier geldt meteen.",
  "t.2b0gnoalz6a": "Op de pagina [[nav.rotator]] haalt de knop “[[rot.onStation.on]]” / “[[rot.onStation.off]]” de kaart boven het Station weg of toont hem weer. De kaart heeft een titelbalk: met de vouwknop sluit of open je hem (“[[rot.close]]” / “[[rot.open]]”); met de X verberg je hem (“[[rot.hideStation]]”); zweeft de kaart, dan verplaats je hem aan de balk (dubbelklik: terug naar zijn plek) en verander je het formaat aan de hoek (“[[rot.resize]]”); met ⧉ gaat hij naar een apart venster. Op de telefoon en de tablet is de kaart op het Station er niet: daar gebruik je deze pagina.",
  "t.2b0gvzmdowi": "Als Aurora uit zichzelf is gesloten en je hebt gevraagd om een melding, verschijnt er bij de herstart het venster “[[rep.crashTitle]]” met drie knoppen: “[[rep.crashSend]]” (verstuurt het rapport), “[[rep.show]]” (toont wat er verstuurd zou worden voordat je beslist) en “[[rep.no]]”.",
  "t.2b0ybm69e7k": "De pagina [[nav.stats]] vat het logboek samen. Kan Aurora het QSO-logboek niet vinden, dan zegt hij “[[stats.unavailable]]”.",
  "t.2b1dgatwn6v": "[[snd.title]] · bericht “[[snd.off]]”: het verschijnt boven de tabel als “[[alert.button]]” uit staat; het herinnert je eraan dat er geen geluid uit zichzelf start, terwijl de test ▶ altijd werkt.",
  "t.2b24nd8nolq": "Instellingen heeft veel pagina’s, verdeeld in families. Bovenaan staat het vak “[[sw.search]]”: typ een woord van de optie (accenten maken niet uit) en de lijst met gevonden opties uit alle pagina’s verschijnt.",
  "t.2b2qj0oloz2": "Rechterpaneel met een gekozen vorm (rechthoek, ellips, kader, balken): [[sstv.p.filled]], [[sstv.p.stroke]] ([[sstv.p.width]], [[sstv.p.color]]), [[sstv.p.width]] en [[sstv.p.height]] van de vorm, [[sstv.p.opacity]] en [[sstv.p.rotation]]. De knop “[[sstv.bg.title]]” onderaan brengt je terug naar het fotopaneel.",
  "t.2b41az7zasi": "[[fil.grp.both]] · [[gen.showAge]]: selectievakje, standaard uit. In [[panel.all]] en [[rxw.title]] toont de eerste kolom hoe oud het bericht is (45 s, 3 min) in plaats van de UTC-tijd en werkt zichzelf bij; houd de muis erboven om de tijd te zien. Het is hetzelfde selectievakje dat je in het vak [[gen.screen]] vindt.",
  "t.2b4corn2m2f": "De keuzelijst “[[contest.choose]]” toont de contests per groep en per startdatum; kies er een en, als er al een contest loopt, schakelt hij over naar die. Ernaast opent “[[contest.how]]” een kaart met wat er verzonden wordt (met een voorbeeld), de tijden in UTC en in lokale tijd, de duur, het maximum aantal uren, de minimale pauze en de link naar de officiële regels.",
  "t.2b4k8fgn2is": "[[fil.decode]] · [[dec.autoClearAvg]]: vakje, standaard uit. Bij Q65 leegt een nieuw bericht op de ontvangstfrequentie het gemiddelde van zijn pariteit, zodat het volgende QSO schoon begint. Zet het aan als je meerdere QSO’s achter elkaar maakt met middelen aan; naast de modus staat de knop “Auto ⟲”.",
  "t.2b73cpwlbty": "Duidelijkere meldingen en vensters",
  "t.2b7bt5j443q": "Een klik op een hoofdstuk in de inhoudsopgave scrolt ernaartoe. De items gebruiken de echte namen van de knoppen en vakken (dezelfde die je op het scherm ziet): zoek je op de naam van een vak, dan vind je het item dat het uitlegt.",
  "t.2b94upr6wkv": "Een “*” is een teken dat morse niet kent: zie je er veel, controleer dan of de toon binnen de filterbandbreedte ligt of zet de AFC aan.",
  "t.2b9j3f8i019": "“[[logio.export]]”: opent de exportpagina van het interne logboek: kies de QSO’s en sla ze op als ADIF-bestand waar je maar wilt (voor een back-up of om ze in een ander programma te laden).",
  "t.2bczmuc2ube": "Satellieten: de pagina, paneel voor paneel",
  "t.2bdl46jl2g8": "Wait and Reply en [[ctl.wait_call]]",
  "t.2bgenbx171q": "Volledig onderdeel: voor geluiden en pop-upberichten: «Meldingen uitzetten of aanpassen: gemarkeerde kaarten, geluiden, kleuren, berichten». Om te leren hoe de kaarten werken: «Nieuwe DXCC en gezochte station: de gemarkeerde meldingen».",
  "t.2bh6ldyhkos": "[[ctl.ap_list]] en [[ctl.mtd]]: verschijnen alleen in FT8. “a7/a8” is decodering met lijst (hij vindt signalen tot ongeveer −24 dB; zo gevonden berichten hebben een sterretje); “Multithread” decodeert op alle processors van de pc: dezelfde berichten in minder tijd op drukke banden.",
  "t.2bmcu2lqo80": "Trage pc",
  "t.2bpa6k6kj0c": "Hoe zet ik de meldingen voor nieuwe DXCC uit die rechtsboven verschijnen?",
  "t.2bq4an6ime0": "[[cmd.report]]: de dB die je verzendt. Aurora stelt ze in op basis van het ontvangen signaal; met de hand gewijzigd gelden ze meteen.",
  "t.2bqaizwuc5q": "[[sw.contest.title]] · [[contest.set.holdTx]] en [[contest.set.rrr]]: twee selectievakjes. [[contest.set.holdTx]] (standaard aan) houdt de zendfrequentie vast tijdens de contest; [[contest.set.rrr]] laat QSO's eindigen met RRR (het gaat vanzelf aan bij contests waarvan de regels het eisen).",
  "t.2bs5eqzdp8x": "Met het tabblad Log zie je de laatste QSO’s, die van Log4OM2 als Aurora zijn logboek leest (alleen lezen), anders die van het interne logboek van Aurora. Kolommen: “[[log.col.date]]”, “[[log.col.call]]”, “[[log.col.band]]”, “[[log.col.mode]]”, “[[log.col.rst]]” (verzonden en ontvangen), “[[log.col.country]]”. De koppen sleep je en pas je in breedte aan zoals die van de DX Cluster; rechtsklik op de kop zet ze terug.",
  "t.2bsbgy9z8xj": "[[sw.wspr.beacon]] · [[mode.wsprPct]]: numeriek veld van 0 tot 100, fabriekswaarde 20. Het is het percentage perioden waarin de baken zendt (onder 40% nooit twee zendingen achter elkaar). Het wordt verstuurd als je op Enter drukt of het veld verlaat; Esc annuleert; een leeg veld verandert niets. De baken zendt alleen met [[ctl.enable_tx]] aan: met 0 luister je alleen.",
  "t.2bu4vemnore": "De afstandsbediening: elke knop",
  "t.2bujz0z2fyg": "Na de QSO start CQ alleen vanzelf opnieuw als [[ctl.auto_tx]] aan staat.",
  "t.2bxipwxugoe": "“[[cop.columns]]”: één vakje per kolom ([[cluster.col.by]], [[cluster.col.freq]], [[cluster.col.call]], [[cluster.col.country]], [[cluster.col.mode]], [[cluster.col.comment]], [[cluster.col.time]]). Standaard staan ze allemaal aan; er moet er minstens één aan blijven.",
  "t.2bxlau1uxbl": "Een QSO corrigeren of verwijderen",
  "t.2bxlh7u6234": "Controleer de “Zendbeveiligingen”: een actieve beveiliging kan Tx blokkeren.",
  "t.2c1ll6zhiu9": "[[seq2.stop]] · [[seq2.haltReplyOther]] (standaard aan): antwoordt het station dat je roept aan iemand anders, dan stop je met roepen in plaats van aan te dringen. Uit stopt het zenden alleen als de ander dicht bij je zendfrequentie spreekt (ongeveer 50 Hz bij FT8, 84 Hz bij FT4).",
  "t.2c1my8cy469": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiMacros]]. Het is de lijst met macro’s (kant-en-klare teksten op de toetsen F1…F12, ook met Ctrl en Shift) van de modus die je op de pagina PSK · RTTY · CW hebt gekozen; de regel bovenaan zegt welke modus in gebruik is. Hij opent ook via het menu [[digi.menu.configure]] van de werkpagina. Alleen toetsen met een naam of een tekst worden getoond.",
  "t.2c412xf6at5": "[[sw.pg.sdr]]",
  "t.2c6n3daq1f9": "Met “[[rot.set.launch]]”: [[rot.set.search]] en [[rot.set.model]]. Typ een deel van de naam (bijvoorbeeld GS-232 of Yaesu) en klik de rotor aan in de resultaten, of kies uit de lijst (“[[rot.set.none]]” aan het begin). Het zijn de modellen van de rotor of zijn interface (GS-232, EasyComm, SPID…); “Hamlib Dummy” is om zonder rotor te proberen. Een regel eronder zegt hoeveel modellen Hamlib heeft.",
  "t.2c7bagwlhvb": "“[[lay.options]]” · “[[wish.bands]]” (standaard leeg = alle banden): schrijf de banden gescheiden door een komma, bijvoorbeeld 20m, 15m; alleen op die banden gaat er een melding af. “[[wish.cooldown]]” (standaard 15, van 1 tot 240 minuten): na een melding voor een station wacht Aurora zo lang voordat het je weer voor hetzelfde station waarschuwt; een station dat elke 15 seconden CQ roept, geeft dus één melding. Bij een ongeldige waarde zie je de rode waarschuwing en wordt er niets opgeslagen.",
  "t.2c9hhmwr4m0": "[[digi.menu.edit]] › [[digi.mi.clearRx]]: maakt het ontvangstvenster leeg (ook met een rechtsklik in het venster).",
  "t.2caoo62vw7e": "Voor het zenden: op de Station-pagina moet de Rx-balk “[[rxl.state.good]]” zeggen. Als de PTT schakelt maar er geen vermogen is, ligt het probleem bijna altijd hier (verkeerde uitgang of Pwr-volume); gaat de radio niet naar TX, dan ligt het aan de CAT.",
  "t.2cazgx9b23d": "De laatste drie categorieën houden zich aan “[[agent.quiet]]”: in die uren komt er niets. “Alleen pictogram” toont de kaart niet en zet de titel in de tooltip van het pictogram.",
  "t.2cc3cerk1m6": "Om een modus te forceren kies je die en druk je op “[[sstv.rx.force]]”. Voltooide beelden komen in “[[sstv.hist.received]]”, in de kolom rechts (onderaan de pagina bij smalle vensters en op de telefoon); klik er een aan om het te vergroten, van ruis te ontdoen, op te slaan of te antwoorden.",
  "t.2cd68ucu2rn": "Filters, op dezelfde rij: het veld “[[exp.search]]” (filtert terwijl je typt), “[[exp.from]]” en “[[exp.to]]” (UTC-datums; je mag er maar één invullen), “[[exp.band]]” en “[[exp.mode]]” (ze vullen zich met de banden en modi die in je logboek staan). “[[exp.clear]]” verschijnt alleen als er een filter actief is en haalt ze allemaal weg.",
  "t.2cddjve6axe": "Een door de ruisvloer gestuurde AGC herstelt het niveau wanneer de AGC van de radio pompt of brede ruisstoten (QRN) binnenkomen. Gemiddelde fouten in de test dalen van 26,5% naar 23,4%, bij breed QRN van 51,9% naar 29,8%.",
  "t.2cj1e9rk1as": "[[not2.grpDisplay]]",
  "t.2cjubxqyjmg": "[[ctl.split]]: aan (gemarkeerd) houdt de zendfrequentie gescheiden van de ontvangstfrequentie. Een tik zet het aan en uit.",
  "t.2cow4u0bjnf": "Aurora past twee volumes van het audiosysteem van de pc aan: het opnamevolume van de ingang (Rx-regelaar) en dat van de uitgang naar de radio (Pwr-regelaar). Dezelfde regelaars staan op twee plekken: in [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]], naast het gekozen apparaat, en op de Station-pagina (Rx-indicator en paneel Zenden). Beweeg je de ene, dan beweegt de andere mee.",
  "t.2cpzz4u5ug4": "DX-kaart: de opdrachtbalk en het tandwiel",
  "t.2cqfi5td91b": "Diepte ([[dec.depth]]) en enkelvoudig decoderen ([[dec.singleDecode]]) staan op de pagina [[sw.sub.ft8]] › [[fil.decode]]; enkelvoudig decoderen geldt ook voor Q65. VHF-contests staan op de pagina [[sw.sub.vhf]] › [[sw.pg.contest]].",
  "t.2cr7hvt9vae": "[[toast.grp]]",
  "t.2crv3ns50s3": "Bovenaan de regel “[[net.waiting]]” tot de telefoon is gekoppeld; onderaan het advies: “[[net.tips]]”",
  "t.2cthvm684ff": "SSTV: de geschiedenissen “[[sstv.hist.received]]” en “[[sstv.hist.sent]]”",
  "t.2cu9fbyvd16": "“[[ens.g.wavelog]]” · “[[ens.k.WavelogSend]]” (standaard uit): stuurt elke QSO naar Wavelog of Cloudlog (dezelfde API). “[[ens.k.WavelogUrl]]” is het adres waarmee je de site opent (met of zonder /index.php). “[[ens.k.WavelogKey]]” is de API-sleutel met lees- en schrijfrechten, aangemaakt in het gebruikersmenu onder “API”. “[[ens.k.WavelogStation]]” is een keuzelijst met de stations die van de server zijn gelezen (adres en sleutel moeten al opgeslagen zijn): kies het jouwe; de knop met de twee pijlen (“[[ens.wl.read]]”) laadt de lijst opnieuw. Als de server niet antwoordt, wordt de keuzelijst een vak waarin je het nummer typt (station_profile_id), met de reden en de knop “[[ens.wl.read]]” (“[[ens.wl.reading]]” tijdens het lezen). Een nummer dat niet op de server staat, krijgt het label “[[ens.wl.unknown]]”. “[[ens.test]]” controleert sleutel en station zonder naar het logboek te schrijven.",
  "t.2cu9qvb1alm": "Azimut, radio bij het starten en Club Log",
  "t.2cuwemslunb": "Aurora probeert ook de berichten die het verwacht: zo leest het zwakkere signalen dan gebruikelijk.",
  "t.2cw6em54wa2": "Zodra het is afgegaan, schakelt [[ctl.wait_call]] uit: schakel het opnieuw in om opnieuw te wachten.",
  "t.2cxhbcch408": "Laad de pagina opnieuw in de browser van de telefoon.",
  "t.2cy49mm5uf4": "[[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]] › [[sw.pg.images]]. Wat van de beelden wordt opgeslagen en in welke mappen. Wijzigingen gaan door met “[[sw.save]]” onderaan het venster.",
  "t.2cyynnkxskx": "De agent in het systeemvak: het pictogram en het menu",
  "t.2czlhquwaxz": "De waterval met de Rx- en Tx-balken, laag, onder de berichten.",
  "t.2d05egqawi2": "De tabel heeft een rij per modus (FT8, FT4 en DIG, de andere digitale modi) en een kolom per band, van 160 m tot 4 m plus “U” (de banden korter dan 4 m). Met een gekozen station toont hij zijn land: groen = gewerkt (en bevestigd, of het logboek zegt niets over bevestigingen), oranje = gewerkt maar niet bevestigd, grijs = nooit. Zonder station toont hij hoeveel landen je per vakje hebt gewerkt.",
  "t.2d0mswp5ay0": "Verschijnt de waarschuwing “De pc heeft moeite om op tijd te decoderen”, druk dan op “[[diag.slow_pc.to2]]”: de decodeerdiepte gaat naar Normaal (je kunt hem ook wijzigen in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › “[[dec.depth]]”). Komt de waarschuwing terug, dan “[[diag.slow_pc.to1]]”. Aurora wijzigt hem nooit zelf. Ook helpen: Multithread aan, SWL en a7/a8 uit en zware programma’s gesloten (browser met veel tabbladen, games, videogesprekken).",
  "t.2d220vjotqe": "[[fil.decode]] · [[dec.singleDecode]]: selectievakje, standaard uit. Hoewel het op deze pagina staat, werkt het op JT65 en Q65: die zoeken alleen rond de ontvangstfrequentie (binnen F Tol) en stoppen bij het eerste bericht. Zet het aan als je in JT65 of Q65 alleen het signaal wilt decoderen waarop je staat; het verandert niets aan FT8 en FT4.",
  "t.2d280rwlj8w": "De menu’s [[digi.menu.file]], [[digi.menu.edit]], [[digi.menu.configure]] en [[digi.menu.help]]",
  "t.2d3an0st1y1": "Statusregel naast de knoppen: toont de uitkomst van de twee tests; zijn er nog niet opgeslagen wijzigingen in engine-items, dan toont hij in plaats daarvan hoeveel het er zijn (“n wijzigingen om toe te passen”).",
  "t.2d3zxdlh24j": "Modus MSK144 (meteorscatter)",
  "t.2d62y3ela4x": "Wanneer het decoderen start en Full duplex",
  "t.2d7e7t4wnc1": "Bij FT8- en FT4-spots wordt Split DX niet gebruikt: DXpedities werken met Fox/Hound en Aurora regelt de split van de radio via Instellingen › Station › Radio. Met de schakelaar uit stemt de spot alleen af en is het label “UP 5” slechts informatie.",
  "t.2d7uf3nns9s": "Waar je modus, band, taal, geluiden en thema wijzigt.",
  "t.2dca1i4hu67": "[[ap.text]] · [[ap.fontUi]]: het lettertype van menu’s, labels en knoppen. Standaard IBM Plex Sans; alternatieven System UI, Segoe UI, Verdana, Tahoma, Arial, Calibri. Als het op de computer ontbreekt, wordt het meest gelijkende gebruikt; er wordt niets van internet gedownload.",
  "t.2dd993mqjoi": "“[[cmd.tune]]”: verschijnt alleen als je het aanzet in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Het zendt een draaggolf om de antenne af te stemmen; nog een keer drukken stopt het; het duurt hooguit 2 minuten en het zenden moet zijn geopend.",
  "t.2del8sdimr3": "Kies in het logboekpaneel “Kaart”: stations die hun locator zenden verschijnen met hun roepnaam, in de kleur van wat nieuw is (dezelfde als bij Bandactiviteit); CQ-roepers hebben een kader.",
  "t.2dfcj401ku3": "Naar een station in de wachtrij springen",
  "t.2dfwl3gz3ze": "“[[ens.g.tcp]]” · “[[ens.k.EnableTCPConnection]]” (standaard uit), “[[ens.k.TCPServer]]” (127.0.0.1) en “[[ens.k.TCPServerPort]]” (52001): stuurt elke gelogde QSO via TCP naar een logprogramma, zoals JTDX doet met N1MM Logger+: voor elke QSO een nieuwe verbinding met een “Log”-bericht met het ADIF-record; als het programma met NAK antwoordt, is de QSO geweigerd. Zet het alleen aan als je logboek de QSO zo wil. “[[ens.test]]” opent en sluit de verbinding zonder QSO’s te versturen.",
  "t.2dg458a4wkn": "In het paneel [[panel.tx]], rechtsboven naast de DX, toont het label RX (groen) zolang je luistert; tijdens het zenden wordt het de rode knop “[[stop.button]] (Esc)”.",
  "t.2dh5fku7vyc": "[[digi.mi.capsOnly]] (uit): alles wat je in het zendvenster typt en de macro’s gaan in hoofdletters de lucht in; handig in RTTY, dat standaard geen kleine letters heeft.",
  "t.2di2swvoeuk": "[[rep.title]]",
  "t.2dm6ujz849q": "Als je over een roepnaam beweegt, toont het vak azimut en afstand. “Radio verbinden bij het starten van Aurora” gaat vanzelf aan bij de eerste geslaagde verbinding. De meldingen van Club Log zijn in de taal van de interface. De controle van spots op DXSummit zoekt het juiste station.",
  "t.2dn8j0wfrp2": "[[nav.stats]]: de cijfers van je log (zie “Statistieken en de DXCC-kaart”).",
  "t.2dnhupy2umv": "Log gesloten: de QSO’s komen later aan",
  "t.2do1itf2vdh": "[[tab.frequencies]] · [[set.save]]: slaat de tabel op. Hij slaat zichzelf ook op na ongeveer een seconde en als je de pagina verlaat; de knop blijft uit tot je iets wijzigt. Verschijnt “[[freq.invalid]]”, dan is de tabel niet opgeslagen: verbeter de foute rij.",
  "t.2dpol5pha2r": "In de groep «ADIF-bestand van het QSO voor het log sturen» houdt het vakje QSO’s in de wachtrij zolang het log gesloten is en stuurt ze opnieuw als het opengaat, zonder ontvanger in de Integraties.",
  "t.2dqac6b8dvi": "Zet in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] “[[not2.unconfirmed]]” aan (en “[[not2.unconfirmedGrid]]” voor locatorvelden): een land dat is gewerkt maar niet bevestigd (LoTW of QSL in het logboek) blijft “nieuw DXCC” in de kleuren, het filter van Bandactiviteit en Automatisering. Op de DX-kaart zijn bevestigde vierkanten groen, alleen gewerkte geel.",
  "t.2dqwxlgrvu2": "De grote melding voor een nieuwe DXCC verschijnt één keer per station; kies in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] “[[not2.popPos]]” en “[[not2.popSound]]”. Onder de kaarten voor nieuwe DXCC (er worden er hooguit twee getoond) staat de knop “[[newdx.off]]”, die ze allemaal uitzet; om ze terug te krijgen vink je “[[not2.popNew]]” aan in hetzelfde vak “[[not2.grpAlerts]]” (zie “Nieuwe DXCC en gezochte station: de gemarkeerde meldingen”).",
  "t.2dqynwu8yme": "Eén klik op een rij selecteert hem. Dubbelklik: je antwoordt dat station (zie “Een CQ beantwoorden”); het vinkje “[[gen.dblReply]]” is nodig. Rechtsklik op de rij: het station gaat in de wachtrij voor het volgende QSO; nog een rechtsklik haalt het weg (zie “De wachtrij en [[ctl.answer_all]]”). Rechtsklik op de roepnaam: een menu met “Open op QRZ.com” en “Aan wachtrij toevoegen” (of “Uit wachtrij halen”); Esc of een klik erbuiten sluit het.",
  "t.2dr9kuuacvp": "Kies boven de lijst met decodes de “[[contest.order]]”: “[[contest.order.value]]” toont alleen de laatste twee periodes, zodat stations die niet meer worden gehoord niet bovenaan blijven staan; “[[contest.order.time]]” toont ze allemaal in tijdsvolgorde, nieuwste onderaan zoals Bandactiviteit, en de lijst volgt vanzelf tot je omhoog scrolt om te lezen. De keuze wordt onthouden.",
  "t.2dra90twxoa": "“[[snd.addFile]]” laadt je eigen geluid (tot 5 MB): het blijft in de lijst staan voor elke melding; met × verwijder je het.",
  "t.2drtg3y6ebq": "Onder het logboek staat de DXCC-kaart van het station dat je roept (zie “De DXCC-kaart”). Het tabblad “[[log.tab.map]]” toont de DX-kaart van de gebruikte band (zie “De kaart in het paneel Log”).",
  "t.2dt57u62w1t": "Rotor: de pagina en de kaart",
  "t.2dtkfixnzrn": "[[ctl.ap_list]] (standaard aan): “a8” zoekt bij de Rx-balk naar de antwoorden van je partner, als DX Call en DX Grid zijn ingevuld; “a7” zoekt naar de volgende berichten van de QSO’s die in de vorige periode zijn gehoord.",
  "t.2dv7juu1jq1": "[[digi.edit.title]] · “[[digi.edit.clear]]” maakt label, tekst en kleur leeg (de toets blijft de gekozen); “[[digi.edit.cancel]]” sluit zonder op te slaan; “[[digi.edit.ok]]” slaat de macro op. Een lege macro opslaan maakt de toets vrij.",
  "t.2dwzs9qtm0j": "[[digi.log.clear]] (de rode ✕): wist de QSO-gegevens en zet de rapporten terug op 599 (met [[digi.mi.defaultRst]] aan).",
  "t.2dxw0er8iof": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.autocq]] vind je het [[tab.schedule]]: een lijst van maximaal vijf UTC-tijden waarop Aurora zelf van band wisselt. Let op: deze pagina laat Aurora niet zelf CQ roepen; voor automatisch CQ zie “Aurora zelf CQ laten roepen” hieronder.",
  "t.2dzm9cxetuy": "[[digi.mi.waterfall]] (aan): de waterval met zijn schaal. [[digi.band.view]] (aan): het paneel met de signalen van de hele band; het verschijnt alleen in CW en PSK en met bandecodering aan in het menu [[digi.menu.options]]. [[digi.band.wfCalls]] (aan): de roepnamen boven de sporen in de waterval. [[digi.mi.statusBar]] (aan): de balk onderaan.",
  "t.2e0t0i7wr2n": "Houd de muis boven het “?” naast een onderdeel om te lezen wat het doet; een klik houdt de uitleg open.",
  "t.2e14d3t0tsj": "[[snd.title]] · [[snd.volume]]: de volumeschuif voor alle geluiden van Aurora, van 0 tot 100% (standaard 50%), zonder het Windows-volume aan te raken. Het is dezelfde schuif als naast het luidsprekerpictogram rechtsonder.",
  "t.2e1eq1gw5ix": "Er komt niets aan: adres en poort moeten in beide programma’s overeenkomen en het luisteren moet in het logboek gestart zijn.",
  "t.2e2cxs9k50n": "[[gen2.operation]] · [[gen2.watchdog]] (getalveld, 0 tot 99, standaard 6): beveiliging tegen zenden zonder toezicht. Als je zoveel minuten niets doet en er geen nieuw bericht binnenkomt, stopt het automatisch zenden. 0 = geen watchdog. De telling begint opnieuw zodra je iets aanraakt of er een bericht komt dat een antwoord nodig heeft; verhoog de waarde voor lange activiteit, verlaag hem als je vaak zonder toezicht zendt.",
  "t.2e2ewbx8nlc": "[[digi.mi.echoRx]] (uit): de tekst die je zendt, verschijnt ook in het ontvangstvenster, regel voor regel, voorafgegaan door ». Als het uit staat, blijft de uitgezonden tekst in het zendvenster (boven het vak, als “[[digi.tx.sentTitle]]”).",
  "t.2e2pbeuneo7": "Maak je QSO’s ook met het log gesloten: Aurora zet ze in de wachtrij.",
  "t.2e40tft2qym": "Met het adres van de helper in “[[sup.email]]” opent “[[sup.sendMail]]” Gmail in de browser al ingevuld: sleep de zip erin.",
  "t.2e52qb0zx37": "[[not2.grpTable]] · [[not2.colAlert]]: “[[not2.playAlert]]” is een nadrukkelijke geluidsmelding, bedoeld om het nieuwtje niet te missen, ook als je niet bij de pc zit; de kolom “[[not2.perBand]]” die volgt telt alleen mee als de eerste aan staat, en laat de melding ook afgaan voor nieuw op band of mode. Beschikbaar voor CQ-zone, ITU-zone, land, grid en prefix; voor nieuwe roepletters staat er “—”. Standaard uit. Ze werken alleen met “[[alert.button]]” aan.",
  "t.2e8lox35yt8": "Boven de waterval staan de labels van de DX Cluster-spots die binnen de audioband vallen die je ziet: roepnaam en een markering op de spotfrequentie. Als er geen ruimte is, worden de spots samengevoegd tot één label “+N” (beweeg de muis erover voor de lijst). Een klik op een spot zet de ontvangstfrequentie daarheen (alleen ontvangst: het zendt niet).",
  "t.2e8lx2ahqoo": "Aurora kan vanzelf door meerdere banden of frequenties roteren, één elke twee minuten, om te luisteren waar activiteit is.",
  "t.2e92k81cws8": "[[digi.ms.receive]] · [[digi.mi.snap]] (standaard aan): een klik op de waterval van de werkpagina springt naar de dichtstbijzijnde piek (bij RTTY naar het paar tonen). Zet hem uit als je de frequentie precies wilt waar je klikt.",
  "t.2e9zhw2njk6": "Typ een woord in het veld “[[sw.search]]” bovenaan de boom van de Instellingen: alleen de pagina’s die het noemen blijven over. In deze Gids beschrijven de hoofdstukken “Instellingen: …” elke pagina en elk item, in de volgorde van de boom.",
  "t.2eavi3d6zg0": "“[[cluster.servers]]” · “[[cluster.test]]”: test elke server; de test komt niet in de cluster en vertelt je roepletters niet. Hij start vanzelf als je de pagina opent en als je een server toevoegt; druk erop om te herhalen na een netwerkwissel of als een server uit de lucht was.",
  "t.2ecvxrlsbw1": "[[tab.frequencies]] · [[freq.reset]]: zet de starttabel van Aurora (de eerste FT8- en FT4-rijen) in de plaats van de huidige; je eigen rijen gaan verloren zodra de tabel wordt opgeslagen. Gebruik het als je er een zootje van hebt gemaakt.",
  "t.2edi99hgbvm": "Kies in MSK144 naast de modus de T/R-periode (5, 10, 15 of 30 s, zoals WSJT-X): die wordt per band onthouden, standaard 15 s op 6 m en 4 m en 30 s op 2 m en de andere banden. De knop “Sh” schakelt korte berichten in: R+rapport, RRR en 73 gaan uit als “<DX MY> R+03” (rapport afgerond op -03, +00, +03, +06, +10, +13, +16) en de naar jou gezonden worden gedecodeerd. “Sh” en SWL sluiten elkaar uit. Je partner moet dezelfde periode gebruiken en “Sh” aan hebben.",
  "t.2eg8vhnprpk": "[[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]]. Hier kies je waar Aurora het audiosignaal van de radio vandaan haalt (waterval en decodering) en waar het zendaudio naartoe gaat. Keuzes worden na een moment vanzelf toegepast, zonder herstart; als het nieuwe apparaat niet opent, blijft het vorige actief en wordt de keuze niet opgeslagen. De keuzes blijven na een herstart bewaard. De pagina werkt met de eigen engine van Aurora.",
  "t.2egulvy7q5l": "[[agent.tab]]",
  "t.2ei8shrmg6s": "BBLogger (gratis Italiaans logprogramma, site aribusto.it, nu ontwikkeld door IZ2BKT) ontvangt de QSO’s van Aurora zoals die van WSJT-X en JTDX. Er zijn twee dingen nodig: een bestemming in Aurora en de “Wsjtx interface” in BBLogger, met hetzelfde adres en dezelfde poort.",
  "t.2emb7wzh83v": "AFC: volgt het signaal als het wegdrijft. Lock: de zendfrequentie blijft vast. Snap: een klik op de waterval vergrendelt op de piek. Het zijn drie schakelaars; de uitleg staat in het menu [[digi.menu.options]].",
  "t.2eov9vdvqgz": "Tabblad “[[contest.analysis]]”: kies de “[[contest.an.edition]]” (of de actieve contest) en lees QSO’s, multipliers, score, onzekere QSO’s en actieve uren; de grafiek toont de QSO’s uur voor uur (groen = het beste, oranje = het slechtste), daarna “[[contest.an.band]]”, “[[contest.an.best]]” en “[[contest.an.lost]]” (gaten van meer dan 15 minuten zonder QSO), met een advies.",
  "t.2eqcnflmxgj": "Stem en eigen bestanden voor meldingen",
  "t.2esnjm739fr": "[[not2.grpWorked]] · [[not2.strike]] en [[not2.underline]]: hoe een al gewerkt station wordt gemarkeerd, doorgestreept (standaard aan) of onderstreept; de twee keuzes sluiten elkaar uit. Ze zijn vergrendeld als er geen “nieuw”-markering aan staat.",
  "t.2ew9w3aqrj3": "Bovenaan de pagina met geluiden staat “[[snd.voiceLang]]”: de taal van Aurora of altijd Engels.",
  "t.2ewj97dsxt6": "Berichten die niet verzonden kunnen worden: als een roepnaam of bericht anders zou aankomen dan het is geschreven, gaat het niet de lucht in en wordt de reeks uitgeschakeld.",
  "t.2f1kgdymfwv": "De afstandsbediening",
  "t.2f2251yvs2a": "Corrigeer de velden die nodig zijn. Datum en tijd zijn in UTC; de locator mag leeg blijven of 4, 6 of 8 tekens hebben (IO91wm).",
  "t.2f3wlj8tio0": "Op de pagina’s CW en PSK decodeert het paneel “[[digi.band.title]]”, boven de waterval, alle signalen in de audioband tegelijk en toont ze in een lijst, één per rij. Je zet het aan en uit in het menu Opties (“[[digi.band.mi]]” in CW, “[[digi.band.miPsk]]” in PSK) en toont of verbergt het in het menu Beeld (“[[digi.band.view]]”).",
  "t.2f3y16qo0rm": "Bij de eerste start na een update, of met een heel oude versie, kan de poster “[[upd.poster.available]]” verschijnen: “[[upd.poster.install]]” werkt meteen bij (het start na een paar seconden vanzelf, “[[upd.poster.cancel]]” stopt het), “[[upd.later]]” stelt uit, “[[upd.poster.news]]” opent het nieuws.",
  "t.2f4qg59r63a": "Filters: het veld “[[hist.search]]”, de keuzelijsten “[[hist.band]]”, “[[hist.mode]]” en “[[hist.period]]” (“[[hist.p.1h]]”, “[[hist.p.24h]]”, “[[hist.p.7d]]” of “[[hist.p.all]]”). De knop “[[hist.clear]]” verwijdert na een bevestiging alle opgeslagen berichten; het QSO-logboek verandert niet.",
  "t.2f750qz2l2b": "Instellingen: Toegang en ondersteuning",
  "t.2f7pbzvck1o": "[[sw.wspr.beacon]] · [[mode.wsprPower]]: uitklaplijst zonder zichtbaar label, met waarden van 0 dBm (1 mW) tot 60 dBm (1 kW); fabriekswaarde 37 dBm (5 W). Het is het vermogen dat in het bakenbericht staat: kies het echte vermogen aan de antenne, niet wat je zou willen.",
  "t.2f999839t2h": "Instellingen: Station",
  "t.2fa4wuik4yb": "“[[rep.show]]” en “[[rep.showAuto]]”: openen het venster “[[rep.previewTitle]]”, dat precies de tekst toont die zou worden verstuurd: de bestanden van het pakket (elk opent om de inhoud te lezen) of een voorbeeld van een automatisch rapport. Het sluit met “[[rep.close]]” of Esc. Bekijk het voordat je vertrouwt.",
  "t.2fakik3gql3": "“[[ctl.hold_tx]]”: houdt de zendfrequentie vast; als je een station antwoordt, verschuift alleen de ontvangst. Het is om op een vrije plek te blijven.",
  "t.2faxaquer0m": "Eerste instelling met een SDR: zet de TCI-server aan in het SDR-programma, schrijf hier het adres (meestal is leeg laten genoeg) en druk op “[[sdr.useAll]]”. Controleer dan bovenaan of de CAT “[[cat.state.connected]]” zegt met de frequentie van de SDR. Details in de onderdelen “SDR met TCI (ExpertSDR, Thetis)” en “QMAP”.",
  "t.2fco4n32ksg": "Nieuwe berichten onderaan: druk in de titelbalk van Bandactiviteit en van het RX-venster op “[[list.bottom.off]]”. Dit wordt “[[list.bottom.on]]”: het nieuwste bericht is steeds de laatste regel en de lijst schuift omhoog. Elke lijst heeft zijn eigen keuze; die staat ook in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], “[[list.bottom]]”.",
  "t.2fcoi5jx851": "[[lay.status]] · [[upd.check]]: knop die meteen naar een nieuwe versie zoekt, zonder het interval af te wachten. Als de controle klaar is, opent altijd de poster: met de nieuwe versie en zijn nieuws, of met “[[upd.poster.upToDate]]”. Hij is grijs terwijl je in de velden hieronder typt en de wijzigingen nog niet zijn bewaard. Wanneer: nadat je op de site over een nieuwe versie hebt gelezen, of om zeker te zijn.",
  "t.2fde743duxg": "[[tab.updates]]",
  "t.2ffyl8gsh3u": "Afstandsbediening: bandactiviteit, DX Cluster en logboek",
  "t.2fg29dkas1b": "Ik zie signalen in de waterval maar er wordt niets gedecodeerd",
  "t.2fgo7ka7o2w": "[[sw.digi.perMode]] · RTTY, “[[digi.rtty.receiver]]”: [[digi.rtty.receiverAuto]] (fabriek), [[digi.rtty.receiverFilters]] of [[digi.rtty.receiverDisc]]. De discriminator werkt beter bij smalle shifts, onder 40 Hz; bij 170 Hz laat je gewoon Automatisch staan.",
  "t.2fgpckgo5fw": "[[sdr.tci]] · [[sdr.address]]: host en poort van de TCI-server van de SDR; het is hetzelfde onderdeel als [[cat.tci.address]] op de pagina [[sw.pg.radio]]. Leeg = 127.0.0.1:40001 (de poort van ExpertSDR en Thetis, waar je de TCI-server moet aanzetten). Wijzig het als de SDR op een andere pc of een andere poort draait. Het wordt na een korte pauze vanzelf opgeslagen; is het formaat niet host:poort, dan wordt het veld gemarkeerd en verschijnt “[[sdr.badAddress]]”.",
  "t.2fi46ts2c5k": "Als Aurora opnieuw start, gaat het terug naar de laatste pagina waar je was, als dat een van [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], Instellingen of de Gids was. Vanaf het Station, vanaf de modusgroepen en vanaf de andere pagina’s start het altijd weer op het Station.",
  "t.2fiovn4ytm3": "[[bar.watchdog]] met de minuten, bijvoorbeeld “WD 6m”: de zendwatchdog. Na zoveel minuten zonder QSO stopt het zenden vanzelf; zweef erboven om het te lezen. Hij verschijnt alleen als de watchdog aanstaat (niet nul).",
  "t.2fj7d8psror": "[[tab.cluster]]",
  "t.2fkfdu0udc4": "Een klik op de waterval verplaatst de ontvangst naar dat punt; als je met de muis sleept, volgt de cursor (hij bereikt de engine hoogstens tien keer per seconde). Met [[digi.mi.snap]] aan vergrendelt de cursor zich op de piek van het signaal (in RTTY op het paar van de twee tonen). De grens ligt tussen 200 en 3500 Hz.",
  "t.2fkk2o0ktvw": "Waarvandaan de spot vertrekt kies je in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › “[[cluster.spotVia]]”: “[[cluster.spotVia.dxsummit]]” (zoals JTDX: de spot verschijnt op dxsummit.fi maar komt niet in het netwerk van de telnet-clusters) of “[[cluster.spotVia.telnet]]” (Aurora verstuurt hem via de verbonden cluster met het commando DX en meldt “gelukt” pas als de cluster hem herhaalt; van daaruit bereikt hij het hele netwerk). Veel clusters accepteren spots alleen met inloggen: naast elke server staan “[[cluster.access.user]]” (de roepnaam, ook met SSID) en “[[cluster.access.password]]”, dat alleen wordt verzonden als de cluster erom vraagt en na het opslaan niet meer wordt getoond.",
  "t.2fkwan48q8h": "Open in LogHX de instelling van het digitale programma: Ctrl + klik op het JTDX-pictogram (of WSJT-X) in het hoofdvenster, of via het menu Setup. Aurora stelt zich voor als JTDX: gebruik de JTDX-instelling.",
  "t.2fohrcsswxh": "Het vak “[[snd.title]]” staat op de pagina [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], onder het vak met de meldingen: het volume, de stem, de andere meldingen met hun geluid en de geluidenbank om uit te proberen. Alles geldt meteen.",
  "t.2fopm25y6cu": "Bovenaan tonen of verbergen drie knoppen — [[news.kind.new]], [[news.kind.changed]] en [[news.kind.fixed]] — elk type nieuwsbericht (aan = gekleurd). Handig om bijvoorbeeld alleen de oplossingen te zoeken.",
  "t.2fpcqtb67zr": "Gele klokwaarschuwing (met ⚠): hij verschijnt alleen als de pc-tijd buiten de tolerantie ligt ten opzichte van de NTP-servers, of als hij meer dan een dag niet kon worden gecontroleerd. Een klik probeert meteen de Windows-tijd te corrigeren; als Windows het niet toestaat, opent [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] met de test op de NTP-servers (zie “De klok”).",
  "t.2fpihd6elsv": "De pop-upberichten bovenaan (“Handeling uitgevoerd”, “Beantwoorden…”): haal in [[sw.pg.alerts]], vak “[[toast.grp]]”, de vinkjes “[[toast.show.ok]]” en “[[toast.show.info]]” weg. Fouten (“[[toast.show.error]]”) worden altijd getoond en kun je niet uitzetten. Waar ze verschijnen en hoe groot ze zijn: “[[toast.position]]” en “[[toast.size]]”.",
  "t.2fqm22rs92q": "Schakel [[gen2.bandHopOn]] in en sla op: bij de volgende even minuut gaat de rig naar het eerste item.",
  "t.2fsww6z0z6t": "Het paneel Opdrachten",
  "t.2fx4c0idr7r": "Radiodisplay uit en DX-spot weer op zijn plaats",
  "t.2fx9uh3o8d": "[[not2.grpAlerts]] · [[not2.soundFirst]]: een geluid bij het eerste gedecodeerde bericht van elke periode, om te weten dat de ontvangst werkt. Standaard uit; het geluid kies je in het menu “[[snd.ev.first_message]]” van het vak “[[snd.title]]”. Het kan irritant zijn bij veel activiteit: zet het alleen aan voor tests.",
  "t.2fzo599hhzs": "[[sdr.tci]] · [[sdr.useAll]]: de knop die alles in één keer doet. Hij vraagt om bevestiging en zet dan de CAT op TCI met het ingevulde adres, audio-ingang “TCI (dalla radio)” en uitgang “TCI (alla radio)”, en maakt verbinding. De vorige keuzes voor radio en audio worden vervangen (om terug te gaan naar een andere radio gebruik je een profiel of zet je de onderdelen terug in [[sw.pg.radio]] en [[sw.tab.audio]]). De uitkomst verschijnt eronder, regel voor regel. Loopt alles al via TCI, dan maakt de knop plaats voor “[[sdr.allDone]]”.",
  "t.2g07hbfzsh": "Met het middelen van perioden aan wordt een signaal dat voor één periode te zwak is opgeteld bij de vorige perioden met dezelfde pariteit (zelfde frequentie binnen F Tol, zelfde DT binnen 0,2 s, tot 64 perioden) en draagt het bericht uit het gemiddelde het merk van a-priori-berichten. “Clear Avg” maakt het gemiddelde leeg; het leegt zichzelf ook bij wisselen van modus, submodus of frequentie, en met “Auto Clear Avg” na een bericht uit het gemiddelde dicht bij de Rx-frequentie. Dezelfde reset is de knop ⟲ “Clear Avg” naast AP en Prof.: druk erop als je opnieuw wilt beginnen.",
  "t.2g1o7ysm2p7": "Onder het scherm “[[sstv.clean.title]]”: “[[sstv.clean.original]]” of “[[sstv.clean.cleaned]]” (grijs tot er een beeld is). Opgeschoond haalt ruis weg zonder details te vervagen en wordt elke 4 seconden bijgewerkt terwijl het beeld binnenkomt; het origineel verandert nooit. Met “Opgeschoond” aan verschijnen twee schuifregelaars: “[[sstv.clean.order]]” (van 1 tot 6, standaard 3) en “[[sstv.clean.smooth]]” (van 0,10 tot 1,00, standaard 0,40): hoe hoger, hoe schoner maar zachter.",
  "t.2g1u7jyfmp0": "TX tijdens TUNE, split, valse crashes en frequentietabel",
  "t.2g35jdpt4mp": "Alleen met Cat4OM: de knop “[[cat.cat4om.search]]” vraagt Cat4OM om de groepen en radio’s, met hun status, met de hier ingevulde waarden (hij verandert niets en neemt de besturing van de radio niet over). In de lijst “[[cat.cat4om.found]]” schrijft de knop “[[cat.cat4om.use]]” groep en radio in de velden (daarna “[[cat.cat4om.inUse]]”). Werkt de netwerkaudio niet, dan verschijnt hieronder “[[cat.cat4om.audioProblem]]” met de reden.",
  "t.2g3fo34thpb": "[[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]. Een profiel is een kopie met naam van de radio-instellingen (besturingssysteem, model, poort, snelheid, PTT, split, modus, TCI- en Cat4OM-adressen): het is voor wie meerdere radio’s of meerdere kabels heeft en met een klik van de ene naar de andere wil wisselen. Het bevat geen audio, roepletters of andere stationsgegevens.",
  "t.2g4sd55iai0": "Bovenaan: het geanimeerde logo, de naam AURORA, “[[about.tagline]]” en “[[about.version]]” met het nummer van de gebruikte versie (een streepje als Aurora niet antwoordt). Wanneer nodig: het is de versie die je doorgeeft aan wie je helpt.",
  "t.2g5c1977d4w": "Kenwood TS-590SG, TS-890S: virtuele COM-poort via USB. Kies bij [[cat.rig]] het model; [[cat.baud]] gelijk aan die in het radiomenu (zie de handleiding).",
  "t.2g5jahz4tfa": "De radio: LogHX en Aurora kunnen niet dezelfde COM-poort openen. Moet LogHX de frequentie lezen, gebruik dan OmniRig in beide (in Aurora [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] › OmniRig), of laat CAT in LogHX uit.",
  "t.2g5pkeg2sma": "Dit is de pagina die de telefoon de eerste keer ziet, of als de koppeling is verwijderd. Je komt hier via de QR-code op de pc (link “#/associa?codice=…”) of door het adres van Aurora in te typen.",
  "t.2g66olze4e9": "De notch verschijnt als een fluorgroene band met een klein balkje bovenaan: sleep hem om hem te verplaatsen, sleep een van de randen om hem breder of smaller te maken (van 10 tot 100 Hz), rechtsklik om hem te verwijderen. “[[digi.notch.clear]]” in de statusbalk en in het menu [[digi.menu.options]] verwijdert ze allemaal: de knop verschijnt alleen als er minstens één notch is en toont hoeveel.",
  "t.2g9tyx70ry2": "“[[bfl.button]]”: opent onder de titelbalk een rij pillen waarmee je kiest welk nieuws je wilt zien. Als je er een paar hebt gekozen, licht de knop op en toont het aantal (bijvoorbeeld “Filter 3”). Een tweede klik sluit de rij zonder je keuze te wissen.",
  "t.2gbxegzl3uv": "Schuifregelaars Rx, Pwr en AUTO (apparaatvolume)",
  "t.2gc22c5g439": "[[digi.tx.title]] · [[digi.freq.tx]]: de audiofrequentie om te zenden, van 200 tot 3500 Hz (fabriek 1000). Je kunt hem alleen bewerken met “[[digi.mi.lock]]” aan; zonder volgt hij de ontvangst.",
  "t.2getrrv5tz2": "[[cat.share]] · [[cat.share.port]]: verschijnt alleen als het delen aan staat. Fabriekswaarde 4532, de poort die JTDX, Log4OM2 en de andere voorstellen voor “Hamlib NET rigctl”; van 1024 tot 65535. Verander hem alleen als hij bezet is. Hieronder verschijnt, zodra de radio verbonden is, het adres dat je in de andere programma’s schrijft (127.0.0.1 en deze poort). Is de poort gelijk aan die van de netwerkradio gekozen in [[cat.port]], dan zou Aurora met zichzelf verbinden en waarschuwt het je.",
  "t.2ghkg0va80f": "[[seq2.stop]] · [[seq2.strictCq]] (standaard uit): op een gerichte CQ (CQ NA, CQ DX…) antwoordt Aurora alleen als je in het gevraagde gebied zit, ook voor gezochte stations en nieuwe DXCC's. Zet dit aan als je geen periodes wilt verspillen aan CQ's die niet voor jou bedoeld zijn.",
  "t.2gjaf1kdpe2": "Het ontvangst- en het zendvenster",
  "t.2gjnoug3iq7": "Zendsnelheid: in WPM, van 5 tot 60 (standaard 20). Je stelt hem in met de schuifregelaar in het venster “[[digi.ms.title]]” (klik op de WPM-waarde in de statusbalk), met de macro’s <WPM:20> (ook relatief, <WPM:+2>) of met de fabrieksmacro’s F10, F11, F12 (15, 20, 25 WPM). De knop “TX = RX” in de statusbalk zet de zendsnelheid op de snelheid die net bij het ontvangen is begrepen.",
  "t.2gjpglrpg06": "PSK · RTTY · CW, SSTV, telefoon en agent",
  "t.2gk7gxgoigs": "Om elke twee minuten regelmatig van band te wisselen gebruik je liever Band Hopping ([[sw.sub.ft8]] › [[tab.sequence]] › [[gen2.bandHop]]); het schema is voor precieze tijden (bijvoorbeeld 80 m ’s ochtends, 20 m ’s middags).",
  "t.2gkg1n1xusj": "[[fil.decode]] · [[dec.ftolJt65]] en [[dec.ftolJt9]]: twee uitklaplijsten met de frequentietolerantie rond Rx, van 1 tot 1000 Hz (1, 2, 5, 10, 20, 50, 100, 150… tot 1000); fabriekswaarde voor beide 50 Hz. Bij JT65 gebruiken ook enkelvoudig decoderen en middelen deze waarde; bij JT9 is het het venster dat als eerste wordt geprobeerd. Vergroot hem als het signaal ver van de Rx-lijn zit, verklein hem om alleen te decoderen wat dicht bij je zit.",
  "t.2gmsl3urntd": "Dubbelklik op de rij, of druk op ‘[[exp.edit.btn]]’ aan het einde van de rij: het venster ‘[[exp.edit.title]]’ gaat open. In het paneel [[panel.log]] van het Station doet een dubbelklik op de rij hetzelfde.",
  "t.2gnc3l71j9q": "Een linkerklik op het pictogram opent Aurora (als Aurora al open is, komt het venster vóór alle andere).",
  "t.2hkea6ltxf": "De zes knoppen onder “[[int.title]]” ([[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]) voegen een bestemming toe met de juiste beginwaarden, die je daarna kunt veranderen. Hieronder, per knop: de waarden en wat hij ontvangt.",
  "t.2idhbbjbgn": "Een QSO is niet in mijn logprogramma aangekomen: hoe haal ik hem terug?",
  "t.2iu9fgbao6": "[[nav.sat]]: de satellietpagina (zie “Satellieten: de pagina, paneel voor paneel”).",
  "t.2jghd66u7p": "De toets Pause en de automatische CQ met de dubbele Esc horen alleen bij de tekstmodipagina: in SSTV bestaan ze niet.",
  "t.2kixb0xakx": "In [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]] stel je in hoe de waterval en het spectrum worden getekend. Dit is het eerste deel: voorbeeld, resolutie en kleuren. Elke wijziging geldt meteen en blijft bewaard na een herstart; opslaan hoeft niet.",
  "t.2lfgjgyaau": "[[digi.mi.threshold]]: opent het venster “[[digi.ms.title]]” met de squelchdrempel (en de andere onderdelen van de modus).",
  "t.2lsaofxz1r": "De keuzes in het menu [[digi.menu.view]], de breedte van het logboek en de hoogte van de waterval en van het paneel Signalen blijven op deze computer (in de browser van Aurora). De modusinstellingen (frequenties, AFC, squelch, macro’s, geheugens) worden in plaats daarvan in de engine bewaard. Verschijnt bovenaan “[[set.loadError]]”, dan antwoordt Aurora niet: controleer of de engine aan staat.",
  "t.2ltd527tjr": "Rechts van het tabblad “[[sstv.view.rx]]”: hiermee log je de QSO die je in SSTV hebt gemaakt. De roepnaam komt vanzelf uit de FSK ID na het beeld (als het veld leeg is of door Aurora is ingevuld) en zodra er een roepnaam is, zoekt Aurora het station op met de al ingestelde dienst (QRZ.com of HamQTH) en vult naam, QTH en locator in die leeg waren. Wat je met de hand schrijft, wordt niet aangeraakt.",
  "t.2m9euithze": "[[cat.profile.save]]: slaat de radio-instellingen zoals ze nu zijn op onder de naam in “[[cat.profile.name]]”; bestaat er al een profiel met die naam, dan wordt het vervangen. Het profiel wordt het profiel in gebruik. Druk erop als je een radio goed hebt afgesteld, zodat je niet alles opnieuw hoeft te doen.",
  "t.2o2eol4qd4": "De Tx-balk kun je ook verplaatsen terwijl je zendt: de toon verandert meteen. Kies een vrije plek op de waterval om te zenden.",
  "t.2qlm47od2w": "[[ens.g.log]] · [[ens.k.ClearCallGrid]] (standaard uit): wist na het loggen van een QSO de roepletters en locator van het DX-station, klaar voor het volgende. Omdat Aurora aan het eind van het QSO het DX-station sowieso wist, doet het vakje er bij automatisch loggen weinig toe; houd het aan als je zeker wilt altijd met lege velden te beginnen.",
  "t.2rv0bqpda6": "[[sw.close]]: sluit de Instellingen; zijn er niet-opgeslagen wijzigingen, dan vraagt het eerst of je ze wilt weggooien. [[sw.save]]: slaat de wijzigingen in engine-items (zoals Roepletters en Locator) op en past ze toe. De items van radio, audio, rotor en klok worden vanzelf opgeslagen en wachten niet op “[[sw.save]]”.",
  "t.2ta08in5ls": "“ADIF opslaan…” opent het Windows-venster om map en naam te kiezen: het bestand bevat alleen de geselecteerde QSO’s. Op de telefoon downloadt de knop het bestand.",
  "t.2xpl7ymgkj": "[[tab.online]]",
  "t.30ylqi459n": "[[lay.settings]] · [[clock.interval]]: hoeveel minuten tussen de klokcontroles van Aurora, van 1 tot 1440 (een dag); standaard 15. Eén controle per 15 minuten is genoeg en belast de servers niet; ligt de tijd buiten tolerantie, dan controleert het zelf elke minuut opnieuw.",
  "t.34r3o4v678": "Leeftijd van berichten: open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] en vink in het vak “[[fil.grp.both]]” “[[gen.showAge]]” aan. De eerste kolom geeft aan hoe lang geleden het bericht binnenkwam (45 s, 3 min) en werkt zichzelf bij; houd de muis boven het getal om de UTC-tijd te zien.",
  "t.358v0jrx55": "“[[ens.g.lotw]]” · “[[ens.k.LoTWSend]]” (standaard uit): ondertekent en uploadt elke QSO met TQSL, het ARRL-programma voor LoTW; Aurora ondertekent zelf niet, dus TQSL moet geïnstalleerd en ingesteld zijn met je certificaat (zonder wachtwoord, anders stopt het). “[[ens.k.LoTWTqsl]]”: waar tqsl.exe staat; leeg = Aurora zoekt het in de mappen van Program Files; vul het alleen in als het ergens anders staat. “[[ens.k.LoTWLocation]]”: de naam van de stationslocatie die je in TQSL hebt aangemaakt (“Station Locations”), precies zo geschreven: daarmee weet TQSL met welke roepletters en locator het moet ondertekenen. Wachtende QSO’s gaan samen in één upload weg; dubbele QSO’s en QSO’s buiten de datums van het certificaat worden overgeslagen. “[[ens.test]]” controleert TQSL en de locatie zonder iets te uploaden. LoTW is de enige dienst die ook verschijnt zonder Windows-bescherming van geheimen.",
  "t.35qrp9y5cq": "Welke panelen je ziet en waar ze nu staan: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] (“[[win.where]]”, “[[win.shown]]”, “[[win.reset]]”).",
  "t.362kcir4h7": "Selectie: de eerste keer dat de pagina opent, zijn alle QSO’s geselecteerd (meestal wil je alles exporteren). Elke rij heeft een eigen vinkje; het vakje bovenaan selecteert of wist alle getoonde rijen (“[[exp.selectShown]]”). De knoppen “[[exp.all]]” en “[[exp.none]]” doen hetzelfde, maar alleen voor de QSO’s die de filters tonen. Een regel zegt hoeveel QSO’s geselecteerd zijn, hoeveel er getoond worden en hoeveel er in het logboek staan; geselecteerde QSO’s die door een filter verborgen zijn, worden toch opgeslagen.",
  "t.39j8oqw3rh": "Aan de slag",
  "t.39llsn4rxy": "Kies in het menu Modus van de pagina [[nav.textModes]] CW: het zenden gebruikt een toon met afgeronde flanken op de ingestelde snelheid, het ontvangen volgt vanzelf de snelheid van het station (tussen de helft en het dubbele van de ingestelde).",
  "t.3a36ojyj4j": "“FT8”: de groep van HF-modi. Het modusmenu (zie “Modus, submodus en frequentie”) biedt FT8, FT4, JT9, JT65, FST4, FST4W en WSPR. Eén klik brengt je terug naar de pagina [[nav.station]] en herstelt de laatste modus die je in deze groep gebruikte (standaard FT8). Als de radio niet op een frequentie van die modus staat, zet Aurora hem op de eerste band waar de modus bestaat.",
  "t.3aa43gimsc": "Een klik op de rij opent de expeditiekaart: status (in de lucht, komt eraan, afgelopen), hoe lang nog, of je haar hoort, de laatste spot, de data, de NG3K-notities, de afstand en richting vanaf jou, de kaart van het land en de knop “Tune to … kHz” die de radio naar de laatste spot zet. Een dubbelklik op een gehoorde expeditie roept haar zonder de kaart te openen. “[[dxd.close]]” of Esc sluit de kaart.",
  "t.3b0w7beqje": "[[sstv.set.grpRx]] · [[sstv.set.rxOffset]]: van -200 tot 200 Hz in stappen van 5 (fabriek 0). Verschuift de ontvangstafstemming met zoveel Hz, voor radio’s of stations die een beetje naast de frequentie zitten: komen beelden met verkeerde kleuren of scheef binnen terwijl het signaal sterk is, probeer dan hier een paar tientallen Hz.",
  "t.3elxiv4637": "Open [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]] en zet de dienst aan.",
  "t.3fmkv8huoc": "Welke banden in de keuzelijst verschijnen, kies je in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (de band in gebruik wordt altijd getoond); de frequenties zelf wijzig je in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].",
  "t.3gnbswe959": "Hoge SWR: als de radio tijdens het zenden een SWR boven de limiet meet, stopt Aurora meteen. De limiet staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]] (standaard 2,5, 0 = nooit).",
  "t.3gp6y8tgnj": "Aurora bevat een wereldkaart, “Aurora-kaart” (land en grenzen onder dag en nacht, sporen en voetafdrukken): dit is de basiskaart als “Contour HiRes” ontbreekt. De afbeeldingen die je toevoegt met “[[sat.map.add]]” (equirectangulair 360° × 180°, in de map “maps” van de Aurora-gegevens) blijven altijd te kiezen in de keuzelijst “[[sat.map.pick]]” en in de instellingen van de pagina, waar ook “[[sat.set.mapAuto]]” staat. Controleer de satellietfrequenties bij AMSAT; schrijf het bestand satelliti-utente.json om meer satellieten toe te voegen.",
  "t.3l9tyiobvx": "Split uit-knop naast het display van de radio",
  "t.3lrmt8u63e": "[[not2.grpAlerts]] · [[alert.button]]: de hoofdschakelaar voor geluiden (het is ook het luidsprekerpictogram rechtsonder, met de volumeschuif). Als het uit staat, speelt Aurora uit zichzelf niets af; standaard uit, omdat een geluid waar niemand om vroeg hinderlijk is in een radiohoek. Zet het aan als je de meldingen wilt horen.",
  "t.3lsi3kgdcp": "[[clock.state]] · [[clock.check]]: vraagt meteen de servers en toont de afwijking. Het verandert niets op de pc: het is om te kijken. Gebruik het als de gele klokwaarschuwing verschijnt of vóór een contest.",
  "t.3mgos8huk2": "[[acc.home]] · [[acc.open]]: vakje, standaard aan. Als het aan staat, bestuurt iedereen op het thuisnetwerk Aurora zonder code, ook het zenden als dat openstaat; vanaf internet, tunnels of proxy’s is altijd een code nodig. Het blijft zo na een herstart. Wanneer uitzetten: als het thuisnetwerk niet alleen van jou is (gasten, flatgebouw, gedeeld wifi) of na je tests; als het uit staat, moet elke telefoon of tablet met een code worden gekoppeld.",
  "t.3n412xlbtn": "In FT8 moet de pc-tijd binnen een fractie van een seconde kloppen. Als alles goed is zie je niets; anders verschijnt bovenaan een gele waarschuwing.",
  "t.3ol1640qhy": "Naast de diagnosemeldingen (zie “De diagnosemeldingen rechtsonder”) toont Aurora nog een paar andere berichten, bijna altijd maar één keer.",
  "t.3qh4n3xejg": "Contest: het tabblad Racing, paneel voor paneel",
  "t.3ruu8z7n7g": "Op de pc is er geen knop “CQ”: CQ is het zesde bericht van het paneel [[panel.tx]]. Op de telefoon doet de knop “[[phone.cq]]” alles in één tik.",
  "t.3tn40cwkq9": "“[[panel.cluster]]”: de eerste 5 spots, met frequentie in MHz, vlag, roepletters, land, modus, wie het meldde en UTC-tijd. Tik op een spot en de radio gaat naar dat station; zonder CAT verschijnt een melding. Met de filters die je in Aurora koos zie je de passende spots; zijn het er minder dan 5, dan wordt het aangevuld met de andere. Tik op de titel om het paneel te sluiten of te openen (zolang de pagina open blijft; de volgende keer gaat het vanzelf weer open). Het paneel is er niet als je de DX Cluster in Aurora hebt uitgezet.",
  "t.3xcyd59sjx": "Stond de radio uit of de USB-kabel los toen Aurora startte? Opnieuw starten is niet nodig: zet de radio aan (of steek de kabel weer in) en het zenden herstelt zich vanzelf op dezelfde geluidskaart.",
  "t.40rsy6vow4": "Een tweede radio toevoegen: 1) stel in [[sw.pg.radio]] de eerste radio in en schrijf in [[sw.pg.profiles]] een naam en druk op “[[cat.profile.save]]”; 2) schrijf de naam van de tweede en druk op “[[cat.profile.new]]”; 3) stel in [[sw.pg.radio]] de tweede radio in en druk opnieuw op “[[cat.profile.save]]”. Van radio wisselen: kies het profiel, “[[cat.profile.load]]”, dan [[cat.connect]]. Vergeet niet ook ingang en uitgang in [[sw.tab.audio]] te wijzigen: profielen raken die niet aan.",
  "t.41aaxkfknq": "Muiswiel of de kleine knoppen + en − om te zoomen; indrukken en slepen om te verschuiven.",
  "t.41geiggv4v": "Notch en bandfilter in PSK, RTTY en CW",
  "t.41vdc321co": "“[[qmap.center]]” (in kHz): de frequentie in het midden van het stuk, als de bron die niet meldt (TCI stuurt hem vanzelf; bij bestanden wordt hij uit de naam gelezen, bijvoorbeeld …_144100kHz.wav). Zonder midden weet de klik “[[qmap.qso]]” niet waarheen.",
  "t.43lgi9fivi": "Pagina niet gevonden? Typ in het zoekvak bovenaan de boom: alleen de pagina’s die erover gaan blijven over, en een klik brengt je naar het juiste pad. Het zoekvak vindt ook losse instellingen.",
  "t.45gnuryeym": "Netwerkcontrole voor de telefoon",
  "t.46gzysibvy": "Bij de rij “[[ctl.skip_tx1]]” is, als die actief is, Tx1 doorgestreept; in Hound staat Tx6 (CQ) uit. Onder de berichten kan een korte melding verschijnen als een opdracht is mislukt.",
  "t.46p77ysual": "Eén klik op “[[stop.button]] (Esc)” stopt het zenden meteen en het label gaat terug naar RX. De Esc-toets stopt het ook en schakelt [[ctl.enable_tx]] uit, als “[[gen.escStop]]” aan staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]].",
  "t.46razahyii": "Onderaan staat de statusbalk: RX/TX, Sq, AFC, Lock, Snap, de audiofrequentie, de modusgegevens en de signaalmetingen.",
  "t.47ltj8m9w8": "Kies in Instellingen › Station › Radio, onder «Besturingssysteem», «Geen (geen CAT, met de hand afstemmen)».",
  "t.4apjb8pkys": "“[[contest.settings]]” opent de contestinstellingen, met de berichtkeuzelijst (de activiteit), het CQ-woord, de vaste exchange, het eerste serienummer, de modus, het vermogen, de bonuspunten, Hold Tx Freq en RRR, en de Cabrillo-gegevens (contestroepnaam, locator, antenne, club, naam, e-mail, adres, soapbox, tijdcategorie en extra categorie). De waarden zijn die welke Aurora voor de contest heeft voorbereid; je slaat ze op met “[[contest.set.save]]”. Dezelfde onderdelen staan in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].",
  "t.4dwq6n0ocv": "Markeringen op de rij: een rode strook aan de rechterrand (de markering) en een gemarkeerde achtergrond = dat station roept jou; de strook (en de roepnaam) wordt paars = het heeft jou geantwoord; doorgestreepte rij = station al gewerkt op deze band en in deze modus (hoe je dat markeert — doorgestreept, onderstreept, gekleurd, verborgen — kies je in [[sw.tab.colors]]); het station dat je roept is gemarkeerd en blijft bovenaan vast staan, met een kleur die bij elk van zijn antwoorden verandert (rapport, R+rapport, afsluiting); de paarse filterrij = roepnaam, prefix of land gekozen in “[[fil.highlight]]”; een bijzondere achtergrond = station van je zoeklijst; de blauwe stip met een getal = in de wachtrij.",
  "t.4f4wvxrufg": "Met een contest aan toont de balk: de fase (“Begint over …”, de tijd tot het einde, “[[contest.phase.finito]]” of “[[contest.phase.sempre]]”), “[[contest.qso]]”, “[[contest.mult]]”, “[[contest.score]]”, “[[contest.rate10]]” en “[[contest.rate60]]” (QSO’s per uur), “[[contest.forecast]]” (de score als je dit tempo volhoudt), “[[contest.sent]]”, de categorietegel (klik: kies categorie, operators, vermogen, assistentie of Field Day-zenders) en “[[contest.hours]]”. Is de band of de modus niet toegestaan, dan verschijnt er een rode waarschuwing.",
  "t.4f9gqij7sj": "Instellingen: Logboek, cluster en diensten",
  "t.4fconwndvm": "[[sw.sec.sstv]]: drie pagina’s, [[sw.pg.rx]], [[sw.pg.tx]] en [[sw.pg.images]]. Ze delen één concept: wijzigingen gaan door met “[[sw.save]]” onderaan het venster, en een onderdeel dat is gewijzigd maar nog niet opgeslagen heeft het gele teken. De uitzondering is “[[sstv.rx.smooth]]”, dat meteen werkt.",
  "t.4ftp1elns5": "[[auto.b3]] · [[auto.window]], [[auto.windowFrom]], [[auto.windowTo]] (een vakje en twee tijdvelden, standaard uit, dan 08:00 en 22:00): met het vakje aan antwoordt en roept Aurora CQ alleen binnen het venster, in de lokale tijd van de pc; daarbuiten blijft het aan maar doet het niets, en het logboek meldt wanneer het weggaat en wanneer het terugkomt. Het venster kan over middernacht gaan (bijvoorbeeld 22:00–06:00). De twee tijdvelden kun je alleen bewerken als het vakje aan staat.",
  "t.4gw8f3x40x": "[[sup.privacy]]",
  "t.4h0fnwsgiq": "[[phone.cq]]: vraagt om een CQ (“[[tx.cqAsked]]” verschijnt). Grijs als zenden niet is toegestaan.",
  "t.4hso343o5x": "[[cat.detect]] (alleen Hamlib): leest wat het systeem al weet (poortnamen, USB-identiteit, geluidskaarten) en stelt de gevonden radio’s voor in “[[cat.detected]]”, elk met zijn betrouwbaarheidspercentage en de reden. Het opent geen poort en stuurt geen opdracht naar de radio. “[[cat.detected.use]]” zet model, poort en snelheid in de velden (daarna gaan ze vanzelf in); waar “[[cat.detected.manual]]” staat, kies je het model zelf. Gebruik het als je poort en snelheid niet weet.",
  "t.4lot4bn2bh": "Zet [[ctl.filter]] uit: als het aan staat decodeert het alleen van 60 Hz onder tot 110 Hz boven Rx. Als het aan staat is de waterval aan de zijkanten donker.",
  "t.4lxg5dg113": "Op een smal scherm wordt de pagina Station een compacte afstandsbediening.",
  "t.4m7cw41z8w": "[[fil.grp.rx]] · [[list.bottom]]: zoals het selectievakje van [[panel.all]] maar voor het venster [[rxw.title]]; standaard uit. Aan staan de nieuwe berichten van het venster onderaan.",
  "t.4ni331k4ay": "Met een SDR die TCI heeft (SunSDR met ExpertSDR, ANAN met Thetis) is één verbinding genoeg: commando's en audio lopen via TCI, zonder virtuele audiokabels.",
  "t.4og0qlfga5": "Hetzelfde logboek mag de QSO maar via één route ontvangen: WSJT-X-stream met QSO Logged, Logged ADIF, ADIF via UDP, N1MM XML of TCP. Komt hij via twee routes binnen, dan verschijnen de QSO’s dubbel.",
  "t.4p6twbl9hj": "Zolang automatisch CQ aan staat, verandert de toets die het bedient (standaard F1) van uiterlijk, zodat je meteen ziet dat hij herhaalt.",
  "t.4pnpzkutem": "Tabblad “[[contest.training]]”: een simulator (zie “Contest: kalender, training en analyse”). Tabblad “[[contest.analysis]]”: de terugblik na de contest.",
  "t.4reeptdrpb": "Telefoon: de pagina “[[pair.title]]”",
  "t.4ry3petuai": "Alleen met Hamlib en een seriële poort: [[cat.databits]] en [[cat.stopbits]] (normaal “[[cat.default]]”: verander ze alleen als de handleiding van de radio iets anders zegt; veel Yaesu’s, zoals de FT-2000, willen 8 bits en 2 stopbits), [[cat.handshake]] (“[[cat.handshake.none]]”, “[[cat.handshake.xonxoff]]” of “[[cat.handshake.hardware]]”: veel Yaesu’s willen hardware), [[cat.dtr]] en [[cat.rts]] (“[[cat.line.auto]]” houdt de lijn laag bij het openen, omdat veel interfaces die lijn op de PTT hebben aangesloten; “[[cat.line.high]]” of “[[cat.line.low]]” alleen voor bijzondere interfaces).",
  "t.4sbogacpvm": "Na «Bijwerken» downloadt Aurora de nieuwe versie, sluit samen met de agent in het systeemvak, installeert en start maar één keer opnieuw op als de installatie klaar is. Twee snelle verzoeken starten niet meer twee installatieprogramma’s.",
  "t.4slj7qmi37": "Via UDP gaat een QSO naar een gesloten log verloren: er is geen bevestiging. Met “[[int.resend]]” kijkt Aurora of het log op deze pc open is; is het gesloten, dan houdt Aurora de QSO apart en stuurt die zelf zodra het log weer open is. Geldt voor alle logs die “[[int.adif]]” of “[[int.n1mm]]” ontvangen: Log4OM, HRD Logbook, WaveLogGate en de andere.",
  "t.4tf523r1oa": "Geen spots in het clusterpaneel.",
  "t.4tr0ifeslh": "Het menu [[digi.menu.mode]]",
  "t.4ukipd4mig": "Het venster om een QSO te corrigeren of te verwijderen",
  "t.4vj39tx6rx": "[[lay.notes]]: vak met de algemene uitleg. De wijzigingen op deze pagina worden na een korte pauze en bij het verlaten van de pagina vanzelf opgeslagen, zonder ergens op te drukken. De klokindicator bovenaan ([[clock.pill]]) en de gele waarschuwing worden uitgelegd in het Guide-onderdeel “De klok”.",
  "t.4vsfmv4swt": "Eén knop verzamelt logboeken, crashrapporten en instellingen in een zipbestand op het Bureaublad, zonder wachtwoorden.",
  "t.4xrwituegp": "In [[tab.sequence]], vak [[gen2.wsjtx3]]: zet bij een full-duplex satellietradio [[gen2.fullDuplex]] aan: dan zie je ook je eigen downlink. Uit wordt de periode waarin je zendt niet gedecodeerd.",
  "t.4yx14xyg01": "[[not2.grpAlerts]] · [[not2.popPos]]: waar de kaart verschijnt: boven of onder, links, midden of rechts (zes posities: de vier hoeken, plus midden boven en midden onder; standaard rechtsboven). Wijzig het als de kaart iets bedekt wat je nodig hebt.",
  "t.51pxldzaet": "[[lay.settings]] · [[upd.enabled]]: vakje, standaard aan. Aurora controleert zelf of er een nieuwe versie is en biedt hem aan; het installeert niets tenzij je erom vraagt. Wanneer uitzetten: als de pc hiervoor niet online mag, of als je zelf wilt bepalen wanneer je kijkt (de knop “[[upd.check]]” blijft).",
  "t.53aupnmtnd": "Voor een contest of als niemand je decodeert: druk op “[[clock.check]]”. Is de afwijking groter dan een halve seconde, corrigeer dan de klok (Windows: “[[clock.correct]]” als administrator, of synchroniseer via de Windows-instellingen).",
  "t.53hpka5dpm": "Alle geluiden tegelijk: zet “[[alert.button]]” uit, het eerste vakje van [[sw.pg.alerts]] (het is ook het luidsprekerpictogram rechtsonder, naast de UTC-klok, met het volume). Als het uit staat, speelt Aurora uit zichzelf niets af; de testknop ▶ werkt altijd. Standaard staat het uit.",
  "t.566chr7ra3": "De pagina [[nav.sat]] (titel “[[sat.title]]”) heeft bovenaan de kaart en eronder de vakken. Hoe je haar instelt, staat bij “Satellieten: overvluchten, Doppler en rotor”. Zonder je locator zegt de pagina “[[sat.noObserver]]”.",
  "t.56i4ptld28": "[[sw.tab.audio]]",
  "t.56v2d7rakm": "[[phone.stop]] (wordt “[[stop.button]]” tijdens het zenden): stopt het zenden meteen en zet de automatiseringen uit, altijd actief en zonder bevestiging. Twee tikken achter elkaar (binnen 0,7 seconden) maken ook het station vrij dat wordt geroepen, zoals de dubbele Esc op de pc.",
  "t.5844d68gu": "[[tab.dxcc]]",
  "t.59s1oakaaf": "Druk op “Start UDP”: standaard luistert de server op 127.0.0.1, poort 50001.",
  "t.5bjbtfy6hk": "Voeg teksten en vormen toe (“[[sstv.add.text]]”) of een sjabloon uit “[[sstv.tpl.title]]”: {MYCALL}, {CALL}, {RST}, {GRID}, {DATE} worden vanzelf ingevuld. Elke laag verplaatst, schaalt en draait met zijn handvatten.",
  "t.5bk8rvlrzd": "Volledig onderdeel: «De geluidskaart»; «De Pwr-schuif»; «[[sw.tab.audio]]»; «Hij zendt maar het vermogen is nul».",
  "t.5daziufif6": "Het tabblad “Kaart” van het logboekpaneel volgt altijd de gebruikte band en heeft één rij met bedieningselementen: Lijnen, Wie roept wie, Alleen wie mij hoort, Roepnamen. Al het andere stel je in op de DX-kaartpagina. Als een QSO wordt gelogd, schakelt het paneel vanzelf naar het Logboek (of Intern logboek), toont de nieuwe rij en gaat terug naar de Kaart.",
  "t.5gcz3cqurm": "[[digi.mi.modeSettings]]: opent de Instellingen op de pagina “[[sw.pg.digiRxTx]]” (zoals in [[digi.menu.configure]]).",
  "t.5h1hm9np26": "Het antwoordt niemand: controleer of het aan staat ([[auto.turnOn]]), of de mode [[auto.modeLive]] is (in [[auto.modeDry]] zendt het nooit), of [[ctl.enable_tx]] niet met de hand is uitgezet, of [[auto.outWindow]] niet verschijnt en of er geen rood blok in het [[auto.log]] staat.",
  "t.5hvm15e3ho": "Het laatste segment, “[[autoSwitch.off]]”, zet de Automatiseringen aan of uit zonder de Instellingen te openen. Groen: Automatiseringen in live-modus (ze antwoorden vanzelf en Enable Tx gaat aan). Oranje: proefrun (ze beslissen en schrijven in het log maar zenden niet). Grijs: uit. Als het uit staat en zenden is toegestaan, vraagt een klik of je naar live-modus wilt schakelen (Ja = live, Nee = proefrun); na je bevestiging zetten de volgende klikken ze aan en uit zonder vragen. De regels staan in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (zie “Automatische antwoorden”).",
  "t.5i15q5m1c0": "Het zenden stopt vanzelf na een paar minuten: dat is de [[gen2.watchdog]]; verhoog de minuten of zet hem op 0.",
  "t.5i79ui7nsx": "[[sw.sec.log]]",
  "t.5isz5yv3zr": "[[not2.grpTable]] · [[not2.colKind]]: één rij per nieuwtje: “[[not2.n.cqz]]”, “[[not2.n.itu]]”, “[[not2.n.dxcc]]”, “[[not2.n.grid]]”, “[[not2.n.px]]”, “[[not2.n.call]]” en aan het eind “[[not2.n.worked]]”. De naam heeft een “?” die het nieuwtje uitlegt.",
  "t.5jynxokwi": "Het blok [[bands.title]] van de pagina Station vertelt welke banden open zijn en wie jou hoort. Het heeft de onlinediensten nodig: als die uit staan, zegt het blok dat en leidt de knop “[[prop.settings]]” naar [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], waar je propagatie en PSK Reporter aanzet.",
  "t.5m3sdjc0r": "Q65-30A kies je in de modusschakelaar: periodes van 30 s (even en oneven), berichten in FT8-stijl (ook RR73), 65 tonen over ongeveer 217 Hz. Het is gevoeliger dan FT8 en geschikt voor 6 m en 2 m: de frequenties zijn 50,275 en 144,180 MHz, met de EME-frequenties in de frequentielijst.",
  "t.5peakirobp": "[[rep.title]] · [[rep.auto]]: vakje, standaard aan. Bij elke ernstige fout wordt vanzelf een kort anoniem rapport verstuurd (identieke fouten hoogstens één keer per uur, en er is een daglimiet). Als je het uitzet, wordt er niets verstuurd en wordt de wachtrij geleegd. Onder het vak staat een regel met hoeveel rapporten er wachten en hoeveel er vandaag al zijn verstuurd (alleen met het vakje aan).",
  "t.5s7xymi4qb": "[[sw.p.operator]] · [[sw.p.surname]] en [[sw.p.email]] (optioneel): ze blijven hier op deze pc bewaard en worden niet verzonden. Vul ze alleen in als je dat handig vindt.",
  "t.5vmema00gg": "De split schakelt zichzelf niet meer in",
  "t.5vw53tjgnw": "In [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] kies je welke nieuwtjes Aurora in de lijsten (Bandactiviteit, RX-venster) markeert en met welke kleuren. Dit is het eerste deel: de tabel met nieuwtjes en het “al gewerkt”. De vakjes in de tabel zijn engine-items: ze gelden met “[[sw.save]]” onderaan; de andere op deze pagina gelden meteen. Met een externe engine (JTDX) toont de pagina in plaats daarvan één tabel met kleur, markering en geluid per type.",
  "t.5vxf2cs3po": "[[sw.tab.autocq]]",
  "t.5y21s74qhh": "[[digi.ms.receive]] · [[digi.freq.rx]]: de audiofrequentie waarop de ontvanger luistert, van 200 tot 3500 Hz (fabriekswaarde 1000). Typ het getal en verlaat het veld; valt het buiten het bereik, dan komt de vorige waarde terug. Verander het als je naar een ander signaal wilt luisteren.",
  "t.5y8wwgd4me": "Deze gegevens komen alleen binnen met “[[cat.extras]]” aan (met Hamlib). Staat het uit, dan zegt het uitgebreide display dat.",
  "t.5zif2xo3cx": "De macrobalk wordt langer of korter door aan de rechterrand te slepen (de dunne lijn ernaast); een dubbelklik op de lijn herstelt het beginformaat.",
  "t.5zj325q98c": "Instellingen: Uiterlijk en meldingen",
  "t.61olh4f8ap": "De knop “RX” in de tabbladen van het paneel Log (naast “[[log.tab.log]]” en “[[log.tab.map]]”) zet het RX-venster aan en uit: als het uit staat, neemt het paneel Log alle ruimte in. Je keuze blijft bewaard.",
  "t.61wrjax8vy": "Je roepnaam en locator ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]) en de radiofrequentie via CAT zijn nodig. Het lampje in het vak toont hoe de laatste verzending ging; antwoordt WSPRnet niet, dan wordt het hoogstens een uur opnieuw geprobeerd. De pagina toont ook hoeveel verzendingen nog wachten, inclusief de lopende.",
  "t.64k0z9tvzw": "Het gele label “DX” met roepnaam, locator, vlag en land is het station dat je roept; zonder station staat er een streepje.",
  "t.64yjq7sg1i": "PTT alleen via RTS of DTR, zonder CAT: kies het Hamlib-model “Dummy” en geef de poort op in [[cat.port]]; kies dan in het vak [[cat.grp.ptt]] RTS of DTR.",
  "t.658fqstg8w": "Om terug te gaan, of op een andere pc: “[[bak.restore]]”, kies het zipbestand, sluit dan Aurora af via het systeemvak en open het opnieuw.",
  "t.6839g5vffi": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] → “[[int.title]]”: voeg de bestemming van het log toe of open die, met adres 127.0.0.1 en de poort waarop het log luistert.",
  "t.68o80n33zg": "De rijen van Bandactiviteit en van het RX-venster hebben dezelfde markeringen. Bijna elke kleur heeft een hint: beweeg de muis over de rij.",
  "t.6acv079pks": "Op Windows 10-versies ouder dan 2004 ging het programma niet open: nu start het gewoon.",
  "t.6eh9mk1rf1": "Als “[[not2.unconfirmed]]” (of “[[not2.unconfirmedGrid]]”) aan staat, hebben in de lijst Bandactiviteit de rijen die alleen nieuw zijn omdat ze niet bevestigd zijn dezelfde kleur als de nieuwe, maar lichter en gestreept; echt nieuwe blijven egaal gekleurd. Het voorbeeld in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] toont het verschil.",
  "t.6g8k1mp32h": "Het venster “[[cop.title]]”",
  "t.6gubpzi4od": "Updates zonder haperingen en WebView2",
  "t.6ic5d7r7k2": "Slechts één venster wissen: druk in de titelbalk van Bandactiviteit en van het RX-venster op “[[list.clear]]”. Dit wist alleen dat venster, nieuwe berichten verschijnen weer.",
  "t.6if3zsih4t": "FT8-vensters: periodescheiding en Tx in de QSO",
  "t.6m74ymojqa": "Contest: de balk en de tabbladen",
  "t.6mg9gb24dv": "[[tab.bands]] · [[bands.all]]: zet de lijst terug op de beginstand, banden van 160 m tot 2 m (ondanks de naam zet het de zeldzame banden niet ook aan: die zet je een voor een aan).",
  "t.6ozcdlxpxt": "Aurora stuurt elke QSO maar één keer naar de logprogramma’s en de online diensten, op het moment dat hij gelogd wordt. Was het logboek gesloten of lag het netwerk plat, dan komt de QSO misschien niet aan. Er is geen knop “opnieuw sturen” voor QSO’s die al in het logboek staan; dit kun je doen.",
  "t.6p3tat9qbw": "[[ca.station]]: “[[ca.station.ok]]” als roepletters en locator zijn ingesteld; “[[ca.station.bad]]” als er een ontbreekt. De link “[[diag.fix]]” leidt naar de pagina met persoonlijke gegevens.",
  "t.6qno0ail04": "[[fil.decode]] · [[dec.depth]]: keuzelijst met [[dec.depth1]], [[dec.depth2]] en [[dec.depth3]] (fabrieksinstelling). Het geldt voor FT8, FT4, JT65, JT9 en MSK144; Q65 gebruikt altijd de diepe zoekmodus. Hoe dieper, hoe meer zwakke berichten je vindt, maar hoe harder de processor werkt: ga naar [[dec.depth1]] als de pc traag is of het decoderen niet op tijd klaar is.",
  "t.6tqy24ukgf": "DX-kaart: band, lijnen en roepnamen",
  "t.6uih8tcruq": "Hoe QSO’s worden gelogd",
  "t.6yip7mrxjd": "“[[sstv.rx.stop]]” zet het SSTV-luisteren uit (FT8 blijft ongemoeid) en wordt “[[sstv.rx.start]]”; luisteren dat uit staat, blijft uit tot je het weer aanzet.",
  "t.70756ntvu4": "Station-pagina, indicator “[[rxl.title]]”: de balk links toont het niveau van het audiosignaal van de radio en de schuifregelaar ernaast is “[[rxl.volume]]”. Onder de balk staat een label dat zegt hoe het gaat: [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] of [[rxl.state.overdrive]]. Het doel is “[[rxl.state.good]]”. Is het laag, zet de regelaar dan hoger; is het oversatureerd, zet hem dan lager (of verlaag het audioniveau op de radio). De indicator verschijnt alleen terwijl de audio-ingang ontvangt.",
  "t.74jvtmcft1": "Het paneel “[[digi.band.title]]”",
  "t.75rxy2xre8": "Beelden in SSTV",
  "t.77ddadg6r1": "Luisteraars (SWL) krijgen met «Log QSO» nu het invoervenster al ingevuld met het DX-station, in plaats van een melding zonder opslag. «Aanzetten» werkt nu ook met Cat4OM en met Yaesu-radio’s (RTS hoog tijdens het aanzetten).",
  "t.77g5az7xo0": "Onder de waterval heeft de smalle liniaal elke 100 Hz een streepje (elke 500 een getal), twee haken voor Tx (oranje) en Rx (groen) en een teken voor elk bericht van de laatste periode.",
  "t.77lakfdx0x": "Wat wordt verzonden: versie van Aurora en Windows, engine, radiomodel, PTT, CAT-backend, naam van de geluidskaart, probleemgebied, opgeschoonde foutmelding en hoe vaak het gebeurde; na een crash ook het opgeschoonde logboek en de crashtekstrapporten.",
  "t.77tjno1seh": "[[aud.mode]] · [[aud.dir]]: de map waar de audiobestanden terechtkomen (namen als yymmdd_hhmmss.wav). Leeg (standaard) = de map “save” in de gegevens van Aurora, in grijs in het vak getoond. Vul het alleen in als je de bestanden op een andere schijf wilt; een map buiten de gegevens van Aurora die van andere programma’s is overgebleven telt niet mee en wordt niet getoond.",
  "t.78hj5bkf0t": "“[[dxs.preview]]”: de kaart met voorbeeldgegevens (roepletters IU3ABC), die meteen verandert bij elke keuze hieronder, zodat je het resultaat ziet voordat je teruggaat naar het logboek.",
  "t.78x1ik4zg6": "De DX Cluster is leeg",
  "t.79v58u75ag": "Als bovenaan “[[set.loadError]]” verschijnt, reageert Aurora niet: controleer of de engine aan staat.",
  "t.7ak4ukn88c": "Welk geluid bij welke gebeurtenis (oproep aan mij, nieuwe DXCC, QSO gelogd…), de stem en je eigen WAV- of MP3-bestanden, stilte terwijl je zendt: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (zie “Geluiden” en “Stem en eigen bestanden voor meldingen”). De pop-upmeldingen staan in “Pop-upberichten”.",
  "t.7glesm887j": "[[digi.mi.seekLeft]] en [[digi.mi.seekRight]]: verplaatsen de ontvangst naar het volgende signaal links of rechts, tussen 300 en 3300 Hz. Wordt er geen gevonden, dan verschijnt “[[digi.run.seekNone]]”; met luisteren uit, “[[digi.run.noSpectrum]]”.",
  "t.7husjuoul4": "Icom: 115200, PTT CAT, CI-V 0; in de radio CI-V USB Port “Unlink from [REMOTE]”, Echo Back OFF, DATA MOD USB. Yaesu: 38400, CAT RTS OFF. Kenwood: 115200, DATA VOX OFF.",
  "t.7k4bb02na5": "“[[lay.settings]]” · “[[cluster.enabled]]” (standaard aan): aan verbindt Aurora met de gekozen servers zodra er roepletters van het station zijn; uit verbindt hij met geen enkele en blijft het paneel DX Cluster leeg.",
  "t.7noy6nyclb": "Aurora installeren",
  "t.7ojn5qkjfw": "Pad: [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]]. De DXCC-kaart (onder het logboek, op de pagina [[nav.station]]) vertelt je, voor het station dat je roept, of zijn land nieuw is en op welke banden en modes je het al hebt gewerkt. Hier kies je wat hij toont en met welke kleuren. Keuzes gelden meteen, blijven op dit apparaat bewaard na een herstart en gaan niet via “[[sw.save]]”. De gegevens komen uit het interne logboek van Aurora en uit gekoppelde logprogramma’s (bijvoorbeeld Log4OM). Volgorde op het scherm: “[[dxs.guide.title]]”, “[[dxs.preview]]”, “[[dxs.look]]”, “[[dxs.rows]]”, “[[dxs.bands]]”, “[[dxs.colors]]”.",
  "t.7q1u47oqs4": "Laat Aurora de radio besturen: frequentie, mode en zenden.",
  "t.7qnhr3i66n": "Een losgemaakt paneel zie je niet meer in het hoofdvenster; waar nodig blijft er een melding staan (“[[win.elsewhere]]”) en de panelen ernaast worden vanzelf breder om de ruimte te vullen. Zet je ze allemaal terug, dan komt de gewone pagina terug.",
  "t.7qw8hdnyii": "“[[pair.name]]”: een naam om het apparaat te herkennen in de lijst met gekoppelde apparaten (van 1 tot 64 tekens). Daarna “[[pair.button]]”.",
  "t.7t4yfoafpu": "Contest: kalender, training en analyse",
  "t.7t8f9gxw4m": "[[cat.profile.new]]: maakt een NIEUW profiel met de basisinstellingen (alleen het gekozen besturingssysteem blijft behouden: al het andere, poort en model inbegrepen, begint opnieuw) en maakt het het profiel in gebruik; de verbinding met de radio wordt verbroken. Is het naamveld leeg of bestaat er al een profiel met die naam, dan stelt Aurora een vrije naam voor. Stel daarna de nieuwe radio in op de pagina [[sw.pg.radio]].",
  "t.7wh43tryrj": "Kleuren van de rijen: de band waarop je staat is gemarkeerd; een andere achtergrond voor de stations van de zoeklijst en voor de DXpedities in de lucht volgens NG3K (de kleur kies je in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).",
  "t.7zbip0uwcg": "[[sdr.radios]]: een tekstvak met de geschikte radio’s (TCI: SunSDR2, ColibriNANO met ExpertSDR2/3, ANAN en Hermes-Lite 2 met Thetis; QMAP heeft ook de I/Q-stroom van TCI of een I/Q-WAV-bestand nodig) en twee knoppen, [[sdr.guideTci]] en [[sdr.guideQmap]], die de Guide-onderdelen over TCI en QMAP openen (staan de Instellingen in een apart venster, dan opent de Guide in het hoofdvenster en verschijnt “[[sdr.opened]]”).",
  "t.81rjwcggbr": "QMAP: alle opdrachten",
  "t.82rtrixm2i": "De knop RX/TX (of de toets Pause) opent de uitzending en houdt die aan: zonder tekst stuurt RTTY het wachtsignaal. Wat je in het zendvenster typt, gaat de lucht in terwijl je typt; druk opnieuw op RX/TX of Pause en zodra de al getypte tekst verzonden is, ga je terug naar ontvangst. Esc stopt meteen.",
  "t.83xmrihth": "Er verscheen geen kaart: wie “Uit” of “Alleen pictogram” koos, is dit normaal; tijdens “Niet storen” komt er geen enkele. Kaarten verschijnen alleen als Aurora gesloten is: met Aurora open toont Aurora zelf de meldingen in zijn venster. De agent schrijft een klein logboek in %TEMP%\\aurora-agente.log, handig voor wie je helpt.",
  "t.864ykzvw51": "De pagina [[nav.propagation]] (titel “[[prop.title]]”) toont links de omstandigheden van de zon en de banden, rechts de kaart en de lijst van wie jou heeft ontvangen. Hij heeft de online diensten nodig; staan die uit, dan zegt de pagina dat met de knop “[[prop.settings]]” (je zet ze aan in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). Bovenaan vraagt de knop “[[prop.refresh]]” meteen om nieuwe gegevens in plaats van de 10 seconden af te wachten.",
  "t.893l0gpyf5": "Typ in het vak “[[fil.highlight]]” roepnamen, prefixen of landen: hun rijen worden paars. “[[fil.bypass]]” toont een tijdje alles zonder de filters kwijt te raken.",
  "t.89j2ekcpth": "Volledig onderdeel: volledige uitleg: «Meldingen uitzetten of aanpassen: gemarkeerde kaarten, geluiden, kleuren, berichten»; voor de kleuren «[[sw.tab.colors]]».",
  "t.8hefxikt8f": "De CW-decodering van de hele band gebruikt ongeveer 40% minder CPU, met identieke resultaten. Ook het opnieuw bemonsteren van de audio door de engine kost 20 keer minder.",
  "t.8hsl3gdylv": "Het paneel Log heeft drie tabbladen in de titelbalk: “[[log.tab.log]]” (of “[[log.tab.internal]]” als er geen extern logboek is), “[[log.tab.map]]” en “RX” (het RX-venster). In de balk, rechts, het totaal aantal QSO’s (“n QSOs”).",
  "t.8iair2nbfn": "[[panel.cq]] en DXpedities",
  "t.8ky5022i6j": "[[cat.civ]]: verschijnt alleen met Hamlib, een seriële poort en een Icom-radio (of als de waarde niet 0 is). Hij moet DECIMAAL worden geschreven en meestal op 0 blijven (= het fabrieksadres van het model). Hoe je hem omrekent en de meest gemaakte fouten staan in een eigen onderdeel.",
  "t.8l8nb6e2zc": "De bovenbalk: modi",
  "t.8lc8xmywjv": "[[auto.b1]] · vakjes voor nieuwigheden: [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_zone]], [[kind.new_call]], [[kind.new_call_band]]. Aurora beantwoordt alleen CQ's die een van de aangevinkte nieuwigheden opleveren; gewone CQ's zijn nooit genoeg. Standaard staan deze aan: [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]] en [[kind.new_grid]] (nieuw land, DXCC op een nieuwe band of mode, CQ-zone, nieuw grid); vink ook de andere aan als nieuwe stations je interesseren.",
  "t.8nx29ewr2p": "“[[rep.sendBundle]]” uploadt het pakket zonder persoonlijke gegevens en toont een code: geef die door aan wie je helpt, zodat die het kan terugvinden.",
  "t.8ojezq0kub": "Verbind na een update de programma’s die de radio via Aurora gebruiken opnieuw. Wat er veranderd is, staat in [[nav.news]]. Dezelfde nieuwe versie zie je ook in de kop (zie “De kopbalk en de poster”).",
  "t.8rykxs8cxp": "[[ctl.stop_rx]]: stopt de ontvangst en de lopende decodering (niet het zenden). [[ctl.decode]]: decodeert meteen de laatst opgenomen periode.",
  "t.8xb25moa08": "Terwijl je zendt, schakelen de pillen “FT8” en “VHF” niet van groep: zweef erboven en je leest “[[mode.locked]]”. Wacht tot het einde van de periode of stop het zenden met STOP TX.",
  "t.8xs9yiu4ax": "“[[contest.map]]”: voor de band die in de tabbladen is gekozen, de multipliers die je al hebt gewerkt, de nieuwe die je nu kunt horen (oranje) en die je hoort maar al hebt (uit de decodes van de laatste 15 minuten). Een klik op een vakje of op een roepnaam roept het station. Heeft de contest geen multipliers, dan zegt hij “[[contest.noMult]]”.",
  "t.8zenfk21dm": "Lampje van elke dienst (cirkel voor de naam): het zegt “[[ens.led.off]]”, “[[ens.led.untested]]”, “[[ens.led.ok]]” of “[[ens.led.err]]”; beweeg erover voor de reden. De “?” naast de naam legt de dienst uit. De schakelaar van de dienst heet “[[ens.svc.on]]”; de “?” ernaast zegt wat hij doet.",
  "t.90xgkxizz2": "Stem de radio af op een PSK31-frequentie (bijvoorbeeld 14.070 MHz USB) of RTTY (14.080 MHz) en open [[nav.textModes]]: het luisteren start vanzelf als je de pagina opent en stopt als je hem verlaat, tenzij “[[digi.autoReceive]]” aanstaat in de Instellingen. Via [[digi.menu.options]] › [[digi.mi.listen]] stop en herstart je het. Kies de modus in het menu [[digi.menu.mode]] en breng de afstemming op het signaal met een klik op de waterval: de tekst verschijnt in het ontvangstvenster.",
  "t.917qkm25ir": "“[[lay.lists]]” · “[[wish.calls]]” en “[[wish.prefixes]]” (vier tekstvakken, één item per regel, maximaal 200 per lijst): bij “[[wish.calls]]” de roepletters, bijvoorbeeld 3Y0J (ook geldig met achtervoegsel, K1ABC/P, of voorvoegsel, F/K1ABC); bij “[[wish.prefixes]]” het begin van de roepletters, bijvoorbeeld VP8, ZL9 of 3Y, handig voor expedities. Alleen letters, cijfers en schuine streep, geen spaties.",
  "t.92sck5hajn": "Op de pc is er geen knop “CQ”: klik in het paneel [[panel.tx]] op de zesde rij (“[[tx.step.6]]”) en zet [[ctl.enable_tx]] aan; op de telefoon is de knop “[[phone.cq]]” genoeg. Wie antwoordt, wordt automatisch afgehandeld (zie “CQ roepen vanaf de pagina Station”).",
  "t.937b96y30u": "[[digi.edit.title]] · [[digi.edit.subset]]: de uitklaplijst filtert de commandolijst per groep ([[digi.edit.group.all]], [[digi.edit.group.text]], [[digi.edit.group.program]], [[digi.edit.group.frequency]], [[digi.edit.group.autocq]], [[digi.edit.group.macros]], [[digi.edit.group.mode]], [[digi.edit.group.rotor]], [[digi.edit.group.rtty]], [[digi.edit.group.sstv]], [[digi.edit.group.cw]], [[digi.edit.group.hell]]). Eronder staat de lijst: één klik kiest een commando en toont de uitleg, een dubbelklik voegt het in; die met “[[digi.edit.soon]]” zijn gepland maar nog niet actief.",
  "t.93o8nisihm": "BBLogger: QSO’s uit het ADIF-bestand van Aurora",
  "t.93swe6ydkk": "Zet “[[rot.set.enabled]]” aan: de status wordt “[[rot.state.connected]]” en Aurora blijft ook bij de volgende starts verbonden.",
  "t.93uty182p7": "“[[sstv.rx.mode]]” (de keuzelijst) en “[[sstv.rx.force]]”: om een modus af te dwingen zonder op de VIS te wachten ([[sstv.rx.forceHint]]). De keuzelijst begint bij de modus die in “[[sstv.rx.lock]]” in de SSTV-instellingen is gekozen (of bij die welke voor het zenden wordt voorgesteld).",
  "t.94qchg6es7": "Al je QSO’s, doorzoekbaar op roepnaam, data, band en modus: kies degene die je wilt en sla ze op in een ADIF-bestand met “Save ADIF…”.",
  "t.957ettm5zf": "Volledig onderdeel: «Foutrapporten»; «Foutrapporten: wat er wordt verstuurd en hoe je ze uitzet»; «Het log sturen naar wie je helpt».",
  "t.95v4sifku3": "Alleen foutrapporten zonder persoonsgegevens, en alleen als de vakjes aangevinkt zijn (standaard zijn ze dat). Zet ze uit in [[nav.settings]] › [[sw.sec.access]] › [[tab.support]].",
  "t.96w8hg93nm": "Dubbelklik op een rij van het interne logboek: het venster om het QSO te corrigeren of te verwijderen opent (zie “Een QSO corrigeren of verwijderen”). In het logboek van Log4OM2 lees je “[[log.readonly4om]]”.",
  "t.96xzk0is4d": "Onzintekst bij RTTY: controleer [[digi.rtty.shift]] en [[digi.rtty.baud]] (ze moeten die van het station zijn) en probeer [[digi.rtty.reverse]].",
  "t.97umn1xrzs": "[[gen2.logFilter]] · [[gen2.fromDate]] (tekstveld, standaard leeg): telt alleen de QSO’s vanaf die datum en tijd, in het formaat JJJJMMDDUUMMSS (bijvoorbeeld 20260101 om opnieuw te beginnen vanaf 1 januari; ontbrekende cijfers tellen als nul). Leeg = het hele log telt. Handig om opnieuw te beginnen voor een diploma of een nieuwe locatie zonder het log te wissen.",
  "t.98zyavxb98": "[[nav.settings]] › [[sw.tab.info]]. Het is de presentatiepagina van Aurora, onderaan de instellingenboom en buiten de families. Hij heeft geen vakjes of velden om in te stellen: je leest hem en er zijn links.",
  "t.999zccnqgw": "Open [[nav.log]] in het menu bovenaan en zoek de QSO: typ de roepnaam in het zoekveld of filter op datums, band en mode.",
  "t.9aem6g1d7c": "“[[rep.active]]”: [[rep.activeTip]]",
  "t.9c02ucdo2": "In de modipagina’s van [[nav.settings]] › [[sw.fam.modes]] ([[sw.sub.ft8]] › [[fil.decode]], [[sw.sub.jt]], [[sw.sub.vhf]]) vind je de decoderopties van WSJT-X, met zijn fabriekswaarden: diepte (Fast, Normal, Deep), enkelvoudig decoderen rond Rx, periode-middeling en automatisch wissen van het gemiddelde voor Q65, a-priori-analyse, deep search en aggressief niveau voor JT65, F Tol voor JT65, JT9, MSK144 en Q65. De meest gebruikte zijn ook knoppen naast de modus: “Avg” en “Auto ⟲” in Q65, “AP” en “Deep” in JT65. Ze gelden vanaf de volgende periode.",
  "t.9c4mamtdlg": "[[rep.title]] · [[rep.id]] en [[rep.newId]]: een willekeurig nummer dat deze installatie in de rapporten identificeert, zonder te zeggen wie je bent. “[[rep.newId]]” maakt een nieuw nummer: eerdere rapporten kunnen niet meer aan deze installatie worden gekoppeld. Wanneer: als je “bij nul wilt beginnen”.",
  "t.9f73n1nfny": "[[snd.title]] · geluidenbank: onderaan het vak staat een keuzelijst “Geluidenbank” met alle geluiden per categorie; een klik op een naam speelt het af (op het gekozen volume) zonder het aan iets toe te wijzen. Het is om rustig te kiezen voordat je het menu van een gebeurtenis gebruikt.",
  "t.9fv2msrwwb": "“[[digi.band.validation]]”: hoe streng Aurora met roepnamen omgaat ([[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]], [[digi.band.valMaximum]]; standaard “Normaal”). Aurora telt hoe de roepnamen van elk land eruitzien (uit het logboek, uit de DX Cluster-spots en uit MASTER.SCP als je dat in de gegevensmap zet) en een roepnaam met een zeldzame vorm moet meerdere keren gehoord zijn voordat hij als geverifieerd telt. Hoger = minder verzonnen roepnamen, maar ze verschijnen later. De wijziging wordt opgeslagen en de knop toont een paar seconden je keuze.",
  "t.9g4dn70ez6": "Test op een kunstantenne: roep CQ en let op de radio.",
  "t.9h6d0x3qgn": "Pas op voor dubbelen: hetzelfde logboek mag de QSO maar via één route ontvangen (WSJT-X-stream met QSO Logged, Logged ADIF, ADIF via UDP of N1MM XML). Als een waarde rood is gemarkeerd, corrigeer die: zolang hij niet geldig is, wordt de lijst niet opgeslagen.",
  "t.9hpqo3h9r0": "[[sstv.set.grpTx]] · [[sstv.set.defaultMode]]: de modus die al is gekozen in de samensteller als je het zenden opent (fabriek Martin 1). Kies degene die je meestal gebruikt; hij kan nog steeds per beeld worden veranderd.",
  "t.9kg79qblm9": "Aurora werkt ook als de radio niet via CAT is verbonden: het decodeert en zendt gewoon, maar je wijzigt de radiofrequentie zelf.",
  "t.9noy5epnzd": "Alternatief: type JT_MESSAGE op de poort van de primaire server, als je ook de status in Log4OM wilt (frequentie, huidige DX). Slechts één van de twee, niet allebei.",
  "t.9pbtgwzcrg": "Meestal hoef je [[ctl.hound]] niet aan te raken: met [[gen2.houndAuto]] aan (standaard) schakelt Aurora Hound in, zodra je de Fox kiest en hoort zenden in Fox/Hound (regels met het label FOX), zet Tx boven 1000 Hz en schakelt [[ctl.split]] in; het schakelt vanzelf uit als het station met normale berichten antwoordt of je een andere DX kiest. De knop [[ctl.hound]] is alleen om het met de hand af te dwingen.",
  "t.9qxdctd8wa": "Modes FST4 en FST4W (baken)",
  "t.9qzmjcgx19": "[[ctl.enable_tx]] en STOP zijn altijd binnen handbereik.",
  "t.9te3twz5oe": "[[gen2.operation]] · [[gen2.swr]] (getalveld, 0 tot 10, standaard 2,5): beveiliging van de antenne. Als de radio tijdens het zenden een SWR boven deze waarde meet, stopt Aurora meteen met zenden en waarschuwt je. 0 = controle uit. Hiervoor is een CAT-verbinding nodig die de SWR van de radio kan lezen; geeft de radio die niet door, dan doet de controle niets.",
  "t.9uzm17xubq": "Netwerkcontrole tijdens het koppelen",
  "t.9wobeehnhq": "Je roepnaam ontbreekt: zonder roepnaam weet Aurora niet welke berichten voor jou zijn. “[[diag.fix]]” opent [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].",
  "t.9ylyeswjgx": "Het bericht gaat uit met een afgeknipt begin: verhoog [[gen2.txDelay]] (0,3 of 0,4).",
  "t.a0gif2icbs": "[[nav.qmap]]: verschijnt alleen in de groep “VHF” en alleen als je “QMAP-pagina in het menu” hebt aangezet in [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. Hij heeft een SDR-ontvanger nodig (zie “QMAP: elk commando”).",
  "t.a1nh4ms5ti": "[[cop.choose]] · [[cop.double]] en [[cop.single]]: kies of je de radio naar het station van de spot brengt met een dubbelklik (fabriek, voorkomt per ongeluk klikken) of dat één klik genoeg is (sneller).",
  "t.a2n5tqidvq": "Oranje balk in de kop: op de pc downloadt Aurora de nieuwe versie, zodra die is gevonden, op de achtergrond en zie je in plaats van het icoon het versienummer met een pijl omlaag, een voortgangsbalk met percentage en resterende seconden, daarna “[[upd.strip.verifying]]” (controle van de handtekening). Als de download klaar is, wordt het “[[upd.strip.ready]]” met de knop “[[upd.strip.install]]” (installeren en herstarten met één klik). Als de download mislukt, verschijnt “[[upd.strip.failed]]” met “[[upd.strip.retry]]”. Een klik op de versie opent het kleine paneel hierboven.",
  "t.a3krvubt7f": "Onder Linux gebruikt Aurora PulseAudio of PipeWire en toont dezelfde apparaten als WSJT-X en JS8Call: kies voor ontvangen de ingang (“alsa_input…”), voor zenden de uitgang (“alsa_output…”). De naam die je in WSJT-X gebruikt kun je ook met de hand intypen.",
  "t.a76c6sw8s3": "De coderegels zijn verborgen; om ze te zien schakel je [[gen2.showOtp]] in in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].",
  "t.a7g7gtp06d": "“＋ [[exp.add]]” opent een formulier voor een QSO die je buiten Aurora hebt gemaakt: [[exp.f.call]], [[exp.f.date]] en [[exp.f.time]] (UTC), [[exp.f.band]] of [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] en [[exp.f.comment]]. “[[exp.addSave]]” logt hem als een gewone QSO (logboek, ADIF-bestand en verbonden programma’s); “[[exp.addCancel]]” sluit het formulier.",
  "t.aau531gtyu": "Ik vind een instelling niet: waar zoek ik?",
  "t.ab5g7yj0ve": "De baken zendt alleen met [[ctl.enable_tx]] aan en tussen 1400 en 1600 Hz. Het uploaden naar WSPRnet staat standaard uit, net als “Upload spots” in WSJT-X. De pagina geldt voor zowel WSPR als FST4W.",
  "t.abp15bzhz6": "Als een sterk station begint of ophoudt, verandert de AGC van de radio het volume en gaan zwakke signalen op dat moment verloren. [[ctl.agc]] brengt die stukken terug op het juiste niveau. Laat het aan staan.",
  "t.ae9exi2tpe": "[[rep.title]] · [[rep.active]]: vakje, standaard aan. Eén keer per dag verstuurt het een willekeurige installatiecode (of, als je de roepletters hebt ingesteld, een code die daarvan is afgeleid: de roepletters zelf worden nooit verstuurd), de Aurora-versie, het besturingssysteem, het land en het type computer (processor, aantal kernen en geheugen). Het dient om te tellen wie Aurora gebruikt en om te leren op welke computers het moeite heeft. Zet het uit als je zelfs dit niet wilt.",
  "t.affhv0akh1": "Na te veel proberen vind je het uiterlijk niet meer mooi: “[[ap.reset]]” onderaan de pagina zet alles terug zoals bij het begin (behalve de taal).",
  "t.afgw5x3e1m": "Automatisch CQ is een regel van het vak [[auto.b5]] in [[nav.automation]]: het staat niet op de pagina [[sw.tab.autocq]], die alleen op vaste tijden van band wisselt.",
  "t.aias45wioh": "De stijl van het radiodisplay kiezen.",
  "t.aieq7eevnp": "De bovenrand van de waterval (een dunne lijn) kun je slepen om de hoogte te wijzigen.",
  "t.ancesr0xh0": "De pagina “[[hist.title]]” toont alle berichten die je hebt ontvangen, doorzoekbaar. Het is niet het QSO-logboek: hier staan de gehoorde stations, niet de gemaakte contacten. Hij heeft geen item in de menu’s: hij opent via het adres “#/storico” (bijvoorbeeld in de browser, achter het adres van Aurora). Aurora onthoudt hem als laatst geopende pagina.",
  "t.aoaohszh2x": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]: “[[bak.make]]” zet het bestand Aurora-impostazioni-….zip op het Bureaublad.",
  "t.aq5rhdvhac": "“[[int.port]]”: de poort waarop het programma luistert (1 tot 65535). Gebruikelijke waarden: 2237 voor de WSJT-X-stream, 2333 voor veel logboeken die ADIF ontvangen, 12060 voor de XML van N1MM. Hij moet gelijk zijn aan die in het ontvangende programma; twee programma’s kunnen niet op dezelfde unicastpoort op dezelfde pc luisteren (gebruik andere poorten of multicast).",
  "t.aw03ud6q49": "Open [[nav.settings]]: links staat de boom met instellingen, verdeeld in gekleurde families: “[[sw.sec.station]]”, “[[sw.fam.modes]]”, “[[sw.fam.log]]”, “[[sw.sec.look]]” en “[[sw.sec.access]]”. Bij het openen is alles dichtgeklapt: een klik op een familie klapt die open, en binnen “[[sw.fam.modes]]” heeft elke modus een eigen tak met eigen pagina’s.",
  "t.ayneulhr64": "[[wfs.colors]] · [[wfs.gain]] en [[wfs.zero]] (−50 tot 50, standaard 0): een hogere gain maakt signalen levendiger (en breder), een lagere maakt ze dunner en donkerder; de nul verschuift de hele kleurschaal: verhoogd wordt ook de achtergrond lichter, verlaagd wordt de achtergrond donkerder en blijven alleen sterke signalen over. Wijzig ze als de waterval te helder of te flets is.",
  "t.b1cmu6sai6": "Welke meldingen de agent stuurt en wanneer",
  "t.b4iufcpm78": "Fabrieksmacro’s, eerste rij: F1 AutoCQ (zet automatisch CQ aan), F2 CQ, F3 Call 3, F4 Call, F5 Info, F6 Brag, F7 Bye (sluit af, slaat de QSO op en ruimt op), F8 Clear (maakt de vensters en de QSO leeg), F9 TX, F10 RX, F11 “<<” en F12 “>>” (zoek een signaal links of rechts). Ctrl-rij: MyCall, MyName, MyQTH, en Call, Name, QTH, die de QSO-gegevens in het vak schrijven; Ctrl-F12 “BM” is een bladwijzer die nog niet actief is.",
  "t.b50c7d04mf": "Met de muis erboven zie je [[hl.cpu]], [[hl.mem]], het laatste decoderen (bijvoorbeeld «0,9 s van 15,0 s»), de [[hl.threads]] en de toestand van [[hl.audio]], [[hl.cat]] en [[hl.clock]].",
  "t.b5lrj6ntbq": "“[[cluster.callsign]]” is alleen-lezen en komt uit [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]: schrijf daar je echte roepletters, want veel servers willen ze om in te loggen.",
  "t.b69qeopzkh": "“[[ens.g.pskspot]]” · “[[ens.k.PSKReporter]]” (standaard aan): stuurt PSK Reporter de stations die je ontvangt, zodat wie zendt kan zien waar hij aankomt; zo draag je bij aan de propagatiekaart. Zet het uit als je niet wilt dat je roepletters en die van de ontvangen stations op internet komen. “[[ens.test]]” controleert of PSK Reporter bereikbaar is, zonder spots te versturen.",
  "t.b6az7cq712": "[[nav.sat]] › [[sat.set.catMap]]",
  "t.b7vrihwz6k": "Voer je roepnaam en je locator in (6 tekens, bijv. FN42ab).",
  "t.ba4952fi8e": "[[nav.textModes]]: PSK31, PSK63, RTTY, CW en SSTV staan op dezelfde pagina; de modus kies je in het menu “Modus” van de pagina. Als je vanaf een andere pagina binnenkomt, zet Aurora de radio op de band van het IARU-bandplan van die modus (en, als de huidige band hem niet heeft, op de eerste). Tijdens het zenden doet het dat niet.",
  "t.baxob1wmt3": "Roepnaam en locator: het eerste wat je invoert.",
  "t.bbj7uggux": "[[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]]: ingang (van de radio) en uitgang (naar de radio). Op de hoofdpagina moet de Rx-balk “Right” aangeven; het vermogen stel je in met de Pwr-schuif, niet met de microfoonknop.",
  "t.bbpzoqugz": "Open op de pc [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] en druk op “[[acc.pair]]”.",
  "t.bd8gd5j7r2": "Om QSO’s naar een ander logprogramma of een onlinedienst te sturen, en om de gemiste QSO’s opnieuw te sturen terwijl het log gesloten was (het onderdeel “[[ens.k.UDP2Resend]]”), ga je naar [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]]: dat zijn loginstellingen, geen onderdeel van deze pagina.",
  "t.bdm0ifml2s": "Het knipperende kaartje rechtsboven toont de vlag, de roepnaam, het land en de UTC-tijd van de laatste ontvangst (“[[newdx.last]]”, met het signaal in dB) van een station dat een nieuw land is (“[[newdx.dxcc]]”) of nieuw op de band (“[[newdx.band]]”). De tijd wordt bij elke uitzending van het station bijgewerkt; het kaartje verdwijnt 10 minuten nadat je het station voor het laatst hoort. Er worden hooguit 4 kaartjes getoond.",
  "t.be9g4p5mmd": "Open [[nav.log]] in het bovenmenu en dubbelklik op de rij: het venster “[[exp.edit.title]]” opent, met “[[exp.edit.save]]” en “[[exp.edit.delete]]”. De wijziging geldt alleen voor het log van Aurora, niet voor externe logs.",
  "t.bfl67i7yhl": "[[ctl.spot]]: opent het venster “[[digi.spot.title]]” om een station aan DXSummit te melden (zie “Een spot versturen”).",
  "t.bg561tqmnp": "[[bfl.title]] · [[bfl.bands]]: een selectievakje voor elke band die je in [[sw.pg.bands]] hebt gekozen. Geen enkele aangevinkt = alle banden. Zodra je er een paar aanvinkt, blijft [[panel.all]] leeg op de andere banden: gebruik het als je één band volgt terwijl de radio tussen meerdere wisselt.",
  "t.bgxfn1t9w1": "Welke computer je nodig hebt",
  "t.bicbv2se9o": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: kies het model, daarna “[[cat.preset.apply]]” en [[cat.connect]].",
  "t.bjkckxfzzp": "Maak het paneel hoger door het kleine streepje aan de bovenrand te slepen (van drie regels tot de helft van de kolom; de hoogte wordt onthouden). “[[digi.band.clear]]” leegt de lijst, de geschiedenis en de roepnamen op de waterval: signalen die er nog zijn komen vanzelf terug. Op de waterval verdwijnt een roepnaam zodra hij 75 seconden niet meer is gehoord; “[[digi.band.wfCalls]]” in het menu [[digi.menu.view]] zet ze allemaal uit.",
  "t.bm77xne3td": "Kolom [[freq.preferred]] (vinkvak): de rij waar Aurora naartoe gaat als je de band in die modus kiest. Heeft een band en modus meerdere rijen, dan wint die met het vinkje; de andere zijn alternatieven die je kiest uit de frequentielijst naast de bandknoppen. Zonder aangevinkte rij wint de laagste frequentie.",
  "t.bn8ldujd3y": "Zet op dezelfde pagina, bij “[[rx.grp]]”, aan wat je in het uitgebreide display wilt zien: tweede VFO, meters, PRE en ATT, AGC, NB/NR/notch, versterkingen, RIT/XIT, ATU, gebruikte VFO.",
  "t.bqdobcl2dx": "De berichtenlijst",
  "t.bqie0bvg5f": "“[[sstv.sel.start]]” (grijs als de strook leeg is): kies meerdere miniaturen met een klik op elk; “[[sstv.sel.all]]” neemt ze allemaal, de knop “Wissen” met het aantal wist ze na een bevestiging (het kan niet ongedaan worden gemaakt) en “[[sstv.sel.done]]” verlaat de selectie.",
  "t.brtyg0hb81": "[[sw.contest.title]] · [[sw.contest.which]]: uitklaplijst met de contests waarin MSK144 of Q65 mag; de actieve contest heeft het woord “[[sw.contest.active]]”. Zolang je er geen kiest staat er “[[sw.contest.choose]]” met de opmerking [[sw.contest.note]]. Zonder de eigen engine staat er “[[contest.unavailable]]”.",
  "t.bt13cugmym": "Het tandwiel ⚙ op elke modipagina (FT8, PSK · RTTY · CW, SSTV, Satellieten, Contest…) opent Instellingen meteen op de tak van die modus.",
  "t.c1brvz8d3h": "Bij de eerste start vraagt een stapsgewijze gids om taal, roepnaam en locator, geluidskaart en radio; elke stap kan worden overgeslagen en alles kan later worden gewijzigd in [[nav.settings]].",
  "t.c2ymqxc0sf": "Logboek op dezelfde pc: 127.0.0.1. Logboek op een andere computer: het IP-adres daarvan.",
  "t.c58v68c4e": "[[rxl.auto]] (knop naast de Rx-regelaar, standaard uit): stelt het opnamevolume zelf bij. Het zakt meteen als het signaal oversatureert en stijgt langzaam als het zwak blijft; het pauzeert tijdens het zenden en schakelt zichzelf uit als je de regelaar met de hand verschuift. Zet het aan als de signalen sterk wisselen of als je er niet over wilt nadenken; zet het uit en stel het met de hand in als je liever een vast niveau hebt.",
  "t.c6unc4ejpk": "De knop met de naam van de modus en de pijl ▾ opent het menu van de modi van de bovenaan gekozen groep (“FT8” of “VHF”). Kies een modus en Aurora stelt hem in; tijdens het zenden reageert de knop niet (“[[mode.locked]]”). Hij is alleen grijs als noch de radio (CAT) noch de eigen engine van Aurora de modus kan wijzigen: de hint zegt hoe ([[band.noRig]]).",
  "t.cbde8ixl4c": "“[[wft.palette]]”: de kleuren (30 paletten plus je eigen). “[[wft.gain]]” en “[[wft.zero]]”: twee schuifregelaars van -50 tot 50 (standaard 0); Gain maakt de signalen levendiger, Zero maakt ook de achtergrond lichter of donkerder.",
  "t.cbobu5s35c": "Wie SSTV of PSK · RTTY · CW verlaat, zet het luisteren uit. Op een pc die het zwaar heeft laat «Trage pc» (Instellingen › Modi › FT8 · FT4 › Decodering) cluster, opzoekingen en updates wachten tot de decodering klaar is.",
  "t.cfq9xk9ew7": "[[lotw.grp]] · [[lotw.enable]]: zet een gekleurde balk onder de roepletters van wie onlangs een log naar LoTW heeft geüpload, in Bandactiviteit en het RX-venster (standaard aan). Aurora downloadt elke dag de openbare lijst van de ARRL; beweeg over de roepletters om de datum van de laatste upload te lezen.",
  "t.chnczvbe56": "[[digi.edit.title]] · [[digi.edit.macro]]: de uitklaplijst met toetsen (F1…F12, ook met Ctrl, Shift en Ctrl-Shift) en met gebeurtenismacro’s die vanzelf starten (OnStart, OnEnd, OnTX, OnCR, OnClickAny, OnAlarm, OnSP0, OnSP1, Gray+, Hello, AutoCqText). Kies de toets waaraan je de tekst wilt toewijzen.",
  "t.cif26b4j8h": "Log4OM: Settings → Program Configuration → Software Integration → Connections. (indicatieve naam, controleer je programmaversie)",
  "t.ciosirf7nt": "[[sw.digi.perMode]] · CW, “[[digi.cw.som]]” (standaard uit): in plaats van de tabel kiest hij het teken dat het dichtst bij de duur van punten en strepen ligt; het helpt bij een onregelmatige hand op de seinsleutel.",
  "t.cmckknb386": "SDR met TCI (ExpertSDR, Thetis)",
  "t.cnmctw3zpf": "DX-Cluster: volledige opmerking bij de cel",
  "t.con3u3l5we": "[[digi.edit.label]]: de tekst op de knop (maximaal 60 tekens). Is hij leeg en is er geen tekst, dan blijft de toets leeg.",
  "t.cqhp25ac1n": "[[bak.title]] · [[bak.restore]]: opent een bestandskiezer; kies een zip die met “[[bak.make]]” is gemaakt. Aurora vraagt om bevestiging (“[[bak.confirm]]”); als je akkoord gaat, wordt de kopie klaargezet en toegepast bij de volgende start: sluit Aurora via het systeemvak (rechtsklik › Afsluiten) en open het opnieuw. Is het bestand geen Aurora-kopie, dan zegt het dat. Na een herstel voer je wachtwoorden en dienstsleutels opnieuw in. Let op: de huidige instellingen en het logboek worden vervangen.",
  "t.cra1tccxuh": "De eerste keer leest het vak de pagina’s in en duurt het anderhalve seconde; daarna is zoeken direct. Ook paginanamen worden doorzocht.",
  "t.ctzb98fvg6": "F1: zendt het beeld (zoals “[[sstv.tx.send]]”), ook terwijl je in een tekstvak typt. Het start niet als je al zendt of als het zenden niet klaar is.",
  "t.cucqd1jmqp": "[[digi.spot.call]]: de roepnaam van het station, al overgenomen uit de huidige QSO (je kunt hem aanpassen; maximaal 20 tekens, in hoofdletters).",
  "t.cwz5zkuxn2": "Fox-expedities zenden af en toe een code (bijv. K8R.920749). Aurora laat die controleren en zegt je of de Fox de echte is.",
  "t.cx84d3g626": "De keuze voor de SSTV-band en -frequenties (het IARU-plan, bijvoorbeeld 14.230 MHz USB): dezelfde als op de tekstmodipagina; vergrendeld terwijl je zendt.",
  "t.d3l1uux8jy": "[[lay.lists]] · [[fil.always]]: tekstveld; deze roepnamen of prefixen worden altijd getoond, ook als continent, land of een ander filter ze zou verbergen. Zet hier vrienden en de stations die je niet wilt missen.",
  "t.d3z42ldd9g": "Het paneel [[panel.all]] toont alle berichten die op de band zijn gedecodeerd, de meest recente bovenaan. In de titelbalk staan drie kleine knoppen, daarna de knop ⧉ om het paneel los te maken (zie “Losse vensters en indeling”).",
  "t.d4jxky1ak1": "Elk gedecodeerd bericht verschijnt met zijn frequentie; “QSO” brengt de radio naar dat signaal in Q65 met de juiste periode en submodus. Voor EME toont de Maan-regel azimut, elevatie en Doppler, en de kolom Sked de te gebruiken frequentie.",
  "t.d5jtu28zv2": "[[acc.pair]] · [[acc.ttl]]: numeriek veld in minuten, van 1 tot 60 (standaard 10). Het zegt hoe lang een code geldig blijft; de code blijft voor eenmalig gebruik en wordt geblokkeerd na te veel foute pogingen. Het wordt vanzelf bewaard als de waarde binnen de grenzen valt (“[[acc.ttlSaved]]” verschijnt); buiten de grenzen wordt het niet bewaard. Wanneer: verleng het als je meer tijd nodig hebt om de QR te scannen, korter is veiliger.",
  "t.d5vgf3ekfu": "Decodeerdiepte ([[dec.depth]]) en enkelvoudig decoderen ([[dec.singleDecode]]) gelden ook voor JT65 en JT9, maar staan op de pagina [[sw.sub.ft8]] › [[fil.decode]]. De knop [[ctl.jt_both]] naast de mode decodeert ook de andere JT-mode.",
  "t.d61pm7e56g": "Blokkade door een ander programma: met “Accept UDP requests” aan kan een verbonden programma het zenden voor beperkte tijd blokkeren; het Tx-paneel zegt wie het blokkeert.",
  "t.d63oxmazzi": "[[rot.set.range]]: hoeveel graden de rotor kan draaien. De keuzes: 0° … 360° (standaard, één rondje), 0° … 450°, −180° … 180° (midden zuid), −90° … 450°, 0° … 540°; “[[rot.set.rangeCustom]]” toont [[rot.set.rangeFrom]] en [[rot.set.rangeTo]] om de waarden met de hand in te vullen. Bij rotors met 450° (overlap voorbij het noorden) kiest Aurora de dichtstbijzijnde hoek en toont de overlapzone.",
  "t.d72vbvtpo6": "“[[int.enabled]]” (aan als je hem aanmaakt): uit blijft de bestemming met zijn keuzes in de lijst staan, maar ontvangt niets. Handig om een programma te pauzeren zonder het opnieuw in te stellen.",
  "t.d8g5lzsf9j": "Kies in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] een geluid voor elke gebeurtenis.",
  "t.d8klr0d1h8": "[[sw.mem.title]] · “[[sw.mem.load]]”: zet de instellingen van dat geheugen (modus, frequenties, RTTY, AFC, Snap, squelch) terug in de engine en bevestigt met een melding. Het is uitgeschakeld bij lege geheugens of als de instellingen nog niet zijn aangekomen. “[[sw.mem.clear]]” maakt het geheugen leeg (uitgeschakeld als het al leeg is).",
  "t.dg3ew10dev": "[[cqp.title]] · [[set.reset]]: knop; zet de keuzes van [[panel.cq]] (categorieën, lijsten, regels) terug op de fabrieksinstellingen. Het werkt alleen op dit vak: de bandactiviteit blijft zoals ze is.",
  "t.dg9hfpm8v0": "Druk op “[[rot.short]]” om naar het DX-station te draaien, “[[rot.long]]” voor de lange weg, de stappen −10°/−2°/+2°/+10° om bij te stellen, of klik op de roos of typ de graden en druk op “[[rot.go]]”. “[[rot.stop]]” stopt de rotor meteen.",
  "t.dgygycjm1e": "[[auto.b4]]: stations, landen gekozen uit de DXCC-lijst en, als je wilt, alleen bepaalde continenten. De filters van [[panel.all]] (Instellingen › Modi › FT8 · FT4 › Berichten en filters) tellen ook mee: wie ze verbergen krijgt nooit een automatisch antwoord, ook niet in dry run, en het logboek zegt dat.",
  "t.djk50fqikz": "Bovenaan staat de titel “[[lp.title.lead]] ROEPNAAM?” met labels voor band, modus, frequentie en UTC-tijd van de QSO. Wachten er meer QSO’s, dan staat dat er ook (“n QSO’s wachten”).",
  "t.djnnij0ykf": "Druk bovenaan de pagina op [[wfs.preview.show]]: de echte waterval en het echte spectrum blijven in beeld terwijl je de opties wijzigt, en elke wijziging is meteen zichtbaar. Het voorbeeld gaat uit als je de pagina verlaat.",
  "t.dk3az8ro74": "Algemene geluidsschakelaar: “[[alert.button]]” in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]]. Eén geluid per gebeurtenis: zelfde pagina, geluidenvak. Kleuren en markeringen: [[sw.tab.colors]] (zelfde tak).",
  "t.dnalzjih55": "Het zenden stopt met een SWR-waarschuwing: controleer de antenne en de kabel; verhoog [[gen2.swr]] of zet hem op 0 alleen als je zeker weet dat de meting niet klopt.",
  "t.dokxt6ihvx": "De baken zendt op de Tx-frequentie als die tussen 1400 en 1600 Hz ligt, anders op 1500 Hz. Met een samengestelde roepnaam, of met een locator van 6 tekens en [[mode.wsprType1]] uit, wisselt hij af met “<CALL> LOCATOR6” (in FST4W zonder het vermogen). Bij luisteren decodeert FST4W in de subband 1400-1600 Hz, zoals WSJT-X. Met split “[[cat.split.rig]]” of “[[cat.split.emulate]]” (WSPR, FST4W, FST4) volgt de toon de verschuiving van de radio en komt hij niet naast de frequentie uit.",
  "t.dp4y67n7qx": "Snelheid: [[cat.baud]] moet gelijk zijn aan die in het CAT-menu van de radio (in het radiomenu, zie de handleiding: de optie CAT RATE of CI-V…). Als ze verschillen, antwoordt de radio niet.",
  "t.dpc6qayxb3": "De voorvertoning: een klik op een laag kiest hem; slepen verplaatst hem; de greep rechtsonder verandert de grootte en die bovenaan draait hem (hij springt om de 15 graden). Een klik op lege ruimte heft de selectie op. De rechtsklik, of twee vingers, sleept de achtergrondfoto om hem te kaderen; het wiel zoomt. Als het leeg is, zegt de voorvertoning “[[sstv.bg.drop]]”.",
  "t.dredo7bbn0": "Waarschuwing bij een hexadecimaal geschreven CI-V-adres",
  "t.drq3umslai": "[[win.open]]: de lijst van geopende aparte vensters, met hun onderdelen. Bij elk brengt “[[win.show]]” het naar voren (handig als het onder andere vensters of op een scherm terecht is gekomen dat je niet ziet) en zet “[[win.attach]]” het terug in het hoofdvenster. Zonder aparte vensters zie je “[[win.none]]”. “[[win.attachAll]]” zet ze allemaal terug (staat uit als er geen zijn).",
  "t.du2h29fjqm": "Vier kleine menu’s van de pagina [[nav.textModes]], met elk een paar onderdelen.",
  "t.du7mf6xmb7": "[[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]: “[[cluster.enabled]]” aan en een server gekozen.",
  "t.duprjv57c": "[[bfl.title]] · [[list.bottom]]: selectievakje, standaard uit (nieuwe berichten komen bovenaan en de lijst schuift naar beneden). Aan staan nieuwe berichten onderaan en is de laatste regel altijd het laatste bericht. Het geldt voor [[panel.all]]; die voor [[rxw.title]] staat verderop.",
  "t.dwb9dcp9oa": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › [[sw.pg.vhfModes]] staan de decodeeropties van Q65 (middelen over perioden, voor EME en signalen onder de ruis) en MSK144 (meteorenscatter), met de fabriekswaarden van WSJT-X. De pagina bestaat alleen met de eigen engine; de opties gelden vanaf de volgende periode, na [[sw.save]].",
  "t.dy9zp0tf4g": "Onderaan de pagina. Elk vak is een knop of een veld; met de rechtermuisknop op een ervan opent een klein menu. Wil je hem niet, zet dan “[[digi.mi.statusBar]]” uit in het menu [[digi.menu.view]].",
  "t.dz1p461ttd": "Op Arch Linux en afgeleiden heet de groep voor de seriële poort niet dialout maar uucp: het commando wordt sudo usermod -aG uucp $USER, daarna uit- en weer inloggen.",
  "t.dzbjn87a0i": "[[sw.contest.title]] · [[contest.set.exchange]] en [[contest.set.serial]]: de eerste is de vaste exchange (Field Day: klasse en sectie, buiten de VS en Canada “1D DX”; Roundup: staat of # voor het serienummer); de tweede is het eerste serienummer om te sturen, van 1 tot 9999 (fabrieksinstelling 1). Het volgende nummer is altijd het aantal QSO's in het contestlog + 1. Wijzig [[contest.set.serial]] alleen als je een elders al begonnen contest hervat.",
  "t.e0690gb2u8": "[[sw.tab.phone]]",
  "t.e3hmq7adpo": "Voer in het vak “Modo UDP” IP 127.0.0.1 en poort 2237 in op de rijen “Msg ID 5” en “Msg ID 12” (de rij “Msg ID ADIF” is niet nodig), en dan “Chiudi” (Sluiten).",
  "t.e5jh2e4gby": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] kan Aurora zelf de CQ's beantwoorden die je iets nieuws opleveren en, als je wilt, zelf CQ roepen. Bovenaan staat de kop (status, mode, cijfers van vandaag); daaronder vijf regelblokken, elk met een “?”; onderaan de lijsten van wat Aurora gaat doen en wat het deed. Het begint uit en in dry run: echt zenden kan alleen vanaf de pc worden ingeschakeld. De regels worden opgeslagen met [[sw.save]].",
  "t.e6oetsquo3": "[[sw.contest.title]] · [[contest.set.name]], [[contest.set.email]], [[contest.set.address]], [[contest.set.location]], [[contest.set.assisted]]: Cabrillo-gegevens. Naam, e-mail en adres worden één keer geschreven en gelden voor alle contests; [[contest.set.location]] is de ARRL/RAC-sectie of “DX”; een lege [[contest.set.assisted]] neemt die van de categorie.",
  "t.e7qa2lhu51": "“[[rep.id]]” en “[[rep.newId]]”: het willekeurige nummer dat deze installatie in rapporten identificeert. “[[rep.newId]]” maakt een nieuw nummer aan: eerdere rapporten zijn dan niet meer aan deze installatie te koppelen. Gebruik het als je opnieuw wilt beginnen.",
  "t.e8zxbkyy34": "Bovenaan het venster staan de pillen van de modusgroepen (“FT8”, “VHF”, [[nav.textModes]], [[nav.sat]]) en de pagina’s. De modus (FT8, FT4…) kies je in het menu van de modusknop, linksboven op de pagina [[nav.station]]; de band wijzig je met de frequentieknop ernaast (er zijn geen bandpillen). Zie “Modus, submodus en frequentie” en “De bovenbalk: modi”.",
  "t.ea58klys71": "Procedureseinen worden geschreven als <AR>, <BT>, <KN>, <SK> en gaan als één enkel teken de lucht in; in de andere modi worden het letters.",
  "t.ecx9x8bei5": "Open [[nav.fox]] in het bovenmenu en druk op “[[fox.off]]”: je zendt in even periodes, onder 1000 Hz.",
  "t.ef0htc65o7": "“[[cluster.dxpedColor]]”: de kleur waarmee in de DX Cluster de spots van DXpedities in de lucht worden gemarkeerd volgens de NG3K-kalender (“[[onl.dxped]]” moet aan staan). Een palet met fluorescerende kleuren (“[[cluster.dxpedFluo]]”) en twee zachte, een kiezer “[[cluster.dxpedCustom]]” voor elke kleur en “[[set.reset]]” om terug te gaan naar het standaard fluorescerende geel. De tekst wordt vanzelf donker of licht om leesbaar te blijven. Hij blijft op dit apparaat.",
  "t.egavdggfh6": "Alleen CW en PSK: “[[digi.band.mi]]” (CW) of “[[digi.band.miPsk]]” (PSK31/PSK63) zet het paneel met de signalen van de band en hun decodering aan en uit; “[[digi.band.spots]]” stuurt de geverifieerde roepnamen naar het DX Cluster-paneel van Aurora, op je pc en nooit over het netwerk; “[[digi.band.spotsCqOnly]]” (grijs als spots uit staan) beperkt de spots tot stations die CQ roepen. Ze staan standaard aan.",
  "t.eiapucegxa": "Bandactiviteit toont de hele band (met de knop “Filter” kies je slechts enkele soorten oproepen); het RX-venster toont jouw RX-frequentie (±50 Hz) en de berichten aan jou gericht. Beide zijn aanpasbaar.",
  "t.emmy5zrur5": "De pagina “Dit apparaat koppelen”",
  "t.eqbos729iz": "[[nav.sat]] › [[sw.pg.doppler]]",
  "t.er9xqwxw7i": "Een macro indrukken toont “Command not available yet: …”: de genoemde opdracht wordt nog niet door Aurora uitgevoerd; haal hem uit de tekst.",
  "t.etrcfd0162": "[[tab.support]]",
  "t.evvwlsv3s4": "“[[contest.export]]”: kies het “[[contest.exp.format]]” (Cabrillo 3.0, EDI of ADIF volgens de regels); de lijst “[[contest.exp.problems]]” zegt wat je moet herstellen voor het versturen (of “[[contest.exp.ok]]”); “[[contest.exp.save]]” slaat het bestand op en “[[contest.exp.send]]” opent de pagina van de organisator. Aurora verstuurt zelf niets.",
  "t.exauphqtlq": "De knop “[[ctl.spot]]” staat in het tabblad DX Cluster van de pagina Station (FT8 en de andere modi): hij opent het spotvenster met de DX van de QSO, de radiofrequentie en de modus. De spot die je verzendt verschijnt meteen in de lijst onder je roepnaam.",
  "t.ey2z02kur": "“[[sstv.img.save]]”: slaat het bestand dat je ziet op schijf op (als je Opgeschoond hebt gekozen, het opgeschoonde). “[[sstv.img.delete]]”: wist het beeld na de vraag “[[sstv.img.deleteConfirm]]”.",
  "t.ey73gwvooc": "De radio zendt niet",
  "t.f069ydugd": "“[[newlog.button]]” (op de pagina Log en diensten): om opnieuw te beginnen met een leeg logboek (bijvoorbeeld aan het begin van het jaar of met een nieuwe roepnaam). Een waarschuwing toont het aantal QSO’s in het huidige logboek, de knop “[[newlog.exportFirst]]” en twee keuzes; “Annuleren” is de standaardkeuze en Enter noch Esc start iets. “[[newlog.keep]]” kopieert het logboek naar een bestand naast het huidige, met datum en tijd in de naam (logbook-archivio-JJJJMMDD-UUMMSS.db), controleert dat de kopie alle QSO’s bevat en opent pas dan het nieuwe logboek: er gaat geen QSO verloren. “[[newlog.replace]]” wist de QSO’s echt: er volgt een tweede, rode bevestiging waarin je het woord “[[newlog.word]]” moet typen. Ook het bestand aurora_log.adi wordt met datum en tijd apart gezet. Dit kan niet tijdens het zenden of met Enable Tx aan. Gewerkte stations, DXCC-overzicht, statistieken en kaart beginnen meteen opnieuw met het nieuwe logboek, zonder herstart. Om de QSO’s van een gearchiveerd logboek terug te krijgen: exporteer ze als ADIF voordat je een nieuw logboek maakt en importeer ze opnieuw met “[[logio.import]]”, of zet, met Aurora gesloten, het archiefbestand terug in plaats van logbook.db (nadat je het huidige apart hebt gezet).",
  "t.f0voywy549": "[[digi.mi.listen]]: vinkje = Aurora luistert. Een klik stopt of herstart het luisteren. Als je de pagina opent, gaat het luisteren vanzelf aan.",
  "t.f51z6cwcrq": "[[digi.edit.title]] · [[digi.edit.label]] en [[digi.edit.color]]: het label (tot 60 tekens) is de tekst op de knop op de werkpagina; de kleur is de achtergrond van de knop, om groepen in één oogopslag te herkennen (CQ, antwoord, 73).",
  "t.f5l3jf3u6p": "[[ctl.hold_tx]] houdt je Tx vast: bij het beantwoorden verschuift alleen Rx.",
  "t.f79kv9xouv": "“+ [[int.p.adif]]”: naam Log4OM, 127.0.0.1, poort 2333, “[[int.adif]]” en “[[int.resend]]” aan. Voor elke QSO ontvangt hij het volledige ADIF-record als gewone tekst, één datagram per QSO, zonder stream en zonder status. Voor Log4OM 2 (inkomende verbinding van het type ADIF_MESSAGE) en WaveLogGate. De poort moet gelijk zijn aan die in het logboek: luistert het logboek op 2237, verander dan de poort hier. Met “[[int.resend]]” komen QSO’s die met het logboek dicht zijn gemaakt aan als je het weer opent.",
  "t.f9iaul69kt": "Het totaal aantal QSO’s staat in de balk van het paneel; om het hele logboek te zien en als ADIF te exporteren gebruik je [[nav.log]] in het bovenmenu.",
  "t.f9my60cnmt": "“Al eerder gewerkt” uit het Log4OM-log: druk in [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]], vak “[[l4.title]]”, op “[[l4.choose]]” en kies de Log4OM SQLite-database (of typ het pad en druk op “[[l4.use]]”; soms vindt Aurora hem zelf). Aurora leest hem alleen, en het paneel [[panel.log]] toont de Log4OM-QSO’s. De variabele AURORA_LOG4OM_DB is alleen een andere mogelijke bron, voor wie hem al gebruikt.",
  "t.fc5unsp08w": "Stappen in Aurora, van de frequentie tot de gelogde QSO.",
  "t.fci05adtwr": "Maak in Cat4OM de groep aan met je radio en controleer of die verbonden is. Log4OM en Aurora gebruiken beide die groep.",
  "t.fd24ivyy7i": "Het getal linksboven is het totaal aantal gewerkte landen; onderaan staat hoeveel landen je hebt gewerkt van hoeveel er zijn, en het aantal QSO’s in het logboek.",
  "t.fdq1mmltjt": "Een rechtsklik op een knop (ook een lege) opent het venster “[[digi.edit.title]]” voor die toets: zie “Een macro bewerken”. Met de muis boven een knop zie je de toets en de macrotekst.",
  "t.feipt5eqk5": "Als de Fox niet antwoordt, blijft Aurora roepen. Na de eerste R+rapport zonder RR73 verschuiven latere pogingen 300 Hz ten opzichte van de Fox-frequentie.",
  "t.fek4ozmxvx": "De Gids legt nu elke pagina van de Instellingen uit, één regel per vakje, veld en keuzelijst, plus de panelen, de sneltoetsen van PSK · RTTY · CW en SSTV en een hoofdstuk met veelgestelde vragen.",
  "t.fh4awhy5md": "[[digi.mi.scan]] › [[digi.mi.scanStart]]: elke “verblijftijd” (standaard 10 seconden, van 2 tot 600) gaat de ontvangst naar het volgende signaal rechts en begint aan het einde van de band weer van voren af aan; [[digi.mi.scanStop]] stopt het; [[digi.mi.scanProps]] opent de Instellingen op de pagina “[[sw.pg.digiScan]]” om de verblijftijd te kiezen, of hij bij het eerste signaal stopt en of tijd en frequentie in de tekst worden geschreven.",
  "t.fjhs4b1fkc": "Alles terugzetten in het hoofdvenster: de knop ⤓ (“[[win.attachAll]]”), die rechtsboven alleen verschijnt als er minstens één apart venster is. Elk apart venster heeft ook een eigen knop “[[win.attach]]”.",
  "t.fjlw80s2iq": "Boven de waterval staat een opdrachtbalk met dezelfde opties als [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: hier of daar wijzigen is hetzelfde en de wijziging is meteen zichtbaar. Elk onderdeel heeft zijn hint (beweeg de muis erover).",
  "t.fk0qxa4ljv": "[[ctl.jt_both]]: verschijnt alleen met JT65 of JT9; als hij aanstaat, decodeert hij ook de andere van de twee in dezelfde minuut. [[ctl.agc]]: compenseert de variaties van de AGC van de radio (zie “[[ctl.agc]]: zwakke signalen naast sterke stations”).",
  "t.fki0flzr4y": "Op de Contest-pagina: F1 start Auto CQ (de contest-CQ elke periode), F2 uitwisseling, F3 R + uitwisseling, F4 afsluiting; Esc stopt het zenden meteen, dubbel Esc wist ook het huidige QSO. Boven de decodes: de frequentie (alleen contestbanden) en het vak RX/TX (klik op TX om te stoppen, klik op RX om het QSO te wissen). “Hoe werkt het” vat de regels samen en wat er wordt verzonden. Alleen QSO’s die tijdens de wedstrijd vanaf deze pagina zijn gestart komen in het contestlogboek.",
  "t.fkoa83vd4y": "[[digi.mi.memory]] › [[digi.mi.memWrite]] / [[digi.mi.memRead]]: twintig geheugens. Een geheugen bewaart modus, ontvangst- en zendfrequenties, Lock, RTTY-shift en -snelheid, Rev, AFC, Snap, squelch en de drie drempels. De geheugens worden op deze computer bewaard; je kunt ze ook oproepen of legen bij “[[sw.mem.title]]” in de Instellingen. Een leeg geheugen antwoordt met een melding.",
  "t.folw8r9el2": "Controleer of [[ctl.monitor]] aan staat.",
  "t.fp2sngrhtn": "«Verloren QSO’s opnieuw sturen» ook voor de tweede UDP-server",
  "t.fql6y07krc": "De pagina [[nav.rotator]] (titel “[[rot.title]]”) toont de kompasroos en de rotorbediening. Dezelfde kaart kan ook boven het Station staan, in de modi FT8, FT4, JT65, Q65 enzovoort. De rotor stel je in bij “De antennerotor”.",
  "t.fr5hkkschj": "In [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]] stelt de knop “[[sdr.useAll]]” CAT en audio in één keer in. S-meter, vermogen en SWR komen van de SDR; PWR − / + van het display wijzigen het SDR-vermogen en TUNE schakelt de tune-draaggolf aan en uit. Elk commando wacht tot de SDR het bevestigt: gebeurt dat niet, dan meldt Aurora het. “Power on” en “Power off” schakelen de SDR via TCI aan en uit.",
  "t.ft3y4nqdh4": "Waar de instellingen staan en hoe ze worden opgeslagen.",
  "t.fuspnf34v3": "Er is een instelling “[[dec.slowPc]]” in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]], met drie opties: “[[dec.slowPc.auto]]” (standaard), “[[dec.slowPc.always]]” en “[[dec.slowPc.never]]”. In automatisch gaat ze vanzelf aan na 3 van de 10 perioden boven 70% van de tijd, na 3 verloren audioblokken in 10 minuten of bij 2 processors of minder, en gaat uit na 20 rustige perioden. Zolang ze aan staat, zet Aurora tijdens het decoderen DX Cluster, DXpedities, PSK Reporter, het opzoeken van roepletters, de LoTW-lijst, satellietgegevens en de updatecontrole opzij; die werken zodra het decoderen klaar is (hoogstens 30 seconden later). Daarnaast is er een controle die meet hoe lang het decoderen van elke periode duurt en, als minstens 4 van de laatste 10 perioden boven 70% van de periodelengte uitkomen (bij FT8 ongeveer 11 van de 15 seconden), rechtsonder een gele kaart toont: die verandert nooit iets uit zichzelf.",
  "t.fvamc8r6t8": "[[digi.mi.hairlines]] (uit): tekent een dunne verticale lijn langs de ontvangstfrequentie (en de zendfrequentie, met Lock) om het signaal beter te centreren.",
  "t.fxt2hq4odp": "Eén keer Esc: stopt het zenden meteen. In Aurora heeft Esc ook een algemeen effect, geldig op alle pagina’s en standaard aan: het zet “[[ctl.enable_tx]]” uit (zet dit uit met “[[gen.escStop]]” in de Instellingen).",
  "t.fy02sxwno0": "Daaronder staan bandactiviteit, de DX Cluster van de band, laatste QSO’s, de zes Tx-berichten, waterval en CQ.",
  "t.fyozk8etkn": "“[[exp.save]]” (op de pc opent dit het Windows-venster om de map en de naam van het ADIF-bestand te kiezen) of “[[exp.download]]” (vanaf de telefoon of een andere computer: het bestand komt in de downloadmap): ze slaan alleen de geselecteerde QSO’s op. “[[exp.saveCbr]]” slaat dezelfde QSO’s op in Cabrillo 3.0 (voor een contest met eigen regels gebruik je de pagina [[nav.contest]]). Zonder geselecteerde QSO zijn de knoppen grijs.",
  "t.fzcomkyzb3": "Een stip rechtsboven, groen, oranje of rood, op basis van de CPU van Aurora, geheugen, decodeertijd, audio, CAT en klok. De tooltip geeft de details; met een klik opent «Gezondheid van het station», met de grafiek van de laatste 10 minuten en het advies «Trage pc».",
  "t.g09cbf3nv7": "Bovenaan de cijfers van het logboek (QSO’s, landen, zones); eronder de QSO’s per band en de DXCC-kaart van het station dat je werkt. Ontbrekende landen openen met een klik; het vak “[[logio.title]]” staat al open, met [[logio.export]] en [[logio.import]].",
  "t.g0yx2wnzf7": "Geen enkele correctie of verwijdering wordt doorgestuurd naar externe logboeken (programma’s verbonden via UDP, Wavelog, ClubLog, QRZ, LoTW): daar corrigeer je de QSO met de hand.",
  "t.g1d92z0iow": "Hard geseinde CW-stations laten bij elke flank een horizontale lijn op de waterval achter (klikken). “[[digi.mi.anticlick]]” in het menu [[digi.menu.view]], standaard aan, haalt ze weg zolang de pagina luistert: breedbandige energie die korter dan 10 ms duurt wordt gedempt voordat de regel wordt getekend, de signalen blijven. Zolang deze pagina luistert geldt dit ook voor de waterval van de andere pagina’s.",
  "t.g2y3p4gu3s": "[[acc.devices]] · lijst en “[[acc.revoke]]”: elke gekoppelde telefoon of tablet heeft zijn naam en een knop “[[acc.revoke]]” die de toegang meteen intrekt (hij moet dan opnieuw koppelen). Als er geen zijn, lees je “[[acc.noDevices]]”. Wanneer: telefoon kwijt, verkocht of uitgeleend.",
  "t.g5biuv451j": "[[sw.pg.bands]]",
  "t.g6z5e46cpn": "Stations in de wachtrij zetten die je roepen terwijl je in een QSO zit.",
  "t.g7ocqb0ygi": "Kies in FT991Link de poort van de radio en druk op “COM Port” om hem te openen.",
  "t.g9l15etnfs": "De wachtrij en [[ctl.answer_all]]",
  "t.ga36xt3kfr": "“[[qmap.source]]”: [[qmap.source.off]], [[qmap.source.tci]] (met “[[qmap.tci]]”, bijvoorbeeld 127.0.0.1:40001, en de “[[qmap.rate]]”) of [[qmap.source.file]] (met het “[[qmap.file]]” en de knop “[[qmap.decodeFile]]”). De bron kun je alleen wijzigen vanaf de pc waarop Aurora draait.",
  "t.gaevr1vxz2": "[[fil.decode]] · [[gen2.decStart]]: keuzelijst die bepaalt hoe ver in de periode het FT8-decoderen begint. [[gen2.decStartEarly]] laat meer tijd om te antwoorden vóór de volgende periode; [[gen2.decStartLate]] vangt ook signalen die laat binnenkomen; fabrieksinstelling [[gen2.decStartNormal]]. Wijzig dit alleen als je tijd tekortkomt om te antwoorden of late signalen mist.",
  "t.gcdejo2n4n": "[[ens.g.log]] · [[ens.k.AutoQSOLogging]] en [[ens.k.ClearCallGridExit]]: deze twee onderdelen verschijnen niet in Aurora omdat ze altijd gelden. Het QSO wordt vanzelf gelogd (tenzij [[ens.k.PromptToLog]] om bevestiging vraagt), aan het eind van het QSO stopt het zenden en wordt het DX-station gewist; om verder te gaan roep je opnieuw CQ of kies je een andere DX. Bij het starten begint Aurora altijd zonder DX-station.",
  "t.gfiwgibl0p": "Tx-vertraging: in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], vak [[gen2.operation]], is [[gen2.txDelay]] de tijd tussen PTT aan en het begin van de audio, 0 tot 0,5 s (standaard 0,2 s, zoals “Tx delay” in WSJT-X). Verhoog hem als de radio of CAT traag is en het begin van het bericht verloren gaat.",
  "t.gh252g4655": "Het venster “QSO loggen met…”",
  "t.ghey2037ce": "[[cqp.title]] · categorieën: een selectievakje voor elk van [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]]; standaard allemaal aan. Ze bepalen wat het venster [[panel.cq]] toont: haal de vinkjes weg bij wat je niet nodig hebt.",
  "t.gkwllsuexv": "Zegt Aurora dat rigctld (het Hamlib-programma) ontbreekt? Meestal heeft de antivirus het verwijderd. Onder Windows: 1) open [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]; 2) druk op “[[cat.restore]]”: Aurora downloadt het opnieuw van de officiële Hamlib-release en controleert de checksum; 3) druk op [[cat.connect]]. Verdwijnt het weer, voeg dan de Aurora-map toe aan de uitzonderingen van de antivirus.",
  "t.glmednso3e": "DX-regel: “[[phone.cqCall]]” als je CQ roept (of nog geen station hebt gekozen); anders “[[phone.dx]]” (of “[[phone.calling]]” tijdens het zenden), roepletters, vlag en een regel met land, locator, afstand in km en S/N.",
  "t.glth09yywf": "Een klik op een resultaat (of Enter voor het eerste) opent de juiste pagina en brengt de optie in beeld, even oplichtend.",
  "t.gpqngvvfwy": "[[rep.title]] · [[rep.show]] en [[rep.showAuto]]: twee knoppen die een venster “[[rep.previewTitle]]” openen met de exacte tekst van wat er verstuurd zou worden: de eerste het pakket (een lijst met te openen bestanden, met groottes), de tweede een automatisch rapport (dat in de wachtrij, of een voorbeeld). Ze versturen niets; sluiten met “[[rep.close]]” of Esc.",
  "t.gq2l6yrsos": "Het tandwiel ernaast: opent “[[cop.title]]” (zie hieronder). De tooltip van de knop is “[[cop.tip]]”.",
  "t.gqrxbaq943": "[[bfl.title]] · [[bfl.minKm]] en [[bfl.maxKm]]: twee getalvelden van 0 tot 25000 km. Met een limiet worden alleen stations getoond waarvan de locator bekend is. Leeg = geen limiet. Gebruik ze om alleen ver DX te zoeken (minimale afstand) of alleen nabije stations (maximale afstand).",
  "t.gs2zqhpdnm": "In [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] kies je welke banden in de bandbalk van het station staan. De keuze werkt meteen en wordt bewaard.",
  "t.gsf69m2sgs": "De brede DXpeditie-modus, compatibel met WSJT-X SuperFox. In test.",
  "t.gtb7onmmp0": "Kun je het pakket of de back-up niet maken? Open deze pagina vanaf de pc waarop Aurora draait, niet vanaf een telefoon of een andere computer.",
  "t.gzcnj3gzey": "[[tab.macros]] · lijst: elke regel is een macro, met een knop [[set.remove]] om hem te verwijderen. Standaard zijn er vijf: “@ TNX 73”, “TU ^ 73”, “@ &”, “@ #”, “@ R#”. Is de lijst leeg, dan verschijnt “[[macro.empty]]”.",
  "t.h111i6llgy": "De radio instellen",
  "t.h1swcc1tcd": "Icoon in de kop (naast de taal): het verschijnt als er een nieuwe versie is; een klik opent een klein paneel met “[[upd.install]]” (als het kan worden geïnstalleerd), “[[upd.open]]” en “[[upd.later]]”, dat het verbergt tot de volgende versie. Het sluit met Esc of een klik erbuiten.",
  "t.h4oilo7ebj": "Integraties: wat elk programma ontvangt",
  "t.hc09ot3frp": "Zonder je locator of zonder DX-station kunnen de knoppen “[[rot.short]]” en “[[rot.long]]” de richting niet berekenen: de kaart zegt dat (“[[rot.noMyGrid]]”, “[[rot.noDxAny]]”).",
  "t.hc1rnmojb1": "Elke miniatuur toont de roepnaam (of de modus) en de UTC-tijd; het label “[[sstv.img.partial]]” zegt dat het beeld maar gedeeltelijk is binnengekomen. Met de muis erboven zie je modus en tijd.",
  "t.hdy6ozn1j9": "[[sw.digi.perMode]] · CW, schuifregelaar voor de zendsnelheid (van 5 tot 60 woorden per minuut, fabriek 20): het is de snelheid van de automatische keyer van Aurora; verander hem als je sneller of langzamer seint dan het andere station.",
  "t.hg8je5qhsk": "FT-991/FT-991A met FT-991(A) Link",
  "t.hi886iwg83": "[[fil.grp.rx]] · [[bfl.hideOwnTx]]: selectievakje; verbergt je eigen verzonden berichten in het venster [[rxw.title]]. Het is dezelfde keuze als “[[gen2.showTx]]” in het vak [[gen.screen]], maar andersom gezien: als je het ene aanzet, gaat het andere uit.",
  "t.hky2qb26ee": "Pad: [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]], onder de QR, terwijl je de telefoon koppelt. Dit zijn de regels waarmee Aurora je vertelt wat het weet over het netwerk van de pc, zodat wie geen verbinding krijgt meteen begrijpt waarom. Het ververst zichzelf elke 15 seconden terwijl je op de telefoon wacht.",
  "t.hkyeifxcpt": "“[[int.loggedAdif]]”: na elke QSO stuurt hij het ADIF-record in binair bericht nummer 12 (gelezen door MacLoggerDX, GridTracker, BBLogger, LogHX en andere). Je kunt het ook los aanzetten, zonder de stream. Zet het aan als de QSO niet in het logboek aankomt terwijl de status wel aankomt.",
  "t.hm4ab36uew": "Bij RTTY: [[digi.rtty.reverse]], [[digi.rtty.uos]], “[[digi.rtty.receiver]]” ([[digi.rtty.receiverAuto]], [[digi.rtty.receiverFilters]], [[digi.rtty.receiverDisc]]) en de schuifregelaar voor de squelchdrempel (S/N van 0 tot 40 dB, standaard 0).",
  "t.hm5hfjrtpq": "Het vak met de Tx-berichten: titel “[[phone.txMessages]]” met de Tx-frequentie (hij wordt rood “[[phone.transmitting]]” terwijl je zendt), de DX-rij (“[[phone.dx]]” of “[[phone.calling]]” met vlag en afstand) en de knop “[[ctl.split]]”, dan de zes berichten met hun type ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): een tik kiest het volgende dat wordt uitgezonden. Daaronder de waterval.",
  "t.hmzyk9q8wy": "[[sstv.set.grpSave]] · [[sstv.set.autoSave]] (standaard aan): elk volledig ontvangen beeld wordt vanzelf opgeslagen in de beeldenmap. Zet het uit als je zelf wilt kiezen wat je bewaart (vanaf de SSTV-pagina kun je beelden nog steeds met de hand opslaan).",
  "t.hnws1pedtz": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]], vak [[fil.decode]].",
  "t.hp6708prb4": "Onder “[[fox.callers]]” staat de waterval (“[[fox.waterfall]]”): klik = Rx-frequentie, rechtsklik of Shift + klik = Tx-frequentie; de hoogte pas je aan door aan de greep te slepen. Rechts toont “[[fox.received]]” de laatst gedecodeerde berichten, met de aan jou gerichte gemarkeerd. De regel “Pogingen … wacht … cycli …” vat de parameters samen.",
  "t.hvxn9j9d0d": "Rechterkolom: het tabblad “[[digi.tab.cluster]]”",
  "t.hz4a6rogoo": "Uploadt je externe logboek al naar een dienst (bijvoorbeeld ClubLog of QRZ.com), zet hem hier dan niet ook aan: het QSO zou dubbel aankomen.",
  "t.i2f1r39jrg": "De laatste QSO’s in één oogopslag en de ADIF-export.",
  "t.i2yuljslky": "Met de contest uit zegt de balk “[[contest.none]]” en opent de knop “[[contest.calendar]]” de lijst van contests van de komende maanden, met “[[contest.cal.prepare]]” om er direct een te activeren (datums gemarkeerd met “[[contest.cal.check]]” moet je met de regels vergelijken).",
  "t.i46qbtc2t5": "“[[l4.title]]” (bovenaan; verschijnt alleen als Aurora de status kan lezen): Aurora leest, alleen-lezen, het SQLite-bestand van Log4OM 2 om te weten wie je al hebt gewerkt en om “nieuw DXCC”, “nieuwe band”… te markeren. Onder de titel zie je het pad (of “[[l4.none]]”) en hoe het is gevonden: “[[l4.srcAuto]]”, “[[l4.srcChosen]]” of “[[l4.srcEnv]]”; “[[l4.missing]]” als het bestand weg is. Je hebt het alleen nodig als je Log4OM gebruikt en het bestand niet vanzelf is gevonden of je er meer dan één hebt.",
  "t.i6a22fg6dk": "USB-stuurprogramma: open Apparaatbeheer van Windows en kijk onder “Poorten (COM en LPT)”: de poort van de radio moet daar staan, met de radio aan en de kabel aangesloten. Ontbreekt hij, of heeft hij een geel uitroepteken, dan ontbreekt het USB-stuurprogramma: installeer dat van de fabrikant (voor veel Yaesu-radio's is dat het Silicon Labs CP210x-stuurprogramma).",
  "t.i6hhzs4qvt": "Na elk beeld wordt je roepletters in FSK-ID uitgezonden, ook leesbaar voor MMSSTV (uit te zetten in Instellingen); bij ontvangst wordt het gelezen en in het log gezet. Ook als de VIS gemist is, wordt de mode herkend aan het ritme van de regels; het spectrum toont afstemmarkeringen en het binnenkomende beeld heeft ruisonderdrukking.",
  "t.i79tsd3b8m": "Het veld “[[dxcc.tryCall]]” (alleen als je het in de instellingen aanzet): typ een roepnaam om te zien welk land het is en of je het al hebt gewerkt, zonder het te roepen. Op de pagina [[nav.stats]] schakelen de knoppen “[[dxcc.view.station]]” en “[[dxcc.view.totals]]” van het land van het station naar de totalen.",
  "t.i8mhlawjed": "Als het signaal buiten het audiobereik van 200-2700 Hz komt, verminderen veel radio’s daar het vermogen.",
  "t.i8n91erpo5": "Linux: audio-uitvoer en pagina Radio",
  "t.idef94aflm": "[[sup.title]] · [[sup.openFolder]]: verschijnt alleen nadat een pakket is gemaakt; het opent Verkenner opnieuw met de zip al geselecteerd (om hem in een bericht te slepen).",
  "t.ihl64zzw7z": "Het tandwiel ⚙ (“[[dxmap.more]]”) opent de andere instellingen: “[[dxmap.spotMax]]” (van 5 minuten tot 6 uur: hoe oud de getoonde PSK Reporter-spots mogen zijn), “[[dxmap.background]]” (kleur), “[[dxmap.autoNight]]” met de nachtstijl en “[[dxmap.nightDark]]” (hoe donker), “[[dxmap.twilight]]”, “[[dxmap.moon]]”, “[[dxmap.animated]]” (bewegende lijnen), voor de propagatie “[[dxmap.spotPaths]]” en de kleur ervan en “[[dxmap.dots]]”, voor “Wie roept wie” de kleur, “[[dxmap.linkMeColor]]”, de dikte en de snelheid, en “[[dxmap.decay]]” (van 2 tot 60 minuten: hoe lang het duurt voordat een station vervaagt en verdwijnt).",
  "t.ihlpswr36n": "Pop-upmeldingen",
  "t.ihyk5hjoql": "[[sw.contest.title]] · [[contest.set.freqs]]: een rij knoppen met band, mode en kHz; hij verschijnt alleen als de regels frequenties noemen. Eén klik zet de radio op de voorgestelde frequentie voor die band en mode (CAT is nodig).",
  "t.ii6zt926fg": "“[[sat.ctl.title]]”: het keuzemenu “[[sat.ctl.transponder]]”, de “[[sat.ctl.downlink]]” (schuifregelaar), de “[[sat.ctl.txOffset]]”, de “[[sat.ctl.minEl]]” (0-60°), “[[sat.ctl.doppler]]” (met de status van de radio en de gecorrigeerde ontvangst- en zendfrequenties), “[[sat.ctl.rotor]]” en “[[sat.ctl.prepoint]]”. Onder elke schakelaar zegt een regel of de radio of de rotor verbonden is (“[[sat.ctl.radioReady]]”, “[[sat.ctl.rotorReady]]”, anders “[[sat.ctl.radioNot]]”, “[[sat.ctl.rotorNot]]”).",
  "t.ij4d5h0owr": "[[digi.mi.wideWaterfall]] (aan): de waterval toont 0-5 kHz; als het uit staat 0-3,5 kHz (sterker vergroot, maar wat boven 3,5 kHz ligt, is niet te zien).",
  "t.ijgxpkih5w": "Terwijl je zendt, verschijnt naast de macrobalk een rood TX-label; het knippert als [[digi.mi.flashTx]] aan staat in het menu [[digi.menu.view]].",
  "t.il6pe9mko5": "In het filter van Bandactiviteit tonen de knoppen “[[kind.new_state]]” en “[[kind.new_state_band]]” Amerikaanse stations uit een staat die nog nooit of nog niet op deze band is gewerkt. De staat komt van QRZ.com of HamQTH (roepnaamopzoeking aan), de gewerkte staten uit het Log4OM-logboek. Dezelfde twee keuzes staan ook in Automatisering: Auto antwoordt op CQ’s uit een nieuwe staat.",
  "t.imvizmlblk": "Aurora logt QSO’s zelf: je kiest alleen of je de gegevens eerst wilt controleren. De onderdelen staan in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.pg.qso]].",
  "t.io3xsh4zpc": "[[ap.text]] · [[ap.fontLog]]: het lettertype van de logtabel voor de modes PSK, RTTY en CW. “[[ap.fontLogData]]” (standaard) gebruikt het datalettertype; alternatieven JetBrains Mono, Cascadia Mono, Consolas, Lucida Console, Courier New, IBM Plex Sans.",
  "t.iquy6jdlvo": "De tekst staat in de taal van Aurora. Voor wat er na een update is veranderd, zie ook “Updates”.",
  "t.iuuvg0xxt0": "Het menu [[digi.menu.options]]",
  "t.ivlwl6go0j": "Alleen met Hamlib en een seriële poort: [[cat.baud]] (keuzes van 1200 tot 115200; “[[cat.default]]” gebruikt de standaardwaarde van het model). Hij moet gelijk zijn aan die in het CAT-menu van de radio: zijn ze verschillend, dan antwoordt de radio niet. Icoms met PTT via CAT willen 115200 (Aurora waarschuwt als het anders is), recente Yaesu’s meestal 38400. Hij verschijnt niet als de poort een netwerkadres is.",
  "t.iw2zdrzz5u": "Als de DXpeditie niet zegt Fox/Hound te gebruiken, roep haar dan als een gewoon station, zonder [[ctl.hound]].",
  "t.ix2lj2j36a": "De andere filters van dit paneel (minimumsignaal, minimale en maximale afstand, berichten aan mij verbergen, mijn uitzendingen verbergen, alleen bepaalde banden) staan in het vak “[[bfl.title]]” van [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; daar schrijf je ook de roepnamen die je altijd of nooit wilt zien en de bypass die even alles toont (zie “Filters op roepnaam, prefix en al gewerkt”).",
  "t.ix83n1ftf8": "Contest: toetsenbord en commando’s",
  "t.iyhnvsq502": "Kolom [[freq.region]] (keuzelijst): [[gen2.regionAll]], [[gen2.region1]], [[gen2.region2]] of [[gen2.region3]]. Ze zegt tot welke regio die frequentie behoort. Een rij van een andere regio dan je koos blijft in de tabel maar wordt grijs en niet gebruikt (bij aanwijzen verschijnt “[[freq.hidden]]”).",
  "t.iz5pfbc3oq": "[[nav.settings]] › [[sw.sec.station]] › [[tab.clock]]. Bij FT8 en FT4 moet de klok van de pc goed staan: bij meer dan een halve seconde afwijking gaan berichten verloren en decoderen anderen jou niet. Aurora vraagt NTP-servers om de tijd, toont de afwijking en kan de Windows-klok corrigeren. Op Linux is er geen correctie: het systeem synchroniseert de tijd.",
  "t.j2ivm9tewh": "Onderaan de pagina, in kleine letters, staat “[[sstv.credits]]”: dit zijn de vermeldingen van de SSTV-algoritmes en de gebruikte lettertypen. Er valt niets in te stellen.",
  "t.j3fb4ocirw": "Gekoppelde telefoons en tablets tonen één enkele pagina, het Station, als afstandsbediening. Met een smal venster (onder 768 punten) is het een compacte afstandsbediening; de tablet in landschap (van 768 tot 1366 punten, op een afstandsbediening of aanraakapparaat) heeft twee kolommen. De Instellingen, de andere pagina’s en de aparte vensters gebruik je alleen vanaf de pc.",
  "t.j4prr3dmlw": "Een net gelogd QSO knippert bovenaan met het label “[[log.loggedBadge]]”. Met het tabblad “[[log.tab.map]]” open schakelt het paneel bij elk gelogd QSO even naar het Log, toont de nieuwe rij en gaat dan terug naar de kaart.",
  "t.j5fi51ynwf": "Ctrl+klik op de waterval plaatst daar een notch van 30 Hz breed; die verzwakt dat gebied met minstens 60 dB en laat wat er net naast ligt ongemoeid. Je kunt er zoveel plaatsen als nodig.",
  "t.j6pvv3dir9": "[[sw.pg.alerts]]",
  "t.jalszt5fa9": "[[sstv.set.grpSave]] · [[sstv.set.saveTx]] (standaard aan): de beelden die je zendt worden ook opgeslagen in de beeldenmap, zodat je terugvindt wat je hebt verstuurd. Zet het uit om te voorkomen dat de schijf vol raakt.",
  "t.jba2d6esut": "Aurora zelf CQ laten roepen",
  "t.jfubj1ok0m": "Als er geen berichten in de buurt van de Rx-frequentie zijn, zegt het venster “[[rxw.empty]]”.",
  "t.jl8kri6815": "De pagina’s in de bovenbalk",
  "t.jlzjxdm1u3": "Kies, nog steeds in “Fast QSO”, in het menu onder “Auto-Save” “UDP 12” (dat krijgt alle QSO-gegevens) en vink “Auto-Save” aan als je wilt dat het QSO aan het eind vanzelf wordt gelogd.",
  "t.jm6lo2sihu": "[[auto.b1]] · [[auto.direction]] (standaard aan): een “CQ NA” roept alleen Noord-Amerika en een “CQ DX” alleen stations buiten het continent van de roeper; met het vakje aan antwoordt Aurora niet als de CQ niet voor jou bedoeld is. Hiervoor moet je roepnaam ingesteld zijn in [[sw.pg.personal]].",
  "t.jn63pyd2e4": "Het RX-venster staat boven het paneel Log (het staat standaard aan) en toont alleen wat je ontvangstfrequentie aangaat: de stations die zenden waar de groene Rx-markering staat (±50 Hz; ±100 Hz in MSK144), de berichten aan jou en je eigen uitzendingen. Het is het venster “Rx Frequency” van WSJT-X. Om alleen de DX te volgen, zet je de Rx-markering op hem.",
  "t.jnbws1wb1i": "Decoderopties van WSJT-X",
  "t.jqgnx0ut2y": "De Gids: zoeken",
  "t.js771xsd16": "Twee programma's die tegelijk de radio besturen storen elkaar. Beter is dat alleen Aurora met de radio praat en de andere programma's Aurora vragen.",
  "t.jsguk5ilg7": "Open [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].",
  "t.jtku7j7w4c": "Rechtsklik op een vak: [[digi.mi.squelch]], [[digi.mi.afc]], Lock, [[digi.mi.snap]], “[[digi.st.threshold]]”, de UTC-klok (die verschijnt in de balk) en [[digi.mi.flashTx]].",
  "t.jv8j62bx7p": "“[[panel.all]]”: de lijst met ontvangen berichten, met je eigen Tx-regels ertussen. Tik op een bericht om dat station te antwoorden (dubbelklikken hoeft niet); een tweede tik op hetzelfde bericht binnen 2 seconden wordt genegeerd. De landenvlaggen staan altijd aan.",
  "t.jwzd5j6sbj": "Het thema wijzigen: in de onderbalk, rechts, het themapictogram (maan = donker, zon = licht, half gevulde cirkel = automatisch). Elke klik gaat naar het volgende, in de volgorde donker, licht, automatisch; “automatisch” volgt het Windows-thema en verandert mee. Standaard is het donker. Dezelfde keuze staat in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (item “[[ap.theme]]”), waar je ook “[[ap.contrast]]” en de tekstgroottes vindt. Op de telefoon staat het thema rechtsboven, in de afstandsbedieningsbalk.",
  "t.jykexm1ajm": "Andere labels: “Queue” gevolgd door een getal (het station staat in de wachtrij, het getal is zijn plaats) en “Fox” (een DXpeditie in de modus Fox/Hound).",
  "t.jz1muqdbh4": "“[[acc.open]]”: geen code voor wie op het thuisnetwerk zit. Het staat standaard aan, dus thuis is geen code nodig; via internet is de code altijd vereist. Dit wijzig je alleen vanaf de pc. Een pagina van een andere website die in de browser op dezelfde pc openstaat, kan de status (roepnaam, locator, log) niet lezen en de radio niet laten zenden.",
  "t.k027ipmga7": "Kies de [[fox.slots]] (tot 5 stations in dezelfde zending) en voor wie de CQ is.",
  "t.k0pdpxs4gf": "Na het verzenden van een spot controleert Aurora anderhalve minuut de openbare lijst van DXSummit: de dienststatus meldt “spot gepubliceerd” als de spot er echt staat, of “geaccepteerd maar niet gepubliceerd”.",
  "t.k3v40fpncz": "[[bak.title]] · [[bak.make]]: maakt op het Bureaublad een zip Aurora-impostazioni-….zip met alle instellingen (station, radio, audio, meldingen, kleuren, panelen) en het QSO-logboek, en zegt de naam en het aantal bestanden. Wachtwoorden en dienstsleutels (QRZ, LoTW, ClubLog…) zitten er niet in. Wanneer: voordat je Windows opnieuw installeert, van pc wisselt of riskante tests doet.",
  "t.k42gvylxxy": "Het logboek van Aurora en dat van de gekoppelde programma’s beheer je elders ([[nav.log]] en [[nav.settings]] › [[sw.fam.log]]): hier zie en bewaar je alleen de QSO’s van Aurora.",
  "t.k4jp7vlfoq": "De balk heeft 4 rijen van 12 toetsen (F1-F12), in groepen van 4: de eerste zonder modifiers, dan “Ctrl”, “Shift” en “Ctrl+Shift” (het label staat rechts van elke rij). Elke knop heeft de kleur van zijn macro; die zonder label zijn leeg.",
  "t.k6p28xt2zh": "[[sw.p.operator]] · [[sw.p.name]] en [[sw.p.qth]]: je naam en je woonplaats. Het zijn dezelfde velden als “[[digi.f.myname]]” en “[[digi.f.myqth]]” op de pagina PSK·RTTY·CW en ze vullen de woorden <MYNAME> en <MYQTH> van de macro’s. Ze worden meteen opgeslagen.",
  "t.kbiuvbcx2e": "Elke rij is een gedecodeerd bericht: tijd, rapport, tekst, land met vlag en afstand. De labels rechts geven aan wat er bijzonder aan is.",
  "t.kdcexiomd2": "“[[cta.log.section]]” · “[[logio.export]]” en “[[logio.import]]”: exporteer het interne logboek als ADIF en importeer je geschiedenis, zoals in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.files]].",
  "t.kezkywakhh": "Schrijf in [[gen2.bandHopList]] de items gescheiden door komma’s: «FT8 20m», «FT4 40m» of een frequentie in kHz zoals «14090».",
  "t.khtearoamd": "Radio delen met Log4OM via Cat4OM",
  "t.kj0vm43jhh": "Lampje, “[[ens.test]]” en resultaat: in de vakken voor spots en opzoekingen werken ze zoals in [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]]; in “[[onl.grpSolar]]” en “[[onl.grpDxped]]” zegt het lampje of de dienst aan staat en doet “[[ens.test]]” één enkel verzoek, los van de periodieke. De WSPRnet-spot (“[[ens.g.wsprnet]]”, “[[ens.k.WSPRnetUpload]]”, standaard uit) staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.wspr]].",
  "t.kjki0dxvs4": "Rood label: dat station roept jou.",
  "t.kkxhny9u39": "Hij opent via [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] › [[ca.title]] met “[[ca.run]]”. Hij controleert vijf dingen en toont bij elk een teken: ✓ alles goed, ! even naar kijken, × oplossen, … nog aan het meten. Bovenaan vat een regel het samen: “[[ca.allOk]]” of “[[ca.someBad]]”. Hij verandert geen enkele instelling.",
  "t.kmxlgvb2wl": "[[nav.stats]]",
  "t.knqavm0mr8": "Het paneel toont spots voor de gebruikte band: op een stille band kan het leeg blijven. Probeer een andere server.",
  "t.koakbxorqp": "CW: pompende radio en ruisstoten",
  "t.komauxu99x": "De typische fout: de handleiding zegt 88h en jij schrijft 88. Maar 88 in decimaal is 58h, een andere radio, en de Icom antwoordt niet. Aurora merkt het: onder het veld verschijnt een klein briefje met het getal in hexadecimaal en het getal dat je moet schrijven, met een knop “Gebruik” die het voor je invult. Druk erop als het getal dat je typte dat van de handleiding was.",
  "t.kq89c29o3a": "Het logboek sturen naar wie je helpt",
  "t.kqsb0dhg8a": "De pagina is leeg: Aurora draait niet met zijn eigen engine of kan zijn instellingen niet lezen. Start Aurora opnieuw en open de pagina nog een keer.",
  "t.ktd4qpq0wc": "Bovenbalk: het label RX (groen) of TX (rood); het bandmenu en het modusmenu (grijs als de radio niet wordt bediend; als je zendt, vraagt Aurora om bevestiging voordat je ze wijzigt); de knop met de watts (het echte vermogen dat de radio zendt): een tik opent − en +, waarmee je het vermogen van de radio met 5% verhoogt of verlaagt; de seconden van de periode; de knop ⟳ die de pagina opnieuw laadt vanaf de pc (“[[phone.refresh]]”); het themapictogram. Daaronder toont een balk de voortgang van de periode.",
  "t.ku7gfu5kxq": "[[bak.note]]",
  "t.kut2fdg4rz": "Modus JT4",
  "t.kvszyri4pd": "[[sw.pg.digiMacros]] · “[[sw.macros.new]]”: opent de editor op de eerste nog vrije toets, geldig voor alle modi; je kunt de toets in de editor veranderen. “[[sw.macros.edit]]” opent de macro van die rij.",
  "t.ky57cmhior": "Met “UP N” in de opmerking (bijvoorbeeld “UP 5”) is de spot een DXpeditie in split: het zenden schuift N kHz boven het ontvangen op, tot 3,5 kHz audio; daarboven verschijnt een melding en blijft het zenden waar het is. Echte DX Split, met de radio in split, doe je vanuit het DX Cluster in de Instellingen.",
  "t.l04og0i7fm": "Dubbelklik op de CQ-rij: het antwoord start meteen, daarna gaat [[ctl.enable_tx]] aan en een melding zegt “Answering …”. Aurora zendt in de juiste periode. Als je al zendt en het nieuwe station in dezelfde periode moet worden geroepen, stopt de zending niet: het bericht wisselt direct om.",
  "t.l1o8ofw5m5": "“[[lay.settings]]” · “[[cluster.max]]” (standaard 500, 50 tot 2000): hoeveel spots in het geheugen blijven; de oudste worden het eerst weggegooid. “[[cluster.age]]” (standaard 60, 5 tot 1440 minuten): hoe lang het duurt voordat een spot wordt weggegooid; een oude spot is zelden nog nuttig, 60 minuten is prima. Een waarde buiten de grenzen toont de rode waarschuwing en wordt niet opgeslagen.",
  "t.l2bm1ohmkn": "Een optie vinden in Instellingen",
  "t.l347ug8vj8": "De opdracht van de auteur (“[[about.dedica]]”) en vier alleen-lezen vakken: “[[about.author]]”, “[[about.license]]” (GPL-3.0: vrije software, zonder garantie), “[[about.derived]]” (de programma’s waarvan delen van Aurora zijn afgeleid) en “[[about.thanks]]” (de projecten waarop Aurora steunt).",
  "t.l37l2iejae": "Het blok “Open banden”",
  "t.l5a66cqtcd": "Een station in de lijst heeft logboeken geüpload, maar dat betekent niet dat het jouw QSO zal bevestigen: de balk is slechts een hint.",
  "t.l61o9lspas": "[[toast.grp]] · [[toast.show.ok]] en [[toast.show.info]]: welke soorten bericht je wilt zien (beide standaard aan). Haal het vinkje bij [[toast.show.ok]] weg om geen bevestigingen van succes meer te zien, bij [[toast.show.info]] voor informatie. “[[toast.show.error]]” staat altijd aan en is niet te wijzigen: een fout moet je zien.",
  "t.l6a5njy109": "“[[cop.spots]]” · [[cop.expire]]: spots die ouder zijn dan 5, 10, 15, 20, 30, 60 of 120 minuten verdwijnen; “[[cop.never]]” (standaard) bewaart ze zolang de cluster ze bewaart.",
  "t.l7n1vo4azh": "Logboek op een andere pc: de Windows-firewall van die pc moet UDP op de gekozen poort doorlaten.",
  "t.l87e21wi4x": "[[tab.bands]]: een knop met een selectievakje voor elke band, van 2200 m tot 1,25 cm (25 in totaal); met een klik zet je hem aan of uit in de balk. Standaard staan de banden van 160 m tot 2 m aan (160, 80, 60, 40, 30, 20, 17, 15, 12, 10, 6 en 2 m); 2200 m, 630 m, 8 m, 4 m, UHF en microgolven zet je hier aan. Er blijft er altijd minstens één aan, en de band waarop de radio staat wordt altijd getoond, ook als je hem hebt uitgezet.",
  "t.la4o0nopgh": "Open altijd eerst Aurora en daarna de andere programma's.",
  "t.lbkhtx7nap": "Op de SSTV-pagina’s zijn de toetsen anders: F1 zendt het beeld, Esc stopt het. Pause en dubbele Esc zoals hier bestaan niet in SSTV.",
  "t.lfdi5hk4iu": "Adresregel: hij zegt welk adres van de pc in de QR is gezet (virtuele adapters van WSL, Hyper-V, VirtualBox en VPN’s zijn uitgesloten). Is hij in plaats daarvan rood, “[[net.noAddress]]”: dan heeft de pc geen adres op het thuisnetwerk, controleer de kabel of het wifi van de pc.",
  "t.lhlcu1lnyx": "Linksonder de legenda: QSO (vierkant gewerkt volgens het logboek), QSL (bevestigd), QSX (verkeer in de lucht, niet met jou), CQ, CQDX en QRZ (wie jou roept). Tijdens het zenden loopt een rode lijn naar het station dat je roept.",
  "t.ljgxl1otvw": "[[tab.waterfall]]",
  "t.ljp664ufso": "Frequentielijst",
  "t.ljvyi8gwq2": "“[[digi.cw.som]]”: om een onregelmatige sleutel met de hand te ontvangen, kiest het het teken dat het dichtst bij de duur van punten en strepen ligt. Standaard uit; zet het alleen aan bij stations die niet regelmatig seinen.",
  "t.llqr8x2afi": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › “[[dec.slowPc]]”.",
  "t.lm0kqndiaf": "[[auto.b1]] · [[auto.minSnr]] (getalveld, −30 tot 20, standaard −18): antwoordt niet op signalen die zwakker zijn dan deze waarde. Verhoog hem als je tijd verspilt aan signalen die nooit afgerond worden.",
  "t.lma1pzkqzp": "Wachtwoorden en sleutels: typ ze in het veld en druk op Enter (of verlaat het veld); het veld toont “[[ens.pw.saving]]” en blijft in behandeling tot je onderaan op “[[sw.save]]” drukt. Na het opslaan toont het “[[ens.pw.savedShort]] ••••” met “[[ens.pw.change]]” en “[[ens.pw.remove]]”, en pas dan start de “[[ens.test]]” van het vak vanzelf. QRZ.com en HamQTH-opzoeking staan in “[[sw.fam.log]] › [[tab.online]]”: als je in het DX Cluster boven de DE-roepletters zweeft, zie je vlag, land en, als dat aanstaat, naam en plaats.",
  "t.lnzas6uggy": "Paars label: dat station heeft op jouw oproep geantwoord.",
  "t.lofyx0j9l8": "MSK144 is voor meteorscatter-verbindingen op 6 m en 2 m: T/R-periodes van 5, 10, 15 of 30 s (standaard 15 s), berichten in FT8-stijl, een frame van 72 ms dat de hele periode wordt herhaald, zodat één meteoorping genoeg is om het te ontvangen. Aurora zendt altijd op 1500 Hz (tonen op 1000 en 2000 Hz). De frequenties hangen af van de regio: 50,260 MHz (regio 2 en 3) of 50,380 MHz (regio 1), 144,150 of 144,360 MHz.",
  "t.lp5bjra62j": "«Log QSO» voor luisteraars en «Aanzetten» met Cat4OM en Yaesu",
  "t.lt1g4snzrv": "Test: druk op “[[sw.testCat]]”: er moet staan dat CAT verbonden is. Daarna “[[sw.testPtt]]”: de radio zendt een seconde, gebruik dus een kunstantenne of een geschikte antenne.",
  "t.ltr731tee7": "De waterval, de cursor en het afstemmen",
  "t.lwx664rkmh": "Opdrachtbalk: “[[fox.off]]” / “[[fox.on]]” (schakelaar van de Foxmodus: aan roept hij CQ in de even periodes, onder 1000 Hz; hij is vergrendeld als een contest Fox/Hound verbiedt), “[[fox.enableTx]]” (zonder dit luistert de Fox maar zendt niets), de knop “[[stop.button]]”, de ontvangstbediening (zoals in “De rij met ontvangstbediening”) en “[[ctl.split]]”. Een vak onder de balk waarschuwt als de frequentie beschermd is (de Fox zendt niet binnen 3 kHz van de standaard FT8-frequenties) of als Enable Tx ontbreekt (“[[fox.needTx]]”).",
  "t.lz8o4djfla": "Als de zender na het beeld zijn roepnaam in FSK stuurt (FSK ID, zoals MMSSTV), leest Aurora die, toont die boven het beeld en schrijft die in de geschiedenis en in het veld “[[sstv.log.call]]” van “[[sstv.log.title]]”. Met een roepnaam in het log zoekt Aurora het station meteen op met de ingestelde opzoekdienst (QRZ.com of HamQTH) en vult lege velden voor naam, QTH en locator in; het land komt uit cty.dat. Jouw uitzendingen eindigen met jouw roepnaam in FSK: uit te zetten in [[sw.sec.sstv]] › “[[sstv.set.fskId]]”.",
  "t.m1mikxn0cs": "Hij opent via [[nav.news]] in het tandwielmenu. Hij toont de laatst toegevoegde, gewijzigde of verholpen functies, te beginnen bij de nieuwste, met datum en tijd van de release in de tijd van je apparaat.",
  "t.m2g71pdfzc": "[[gen.screen]] · [[gen.showDt]] en [[gen.showAge]]: twee selectievakjes. [[gen.showDt]], standaard aan, toont de kolom DT (tijdverschil van het signaal): zet hem uit om ruimte te winnen. [[gen.showAge]], standaard uit, is hetzelfde selectievakje als in het filtervak: de leeftijd van het bericht in plaats van de tijd.",
  "t.m30ab28chi": "De radio bedienen vanaf het display",
  "t.m4pf4no6od": "[[sw.tab.freq]]",
  "t.m6993g2prk": "Update: een nieuwe versie van Aurora (vergeleken met de laatste release op GitHub). Hij verschijnt altijd, ook bij “Niet storen”; één kaart per versie, met het eerste nieuws in jouw taal (Engels als het ontbreekt). Hij kan niet worden uitgezet.",
  "t.m6idsn0x5e": "Er worden hoogstens de laatste 500 QSO’s gelezen en 300 getoond (met zoeken, uit de laatste 500). Als het logboek leeg is, verschijnt “[[digi.log.empty]]”.",
  "t.m6kmcc5gc2": "[[sstv.set.grpView]] · [[sstv.rx.smooth]]: het vergrote beeld in de viewer wordt afgevlakt getoond in plaats van met scherpe pixels. Het werkt meteen, ook op de SSTV-pagina die al open staat in het hoofdvenster, zonder “[[sw.save]]”.",
  "t.m7jeynxmkm": "“[[sstv.undo]]”, “[[sstv.redo]]” en “[[sstv.clear]]”: ongedaan maken en opnieuw doen (tot 60 stappen), en helemaal opnieuw beginnen (verwijdert ook de foto).",
  "t.m8grk4plxr": "[[gen.screen]] · [[gen2.blank]]: selectievakje, standaard uit. Zet een lege regel tussen twee decodeerperiodes, om de groepen berichten te scheiden.",
  "t.maf11lah0w": "LogHX (gratis logprogramma van RX4HX, rx4hx.qrz.ru, versie 3.1) ontvangt Aurora zoals het WSJT-X, JTDX en MSHV ontvangt: QSO’s worden vanzelf gelogd en het venster “Active calls for FT8” toont de gedecodeerde stations. Je hebt een bestemming in Aurora nodig en de instelling van het digitale programma in LogHX, met dezelfde poort.",
  "t.md469p3nwa": "Gekoppelde programma’s en logboeken",
  "t.mg376v0hgd": "De niveaus Rx en Pwr",
  "t.mjs7qkmw16": "“[[agent.kind.prop]]”: een geomagnetische storm (K-index vanaf 5: de HF-banden zijn verstoord) en de dagopening van 12 en 10 meter (“goede” condities). Hoogstens eenmaal per dag voor elk; de gegevens komen van hamqsl.com. Standaard “Alleen pictogram”.",
  "t.mlg298riw3": "Als er iets niet klopt in het station, verschijnen rechtsonder kleine kaartjes, van de ernstigste (rood) tot de mildste (lichtblauw, alleen informatie). Ze verdwijnen vanzelf als het probleem weg is. In de eerste 20 seconden na het openen wordt niets getoond: de radio en de audio zijn nog aan het opstarten. Elk kaartje heeft een × om het te sluiten (het blijft dicht tot het probleem verandert) en waar nodig de knop “[[diag.fix]]” die de juiste instellingenpagina opent.",
  "t.mmhe3h3f3f": "[[sw.wspr.beacon]] · [[mode.wsprType1]]: aan/uit-knop, standaard aan. Aan: de baken stuurt berichten van type 1 (roepletters, locator van 4 tekens, vermogen). Uit en met een locator van 6 tekens wisselen type 2 en 3 elkaar af; samengestelde roepletters wisselen ze altijd af. Zet hem alleen uit als je de locator van 6 tekens wilt versturen.",
  "t.mmqss4kp96": "Frequenties uit de bandplannen van ARI",
  "t.mpl8zhta2f": "Meldingen uitzetten of wijzigen: gemarkeerde kaarten, geluiden, kleuren, berichten",
  "t.mq1k5uusds": "De instelling wijzig je in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].",
  "t.ms98humib0": "Controleer de klok: als de tijd niet klopt verschijnt bovenaan een gele waarschuwing.",
  "t.mu6kilv7ft": "[[ens.g.alltxt]] · [[ens.k.WriteDecodedDebugALLTXT]] (standaard uit): zoals het vorige, plus de diagnoseregels van de decoder. Het is alleen om een probleem op te sporen en het bestand groeit snel. De twee vakjes sluiten elkaar uit: het ene aanvinken haalt het andere weg.",
  "t.mumakf3c5g": "[[clock.state]] · [[ens.test]] (knop onderaan het vak, met de led naast de titel): doet een afwijkingsmeting zoals “[[clock.check]]”, zonder te corrigeren, en schrijft de uitkomst op (“[[ens.test.ok]]” of “[[ens.test.err]]”). De led brandt alleen als de periodieke controle aan staat, en een test draait vanzelf als je de pagina opent.",
  "t.mwa1bssphr": "Volledig onderdeel: «[[sw.tab.appearance]]»; «Taal, thema en volume vanuit de balk».",
  "t.mwp5gnujxp": "[[auto.b4]] · [[auto.countries]] (keuzelijst “[[auto.addCountry]]” en rij labels): kies uit de DXCC-lijst de landen waarop Aurora nooit antwoordt; elk land verschijnt als label met een “×” om het te verwijderen. Ontbreekt de lijst, dan verschijnt “[[auto.noCty]]”: het prefixbestand cty.dat is nodig.",
  "t.mwsxzvzz2w": "Bovenaan het venster staan links de modispillen; rechts staan de pagina’s (zie “De pagina’s in de bovenbalk”). Het logo “AURORA” links brengt je altijd terug naar de pagina [[nav.station]]. De verlichte pil is waar je nu bent.",
  "t.mx5tdz2veh": "[[digi.log.cols]]: het potloodpictogram opent de lijst met kolommen die je kunt tonen (QSO, Modus, Band, Frequentie, Datum, UTC, Roepnaam, Naam, QTH, Land, Locator, RST verzonden, RST ontvangen). Standaard ontbreken Band, Land en Locator. Daarin staan ook “[[digi.log.fitAll]]” en “[[digi.log.resetWidths]]”.",
  "t.mxutp0qmdu": "De toetsen en knoppen die het zenden aan- en uitzetten op de pagina [[nav.textModes]].",
  "t.mydz7a6b1f": "Controles als de waterval signalen toont maar de lijst leeg blijft.",
  "t.mzw20jxh0r": "[[bak.title]]",
  "t.n0te1iliz3": "RTTY: ontvanger, squelch en RTTY-instellingen",
  "t.n0yhuwvn4l": "Kies bij “[[rd.layout]]” hoe het display en het uitgebreide display rechtsboven staan: [[rd.layout.single]], één scherm met een grote VFO A links en VFO B met de indicatoren rechts, of [[rd.layout.pair]].",
  "t.n1ddyvx0eu": "[[aud.input]] · [[aud.inch]]: “[[aud.ch.mono]]” (standaard) telt de twee kanalen samen; “[[aud.ch.left]]” of “[[aud.ch.right]]” gebruiken één kanaal (nodig als de radio het geluid maar aan één kant stuurt). Links en Rechts vragen een stereo-ingang; bij een mono-ingang zijn ze in de lijst uitgeschakeld.",
  "t.n2i5d715xd": "Als “Bandactiviteit” leeg lijkt, kijk dan meteen naar de knop “[[bfl.button]]”: met een getal ernaast is er een filter actief. Het bericht “[[bfl.empty]]” bevestigt dat.",
  "t.n362wxiqb": "“[[ens.g.udp]]” · “[[ens.test]]”: controleert adres en poort en stuurt een Heartbeat naar het verbonden programma. Hij start niet vanzelf als de pagina opent. Het lampje van dit vak volgt geen schakelaar (de server ontvangt altijd) maar de laatste test. De onderdelen “[[ens.k.udpWindowToFront]]”, “[[ens.k.udpWindowRestore]]” en “[[ens.k.ApplyFiltersToUDPmessages]]” bestaan in het programma maar zijn nog niet aangesloten: ze staan niet op de pagina.",
  "t.n442lclnlg": "[[sup.title]] · [[sup.email]]: tekstveld (standaard leeg) voor het e-mailadres van wie je helpt. Het wordt vanzelf bewaard in dit programma en wordt alleen gebruikt door de knop “[[sup.sendMail]]”: het wordt nergens heen gestuurd.",
  "t.n7ix4l0ynj": "[[digi.menu.file]] › [[digi.mi.macrosReset]]: herstelt de fabrieksmacro’s van Aurora (de basismacro’s, die per modus en de keuze voor samenvoegen) en bevestigt met “[[digi.mi.macrosRestored]]”. Het wist al je wijzigingen in de macro’s: gebruik het alleen als je helemaal opnieuw wilt beginnen. Het werkt alleen vanaf de pc waarop Aurora draait.",
  "t.n8y9xbw3hv": "Waterval: linkermuisknop = Rx-frequentie, rechtermuisknop of Shift + klik = Tx-frequentie; Tab om naar een balk te gaan en pijltjes links/rechts om hem te verplaatsen (10 Hz; Shift = 50 Hz).",
  "t.ndtnjju5b1": "Het paneel Opdrachten: elk veld en elke knop",
  "t.neot2ye04o": "“[[sstv.img.reply]]” (bij de ontvangen beelden): neemt het beeld als achtergrond mee naar de editor en zet de roepnaam van het station als het andere station. “[[sstv.img.useBg]]” (bij de verzonden beelden): gebruikt je beeld opnieuw als achtergrond.",
  "t.nev1yvtq4u": "Kolommen: [[digi.band.colFreq]] (de echte frequentie in kHz als de radio is verbonden, anders de toon in Hz), WPM (alleen CW), S/N in dB, [[digi.band.colCall]] (met vlag, en CQ of DE; schuin gedrukt tot het is geverifieerd, met het land en de verificatiestatus in de tooltip) en [[digi.band.colText]] (de laatste 44 tekens, met de onzekere in grijs).",
  "t.nf4vt4d9bj": "CW: snelheid, toon en seinen",
  "t.nha4xj6b1q": "Als er geen zending start, kijk dan eerst naar [[ctl.enable_tx]]: dat is de enige die aan moet staan om een bericht te sturen; de andere bepalen hoe het QSO verdergaat.",
  "t.ni3j4te482": "[[diag.crashFolder]] · [[diag.openCrashFolder]]: de knop van het vak, die alleen verschijnt als de pc de crashmap heeft (%APPDATA%\\Aurora\\crash). Hij opent de map waarin Aurora elke storing vanzelf vastlegt: een leesbaar .txt-bestand en, bij vastlopers en fouten, een .dmp-minidump. Wanneer: om de bestanden van de dag van het probleem samen met het logboek aan een melding toe te voegen. De laatste 10 dumps en 50 teksten worden bewaard.",
  "t.niq3ak0vdy": "[[auto.b3]]: pogingen en pauze per station, hoogstens zoveel QSO’s per uur (0 = geen limiet) en, als je wilt, een tijdvenster in lokale tijd: daarbuiten wacht de automatisering.",
  "t.njebvowq6y": "Het tweede tabblad toont de QSO die je aan het maken bent (de lichtblauwe rij bovenaan) en daaronder de QSO’s van het logboek van Aurora, de nieuwste bovenaan. In de lichtblauwe rij schrijf je direct.",
  "t.nqnhn7ihgv": "PSK, RTTY en CW: open uitzending en live typen",
  "t.nqqoolfn1p": "Kop: hoeveel signalen er zijn, hoeveel er CQ roepen (hun rijen zijn gemarkeerd) en de opmerking dat grijze tekens onzeker zijn. De knop “[[digi.band.clear]]” maakt de lijst, de geschiedenis en de roepnamen op de waterval leeg; signalen die er nog zijn, komen vanzelf terug.",
  "t.ntactuqu62": "Alleen met Cat4OM: [[cat.cat4om.management]] (fabriekswaarde 127.0.0.1:17300: vanaf hier vindt Aurora de groep en de poort zelf; vanaf een andere pc schrijf je het adres van die pc), [[cat.cat4om.group]] en [[cat.cat4om.address]] (laat ze leeg: de grijze hint toont “[[cat.cat4om.auto]]” of wat is gevonden; schrijf de Control, bijvoorbeeld 127.0.0.1:5001, alleen als het beheer niet antwoordt of om een wachtwoord vraagt), [[cat.cat4om.key]] (het wachtwoord van de groep, alleen als dat nodig is) en [[cat.cat4om.radio]] (de naam van de radio in Cat4OM, bijvoorbeeld kenwood/ts-990; leeg = “[[cat.cat4om.firstRadio]]”).",
  "t.nulgf3f4er": "“[[wft.spec]]”: het uitklapmenu voor het spectrum onder de waterval: “[[wfs.specOff]]” verbergt het, “[[wfs.current]]” toont het laatste spectrum, “[[wfs.cumulative]]” het gemiddelde van de hele periode. De hoogte wijzig je door de grijze greep boven het spectrum te slepen (“[[wf.specHeight]]”).",
  "t.nvlesdka3p": "Voor wie een DXpeditie bedient: de klassieke Fox-modus, in test. Geen SuperFox.",
  "t.ny812tiou9": "Squelchdrempel: S/N van -30 tot +20 dB (standaard -15), gemeten in 3 kHz zoals in WSJT-X. Je stelt hem in in het venster “[[digi.ms.title]]”; onder ongeveer -16 dB wordt niets getoond, ook niet met squelch uit.",
  "t.o2wnagggwo": "Dubbelklik op een bericht: je antwoordt (“[[gen.dblReply]]” is nodig). Rechtsklik op een bericht: in de wachtrij. Rechtsklik op een roepnaam: menu “Openen op QRZ.com”. Dubbelklik op “RX” in het paneel Zenden: maakt de DX vrij. Dubbelklik op een QSO in het Logboek-paneel: corrigeren of verwijderen.",
  "t.o5q8pcv1eb": "[[cat.backend]]: kies Hamlib. Met Hamlib krijg je ook de echte S-meter, het vermogen, de SWR en de ALC van de radio.",
  "t.o6jgv7ztqw": "PSK en RTTY: pagina en weergaveopties",
  "t.o7la0shcta": "Gevoeliger FT8-decoderen",
  "t.o7u6dgxoz1": "Aurora leest de opmerking: “UP 5”, “UP5”, “5 UP”, “5UP”, “10up”, “DN 2” of “DOWN 2” (eronder), “QSX 14.030” of “QSX 030” (waar ze luisteren). “UP” alleen betekent 1 kHz; “UP 1-3” betekent het midden, 2 kHz. Getallen in kHz, hoofdletters of kleine letters. In de spotregel staat een label “UP 5”: erboven zweven geeft aan waar het zenden heen gaat. “UP 14.0305”, “QSX 21.2” en frequentiebereiken worden goed gelezen, en een locator zoals “DN31” wordt niet voor “DN” aangezien.",
  "t.ob26wcoizj": "[[sw.digi.perMode]] · CW, “[[digi.band.mi]]” (standaard aan): decodeert elk CW-signaal in de audioband met een eigen ontvanger, in een aparte thread die hooguit een kwart van één kern gebruikt (bij te veel signalen houdt hij de sterkste). Hij voedt de signaallijst van de werkpagina.",
  "t.obv8pioqff": "Opties: “[[fox.slots]]” van 1 tot 5 (hoeveel stations je in dezelfde periode bedient: meer slots = sneller, maar het vermogen wordt verdeeld); “[[fox.cq]]” (CQ naar iedereen of alleen naar één continent of naar de DX); de schakelaars “UltraFOX” (één breed signaal van 750 tot 2260 Hz met maximaal 9 stations), “[[fox.moreCqs]]” (stuurt de CQ ook in periodes met bezette slots) en “[[fox.autoQueue]]” (zet de roepers vanzelf in de wachtrij, te beginnen bij het beste signaal); “[[fox.reset]]” leegt de roepers, de wachtrij en de lopende QSO’s en zet de tellers op nul.",
  "t.odsygsknkv": "“[[cluster.servers]]” (rechts van de titel het aantal, bijvoorbeeld 3/8): een lijst met servers, maximaal 8. Standaard: HamQTH (hamqth.com), N2KI New York (dxc.n2ki.com) en Hamcloud (dx.hamnet.network), allemaal op poort 7300. Elke rij heeft: een lampje (groen = bereikbaar, met milliseconden; rood = onbereikbaar, met de reden; grijs = bezig met controleren), naam en adres:poort, het vak “[[cluster.server.on]]” (gebruik deze server; haal het vinkje weg om hem in de lijst te houden zonder te verbinden) en “[[cluster.server.remove]]”. Met meerdere servers worden identieke spots maar één keer getoond.",
  "t.ofqqiq0io6": "Linksboven op de pagina [[nav.station]], boven de waterval, staan de modusselectie en de frequentieselectie. Ze werken als de radio met CAT wordt bestuurd; zonder CAT wijzig je de modus op de radio (of op de pagina) en Aurora decodeert nog steeds.",
  "t.ogq8ylljk0": "QMAP: elke Q65 in een stuk van de band",
  "t.ogxbunrapx": "Aurora downloadt elke dag de openbare lijst van de ARRL met LoTW-gebruikers (lukt dat niet, dan blijft de oude staan). Zweef over de roepnaam: “Gebruikt LoTW: laatste upload” verschijnt met de datum. In het roepnaamvak verschijnt “LoTW” alleen als het station het gebruikt, in groen en zonder datum; gebruikt het dat niet, dan verschijnt er niets. Dit geldt ook voor stations uit de DX-cluster, gecontroleerd aan de openbare lijst van de ARRL.",
  "t.ogxtgzei1c": "Dubbelklik op het kaartje: je antwoordt dat station. Met × sluit je het (het komt niet terug zolang Aurora open blijft); elk station verschijnt maar één keer, met zijn geluid.",
  "t.ohpgicrw5e": "Een item van het tandwielmenu ⚙, na [[nav.wiki]]: de laatste wijzigingen van Aurora, één rij per versie met type (nieuw, gewijzigd, opgelost), titel en de datum en tijd van de release in jouw lokale tijd. Een klik op de rij opent de tekst; drie filters ([[news.kind.new]], [[news.kind.changed]], [[news.kind.fixed]]) tonen of verbergen de typen (zie “De pagina Nieuws”).",
  "t.ohvawip0le": "“[[wft.bins]]” (standaard 5): hoeveel spectrumkanalen in één pixel worden opgeteld; minder kanalen = meer detail en meer ruis. “[[wft.start]]”: de audiofrequentie waar de linkerrand begint (0-4900 Hz, standaard 0); als je die verhoogt, wordt het lage deel afgesneden en de rest vergroot.",
  "t.oi90z4hrah": "[[sup.title]] · [[sup.prepare]]: maakt op het Bureaublad een zip Aurora-assistenza-….zip met logboeken, crashrapporten, instellingen (zonder wachtwoorden) en een samenvatting van het station, en toont hem dan in Verkenner. Terwijl het werkt, staat op de knop “[[sup.working]]”. Wanneer: als er iets mis is en iemand je helpt.",
  "t.ojrewyq0k9": "Ernaast acht tellers: “[[fox.logged]]” (QSO’s gelogd in deze sessie), “[[fox.inProgress]]”, “[[fox.callers]]”, “[[fox.queue]]”, “[[fox.stat.rate]]” (QSO’s per uur over de laatste 10), “[[fox.stat.hour]]” (QSO’s per 5 minuten in het laatste uur), “[[fox.periods]]” en “[[fox.continents]]” (QSO’s per continent). Houd de muis erboven voor de uitleg.",
  "t.omdusp9xh0": "[[digi.edit.clear]]: maakt label, tekst en kleur leeg (de toets wordt leeg, na OK).",
  "t.oqqgfoo3er": "“[[prop.bands]]”: een tabel met de gegroepeerde banden (80-40 m, 30-20 m, 17-15 m, 12-10 m) en twee kolommen, dag (zon) en nacht (maan). Elk vakje heeft drie kleine streepjes (één = slecht, twee = redelijk, drie = goed) en het woord “[[prop.cond.Good]]”, “[[prop.cond.Fair]]” of “[[prop.cond.Poor]]”. De kolom waarin je nu zit, is gemarkeerd met “[[prop.here]]”; de rij van de bandgroep waarop de radio staat, is gemarkeerd en zegt “[[prop.tuned]]”. Dezelfde gegevens staan in het blok “[[bands.title]]” van de Stationspagina.",
  "t.oscpgb57ty": "“[[ens.test]]” geeft een fout: controleer gebruikersnaam, wachtwoord of sleutel en, voor Wavelog, adres en stationsnummer; sla dan op met “[[sw.save]]” en probeer opnieuw. Het lampje blijft rood zolang de laatste test of upload is mislukt.",
  "t.p46nmi5b0m": "[[nav.dxmap]]: de wereldkaart met de stations in de lucht (zie “DX Map: de commandobalk en het tandwiel”). [[nav.propagation]]: de zon, de banden en wie jou ontvangen heeft (zie “Propagatie: elk paneel”). [[nav.rotator]]: de antennerotor (zie “Rotor: de pagina en de kaart”).",
  "t.p4a5hf33v1": "[[lay.options]] · [[fil.ownContinent]]: selectievakje, standaard uit. Verbergt stations van je eigen continent: handig om alleen ver DX te zien.",
  "t.p4alaj4tiq": "“[[ens.g.udp]]” · “[[ens.k.UDPServer]]” en “[[ens.k.UDPServerPort]]” (standaard 127.0.0.1 en 2237): waarheen Aurora de WSJT-X-stream stuurt (decodes en status), het protocol dat GridTracker, JTAlert, QLog, Log4OM en dergelijke lezen. 127.0.0.1 is deze pc zelf; voor een andere computer schrijf je het IP-adres, of het adres van een multicastgroep. De poort moet gelijk zijn aan die in het ontvangende programma. Verander ze alleen als 2237 bezet is of het programma ergens anders luistert.",
  "t.p5y2bjbpy0": "[[sw.testCat]]: verbindt de radio met de instellingen van [[sw.pg.radio]] en wacht tot 15 seconden op de uitkomst. Het zegt “[[sw.catOk]]” als de radio antwoordt, anders “[[sw.catFail]]” met de reden (poort, snelheid, radio uit…). Het is hetzelfde als [[cat.connect]] en naar de status kijken.",
  "t.p864fbidug": "Het paneel [[panel.cluster]] toont de spots van de servers waarmee je verbonden bent. Als het leeg is, zie ook “De DX Cluster is leeg”. Als de cluster uit staat, zegt het paneel dat met de knop “[[cluster.settings]]”; hetzelfde gebeurt zonder je roepnaam in de stationsgegevens.",
  "t.p8o7qkfaxa": "De SSTV-pagina: hoe hij is ingedeeld",
  "t.pa3hh2p21r": "[[lay.settings]] · [[clock.warn]]: de alarmdrempel in milliseconden, van 10 tot 5000; standaard 500. Voorbij deze afwijking wordt de klok geel gemarkeerd en, met automatische correctie aan, gecorrigeerd. Voor FT8 is 200 een goede waarde als je strenger wilt zijn; verhoog hem als de waarschuwing te vaak afgaat.",
  "t.pa9qp7j4vo": "Met [[ctl.filter]] aan tonen twee donkere vlakken aan de zijkanten van de Rx-balk het deel van de band dat Aurora negeert.",
  "t.peetesnrqs": "Alleen RTTY: de keuzelijst voor de shift (Hz), de keuzelijst voor de snelheid (bd) en de knop “Rev” (mark en space omgewisseld; met de radio in LSB verschijnt “Rev (LSB)”, omdat Aurora ze dan al zelf omkeert). Op de naam “RTTY” aan het eind kun je klikken om “[[digi.rtty.title]]” te openen.",
  "t.pfvdroh0z0": "Elk CQ-vakje toont vlag, roepnaam en land; bericht, rapport en tijd verschijnen als je er met de muis boven houdt. Dubbelklikken antwoordt, rechtsklikken zet in de wachtrij. Een station dat 15 minuten niet is gehoord verdwijnt vanzelf.",
  "t.pgnostb2v2": "[[lay.settings]] · [[clock.atStart]] (standaard aan): zodra Aurora start, controleert het de tijd bij de NTP-servers en corrigeert die als hij buiten tolerantie ligt (het probeert het ongeveer tien minuten opnieuw tot de servers antwoorden). Om de tijd te wijzigen moet Aurora als administrator starten, anders meldt het alleen.",
  "t.pgszkmlci1": "Zet de radio op de door de expeditie aangekondigde frequentie, in FT8.",
  "t.phrzdgdz8e": "Na een crash (met “[[rep.ask]]” aan): bij de herstart verschijnt het venster “[[rep.crashTitle]]” met “[[rep.crashSend]]”, “[[rep.show]]” (om te lezen wat er zou worden verstuurd) en “[[rep.no]]” (verstuurt niets en vraagt niet meer voor die crash). Na het versturen zie je de code en “[[rep.close]]”.",
  "t.pk321posrh": "Vak “[[prop.solar]]”: drie indicatoren — “[[prop.sfi]]” (de zonneflux op 10,7 cm: boven 100 gaan de hoge banden open, onder 70 zijn ze dicht), “[[prop.a]]” (lager = rustiger propagatie) en “[[prop.k]]” (vanaf 5 is er een geomagnetische storm) — met de kleur van het oordeel; daarna “[[prop.xray]]”, “[[prop.spots]]”, “[[prop.wind]]”, “[[prop.geomag]]”, “[[prop.noise]]” en, indien aanwezig, “[[prop.aurora]]”. Onderaan staan het tijdstip van de laatste update en de gegevensbron (N0NBH, hamqsl.com).",
  "t.po8efitcx7": "Opgeslagen bestanden blijven 7 dagen bewaard (instelbaar) en ALL.TXT roteert vanzelf. Stopt CAT, dan verbindt Aurora de radio opnieuw met steeds langere pauzes. Drie oorzaken van vastlopers bij ontvangst en decodering zijn weg.",
  "t.pp1w3rp27s": "Kolom [[freq.mhz]] (getalveld): de afstemfrequentie in MHz, met drie decimalen (14.074 = 14 074 000 Hz). Ze moet binnen de gekozen band vallen en dezelfde frequentie mag niet twee keer voorkomen voor een band en modus, anders wordt de tabel niet opgeslagen.",
  "t.ppry2pp0z0": "[[cat.catmode]]: kies USB data (DATA-USB) voor FT8. De audio loopt zoals gewoonlijk via de USB-geluidskaart van de radio.",
  "t.psz1ghp9ed": "Het Tx-veld van het bedieningspaneel wordt rood als de Tx-frequentie buiten 200-2700 Hz ligt.",
  "t.pyzt6h99tq": "Laatste kolom, knop “✕” ([[set.remove]]): verwijdert de rij uit de tabel. Het slaat zichzelf op zoals de andere wijzigingen; om verwijderde rijen terug te krijgen gebruik je [[freq.reset]].",
  "t.q2mdekugmo": "In [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] verander je hoe Aurora eruitziet: taal, licht of donker thema, lettertypen en tekstgrootte. Elke keuze geldt meteen en wordt op deze computer bewaard; er is niets op te slaan.",
  "t.q65igl199t": "De knop [[ctl.jt_both]] verschijnt alleen als de modus JT65 of JT9 is: als hij aan staat, decodeert hij ook de andere JT-modus in dezelfde minuut. Je zendt in de gekozen modus.",
  "t.q8nlqs5kai": "In FT8 blijft het vermogen de hele zending constant: dat is normaal.",
  "t.q8yimdbdjy": "[[ctl.agc]]: zwakke signalen naast sterke stations",
  "t.q9ba3kic5a": "De balk boven de waterval",
  "t.q9fxmz4qta": "Kaarten voor nieuwe DXCC zijn beperkt tot twee, met «Deze meldingen uitzetten». De updatemelding gebruikt de taal van Aurora, daarna die van Windows. De Instellingen zijn breder.",
  "t.q9xpjxexiy": "In SSTV zendt F1 en stopt Esc. In PSK · RTTY · CW opent en houdt de RX/TX-knop of de Pause-toets het zenden vast, Esc stopt het en dubbel Esc breekt het meteen af.",
  "t.qdbeun6jt3": "[[wfs.specPct]] (fabriek 30) toont het spectrum onder de waterval; kies in [[wfs.specMode]] [[wfs.current]] of [[wfs.cumulative]] (het gemiddelde van de periode).",
  "t.qe282dzi7r": "Druk na het wijzigen van de vakjes in de tabel op “[[sw.save]]” onderaan: zolang je niet opslaat, veranderen de lijsten niet.",
  "t.qeq0dohwtr": "Verlaag Pwr tot de ALC op of bijna op nul staat. Kies het vermogen met de knop van de radio, niet met Pwr.",
  "t.qeuatmdqtg": "“[[digi.band.clear]]”: maakt de lijst, de geschiedenis en de roepnamen op de waterval leeg; de signalen die er nog zijn, verschijnen vanzelf opnieuw. Handig na een bandwissel of om schoon te beginnen.",
  "t.qg4sta2opv": "Twee keer Esc achter elkaar (binnen een halve seconde): behalve het zenden stoppen zet het ook automatisch CQ uit; de toets voor automatisch CQ (standaard F1) gaat uit en “[[digi.run.autoCqPaused]]” verschijnt. Om te herstarten druk je de toets opnieuw in. Met “[[gen.escStop]]” aan geven twee keer Esc ook, zoals in FT8, het gekozen station vrij.",
  "t.qgjzz2emsw": "Klik bij gebruik van RTTY op de naam van de modus in de statusbalk onderaan (RTTY kiezen in het menu Modus opent het niet): “[[digi.rtty.title]]” bundelt Rev, AFC, Snap, Squelch, UOS, drempel, frequenties, ontvanger, shift, snelheid en [[digi.rtty.charset]] (ook Cyrillisch en Scandinavisch), in vier profielen Set 1-4 die je met de stippen kiest.",
  "t.qi4j72p575": "Rechts staan twee tabbladen, “[[digi.tab.cluster]]” en “[[digi.log.title]]”, met de huidige QSO; de linkerrand kun je slepen om de kolom te verbreden. Ook het tabblad Rotor verschijnt (standaard aan; zet het uit met [[digi.mi.rotor]] in het menu [[digi.menu.view]]).",
  "t.ql6986y0kg": "In de titelbalk van het paneel, rechts: “[[ctl.spot]]” opent het venster om een spot naar DXSummit te sturen met de huidige DX en de radiofrequentie (zie “Het paneel Opdrachten”); het tandwiel opent “[[cop.title]]”, dezelfde als op de pagina PSK · RTTY · CW en ook hier geldig: “[[cop.choose]]” (dubbelklik, standaard, of enkele klik; de rotor die naar het station draait), “[[cop.spots]]” (na hoeveel minuten een spot verdwijnt) en “[[cop.columns]]”. Op de telefoon en in het losgekoppelde venster staan de twee knoppen boven het paneel. Rechts in de filterbalk staat met hoeveel servers je verbonden bent (“Connected to n of m”) of “[[cluster.nobody]]” (geen server verbonden).",
  "t.qlxm1w7be7": "[[rot.set.state]]: alleen-lezen, hoe de verbinding eraan toe is ([[rot.state.off]], [[rot.state.connecting]], [[rot.state.connected]], [[rot.state.moving]], [[rot.state.error]]). Valt ze weg, dan probeert Aurora het na een paar seconden zelf opnieuw. Bij “[[rot.state.error]]” staat de reden in rood eronder: meestal een verkeerde poort (is het die van de radio?), een poort die al in een ander programma open is of een ontbrekende toestemming op Linux.",
  "t.qngj247kdf": "[[wfs.barsOn]] toont de Rx- en Tx-balken; [[wfs.freqOn]] de frequentie waar je met de muis naar wijst. [[set.reset]] zet alles terug op de fabriekswaarden.",
  "t.qnolql7xtv": "De balk met de zoeklijst (ster ★): een strook bovenaan de pagina met “roepnaam gezocht (reden)” [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] of [[wish.reason.grid]], de bron ([[wish.source.decode]] of [[wish.source.cluster]]), het bericht, de band en het signaal. Bij een clusterspot staat er ook “[[wish.tune]]”, waarmee de radio naar de spotfrequentie gaat; “[[wish.close]]” sluit de balk. Hij verdwijnt na 90 seconden vanzelf en speelt een geluid als de geluidsmeldingen aan staan (en stuurt, als de browser het toestaat, een notificatie).",
  "t.qq1anzxpdp": "Mijn pc is traag: is er een lichte modus?",
  "t.qq3gs7icww": "[[sw.contest.title]] · [[sw.contest.open]]: knop; opent de pagina [[nav.contest]] in het hoofdvenster, waar je de contest activeert, roept en het log exporteert.",
  "t.qqg4qcfz6z": "Om twee naburige vensters van dezelfde hoogte te verwisselen sleep je de titelbalk naar links of rechts: het venster volgt de muis en het andere schuift over.",
  "t.qqi780mxcy": "In het paneel [[panel.tx]] staat onder de zes berichten het vak “[[ctl.sec.qso]]” met twee kolommen knoppen. Beweeg de muis over elke knop voor de uitleg; aan = groen met de led. Uitzetten mag altijd; de schakelaars aanzetten die je laten zenden kan alleen als het zenden op de pc is geopend.",
  "t.qzbls7dalr": "Druk op [[cat.connect]]: de status moet “Verbonden” worden, met groep, radio en rol (bijvoorbeeld group-1/kenwood/ts-990 — slave). Log4OM houdt de controle over de radio; Aurora schrijft (frequentie, modus, PTT, split) alleen als het nodig is en volgt de QSY’s van Log4OM, bijvoorbeeld bij een klik op een spot.",
  "t.qzmgvyyluo": "De telefoon opent de pagina niet: telefoon en pc moeten op hetzelfde wifi zitten; als de QR niet opent, gebruik dan de alternatieve QR’s van de pc (wifi, kabel, vaste naam) of schrijf het adres met de hand in Chrome of Safari. In Messenger of WhatsApp opent de pagina vaak niet.",
  "t.qzrfwwycxc": "Controle, interval, testversies en repository stel je in bij [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].",
  "t.r377i7cy3a": "De split gaat uit met “[[cluster.splitDx.off]]”, bij het wisselen van band of frequentie, bij een klik op een spot zonder UP en bij terugkeer naar FT8 of FT4. Lukt het uitzetten niet, dan meldt Aurora niet dat het uit is terwijl de radio nog in split staat; “[[cluster.splitDx.off]]” werkt niet tijdens het zenden.",
  "t.r3oewrahj7": "[[ca.radio]]: “[[ca.radio.ok]]” als de radio verbonden is; “[[ca.radio.warn]]” als hij niet verbonden is (of OmniRig niet antwoordt); “[[ca.radio.bad]]” als de verbinding een fout geeft. “[[diag.fix]]” leidt naar de radiopagina.",
  "t.r4jp68ti5f": "[[ctl.filter]]: decodeert alleen ±60 Hz rond de Rx-frequentie (±290 Hz in Hound). Als hij aanstaat, wordt hij geel en zegt dat in de hint: alle andere signalen in de waterval worden genegeerd. Het is handig op een erg drukke band als je alleen je tegenstation volgt.",
  "t.r8cbzncnfy": "“[[phone.log]]”: de laatste drie QSO’s, met UTC-tijd, vlag, roepletters, land, band en modus, en de uitgewisselde rapporten. De titel opent en sluit het paneel. Als het logboek niet antwoordt, verschijnt “[[log.unavailable]]”; als het leeg is, “[[log.empty]]”.",
  "t.ra32xq0h78": "Wait and Reply: als je een DX hebt geroepen en [[ctl.enable_tx]] hebt uitgeschakeld, wordt de QSO vanzelf hervat wanneer de DX jou roept.",
  "t.ra468wnajp": "[[digi.mi.defaultRst]] (aan): na elke QSO (opgeslagen of gewist) gaan de verzonden en ontvangen rapporten terug naar 599. Als het uit staat, blijven de rapporten die je hebt ingevuld.",
  "t.rad6fz68vs": "Logprogramma’s koppelen (UDP)",
  "t.rbb9a93sj5": "Een rechtsklik in het ontvangstvenster opent een menu: op een woord zetten “[[digi.word.call]]”, “[[digi.word.name]]”, “[[digi.word.qth]]”, “[[digi.word.grid]]” en “[[digi.word.rst]]” het woord in het juiste veld van de QSO-rij (het rapport komt in “rcvd.”); altijd aanwezig zijn “[[digi.word.copy]]” (kopieert de tekst die je hebt geselecteerd, of het woord) en “[[digi.mi.clearRx]]”.",
  "t.rbyx53gsup": "Voer UDP-poort 2237 in (adres 127.0.0.1) en laat multicast uit. Laat LogHX JTDX of WSJT-X niet starten: het digitale programma is Aurora.",
  "t.req3rs8tby": "[[not2.grpDisplay]] · [[not2.diffBg]] met de keuze [[not2.cyan]] / [[not2.yellow]]: rijen die jouw roepletters bevatten krijgen een andere achtergrond, cyaan of geel, zodat je ze meteen ziet. De kleurkeuze is pas beschikbaar als het vakje aan staat. Standaard uit.",
  "t.rg32monv8v": "FlexRadio, SunSDR, ExpertSDR: geen COM-poort, gebruik TCI ([[cat.backend]] → “[[cat.backend.tci]]”); bij FlexRadio werkt ook de SmartSDR CAT.",
  "t.rgf9sdzhyq": "Volledig onderdeel: «Ik zie signalen maar niets decodeert»; «De klok».",
  "t.ripejls4px": "De hoofdpagina met blokken",
  "t.rjbsteciih": "De velden, allemaal te wijzigen: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] en [[lp.f.comment]]. Klopt een waarde niet, dan verschijnt “Controleer het veld …” en wordt de QSO niet opgeslagen.",
  "t.rjklfgkwz1": "[[gen.screen]] · [[gen.escStop]]: selectievakje, standaard aan. De toets Esc stopt meteen met zenden en zet [[ctl.enable_tx]] uit; twee keer achter elkaar indrukken maakt het station ook vrij om te roepen. Het werkt op elke pagina; zet het uit als je soms per ongeluk op Esc drukt.",
  "t.rjydkrp3wi": "[[sw.tab.colors]]",
  "t.rkde317uuf": "Het knopje naast het tandwiel brengt de pagina naar een apart venster, om op het tweede scherm te zetten; in het aparte venster is de knop er niet, en op de telefoon ook niet.",
  "t.rkvp7qwege": "[[digi.menu.edit]] › [[digi.mi.copyRx]]: kopieert alle ontvangen tekst naar het klembord.",
  "t.rn94wdf0dy": "[[digi.tx.title]] · [[digi.mi.lock]]: uit (fabriek) zend je op dezelfde frequentie als waarop je ontvangt; aan heeft de zending een eigen frequentie en wordt het veld “[[digi.freq.tx]]” ontgrendeld. Gebruik het om iets naast het signaal waarnaar je luistert te antwoorden (split). Op de werkpagina verplaatst met Lock aan een klik op de waterval de zending en Ctrl+klik de ontvangst.",
  "t.rs0asi1hut": "Gekleurd label rechts: “[[tag.new_dxcc]]”, “[[tag.new_dxcc_band]]”, “[[tag.new_zone]]”, “[[tag.new_zone_band]]”, “[[tag.new_itu]]”, “[[tag.new_itu_band]]”, “[[tag.new_grid]]”, “[[tag.new_grid_band]]”, “[[tag.new_px]]”, “[[tag.new_px_band]]”, “[[tag.new_call]]”, “[[tag.new_call_band]]”, “[[tag.worked_call]]” en “[[tag.auto]]”. Ze vertellen wat er bijzonder is aan dat station voor jouw logboek; de gekleurde balk links van de rij heeft dezelfde kleur. De kleur van elk type wijzig je in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Een lichtere, gestreepte kleur betekent “gewerkt maar niet bevestigd” (als je die optie hebt aangezet).",
  "t.rsti6ivck3": "Volledig onderdeel: «Een QSO corrigeren of verwijderen»; «Het venster om een QSO te corrigeren of te verwijderen».",
  "t.rv1mchckle": "Via UDP gaat een QSO die naar een gesloten logboek wordt gestuurd verloren, want er is geen bevestiging. Aurora kan hem apart bewaren en opnieuw versturen als het logboek weer opent. De functie heeft twee vakken: één voor de secundaire UDP-server en één voor elke bestemming in “[[int.title]]”. De volledige uitleg, met stappen, staat bij het onderwerp “Log closed: QSOs arrive later”.",
  "t.rvvu61wi6f": "De grote knop daarnaast, met de band, de MHz en ▾, is de frequentiekeuzelijst ([[band.freqs]]): klik erop om hem te openen. Per band toont hij de frequenties van de modus in gebruik: de hoofdfrequentie (gekleurde stip, legenda “[[band.main]]”) en de alternatieven, zwakker; sommige gelden alleen in één IARU-regio (de afkorting in superscript). Een klik op een frequentie verplaatst de radio erheen. Een klik op de naam van de band verplaatst hem naar zijn hoofdfrequentie. De rij van de band waarop je zit, is gemarkeerd.",
  "t.rxpdygzsht": "Bijna altijd is het CAT of PTT: probeer “[[sw.testCat]]” en “[[sw.testPtt]]” onderaan in de Instellingen. Als de radio op TX gaat maar er geen vermogen uitkomt, ontbreekt de audio naar de radio.",
  "t.ry0hr60z9r": "[[aud.input]] · [[aud.vol.in]] (in [[sw.tab.audio]]): dezelfde Rx-regelaar, van 0 tot 100 %, het volume “Opname” van het gekozen apparaat, hetzelfde als in de geluidsinstellingen van het systeem. Het wordt verstuurd als je loslaat. Rechts staat de waarde in procenten en, als AUTO aan staat, het woord AUTO. Op Linux is het het opnamevolume van de systeemmixer (PulseAudio of PipeWire).",
  "t.s0kfl562hk": "Een station roept je terwijl je bezig bent: rechtsklik op zijn rij en hij komt in de wachtrij. In de lijst verschijnt een blauwe stip met zijn positie.",
  "t.s2h1ztk9d1": "[[gen.screen]] · [[gen.showCountry]] en [[gen.showFlag]]: twee selectievakjes, standaard aan. Het eerste schrijft de naam van het DXCC-land naast elk bericht, het tweede voegt het vlaggetje toe. Zet ze uit om de tekst meer ruimte te geven.",
  "t.s6svkm86zw": "[[gen2.operation]] · [[gen2.txDelay]] (getalveld, 0 tot 0,5 seconden, standaard 0,2): de minimale tijd tussen PTT aan en het begin van het geluid. Verhoog hem (0,3 of 0,4) als de radio of CAT traag overschakelt naar zenden en het begin van de berichten verloren gaat; verlaag hem alleen als je zeker weet dat de radio meteen klaar is.",
  "t.s7qa8b02if": "[[sw.sub.ft8]] · [[sw.sub.contest]]",
  "t.s8z214vch2": "[[snd.title]] · [[snd.voiceLang]]: de stem kan de melding en de roepletters (in het spellingalfabet) uitspreken in de taal van Aurora (“[[snd.voiceLang.ui]]”, standaard) of altijd in het Engels (“[[snd.voiceLang.en]]”). Het geldt voor de menu’s waar je “Stem” kiest.",
  "t.saekm7o1xh": "Zet in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]], vak “[[cat.share]]”, “[[cat.share.on]]” aan (alleen met Hamlib; de poort staat in “[[cat.share.port]]”, standaard 4532): na ongeveer 1,5 seconde past Aurora het vanzelf toe en maakt één keer opnieuw verbinding met de radio, of meteen met [[cat.apply]]. Het te gebruiken adres verschijnt daar zodra de radio verbonden is.",
  "t.schpi0xdk2": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: druk op [[cat.connect]]; de status moet “Verbonden” zeggen met de frequentie van de radio.",
  "t.sdovh9xuek": "[[auto.b3]] · [[auto.attempts]] (getalveld, 1 tot 10, standaard 2) en [[auto.cooldown]] (0 tot 120 minuten, standaard 15): na zoveel pogingen zonder QSO stopt Aurora met het roepen van dat station en wacht de pauzetijd af voordat het hem opnieuw roept (op een drukke band kan een station dat vandaag niet antwoordt, later wel antwoorden). 0 = geen pauze.",
  "t.sdwvpcluri": "Roepnaamopzoeking (QRZ.com, HamQTH): [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.selrqzrho2": "De schaal boven de waterval: als de frequentie van de radio bekend is, toont hij de echte frequenties in kHz (radio plus audiotoon, in USB), een streepje elke 100 Hz en het getal elke kHz; anders de tonen in Hz, het getal elke 500.",
  "t.shae7n3ti7": "Het vermogen in watt (zoals de radio het echt afgeeft, bijvoorbeeld “50 W”): het verschijnt alleen als de radio het vermogen meldt; als je erop tikt, openen − en + die het vermogen telkens met 5% wijzigen. Als de radio wijzigen niet toelaat, blijft het alleen-lezen.",
  "t.si10133zlo": "Wait and Pounce: kies met [[ctl.enable_tx]] uit in [[gen2.pounce]] ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]) welke CQ je wilt beantwoorden en schakel [[ctl.pounce]] in. Aan het einde van de periode beantwoordt Aurora de gekozen CQ vanzelf, waarbij reeds gewerkte stations worden overgeslagen.",
  "t.slnwecbqnd": "Onderaan: hoeveel berichten je ziet van hoeveel er zijn, de knop “[[hist.more]]” om meer rijen te laden en het totaal aantal berichten en stations met de datum van het eerste.",
  "t.sojh71i9r5": "[[sdr.tci]] · [[cat.backend]] en [[sw.tab.audio]]: twee alleen-lezen rijen. De eerste zegt wat de CAT nu gebruikt; is dat TCI, dan toont ze de led, de status ([[cat.state.connected]]…) en de van de SDR gelezen frequentie. De tweede toont de audio-ingang en -uitgang in gebruik. Zo zie je in één oogopslag of alles via TCI loopt.",
  "t.solo8q4ob2": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] kies je wanneer het FT8-decoderen begint en hoe diep de decoders zoeken. De pagina bestaat alleen met de eigen engine van Aurora. De items gelden vanaf de volgende periode, na [[sw.save]].",
  "t.soythi7erd": "QMAP · [[pref.showQmap]] (standaard uit): zet het onderdeel QMAP in het bovenmenu aan. QMAP luistert naar een stuk van de band tot 90 kHz breed en decodeert alle Q65-signalen tegelijk: het is alleen nodig met een SDR die de I/Q-stroom stuurt (TCI) of met een I/Q-WAV-bestand; laat het uit met een gewone radio. Ernaast zegt een regel welke I/Q-bron in QMAP is gekozen.",
  "t.sqsn231a48": "[[fil.grp.rx]] · [[rxw.exclusive]]: selectievakje, standaard uit. Aan, met het venster [[rxw.title]] open, verschijnen de berichten aan jou en die van het QSO-station alleen daar en niet ook in [[panel.all]]. Uit staan ze in beide lijsten.",
  "t.sr4g1qgw2r": "Tabblad “[[contest.training]]”: kies de contest, de “[[contest.sim.pileup]]” ([[contest.sim.light]], [[contest.sim.medium]] of [[contest.sim.heavy]]) en de “[[contest.sim.duration]]”, dan “[[contest.sim.start]]”; “[[contest.sim.stop]]” stopt. De nepcalls verschijnen zoals de decodes in de contest: dubbelklik om te antwoorden, RR73 om af te sluiten. Het gebruikt de radio niet en schrijft niets in het logboek; de samenvatting toont tempo, dupes, foute exchanges en de “[[contest.sim.nil]]” die je voorkwam door RR73 opnieuw te sturen. Een label “[[contest.sim.badge]]” herinnert je eraan dat het een oefening is.",
  "t.ssmqk2zyp1": "[[digi.mi.afc]]: de ontvangst volgt het station als het in frequentie afdrijft. Standaard aan; bij alleen ruis blijft hij staan.",
  "t.st1vwkk4g6": "Tekst in PSK31, PSK63 en RTTY",
  "t.sxepdxiwbv": "Bediening",
  "t.sxxz15anfr": "Eerste start: er verschijnt een balk met “[[rep.notice]]”, de link “[[rep.notice.open]]” (leidt naar de pagina Ondersteuning) en de knop “[[rep.notice.ok]]” die hem voorgoed sluit. Hij verschijnt niet als je “[[rep.ask]]” en “[[rep.auto]]” al allebei hebt uitgezet.",
  "t.syeo94yu6p": "Adresregel: geeft het adres en de netwerkkaart die in de QR worden gebruikt (virtuele adapters, zoals WSL, Hyper-V, VirtualBox en VPN, blijven buiten beschouwing); als de pc geen adres heeft op het thuisnetwerk, zie je “[[net.noAddress]]”: controleer de kabel of wifi van de pc. Onderaan “[[net.tips]]”: als de telefoon de pagina niet opent, zet dan mobiele data en VPN uit, vermijd het “gast”-netwerk of repeaters met “client isolation” en gebruik op Android, als aurora.local niet werkt, het adres met de cijfers.",
  "t.szo7jtk9k4": "Het deel dat nog niet verzonden is, blijft bewerkbaar: klik erin en verbeter, wis of voeg toe; het al verzonden deel blijft ongewijzigd. Een macro die tijdens de uitzending start, sluit achteraan aan.",
  "t.t0hqszd6n3": "Het hart van UltraFOX is AQP-127 (Aurora Q-ary Polar), de polaire code van Aurora, implementatie door Tiziano Cassone IU3WJQ: 50 symbolen van 7 bits (47 voor het bericht en 3 voor controle) worden 127 tonen. Bij ontvangst weegt de decoder de kansen van de 128 tonen van elk symbool en corrigeert die welke door ruis en fading zijn verpest: hij decodeert tot ongeveer −16 dB in 2500 Hz, met tot 9 stations in één signaal.",
  "t.t1hctlptxy": "[[digi.ms.receive]] · [[digi.mi.afc]] (standaard aan): de ontvanger volgt het signaal als de frequentie langzaam wegdrijft. Zet hem alleen uit als hij het verkeerde signaal naast het jouwe volgt.",
  "t.t1izo9h1pm": "CW van de hele band lichter",
  "t.t2149hi05u": "Macro’s van de modus samenvoegen met de basismacro’s (“[[digi.mi.macrosMerge]]”) en teruggaan naar de macro’s van Aurora (“[[digi.mi.macrosReset]]”) doe je via het menu [[digi.menu.file]] van de pagina PSK · RTTY · CW, niet hier.",
  "t.t3gob4alw4": "Vinkjes: “[[dxmap.greyline]]” (de dag- en nachtlijn), “[[dxmap.arcs]]” (een lijn van jouw station naar elk station in de lucht), “[[dxmap.heat]]” (de heatmap van wie jou heeft ontvangen, van PSK Reporter), “[[dxmap.links]]” (een lijn tussen twee stations als de een de ander roept, goudkleurig als ze jou roepen), “[[dxmap.onlyHeardMe]]” (alleen de lijnen naar wie jou heeft ontvangen), “[[dxmap.callLabels]]” (roepnamen altijd geschreven; staat het uit, dan zie je ze bij het erboven blijven), “[[dxmap.squares]]” (de gewerkte vierkanten: geel = gewerkt, groen = bevestigd).",
  "t.t3j5fcymtu": "“Nu bijwerken”: als Aurora gesloten is, opent de agent het en wacht (tot een minuut) tot het antwoordt; daarna installeert Aurora de nieuwe versie (en downloadt die eerst als dat nog niet is gebeurd). De kaart blijft open en toont de voortgang: een balk met percentage, MB, snelheid en resterende tijd, en de stappen “Downloaden › Controleren › Installeren › Herstarten”. Aan het eind sluit Aurora en opent het vanzelf weer.",
  "t.t3yynge1xt": "[[list.clear]] wist het berichtenvenster.",
  "t.t5rtgudhia": "De pc-klok loopt zoveel milliseconden af: geel boven 4% van de periode (600 ms in FT8), rood boven 8%. “[[diag.fix]]” opent [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].",
  "t.t6tgl6g3es": "Sommige pagina’s van de Instellingen hebben een link naar hun item; het adres “#/guida/naam-van-het-item” opent de Gids direct bij dat item.",
  "t.ta1s9otowr": "De DXCC-kaart",
  "t.tcinq12ddr": "Gebruik de Foxmodus alleen als je echt de expeditie bent en je dat aankondigt: op een gewone band veroorzaakt hij storing.",
  "t.tdt8zms2dg": "[[sw.pg.radio]]: [[cat.grp.link]]",
  "t.tijxj7nv9c": "“[[dxs.colors]]” · “[[dxs.resetColors]]” (knop rechtsboven, uit zolang je geen kleur hebt veranderd): verwijdert alle gekozen kleuren en zet de kaart terug op de kleuren van het lichte of donkere thema; banden, rijen en weergave blijven.",
  "t.tk3kme0bef": "Druk aan het eind op “[[contest.export]]”: Cabrillo 3.0, EDI of ADIF zoals de regels vragen, gecontroleerd vóór het verzenden, met de link naar de pagina van de organisator. Daarna zet “[[contest.end]]” alles terug naar de vorige instellingen.",
  "t.tl0lo3apg0": "[[sstv.set.grpTx]] · [[sstv.set.fskId]] (standaard aan): na elk beeld stuurt hij de roepletters van het station in FSK (ongeveer 2 seconden), zodat wie met een SSTV-programma ontvangt dat het leest ze naast het beeld ziet. Zet hem uit als je de zending niet langer wilt maken.",
  "t.tl2gkbtvrm": "Het verschijnt onder de QR in [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] › [[acc.pair]], alleen zolang de QR open is, en ververst vanzelf elke 15 seconden. Het zegt wat de pc over zijn netwerk weet, zodat wie niet kan verbinden meteen ziet waarom. De regels zijn alleen-lezen; de enige knop is “[[net.allow]]”.",
  "t.tl3j6nutkg": "“[[dxs.rows]]” · FT8, FT4, DIG: de rijen (modes) van het raster. FT8 en FT4 zijn aparte modes en staan aan; DIG bundelt de andere digitale modes (JT65, JT9, RTTY, PSK…) en staat uit. Minstens één rij moet aan blijven: de laatste kun je niet uitzetten.",
  "t.tmggavdxxu": "Druk op ‘[[exp.edit.save]]’: de rij wordt bijgewerkt, het bestand aurora_log.adi wordt gecorrigeerd en ‘eerder gewerkt’ (labels van de decoderingen, DXCC-kaart, kaart) wordt opnieuw berekend. Als een waarde niet klopt, zegt het venster welke en wordt er niet opgeslagen. ‘[[exp.edit.cancel]]’ of Esc sluiten zonder iets te wijzigen.",
  "t.to46xwcz90": "Bijna alle verbindingsproblemen komen door een paar oorzaken. Controleer ze in deze volgorde voordat je elders zoekt.",
  "t.tomzpso2ew": "[[digi.ms.receive]] · [[digi.mi.squelch]] (standaard uit): zet hem aan zodat de decoder stil blijft als het signaal onder de drempel ligt, en er geen willekeurige tekens op ruis verschijnen. De drempel van elke modus stel je in het vak “[[sw.digi.perMode]]” in.",
  "t.tp0fvwawlw": "De knop “Auto” in de bovenbalk schakelt het aan en uit zonder het menu te openen. De eerste keer vraagt hij, als het in dry run staat, of je naar de echte modus wilt overschakelen: met “Ja” start het meteen in de echte modus, daarna schakelt één klik het aan en uit.",
  "t.tqlhorkmi7": "Een station dat nooit de laatste 73 zendt: Aurora herhaalt RR73 hoogstens het aantal keren dat is ingesteld in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], en stopt dan.",
  "t.tqzfvfjvyt": "Met [[ctl.enable_tx]] aan of tijdens het zenden hopt de rig niet: hij blijft waar je werkt.",
  "t.tr4777movl": "Instellingen: Modi",
  "t.trxoxcdz9j": "De knoppen van het uitgebreide display (PRE, ATT, AGC, NB, NR, NOTCH, ATU, VFO, RIT, XIT) bedienen de radio met een klik: zie het item “De radio bedienen vanaf het display”.",
  "t.tsieh1ipmc": "Radio en audio",
  "t.tt94z7c9g2": "Voer onderaan, in het vak “Modo ADIF”, bij “Descrizione” (beschrijving) Aurora in en bij “Percorso file ADIF” (pad van het ADIF-bestand) C:\\Users\\<your user>\\AppData\\Roaming\\Aurora\\aurora_log.adi (of blader met het vergrootglas), en druk dan op de groene +.",
  "t.tv84vqu0gj": "Afstand en azimut verschijnen ook bij berichten zonder locator, als dat station die eerder heeft gezonden.",
  "t.twxpwv4pau": "Als de pc traag decodeert",
  "t.tx073tffry": "De vensters hebben vaste afmetingen; alleen de volgorde en de breedte van naburige vensters veranderen.",
  "t.txgacev1w4": "[[nav.log]]: de pagina met al je QSO’s, zoeken, exporteren en corrigeren (zie “Het Log: zoeken, selecteren en exporteren”).",
  "t.ty0dtyxfkp": "[[rot.set.grp.link]] · [[rot.set.enabled]] (standaard uit): met het vinkje maakt Aurora verbinding met de rotor en blijft verbonden bij de volgende starts; zonder vinkje geen verbinding. Het wordt meteen opgeslagen, samen met de andere al ingevulde onderdelen. Zet het pas aan nadat je model, poort en snelheid hebt gekozen.",
  "t.tyz9d8ka7k": "Het zenden meteen stoppen.",
  "t.tzc30vqhc0": "De scheidingslijn tussen de twee vensters kun je omhoog of omlaag slepen: de verhouding (van 10% tot 90%) wordt onthouden.",
  "t.u118ppvuwa": "“Geselecteerde verwijderen (n)” (met het aantal geselecteerde QSO’s) haalt de geselecteerde QSO’s na een bevestiging uit het logboek en het ADIF-bestand van Aurora; “[[exp.clearLog]]” haalt na een bevestiging alle QSO’s weg om met een leeg logboek opnieuw te beginnen (het oude ADIF-bestand wordt met de datum apart gezet). Vanuit het programma kun je dit niet terughalen.",
  "t.u54zk4t2ck": "Om alles uit te zetten: haal het vinkje weg bij “[[rep.ask]]”, “[[rep.auto]]” en “[[rep.active]]” (en, als je wilt, “[[upd.enabled]]”). Vanaf dan verlaat niets de pc, behalve wat je zelf met de hand verstuurt.",
  "t.u5sfadmpw5": "[[lay.status]] · [[upd.lastCheck]]: datum en tijd van de laatste controle, of “[[upd.never]]”. Alleen-lezen.",
  "t.u99idmjpn0": "De correctie blijft in Aurora: naar de externe logboeken (programma’s die via UDP verbonden zijn, Wavelog, ClubLog, QRZ, LoTW) wordt niets opnieuw verzonden; daar moet de QSO met de hand worden gecorrigeerd of verwijderd. Als het paneel [[panel.log]] het logboek van Log4OM2 toont, zijn die QSO’s alleen-lezen en worden ze in Log4OM2 gecorrigeerd. Het kan alleen vanaf de pc of het thuisnetwerk.",
  "t.uahjb4fsdh": "[[snd.title]]",
  "t.uaqkc1zzm0": "Hoe haal ik de geluiden weg of wijzig ik de kleuren van de meldingen?",
  "t.ub3g29st9p": "Stations die je zoekt: voeg ze toe in [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]].",
  "t.ug1x8iopdf": "Het logboek: zoeken, selecteren en exporteren",
  "t.uio7mjrzv4": "[[cat.powerOn]] en [[cat.powerOff]] (standaard uit; ze verschijnen met Hamlib, TCI en FT-991(A) Link; met Cat4OM is er alleen “[[cat.powerOff]]”): de eerste stuurt de radio de CAT-opdracht om aan te gaan als Aurora verbindt (niet alle radio’s accepteren dat: sommige luisteren niet naar CAT als ze uit staan, bijvoorbeeld de Yaesu FT-2000); de tweede zet de radio uit als Aurora sluit, nadat de PTT is uitgezet (niet als je van radio wisselt). Bij SDR’s via TCI zetten ze de SDR aan en uit.",
  "t.ujctmdn3xo": "S-meter en vermogen op het display",
  "t.uk7mnotwwu": "Daarna audio en radio: de onderdelen “De geluidskaart” en “De radio verbinden (CAT)” in de groep “Radio en audio”.",
  "t.ukyslnubwz": "[[digi.edit.title]] · [[digi.edit.text]]: het macroscript, vrije tekst met commando’s tussen punthaken. Typ het met de hand of voeg commando’s in uit de lijst rechts.",
  "t.um2oor49sk": "Druk op [[sw.save]] en dan in de paginakop op [[auto.turnOn]]. Het CQ gaat alleen uit in [[auto.modeLive]], alleen als het zenden niet bezig is en binnen het tijdvenster, als dat er is. In [[auto.modeDry]] schrijft het log wanneer het dat zou hebben gedaan, zonder te zenden.",
  "t.umsuxfdvui": "[[digi.edit.macro]]: welke toets je wijzigt. De lijst heeft de 48 toetsen (F1…F12, met Ctrl, Shift en Ctrl-Shift) en enkele speciale macro’s: Gray+ (de + van het toetsenblok), AutoCqText (de tekst die automatisch CQ herhaalt; ontbreekt die, dan gebruikt hij die van F2), Hello, OnStart, OnEnd, OnTX, OnCR, OnClickAny, OnAlarm, OnSP0 en OnSP1. Nu voert Aurora alleen Gray+ en AutoCqText uit; de andere kunnen worden opgeslagen maar starten niet vanzelf.",
  "t.uo8tm38is9": "[[auto.b3]] · opmerkingsregel over de grenzen die op de pc zijn vastgelegd (antwoorden achter elkaar zonder QSO, antwoorden per dag, uitschakelen zonder verbonden apparaten): die kun je hier of vanaf de telefoon niet wijzigen, het is het laatste vangnet en het geldt altijd, ook in dry run.",
  "t.uoyx6m6h4f": "Werkt met Hamlib, OmniRig, TCI en Cat4OM (als de radio split meldt); niet met FT-991(A) Link, dat alleen VFO A bestuurt. Zonder CAT stemt de spot alleen af. Is split niet mogelijk, dan gaat de radio toch naar de spot. Na een herverbinding van Hamlib wordt Split DX vanzelf opnieuw gezet; met Cat4OM gaat hij uit bij het afsluiten, ook na een herstart van Cat4OM.",
  "t.upzy42ggio": "De waterval en het spectrum hebben hun eigen instellingen, met fabriekswaarden. Wijzigingen zijn meteen zichtbaar en blijven na een herstart bewaard.",
  "t.uqengvwhnm": "Hoe de instellingen werken",
  "t.urhdtygxyy": "[[sup.title]] · opmerkingen onder het vak: “[[sup.privacy]]” en, in het rood, de reden als het pakket niet is gemaakt. Het pakket blijft op je pc staan tot je het zelf verstuurt.",
  "t.ux5ci7a0j3": "Onder 768 px breedte (telefoon) wordt de Stationspagina een compacte afstandsbediening; op een tablet in liggende stand heeft hij twee kolommen. Hij werkt hetzelfde op de gekoppelde telefoon en in een smal venster op de pc. Hoe je koppelt, staat bij “Een telefoon of tablet koppelen”.",
  "t.uylg1zjyvb": "Open in BBLogger “Configurazione interfaccia Wsjtx” (tandwielpictogram in “Fast QSO” of “Nuovo QSO”).",
  "t.v0xl8rnet0": "Rechterpaneel zonder gekozen laag, “[[sstv.bg.title]]”: “[[sstv.bg.load]]”, of sleep een bestand naar de voorvertoning of plak met Ctrl+V; “[[sstv.bg.fromFolder]]” met de miniaturen van de map met foto’s om te zenden (een klik gebruikt hem; met “[[sstv.sel.start]]” kies je welke je van schijf wilt wissen); dan, als er een foto is, “[[sstv.bg.cover]]” of “[[sstv.bg.contain]]”, “[[sstv.bg.zoom]]” (100-600%), “[[sstv.bg.panX]]” en “[[sstv.bg.panY]]”, “[[sstv.bg.brightness]]”, “[[sstv.bg.contrast]]”, “[[sstv.bg.saturation]]” (van -100 tot +100), “[[sstv.bg.reset]]” en “[[sstv.bg.remove]]”; altijd “[[sstv.bg.color]]” (te zien waar de foto niet reikt).",
  "t.v2cpuo4ip1": "SSTV: het tabblad “[[sstv.view.tx]]” (de editor)",
  "t.v4nvl1nm59": "[[sw.pg.radio]]: [[cat.share]], [[rd.title]], [[rx.grp]]",
  "t.v5jeedo5l8": "Een SSTV-zending duurt van een halve minuut tot bijna vijf: houd Pwr laag en stop de FT8-automatisering voordat je zendt. Valt een getalveld buiten het bereik, dan verschijnt de melding en slaat “[[sw.save]]” niet op totdat je het verbetert.",
  "t.v61u3aw7y": "[[tab.wishlist]]",
  "t.v739g46sn9": "[[fil.decode]] · [[dec.correlation]]: selectievakje, standaard uit. In JT65 vergelijkt het niet-gedecodeerde signalen met een lijst van waarschijnlijke berichten (de QSO met de DX en de roepnamen die op de band zijn gehoord): het vindt zwakkere signalen maar kan een paar valse geven. Naast de mode staat de knop “Deep”.",
  "t.v7960hihgf": "Met “[[rot.set.remote]]”: [[rot.set.host]] (standaard 127.0.0.1: de computer waar rotctld draait, of zijn netwerkadres als het een andere is) en [[rot.set.tcpPort]] (standaard 4533, de poort waarop rotctld luistert).",
  "t.v7rdvq58p": "[[seq2.switches]] · [[seq2.answerB4]]: beantwoordt ook al gewerkte stations (Answer B4); uit worden de stations die al in het log staan overgeslagen. Dezelfde schakelaar als in het QSO-paneel (“[[ctl.answer_b4]]”).",
  "t.v8jtcyid9a": "De vrije tekst van FT8- en FT4-berichten is maar 13 tekens, in hoofdletters, met letters, cijfers en een paar tekens: een langere macro wordt tot 13 ingekort.",
  "t.vc90to0r5k": "Aurora draait op Windows; installeer het één keer en daarna werkt het zichzelf bij.",
  "t.vgea1q9fkz": "Scan en geheugens",
  "t.vgrgqymn0x": "Het geluid van maar één gebeurtenis: kies “[[snd.none]]” in het menu ervan. De menu’s staan in het vak “[[snd.title]]” (gebeurtenissen zoals “[[snd.ev.alert_my_call]]” of “[[snd.ev.qso_logged]]”) en, voor berichttypes, op de pagina “[[sw.tab.colors]]”. “[[snd.clear]]” haalt het geluid bij alle gebeurtenissen weg; “[[snd.stop]]” stopt het geluid dat nu speelt.",
  "t.vhp7ouj18c": "[[sat.ctl.title]] · [[sat.ctl.rotor]] (standaard uit): de rotor volgt het azimut en de elevatie van de gekozen satelliet. Zet het alleen aan met een ingestelde en verbonden rotor.",
  "t.vhsikb8wxe": "[[cat.profile.load]]: zet het gekozen profiel in de radio-instellingen, VERBREEKT de verbinding met de radio en maakt GEEN nieuwe verbinding: die maak je zelf met [[cat.connect]] op de pagina [[sw.pg.radio]] (of met “[[sw.testCat]]”). De knop blijft uitgeschakeld zolang je geen profiel kiest.",
  "t.vjt2eh9zq0": "[[agent.popup]] · [[agent.quiet]] met “[[agent.quietFrom]]” en “[[agent.quietTo]]”: een vakje (standaard uit) en twee tijden (standaard 22:00 en 07:00; typ of kies ze). De twee tijden worden pas actief als het vakje aan staat. In dat tijdvak verschijnt geen pop-up; updates verschijnen wel. Tijdens het zenden verschijnt nooit een pop-up, met of zonder dit vakje. Wanneer: zet het aan voor de nacht.",
  "t.vm1qzmw6qb": "Rechtsboven, net voor het tandwiel (op de telefoon in de kop), staat een stip: het gezondheidslampje. Groen betekent alles in orde. Het wordt oranje als de CPU van Aurora minstens 10 seconden boven 50 % blijft of als het decoderen meer dan 70 % van de periode kost; rood boven 80 % CPU gedurende 10 seconden of als het decoderen niet op tijd klaar is. Het houdt ook rekening met de waarschuwingen over audio, CAT en klok. Als het naar oranje of rood gaat, pulseert het een paar seconden zachtjes.",
  "t.vnnczzmgj1": "[[sstv.set.grpFolders]] · [[sstv.set.txFolder]]: optioneel (fabriek leeg). Geef je er een op, dan worden in de samensteller de foto’s om te zenden uit deze map gekozen. Hij kan alleen vanaf de pc van Aurora worden gewijzigd.",
  "t.vqs7ecwxal": "Het opent met een dubbelklik op een QSO (op de pagina [[nav.log]] en in het paneel [[panel.log]] van het Station) of met “[[exp.edit.btn]]”. Het wijzigt alleen het interne logboek van Aurora en het ADIF-bestand; de vlaggen “al gewerkt” worden opnieuw berekend. Zie ook “Een QSO corrigeren of verwijderen”.",
  "t.vruk7679rv": "De audiofrequentie kun je met de hand typen in het vak “Hz” van de statusbalk, of wijzigen met de opdrachten [[digi.mi.seekLeft]] en [[digi.mi.seekRight]] en met scannen; het paneel met signalen en de spots van de DX Cluster verplaatsen hem voor je.",
  "t.vt4q6pb3pm": "[[not2.grpTable]] · [[not2.colHighlight]]: het vakje zet het markeren van dat type aan (gekleurde rijen in de lijsten). Standaard aan: nieuw land, nieuw grid, nieuwe roepletters; uit: CQ-zone, ITU-zone, prefix. Zet de nieuwtjes uit die je niet belangrijk vindt voor minder kleurrijke lijsten.",
  "t.vu8wux1b1t": "De expeditie kondigt het aan op haar website: frequentie (meestal weg van de normale FT8-frequenties) en of ze klassiek Fox/Hound of SuperFox gebruikt.",
  "t.vuh1wnolf3": "[[aud.output]] · [[aud.vol.out]] = Pwr-regelaar (in [[sw.tab.audio]] en in het paneel Zenden van de Station-pagina, waar hij “[[out.label]]” heet): het is het Windows-volume van de audio-uitgang naar de radio; 100 % op de regelaar = 100 % in de Windows-mixer. Aurora zet hem vóór elke zending weer goed. Hij dient om het uitgaande signaal te verlagen, NIET om het vermogen te kiezen: het vermogen stel je in met de knop van de radio. Zend, kijk naar de ALC en verlaag Pwr tot de ALC op of bijna op nul staat. Op Linux is het het niveau van de systeemmixer.",
  "t.vw15nqasdm": "Zendbeveiligingen",
  "t.vw1s1ntl59": "Esc: stopt de SSTV-zending meteen (zoals “[[sstv.tx.stop]]”), ook terwijl je in een vak typt. In heel Aurora stopt Esc, met “[[gen.escStop]]” aan (standaard), ook de andere zending en zet het “[[ctl.enable_tx]]” uit.",
  "t.vxxsljkzfh": "“[[digi.mi.scanProps]]” in het menu [[digi.menu.options]] opent deze pagina meteen.",
  "t.vy6kqwsjjv": "[[sw.digi.perMode]] · CW, “[[digi.band.spots]]” (standaard aan) en “[[digi.band.spotsCqOnly]]” (standaard uit): geverifieerde roepletters verschijnen als spots in het DX Cluster-paneel van Aurora, met de echte frequentie van de radio; ze blijven op je pc en gaan niet het netwerk op. Het tweede vak stuurt alleen wie CQ roept en kan alleen worden gebruikt als het eerste aan staat.",
  "t.vyaep5884v": "[[digi.edit.title]] · “[[digi.edit.insert]]”: zet het gekozen commando in de tekst, op de cursor (of in plaats van de geselecteerde tekst). Alleen actief nadat je een commando in de lijst hebt gekozen.",
  "t.vzq2tkm2dj": "“[[cluster.add.heading]]” · “[[cluster.add.custom]]”: voor een eigen server of een die niet in de lijst staat: “[[cluster.add.name]]” (laat je het leeg, dan wordt het adres gebruikt), “[[cluster.add.host]]” (servernaam of IP) en “[[cluster.add.port]]” (standaard 7300, 1 tot 65535), dan “[[cluster.add.button]]” (blijft uit tot adres en poort geldig zijn). Staat de server er al, dan zie je “[[cluster.add.exists]]”; boven de acht “[[cluster.add.full]]”. Na het toevoegen begint de verbindingscontrole.",
  "t.w1mhy18q7n": "[[sat.set.servers]] · servers die je hebt toegevoegd: ze staan onder de lijst met het volledige adres en het vak aan; haal het vinkje weg om ze uit de lijst te verwijderen. Het veld “[[sat.set.addPlaceholder]]” en de knop “[[sat.set.add]]” voegen er een toe: het adres moet beginnen met http:// of https:// en een TLE-lijst van drie regels geven; de knop blijft uit als het adres niet geldig is of al aanwezig is. Maximaal 10 servers.",
  "t.w2zzg97glq": "[[lay.status]] · [[upd.current]]: de versie van Aurora die nu draait. Alleen-lezen.",
  "t.w3wmtr6jwf": "“[[int.resend]]”: “verloren QSO’s opnieuw versturen” voor deze bestemming; hij kan alleen worden aangezet als “[[int.adif]]” of “[[int.n1mm]]” actief is en geldt voor een logboek op deze pc (127.0.0.1). Zie het onderwerp “Lost QSOs while the log is closed: where to turn it on”.",
  "t.w49xjmoold": "[[sstv.set.grpRx]] · [[sstv.set.autoSync]] (standaard aan): als de VIS verloren gaat (luisteren aangezet terwijl het beeld al bezig is, storing) wordt de modus herkend aan het ritme van de synclijnen. Eenmaal vergrendeld blijft de modus tot het einde van het beeld. Zet hem alleen uit als hij verkeerde modi herkent.",
  "t.w4p8vnm5sc": "[[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]]: “[[gen.language]]” in het eerste vak, “[[ap.size]]” in het vak “[[ap.text]]”. De taal kan ook worden gewijzigd vanuit de onderbalk.",
  "t.w79q3skt6b": "“rotctld niet gevonden”: herstel Hamlib via [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] (rotctld staat naast rigctld).",
  "t.wa0bq75tx0": "[[cat.poll]] (alleen Hamlib): hoe vaak Aurora frequentie en modus uit de radio leest, van 1 tot 99 (fabriekswaarde 2). Op een seriële poort komt het niet onder 2 seconden en tijdens het zenden worden de metingen schaarser. Verhoog het als de radio traag is of de poort door het uitlezen bezet blijft.",
  "t.wab9kudml1": "[[nav.settings]] › [[sw.sec.access]] › [[agent.tab]]. De agent is een klein programma naast de Windows-klok (het systeemvak): hij blijft daar ook als Aurora gesloten is, opent Aurora met een klik en toont meldingen als pop-upkaarten. Hier kies je welke meldingen je wilt en hoe. Keuzes worden meteen bewaard (er is geen knop “Opslaan”) en de agent leest ze elke minuut opnieuw. Meldingen over Aurora-updates verschijnen altijd, wat je ook kiest.",
  "t.wavjdfmn1y": "Het rechtsklikmenu van de browser verschijnt niet meer: rechtsklikken is voor de wachtrij (kopiëren en plakken werken nog in tekstvelden).",
  "t.wbvl1kwrqa": "“[[acc.home]]” (aurora.local) blijft hetzelfde ook als de router het IP van de pc verandert: zet er een bladwijzer van op de telefoon.",
  "t.wd3md5j3gw": "“[[ens.g.udp]]”: [[ens.k.UDPServer]] 127.0.0.1, [[ens.k.UDPServerPort]] 2237. Het stuurt de WSJT-X-stroom (Heartbeat, Status, Decode, QSO Logged); met “[[ens.k.EnableUDP1adifSending]]” ook Logged ADIF. Bedoeld voor logboeken die naar “WSJT-X/JTDX” luisteren.",
  "t.wewllajgwo": "[[nav.dxmap]]",
  "t.wfm8m1m1sk": "“[[wft.navg]]”: hoeveel rijen worden gemiddeld voordat er een wordt getekend (van 1 tot 50, standaard 1): hoger = langzamere en minder ruisige waterval.",
  "t.wggr4cht8z": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[int.title]]” › in de bestemming: “[[int.resend]]” (standaard uit; de knop “+ [[int.p.adif]]” maakt hem al aan): dezelfde functie voor die bestemming. Hij blijft grijs tot je “[[int.adif]]” of “[[int.n1mm]]” aanzet, want hij geldt alleen voor die twee formaten.",
  "t.wh5zgtsbsp": "Tijdens het zenden (ook met een macro) worden de tekens die al de lucht in zijn gegaan rood, met een klein streepje op het bereikte punt, en, alleen als “[[digi.mi.echoRx]]” aanstaat in het menu [[digi.menu.view]] (standaard uit), verschijnt in het ontvangstvenster de echo in het tempo van het zenden.",
  "t.wiad91ajw9": "Klik op ⧉: er opent een klein menu met “[[win.new]]” (een nieuw venster met alleen dat paneel), “[[win.dash]]” (het blokkendashboard, waar meerdere panelen samenkomen) en, als er al een apart venster is, “Naast: …” om het paneel naast die van dat venster te zetten.",
  "t.wiu4ijft3s": "In RTTY heeft de standaardtekenset ([[digi.rtty.cs.ita2]]) alleen hoofdletters: zet [[digi.mi.capsOnly]] aan om meteen te zien hoe de tekst de lucht in gaat.",
  "t.wjb77lcnwc": "[[rd.title]] · [[rd.layout]]: hoe het display en het uitgebreide display rechtsboven staan. “[[rd.layout.single]]” is één paneel met een grote VFO A en VFO B ernaast; “[[rd.layout.pair]]” zijn twee gelijke blokken naast elkaar. Met de panelen FT-2000 en IC-7610 is de keuze uitgeschakeld (het paneel neemt zelf alles in): kies een andere stijl om hem te kiezen.",
  "t.wlxcvt5ij8": "[[seq2.switches]] · [[seq2.skipTx1]]: bij het beantwoorden van een CQ begint het met Tx2 in plaats van Tx1 (slaat het bericht met de twee roepletters en zonder rapport over). Dezelfde schakelaar als in het QSO-paneel (“[[ctl.skip_tx1]]”).",
  "t.wm8s2fob95": "Netwerkregel: met een groen vinkje zegt hij op welk wifi de pc zit (de telefoon moet op hetzelfde zitten, niet het “gast”-netwerk); met een “i” zegt hij dat de pc op een kabel zit en dat de telefoon het wifi van dezelfde router moet gebruiken.",
  "t.wmpuyibhzb": "Om ook het dB-rapport of de afstand in het log te hebben: vink “[[ens.k.dBtoComments]]” en “[[ens.k.distanceToComments]]” aan; ze komen in de opmerking van het QSO terecht.",
  "t.worcm09gkx": "De volgorde gaat vanzelf verder: rapport, R-rapport, RR73. Zodra je het rapport ontvangt, wordt de QSO gelogd.",
  "t.wotqsh389v": "[[not2.grpTable]] · rij [[not2.n.worked]], vakje “[[not2.worked]]”: geeft roepletters die al in je logboek staan een eigen kleur (standaard uit: ze worden alleen doorgestreept). Het bestaat alleen als minstens één “nieuw”-markering aan staat: een station dat nooit is gewerkt, is nooit “al gewerkt”. Hoe ze worden getekend, bepaal je in het vak “[[not2.grpWorked]]”.",
  "t.wpz4mhb6f6": "Wat je op de pagina ziet en hoe tekst en waterval worden getekend. Elk onderdeel is een vinkje en werkt meteen; de standaardwaarden staan tussen haakjes. De keuzes blijven op deze computer.",
  "t.wtknyg9z8d": "Aurora stuurt QSO’s en status via UDP naar logboeken. Alles staat in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]].",
  "t.wufx184hm5": "Automatische antwoorden",
  "t.wurfvc76w8": "Als het zenden is gesloten (Aurora gestart met AURORA_ALLOW_TX=0), zijn de vier schakelaars die je laten zenden grijs en zegt een regel dat: het kan alleen vanaf de pc worden geopend, bij het opstarten. [[ctl.pounce]] wordt alleen ingeschakeld met [[ctl.enable_tx]] uit.",
  "t.wyzm9kahxf": "Als de kaart niet “nieuw DXCC” toont zoals je verwacht, controleer dan of je geschiedenis in het logboek staat: importeer die in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.files]] of wijs de Log4OM-database aan in [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]].",
  "t.x0priuos7h": "Een klik op een miniatuur (buiten de selectie) opent het grote beeld. Met de pijltjestoetsen ← en →, of met de knoppen aan de zijkanten ([[sstv.img.prev]] en [[sstv.img.next]]), ga je naar het vorige en het volgende van dezelfde strook; Esc of “[[sstv.img.close]]” sluiten.",
  "t.x0r293xyni": "Als je het adres in het menu van de radio hebt veranderd (item CI-V Address), schrijf je hier hetzelfde getal omgerekend naar decimaal: cijfer van de zestientallen × 16 + laatste cijfer. Voorbeelden: 94h = 9×16 + 4 = 148; 88h (IC-7100) = 8×16 + 8 = 136; A4h = 10×16 + 4 = 164 (A = 10, B = 11, C = 12, D = 13, E = 14, F = 15).",
  "t.x2u3fbtt5y": "[[acc.home]] · [[acc.home]]: de vaste naam die Aurora op het thuisnetwerk bekendmaakt (bijvoorbeeld aurora.local). Typ hem in de browser van de telefoon: hij blijft hetzelfde, ook als de router het IP-adres van de pc verandert, dus zet er een bladwijzer van. Zie je in plaats daarvan “[[acc.noHome]]”, dan luistert Aurora alleen op deze pc of laat het netwerk de aankondiging niet toe: gebruik het numerieke adres dat bij de QR staat. Het kan niet worden bewerkt.",
  "t.x3s17hxmzt": "De QSO-bediening zit in [[panel.tx]], onder de zes berichten, met de schuifregelaars Rx en Pwr op één rij. [[ctl.enable_tx]] en [[ctl.auto_tx]] zijn rood als ze aan staan: ze staan op het punt te zenden.",
  "t.x59ea9j2s5": "[[cat.apply]] (en het bericht ernaast): slaat de instellingen op en, als de radio verbonden is, verbindt hem opnieuw met de nieuwe waarden. Het is meestal niet nodig: zijn de waarden geldig, dan gaan ze na een moment vanzelf in en als je de pagina verlaat; de knop blijft uitgeschakeld zolang een waarde fout is (“[[cat.invalid]]”). “[[cat.dirty]]” betekent dat er een wijziging is die nog niet is toegepast.",
  "t.x60rr2w9i3": "In het uitgebreide display zijn PRE, ATT, AGC, NB, NR, NOTCH, ATU, VFO, RIT en XIT knoppen: een klik wijzigt de instelling op de radio via CAT en de waarde wordt meteen teruggelezen.",
  "t.x80rhae3xv": "“[[dec.slowPc.auto]]” (standaard): gaat vanzelf aan na 3 van de 10 perioden boven 70% van de tijd, 3 verloren audioblokken in 10 minuten of bij 2 processors of minder; gaat uit na 20 rustige perioden.",
  "t.xa6p96oohb": "Icom: dezelfde snelheid als de radio (115200 aanbevolen) en in de radio bij CI-V USB Port “Unlink from [REMOTE]”.",
  "t.xcz3p79zjx": "Aurora controleert zelf op nieuwe versies en biedt ze aan. Het installatieprogramma sluit Aurora en start het opnieuw. Op een Mac vervangt Aurora zichzelf (Aurora.app) en start opnieuw: het moet in Programma's (of een eigen map) staan, niet geopend vanuit de .dmg; bij de eerste start na de update kan macOS om bevestiging vragen, omdat Aurora niet door Apple is ondertekend. Verbind na een update de programma's die de radio via Aurora gebruiken opnieuw. Wat er veranderd is, staat in [[nav.news]].",
  "t.xdjs7ci9eu": "Kleuren: groen in de lucht, blauw komende, grijs beëindigd, oranje als je het nu hoort. Hoeveel dagen de beëindigde bewaard blijven: “[[onl.dxpedDays]]”.",
  "t.xf6hx1lvkr": "[[digi.mi.underlineSent]] (aan): onderstreept de uitgezonden regels in het ontvangstvenster; je ziet het alleen met [[digi.mi.echoRx]] aan.",
  "t.xgwzlec8t": "Uploaden naar WSPRnet: zet in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.wspr]], vak [[ens.g.wsprnet]], [[ens.k.WSPRnetUpload]] aan en druk op [[sw.save]]. Na elke WSPR- of FST4W-periode stuurt Aurora binnen 20 s na het decoderen de ontvangen signalen naar wsprnet.org (of, als er geen zijn, de status van je station).",
  "t.xifaddr6rq": "“[[digi.ms.title]]” · [[digi.tx.title]]: [[digi.mi.lock]] (uit: het zenden volgt het ontvangen), “[[digi.freq.tx]]” (grijs zolang Lock uit staat), bij CW de snelheidsregelaar (van 5 tot 60 WPM, standaard 20), bij RTTY shift en snelheid, en [[digi.autoReceive]] (standaard uit: met een vinkje begint het luisteren zodra je Aurora opent).",
  "t.xke4x53y7u": "[[phone.band]] en [[phone.mode]]: twee keuzelijsten om band en modus te wijzigen. Ze zijn grijs als de radio niet via CAT wordt bestuurd (de modus FT8/FT4 kun je ook zonder radio wijzigen). Als je zendt, vraagt Aurora om bevestiging (“Je zendt: van band wisselen…?” of “…overschakelen naar…?”, met de gekozen band of modus).",
  "t.xkjjp5vnbr": "Wat zijn de sneltoetsen van de tekstmodi en SSTV?",
  "t.xl3gjj29bl": "“[[contest.decodes]]” (of “[[contest.decodes.time]]”): de decodes van de laatste periodes. Kolommen: “[[contest.col.utc]]”, “[[contest.col.msg]]”, “[[contest.col.country]]”, “[[contest.col.new]]” (wat voor jou telt) en “[[contest.col.value]]”; de koppen kun je verplaatsen en verbreden door te slepen. Dubbelklik op een rij: je roept dat station (is het een dupe, dan vraagt Aurora eerst om bevestiging); de ster ★ is het aanbevolen station. Rijen: doorgestreept = dupe, geel = “[[contest.nonContest]]”, “[[contest.outOfRules]]” = buiten de regels.",
  "t.xne2nmith2": "“[[ens.g.udp]]” · “[[ens.k.EnableUDP1adifSending]]” (standaard aan): voor elke gelogde QSO stuurt hij ook het ADIF-record naar deze server (bericht “Logged ADIF”), zodat het externe logboek het vanzelf opslaat; zet het uit als hetzelfde logboek de QSO op een andere manier ontvangt (dubbelen). “[[ens.k.preventFalseUDPspots]]” (standaard aan): stuurt de programma’s geen berichten die verdacht onjuist lijken; in FT8 en FT4 verandert het niets (het gaat alleen om de “?”-markering van JT65 en JT9).",
  "t.xoq3nhycgu": "De telefoon (of tablet) ziet hem de eerste keer dat hij het adres van Aurora opent, tot hij is gekoppeld. Op het thuisnetwerk komt de telefoon, met “[[acc.open]]” aan (standaard), vanzelf binnen: de pagina verschijnt alleen als er een code nodig is. Tot hij is gekoppeld, controleert de telefoon elke 3 seconden opnieuw, en als je vanaf de pc de toegang zonder code aanzet, komt hij vanzelf binnen, zonder iets in te drukken.",
  "t.xq1acl8kg4": "[[digi.spot.de]]: je eigen station, alleen-lezen (het komt van je roepnaam in de Instellingen).",
  "t.xqfzypdtxt": "Elke QSO wordt maar één keer verstuurd: meteen als het logboek open is, uit de wachtrij als het dicht was, nooit twee keer. De wachtrij blijft bestaan als je Aurora sluit, en een QSO die langer dan zeven dagen in de wachtrij staat, wordt weggegooid. Bij het adres van een andere pc is er geen manier om te weten of het logboek open is: de QSO’s gaan meteen weg, zoals voorheen.",
  "t.xrm1jff9je": "Zet in Automatisering “[[auto.filterCallers]]” aan: ook bij een met de hand geroepen CQ antwoordt Aurora niet aan stations die door de filters van Bandactiviteit verborgen zijn (bijv. “niet mijn continent”) of in Automatisering uitgesloten zijn. “[[auto.contExcludeShort]]” naast de continenten sluit ze uit in plaats van alleen die te behouden.",
  "t.xs0n62xsr8": "[[nav.automation]]",
  "t.xw2mdgu6r5": "[[gen2.operation]] · [[gen2.qsy]] (standaard aan): hiermee kun je de zendfrequentie wijzigen terwijl je zendt (de radio en het bericht volgen meteen). Als het uit staat, wordt een nieuwe zendfrequentie niet geaccepteerd zolang er wordt gezonden.",
  "t.xyyv82wl3p": "Audiofrequentie: de toon in Hz waarop je luistert (0 beat van de radio). Je kunt hem met de hand invullen, van 200 tot 3500; Enter bevestigt, Esc annuleert. Het is de ontvangstfrequentie (niet die van de radio).",
  "t.y0qhqtshdh": "Zend je en gaat de radio niet op zenden, dan verschijnt bovenaan een melding met de reden. Controleer in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] of de PTT-methode dezelfde is als in WSJT-X (CAT, of RTS/DTR op dezelfde poort) en probeer “Test PTT” onderaan de Instellingen. Aurora probeert de PTT ook als een uitlezing van de radio is gemist; antwoordt de radio niet, dan zegt de fout dat. Bij PTT via RTS/DTR geeft de melding, als een ander programma de poort vasthoudt, aan welk programma: sluit het en start Aurora opnieuw (de PTT-poort opent bij het opstarten, “Verbinden” is niet genoeg).",
  "t.y0rcc8vh4w": "[[ca.clock]]: “[[ca.clock.ok]]” als de tijd klopt; bij een afwijking van ongeveer 4 % van de periode of meer verschijnen een “!” en de waarde in milliseconden, boven ongeveer 8 % een “×” (het decoderen wordt veel slechter). Is de tijd nog niet gemeten, dan staat er “[[ca.clock.none]]”. “[[diag.fix]]” leidt naar de klokpagina.",
  "t.y17z1sapht": "[[not2.markers]] · [[not2.mark7373]]: markeert 73 en RR73 tussen andere stations, dus wie net een QSO heeft afgerond en vrij is om geroepen te worden. Engine-item, standaard aan: het geldt met “[[sw.save]]”.",
  "t.y26f6j5d6g": "Kaarten voor nieuwe DXCC minder opdringerig, updatemelding in jouw taal",
  "t.y2bkj4htoj": "Hij sluit vanzelf na de tijd die je kiest in “[[agent.seconds]]” (standaard 10 seconden; van 3 tot 60); een dunne balk onderaan toont hoeveel tijd er nog is. Met de muis boven de kaart sluit hij niet. De × rechtsboven en de knop “Sluiten” sluiten hem meteen.",
  "t.y4etzu7vvz": "[[sw.pg.digiRxTx]]",
  "t.y6wz3s9a56": "Een geluid voor elke gebeurtenis.",
  "t.y7hccjnbtj": "Voer gebruiker, wachtwoord of sleutel in en bevestig met Enter (of verlaat het veld): ze blijven in behandeling tot je onderaan op “[[sw.save]]” drukt; pas na het opslaan start de test van het vak vanzelf (of je drukt op “[[ens.test]]”).",
  "t.y8wehmelmj": "[[cqp.title]] · [[cqp.only]] en [[cqp.hide]]: twee tekstvelden met roepnamen of prefixen gescheiden door komma's (JA* = alle JA). Het eerste toont, als het niet leeg is, ALLEEN die stations (om een activiteit of expeditie te volgen); het tweede toont die stations nooit (stations die steeds roepen en je niet interesseren). Standaard leeg.",
  "t.y97lypgbu0": "Stem de radio met de hand af op dezelfde frequentie (die Aurora toont, bijvoorbeeld 7,074 MHz in FT8), in USB.",
  "t.yb7rqcogwb": "Hoe kies ik de geluidskaart en het juiste niveau?",
  "t.ybwmky91r1": "De gegevens komen uit het interne logboek van Aurora (en uit Log4OM2 als die verbonden is) en uit het prefixbestand cty.dat; ze worden bij elke gelogde QSO vanzelf bijgewerkt. Ontbreekt een van de twee, dan zegt de kaart “[[dxcc.unavailable]]”.",
  "t.yebn9ov1hw": "[[set.add]] · knop [[set.reset]]: zet de vijf beginmacro's terug en gooit de macro's weg die je had toegevoegd of verwijderd. Gebruik hem als de lijst een rommeltje is geworden.",
  "t.yienm0mp54": "[[not2.grpAlerts]] · [[not2.muteTx]]: terwijl je zendt, zijn de meldingen stil (behalve het geluid van je eigen zendbericht). Standaard aan; vooral handig als het audiosignaal van de pc ook in de radio terechtkomt. Zet het alleen uit als de geluiden naar een aparte luidspreker gaan.",
  "t.ymgea2bovd": "Onder de knop verschijnen meldingen: “[[pair.short]]”, “[[pair.badCode]]”, “[[pair.expired]]”, “[[pair.badName]]”, of “Te veel pogingen” met de resterende seconden (in die tijd kun je het niet opnieuw proberen).",
  "t.yn0v7wunz8": "[[snd.title]] · menu “[[snd.pick]]” (hetzelfde in elke rij van deze pagina en in de Kleuren): “[[snd.none]]”, de stem, de groep “[[snd.myFiles]]” met je bestanden en het item “[[snd.addFile]]”, daarna de geluiden van Aurora per categorie. Je eigen WAV-, MP3- of OGG-bestand mag maximaal 5 MB zijn (anders verschijnt “[[snd.fileFail]]”) en blijft in de lijst voor elke melding. De knop ▶ (“[[snd.try]]”) speelt je keuze af; de × ernaast, alleen zichtbaar bij je eigen bestand, verwijdert het uit de geluiden. Als je een geluid kiest, gaat ook de melding van die functie aan.",
  "t.ynkrevlin0": "Een spot versturen: het venster “[[digi.spot.title]]”",
  "t.yoo5eazqd6": "BPF in de statusbalk (naast AFC, ook in het menu [[digi.menu.options]]) zet de banddoorlaat rond de ontvangstfrequentie aan: PSK31 ongeveer 94 Hz, PSK63 ongeveer 188 Hz, RTTY de shift plus tweemaal de baudrate, CW 80 Hz. Hij volgt de frequentie die je kiest en verwijdert stations in de buurt alleen voor de decoder.",
  "t.ypdch92rlq": "“[[int.host]]”: het IP-adres van het programma: 127.0.0.1 (of localhost) als het op deze pc draait, het IP van de andere computer als die in het netwerk zit, een adres van 224.0.0.0 tot 239.255.255.255 als het een multicastgroep is (zet dan ook “[[int.multicast]]” aan). Een multicastadres zonder dat het vak aan staat is een fout, en andersom ook.",
  "t.yprahqpj9o": "Hoe werk ik Aurora bij, en kan ik de update uitstellen?",
  "t.yqk7hehiia": "Open [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] en kies bij [[cat.backend]] “[[cat.backend.cat4om]]”.",
  "t.yqo9brue7r": "[[auto.b1]] · [[auto.newMode]], [[kind.new_state]], [[kind.new_state_band]] en [[tab.wishlist]] (vier extra vakjes, standaard uit): [[auto.newMode]] beantwoordt een land dat je nog nooit in de gebruikte mode hebt gewerkt (berekend uit je logboek); [[kind.new_state]] en [[kind.new_state_band]] beantwoorden Amerikaanse stations uit een staat die je nog niet hebt gewerkt of nog niet op deze band (de staat komt uit opzoekingen bij QRZ.com/HamQTH en uit de logboeken); [[tab.wishlist]] beantwoordt stations, prefixen, landen en grids van je verlanglijst. Alle beveiligingen gelden: minimaal signaal, pogingen, grenzen, uitsluitingen.",
  "t.ysaoklqcur": "Zet “[[clock.atStart]]” aan: bij elke start corrigeert Aurora de tijd vanzelf. Om de pc-tijd te wijzigen moet Aurora als beheerder draaien.",
  "t.ysu5hbxtd5": "[[digi.edit.color]]: de kleur van de knop.",
  "t.ysyrvvknyu": "Onder de roepnaam zegt een rij “[[dxp.onAir]]” dat een cluster haar net heeft gespot, met frequentie, modus en hoeveel minuten geleden; dubbelklik op de frequentie om de radio erheen te zetten. “[[dxp.heardByMe]]” = je hebt haar zelf gedecodeerd: frequentie, modus, signaal en tijd.",
  "t.yuclonwjzw": "[[lay.options]] · [[set.reset]]: knop; zet alleen de filters van deze pagina (niet de andere keuzes) terug op de fabrieksinstellingen. Druk erop als je niet meer begrijpt waarom een bericht niet verschijnt.",
  "t.yuwksen2ui": "[[sw.digi.perMode]] · CW, schuifregelaar voor de squelchdrempel (S/R van -30 tot 20 dB, fabriek -15): hij meet de signaal-ruisverhouding rond de toon. Op ruis alleen zit hij rond -25 dB; onder -16 dB wordt niets afgedrukt, ook met de squelch uit. Verhoog hem als er tekens op ruis verschijnen. Hij telt alleen met “[[digi.mi.squelch]]” aan.",
  "t.yvmtsq2ndm": "Typ in “[[fil.calls]]” de roepnamen die je wilt verbergen; in “[[fil.showOnly]]” de enige die je wilt zien. JA* komt overeen met elke roepnaam die met JA begint.",
  "t.ywerzvmg0g": "Dezelfde contestinstellingen (activiteit, uitwisseling, categorie, Cabrillo-gegevens) staan ook in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]], met de keuzelijst om de contest te kiezen; voor contests die MSK144 of Q65 toestaan staan ze in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › [[sw.pg.contest]]. Het tandwiel ⚙ van de pagina [[nav.contest]] opent de tak van de modus in gebruik.",
  "t.yztc96psoa": "Zo zet je het uit (de meest gestelde vraag): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], vak “[[not2.grpAlerts]]”. “[[not2.popNew]]” zet het kaartje voor een nieuw land aan en uit, “[[not2.popNewBand]]” dat voor een nieuw land op de band: haal beide vinkjes weg en het kaartje verschijnt niet meer. “[[not2.popPos]]” kiest de hoek of de rand van het scherm waar het verschijnt; het geluid kies je in “[[not2.popSound]]”.",
  "t.z177sfkc9z": "Volledig onderdeel: «SSTV: sneltoetsen»; «RX/TX, Pause, Esc, dubbel Esc en automatische CQ»; «Sneltoetsen en gebaren».",
  "t.z1s4owb3z5": "Alleen CW: de keuzelijst voor de filterbandbreedte (“[[digi.cw.bandwidth]]”) en de knop “TX = RX”, die de zendsnelheid op de ontvangen snelheid zet (grijs zonder signaal).",
  "t.z4627jxyco": "De QSO is kort: jij zendt roepnaam en locator, de Fox geeft je een rapport, jij antwoordt R+rapport, de Fox sluit af met RR73. Geen laatste 73 van jou.",
  "t.z4lw7dq1lr": "De regio die voor de hele tabel geldt, kies je in [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]], vak [[sw.station]], keuzelijst [[gen2.region]] (standaard [[gen2.regionAll]]: rijen van elke regio zijn zichtbaar). Wijzigen verwijdert geen enkele rij.",
  "t.z4pigoj7zn": "“[[rep.ask]]” (aan): na een crash vraagt Aurora bij de herstart of het rapport verstuurd mag worden. Uit, dan vraagt het niets en verstuurt het uit zichzelf niets.",
  "t.z70nibu0un": "Na een herstart kan de radio een minuut nodig hebben om weer klaar te zijn: Aurora wacht nu tot 75 seconden. Bij Yaesu en Kenwood gaat het commando in twee schone paren de deur uit.",
  "t.z77fads81l": "In de cel Opmerkingen van de DX Cluster verschijnt alleen de opmerking. De menu’s voor modus en frequentie hebben een volle achtergrond: het tabblad eronder schemert niet meer door.",
  "t.z7r72qsbmi": "Een klik op een knop, of de toets op het toetsenbord (F1…F12, met Ctrl en Shift voor de andere rijen), voert de macro uit. De “+” van het numerieke toetsenblok voert ook de macro “Gray+” uit (standaard slaat die de QSO op).",
  "t.z7yezacu0a": "Je hebt deze pagina niet nodig om panelen te verplaatsen en van grootte te veranderen: sleep ze aan de titelbalk, wijzig de grootte aan de onderrand en dubbelklikken op de titel klapt ze in.",
  "t.z86af14ogm": "De digitale handtekening (OTP-code) wordt ondersteund: als expeditie voer je de seed in op de pagina Fox en de code gaat mee in het signaal; als Hound controleert Aurora de Fox en de regel wordt “verified” of “invalid”.",
  "t.z8kqe79vg4": "Test: maak een QSO (ook op een kunstantenne) en controleer of de regel in het logboek verschijnt.",
  "t.z9fcxzedlh": "“[[cluster.state]]”: één rij voor elke server die in gebruik is, met een lampje en de status: verbinden, verbonden (met het aantal ontvangen spots) of niet verbonden (met de reden). Is er geen server verbonden, dan zie je “[[cluster.state.none]]”. Het helpt te begrijpen waarom het paneel leeg is.",
  "t.zau0y5vjn2": "Het RTTY-venster opent alleen vanuit de onderbalk, met frequenties en baud zonder decimalen. «Modusinstellingen» staan op volgorde, de metingen hebben een vaste breedte en de greep tussen de vensters is goed zichtbaar.",
  "t.zdx78kent9": "Seriële poorten: Windows en Linux (groep dialout)",
  "t.zezvqjr2t5": "Het aantal keren in de vier scenario’s en de prioriteiten werken direct na [[sw.save]], zonder herstart. De beveiligingen ([[gen2.watchdog]], [[gen2.swr]], [[auto.b3]] in de Automatiseringen) zijn onafhankelijk: elk stopt het zenden op zijn eigen manier.",
  "t.zjfum6915o": "Juiste poort: kies in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] de COM-poort van de radio bij [[cat.port]] (druk op “[[cat.ports.refresh]]” nadat je de radio hebt aangezet of de kabel hebt aangesloten).",
  "t.zkqdpjsksl": "FST4W-baken: kies naast de modus het vermogen (het echte bij de antenne) en [[mode.wsprPct]], en zet dan [[ctl.enable_tx]] aan. Aan het begin van de perioden die het percentage kiest, zendt Aurora “ROEPNAAM LOCATOR dBm”: net als WSJT-X beslist het met een willekeurige trekking per periode en, onder 40%, nooit twee perioden achter elkaar.",
  "t.zlun6yzl82": "[[sw.contest.title]] · [[contest.set.callContest]], [[contest.set.grid6]], [[contest.set.antenna]], [[contest.set.operators]], [[contest.set.club]]: tekstvelden voor de kop van het log. De contestroepnaam wordt alleen geschreven als hij verschilt van die van het station (leeg = die van het station); de locator van 6 tekens is nodig voor EU VHF en het EDI-log; de antenne (bijvoorbeeld “Yagi 9 el”) komt in het EDI van VHF-contests; operators en club alleen als de regels erom vragen.",
  "t.zmwckzhbxv": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[ens.g.adif]]” · “[[ens.k.UDP2Resend]]” (standaard aan): geldt voor de secundaire UDP-server (standaard 127.0.0.1, poort 2237). Als het logboek op deze pc (bijvoorbeeld Log4OM) dicht is wanneer je een QSO maakt, bewaart Aurora hem apart en stuurt hem vanzelf ongeveer 15 seconden nadat je het logboek weer opent, in de volgorde waarin je ze hebt gemaakt.",
  "t.znysdv6yzi": "De knoppen van het paneel Opdrachten springen nu naar de volgende regel in plaats van afgesneden te worden. Op de FT8-waterval staat de muisfrequentie gecentreerd tussen de twee lijnen.",
  "t.zo8b1llifb": "Telefoon en tablet: de afstandsbediening, de bovenbalk",
  "t.zols3w9gwe": "De agent controleert 20 seconden na de start en daarna elk uur. Meldingen verschijnen alleen als Aurora gesloten is (met Aurora open toont Aurora ze zelf), en elke melding maar één keer. De uitzondering is “Controleer op updates” uit het menu, dat altijd antwoordt.",
  "t.zoz9462k0u": "[[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] › [[sat.set.catMap]]. Kiest de wereldkaart onder de satellietsporen op de pagina Satellieten. Elke wijziging wordt meteen opgeslagen.",
  "t.zsd9ka16of": "[[gen2.logFilter]] · [[gen2.useCall]] en [[gen2.useGrid]] (twee vakjes, standaard uit): Aurora telt als “al gewerkt” (kleuren voor nieuwe entiteiten, nieuwe DXCC, automatische antwoorden) alleen de QSO’s uit het log die met jouw roepletters zijn gemaakt, en met het grid-vakje ook alleen met jouw locator (de eerste vier tekens). Gebruik ze als je log QSO’s van een andere roepletters of locatie bevat. Logs die niet bijhouden welke roepletters je gebruikte (het eigen log van Aurora, Log4OM) worden om deze twee redenen niet buitengesloten.",
  "t.ztdinm290o": "Het radiodisplay",
  "t.ztr5yweq5n": "Het paneel [[panel.tx]] toont met wie je in contact bent en hoe ver het QSO is, en bevat de QSO-schakelaars (zie “De QSO-schakelaars”) en de audioniveaus (zie “De niveaus Rx en Pwr”).",
  "t.zv5hw7m6xj": "Een QSO ontbreekt in het externe logboek",
  "t.zwxo4ij1xt": "Knoppen eronder: “[[contest.autoseq]]” (de berichten schuiven vanzelf door), “[[contest.enableTx]]”, “[[contest.autoCq]]” (F1: de contest-CQ bij elke periode tot iemand antwoordt), “[[contest.rr73]]” (stuurt de afsluiting opnieuw als het andere station de exchange herhaalt), “[[stop.button]]”. “[[contest.next]]” zegt wie je hierna moet roepen, op volgorde van waarde.",
  "t.zxz5isp8kv": "[[gen2.bandHop]] · [[gen2.bandHopOn]] (standaard uit): elke twee minuten gaat de radio naar de volgende band of frequentie in de lijst, in een rondje. Hij hopt niet als [[ctl.enable_tx]] aan staat of tijdens een zending (die stap wordt overgeslagen en in de volgende ronde opnieuw geprobeerd). Je kunt het ook aanzetten vanuit [[nav.automation]].",
};
